import { User, Role, StudentData, Lesson, SubjectGuide, Transaction } from './types';
import { supabase } from './supabaseClient';

export const initStorage = async () => {
  console.log("Supabase storage initialized");
};

const calculateLessonStatus = (lesson: Partial<Lesson>): 'Pendiente' | 'En Progreso' | 'Aprobada' | 'Reprobada' | 'Completada' => {
  const interactions = lesson.validInteractionsCount || 0;
  const hasMessages = !!(lesson.chatHistory && lesson.chatHistory.length > 0);
  const grade = lesson.grade;
  const currentStatus = lesson.lesson_status;

  // 1. APROBADA / COMPLETADA: Nota >= 6
  if (grade !== undefined && grade !== null && grade >= 6) {
    return (currentStatus === 'Completada') ? 'Completada' : 'Aprobada';
  }

  // 2. REPROBADA: Nota > 0 pero < 6
  if (grade !== undefined && grade !== null && grade > 0 && grade < 6) {
    return 'Reprobada';
  }

  // 3. EN PROGRESO: Con actividad (interacciones o mensajes) pero sin nota final todavía
  if ((interactions > 0 || hasMessages) && (grade === undefined || grade === null || grade === 0)) {
    return 'En Progreso';
  }

  // 4. PENDIENTE: Sin actividad significativa
  return 'Pendiente';
};

export const autoUpdateLessonStatuses = async (username: string) => {
  try {
    // Sincronización masiva basada en reglas de negocio
    // Aprobadas
    await supabase
      .from('lessons')
      .update({ lesson_status: 'Aprobada', completed: true })
      .eq('student_username', username)
      .gte('grade', 6);

    // Reprobadas
    await supabase
      .from('lessons')
      .update({ lesson_status: 'Reprobada', completed: false })
      .eq('student_username', username)
      .gt('grade', 0)
      .lt('grade', 6);

    // En Progreso
    await supabase
      .from('lessons')
      .update({ lesson_status: 'En Progreso' })
      .eq('student_username', username)
      .or('grade.is.null,grade.eq.0')
      .gt('valid_interactions_count', 0);

  } catch (err) {
    console.error("Error en auto-actualización de estatus:", err);
  }
};

// --- CUENTAS Y SALDOS ---
export const getAccountBalance = async (username: string): Promise<number> => {
  const { data, error } = await supabase
    .from('accounts')
    .select('balance')
    .eq('owner_id', username)
    .single();

  if (error || !data) return 0;
  return data.balance;
};

export const getTransactions = async (username: string): Promise<Transaction[]> => {
  const { data, error } = await supabase
    .from('transactions')
    .select('*')
    .or(`from_account.eq.${username},to_account.eq.${username}`)
    .order('created_at', { ascending: false });

  if (error) {
    console.error("Error fetching transactions:", error);
    return [];
  }
  return data || [];
};

export const getAllTransactions = async (): Promise<Transaction[]> => {
  const { data, error } = await supabase
    .from('transactions')
    .select('*')
    .order('created_at', { ascending: false });

  if (error) {
    console.error("Error fetching all transactions:", error);
    return [];
  }
  return data || [];
};

export const executeCreditTransfer = async (
  studentUsername: string, 
  amount: number, 
  concept: string, 
  lessonIds: string[]
) => {
  const numericIds = lessonIds
    .map(id => parseInt(id, 10))
    .filter(id => !isNaN(id));

  if (numericIds.length === 0) {
    throw new Error("No hay lecciones válidas para transferir.");
  }

  const cleanAmount = Math.floor(amount);
  if (cleanAmount <= 0) {
    throw new Error("El monto a transferir debe ser mayor a cero.");
  }

  const { error } = await supabase.rpc('transfer_credits_v2', {
    student_name: studentUsername,
    admin_name: 'Admin',
    transfer_amount: cleanAmount,
    transfer_concept: concept,
    lesson_ids: numericIds
  });

  if (error) {
    console.error("Error en RPC transfer_credits_v2:", error);
    throw new Error(error.message || "La transferencia falló en el servidor de base de datos.");
  }
};

