      <div className="my-4 p-6 rounded-[2rem] bg-indigo-50 dark:bg-indigo-900/30 border-4 border-dashed border-indigo-100 dark:border-indigo-800 flex flex-col items-center text-center">
        <span className="text-4xl mb-4">🖼️</span>
        <p className="text-xs font-black text-indigo-900 dark:text-indigo-100 uppercase tracking-widest mb-1">Recurso de Referencia</p>
        <a href={src} target="_blank" rel="noopener noreferrer" className="px-6 py-3 bg-indigo-600 text-white text-[10px] font-black rounded-2xl uppercase shadow-lg hover:bg-indigo-700 transition-all active:scale-95">Ver original ↗</a>
      </div>
    );
  }
  return (
    <div className="relative group my-4">
      <img src={src} alt={alt} crossOrigin="anonymous" onError={() => setError(true)} className="max-w-full h-auto rounded-3xl border-4 border-white dark:border-indigo-800 shadow-sm" />
    </div>
  );
};

const SafeLink: React.FC<any> = ({ children, href }) => (
  <a href={href} target="_blank" rel="noopener noreferrer" className="text-indigo-600 dark:text-indigo-400 font-black underline decoration-2 underline-offset-4 inline-flex items-center">
    {children} <span className="ml-1 text-[8px]">↗</span>
  </a>
);

const MarkdownComponents = {
  img: ({node, ...props}: any) => <ImageWithFallback src={props.src} alt={props.alt} />,
  a: ({node, ...props}: any) => <SafeLink {...props} />
};

interface ParsedAIResponse {
  explanation: string;
  challengeType?: 'MCQ' | 'WRITTEN';
  question?: {
    text: string;
    options?: string[];
    correct?: string;
  };
  errorInfo?: string;
  refuerzo?: string;
}

const RichMessage: React.FC<{ 
  text: string; 
  onAction: (val: string) => void; 
  isUser: boolean;
  timeLeft?: number;
  isUnlocked?: boolean;
  persistedSelection?: string;
  isAudit?: boolean;
  studentInitial?: string;
  isLessonFinished?: boolean;
}> = React.memo(({ text, onAction, isUser, timeLeft, isUnlocked = false, persistedSelection, isAudit, studentInitial, isLessonFinished }) => {
  const [selectedOption, setSelectedOption] = useState<string | null>(persistedSelection || null);

  const parseResponse = (raw: string): ParsedAIResponse => {
    const dataMatch = raw.match(/\[DATA_LOGICA\]([\s\S]*?)\[\/DATA_LOGICA\]/);
    const expMatch = raw.match(/\[EXPLICACION\]([\s\S]*?)\[\/EXPLICACION\]/);
    const errorMatch = raw.match(/\[ERROR_INFO\]([\s\S]*?)(?=\[REFUERZO\]|\[EXPLICACION\]|$)/);
    const refuerzoMatch = raw.match(/\[REFUERZO\]([\s\S]*?)(?=\[EXPLICACION\]|$)/);

    let explanation = expMatch ? expMatch[1].trim() : raw;

    explanation = explanation
      .replace(/\[DATA_LOGICA\][\s\S]*?\[\/DATA_LOGICA\]/g, '')
      .replace(/\[DATA_LOGICA\][\s\S]*/g, '')
      .replace(/\[EXPLICACION\]|\[\/EXPLICACION\]|\[RESPUESTA_VALIDA\]|\[PLAGIO_IA\]|\[REFUERZO\]|\[ERROR_INFO\]/g, '')
      .replace(/\{[\s\S]*"type"[\s\S]*\}/g, '')
      .trim();

    let questionData;
    let challengeType;

    if (dataMatch) {
      try {
        const json = JSON.parse(dataMatch[1].trim());
        challengeType = json.type;
        questionData = { 
          text: json.question, 
          options: json.options, 
          correct: json.correct 
        };
      } catch (e) { 
        console.error("Fuga de datos evitada:", e); 
      }
    }

    return {
      explanation,
      challengeType,
      question: questionData,
      errorInfo: errorMatch ? errorMatch[1].trim() : undefined,
      refuerzo: refuerzoMatch ? refuerzoMatch[1].trim() : undefined
    };
  };

  const handleOptionClick = (opt: string) => {
    if (selectedOption || persistedSelection || isAudit || timeLeft === 0) return;
    setSelectedOption(opt);
    setTimeout(() => onAction(opt), 800);
  };

  if (isUser) {
    return (
      <div className="flex items-start space-x-3 justify-end w-full">
        <div className="bg-indigo-600 text-white p-5 rounded-[2.5rem] shadow-sm border-2 border-indigo-700 max-w-full w-fit ml-auto">
          <div className="prose dark:prose-invert max-w-none text-lg font-bold">
            {text}
          </div>
        </div>
        <div className="w-10 h-10 rounded-full bg-white dark:bg-indigo-800 border-2 border-indigo-200 dark:border-indigo-700 flex items-center justify-center text-indigo-600 dark:text-indigo-200 font-black shrink-0 shadow-sm">
          {studentInitial}
        </div>
      </div>
    );
  }

  const parsed = parseResponse(text);
  const activeSelection = selectedOption || persistedSelection;
  const isExpired = timeLeft === 0 && !activeSelection;

  return (
    <div className="flex items-start space-x-3 w-full">
      <div className="w-10 h-10 rounded-2xl bg-indigo-50 dark:bg-indigo-800 border-2 border-indigo-100 dark:border-indigo-700 flex items-center justify-center text-xl shrink-0 shadow-sm">
        🤖
      </div>
      <div className="bg-white dark:bg-indigo-900 text-indigo-900 dark:text-indigo-100 p-6 rounded-[2.5rem] shadow-sm border-2 border-indigo-50 dark:border-indigo-800 flex-1 w-full max-w-full">
        <div className="flex flex-col space-y-4">
          {parsed.errorInfo && (
            <div className="p-4 bg-red-50 dark:bg-red-900/30 border-l-4 border-red-500 rounded-xl animate-in fade-in slide-in-from-top-1">
              <p className="text-[10px] font-black text-red-600 dark:text-red-400 uppercase mb-1">Nota de Refuerzo:</p>
              <p className="text-sm font-medium italic">{parsed.errorInfo}</p>
            </div>
          )}

          {(parsed.explanation || parsed.refuerzo) && (
            <div className="rich-content prose dark:prose-invert max-w-none text-lg">
              <ReactMarkdown remarkPlugins={[remarkGfm]} rehypePlugins={[rehypeRaw]} components={MarkdownComponents}>
                {parsed.refuerzo || parsed.explanation}
              </ReactMarkdown>
              {!isUnlocked && !activeSelection && !isAudit && parsed.question && !isLessonFinished && (
                <div className="mt-6 animate-in fade-in duration-700">
                  <button 
                    onClick={() => onAction("__UNLOCK_QUESTION__")} 
                    className="bg-white dark:bg-indigo-800 text-indigo-600 dark:text-indigo-200 border-2 border-indigo-100 dark:border-indigo-700 px-6 py-3 rounded-2xl font-black text-xs hover:bg-indigo-50 shadow-sm transition-all active:scale-95 flex items-center space-x-2"
                  >
                    <span>Leído y comprendido</span>
                    <span className="text-lg">🎯</span>
                  </button>
                </div>
              )}
            </div>
          )}

          {parsed.question && (isUnlocked || activeSelection) && !isLessonFinished && (
            <div className="animate-in zoom-in-95 duration-300 pt-4 border-t-2 border-indigo-50 dark:border-indigo-800/50">
              <div className="mb-4">
                 <p className="text-lg font-black text-indigo-900 dark:text-indigo-100 mb-4">{parsed.question.text}</p>
                 {timeLeft !== undefined && !activeSelection && !isExpired && (
                   <div className="flex items-center space-x-2 text-[10px] font-black text-indigo-400 uppercase tracking-widest mb-4">
                     <span className="animate-pulse">⏳ TIEMPO RESTANTE:</span>
                     <span className={`text-sm ${timeLeft < 10 ? 'text-red-500' : 'text-indigo-600 dark:text-indigo-400'}`}>{timeLeft}s</span>
                   </div>
                 )}
              </div>

              {parsed.challengeType === 'MCQ' && (
                <div className="grid gap-2">
                  {Array.isArray(parsed.question.options) && parsed.question.options.map((opt, idx) => {
                    const isSelected = activeSelection === opt;
                    const isCorrect = opt === parsed.question?.correct;
                    let btnClass = "bg-white dark:bg-indigo-950 text-indigo-600 dark:text-indigo-200 border-indigo-50 dark:border-indigo-800 hover:bg-indigo-50";
                    if (activeSelection) {
                      if (isCorrect) btnClass = "bg-green-500 border-green-600 text-white";
                      else if (isSelected) btnClass = "bg-red-500 border-red-600 text-white";
                      else btnClass = "bg-slate-50 dark:bg-indigo-900 border-indigo-50 dark:border-indigo-800 opacity-40 text-indigo-300";
                    } else if (isExpired) {
                       btnClass = "bg-slate-200 dark:bg-indigo-950 border-slate-300 dark:border-indigo-900 opacity-50 text-slate-400 cursor-not-allowed";
                    } else if (!isAudit) btnClass = "bg-indigo-600 border-indigo-500 hover:bg-indigo-700 text-white";

                    return (
                      <button 
                        key={idx} 
                        onClick={() => handleOptionClick(opt)} 
                        disabled={!!activeSelection || isAudit || isExpired}
                        className={`w-full text-left px-5 py-4 rounded-xl font-black text-lg shadow-md transition-all active:scale-95 border-2 ${btnClass}`}
                      >
                        {opt}
                      </button>
                    );
                  })}
                </div>
              )}

              {isExpired && (
                <div className="mt-4 p-4 bg-red-50 dark:bg-red-900/30 border-2 border-red-200 dark:border-red-800 rounded-2xl animate-in zoom-in duration-300">
                  <p className="text-sm font-black text-red-600 dark:text-red-400 text-center uppercase tracking-[0.2em]">⚠️ TIEMPO AGOTADO</p>
                </div>
              )}

              {parsed.challengeType === 'WRITTEN' && !activeSelection && !isAudit && !isExpired && (
                <div className="p-4 bg-indigo-50 dark:bg-indigo-800/20 rounded-2xl border-2 border-indigo-100 dark:border-indigo-700 text-indigo-400 text-xs font-black uppercase text-center animate-pulse">
                  Escribe tu respuesta abajo en el cuadro de texto ⌨️
                </div>
              )}

              {parsed.challengeType === 'WRITTEN' && (activeSelection || isAudit) && (
                <div className="p-4 bg-indigo-600 text-white rounded-2xl font-bold text-sm">
                  {activeSelection || "Respuesta pendiente"}
                </div>
              )}
            </div>
          )}
        </div>
      </div>
    </div>
  );
});

const LessonWindow: React.FC<LessonWindowProps> = ({ studentUsername, lessonId, onClose, isAdminAudit: forcedAudit = false }) => {
  const [lesson, setLesson] = useState<Lesson | null>(null);
  const [messages, setMessages] = useState<ChatMessage[]>([]);
  const [input, setInput] = useState('');
  const [isLoading, setIsLoading] = useState(false);
  const [loadingText, setLoadingText] = useState('');
  const [isGeneratingExam, setIsGeneratingExam] = useState(false);
  const [secondsElapsed, setSecondsElapsed] = useState(0);
  const [isPaused, setIsPaused] = useState(false);
  const [isAutoPaused, setIsAutoPaused] = useState(false);
  const [idleSeconds, setIdleSeconds] = useState(0);

  const [validCount, setValidCount] = useState(0);
  const [targetInteractions, setTargetInteractions] = useState(30);
  const [isLessonFinishedLocally, setIsLessonFinishedLocally] = useState(false);

  const [challengeTimeLeft, setChallengeTimeLeft] = useState<number | undefined>(undefined);
  const [isUnlocked, setIsUnlocked] = useState(false);
  const [isWrittenChallenge, setIsWrittenChallenge] = useState(false);
  const [lastValidationResult, setLastValidationResult] = useState<'correct' | 'incorrect' | null>(null);

  // Exam States
  const [showExam, setShowExam] = useState(false);
  const [examData, setExamData] = useState<any>(null);
  const [currentQuestionIdx, setCurrentQuestionIdx] = useState(0);
  const [currentAnswer, setCurrentAnswer] = useState('');
  const [showQuestionFeedback, setShowQuestionFeedback] = useState(false);
  const [isLastAnswerCorrect, setIsLastAnswerCorrect] = useState(false);
  const [aiFeedback, setAiFeedback] = useState('');
  const [isExamFinished, setIsExamFinished] = useState(false);
  const [correctAnswersCount, setCorrectAnswersCount] = useState(0);
  const [examTimer, setExamTimer] = useState(0);

  const chatRef = useRef<any>(null);
  const messagesEndRef = useRef<HTMLDivElement>(null);
  const lastSavedTimeRef = useRef<number>(0);
  const messagesRef = useRef<ChatMessage[]>([]);
  const challengeTimerRef = useRef<number | null>(null);
  const examTimerRef = useRef<number | null>(null);

  const isAdminAudit = forcedAudit || (lesson?.credits_transfered === true);

  useEffect(() => { messagesRef.current = messages; }, [messages]);

  // FÓRMULA DE TIEMPO: (Palabras Enunciado + Palabras Opciones) * 2. Min 20s, Max 180s.
  const calculateWordCountTime = (questionText: string, options: string[]) => {
    const cleanText = (t: string) => (t || '').replace(/[*_`#]/g, '').replace(/<[^>]*>?/gm, '').trim();
    const wordsA = cleanText(questionText).split(/\s+/).filter(w => w.length > 0).length;
    const wordsB = options.map(opt => cleanText(opt).split(/\s+/).filter(w => w.length > 0).length)
                         .reduce((sum, count) => sum + count, 0);
    const totalWords = wordsA + wordsB;
    const calculatedTime = totalWords * 2;
    return Math.min(180, Math.max(20, calculatedTime));
  };

  useEffect(() => {
    const lastMsg = messages[messages.length - 1];
    if (lastMsg && lastMsg.role === 'model') {
      const isWritten = lastMsg.parts[0].text.includes('"type": "WRITTEN"') || lastMsg.parts[0].text.includes('"type":"WRITTEN"');
      setIsWrittenChallenge(isWritten);
    } else {
      setIsWrittenChallenge(false);
    }
  }, [messages]);

  useEffect(() => {
    if (!isAdminAudit && isUnlocked && challengeTimeLeft !== undefined) {
      challengeTimerRef.current = window.setInterval(() => {
        setChallengeTimeLeft(prev => {
          if (prev !== undefined && prev <= 1) {
            handleTimeout();
            return 0;
          }
          return prev !== undefined ? prev - 1 : 0;
        });
      }, 1000);
    } else {
      if (challengeTimerRef.current) clearInterval(challengeTimerRef.current);
    }
    return () => { if (challengeTimerRef.current) clearInterval(challengeTimerRef.current); };
  }, [isUnlocked, challengeTimeLeft, isAdminAudit]);

  useEffect(() => {
    if (showExam && !showQuestionFeedback && examTimer > 0) {
      examTimerRef.current = window.setInterval(() => {
        setExamTimer(prev => {
          if (prev <= 1) {
            handleCheckAnswer();
            return 0;
          }
          return prev - 1;
        });
      }, 1000);
    } else {
      if (examTimerRef.current) clearInterval(examTimerRef.current);
    }
    return () => { if (examTimerRef.current) clearInterval(examTimerRef.current); };
  }, [showExam, showQuestionFeedback, examTimer]);

  const handleTimeout = async () => {
    setIsUnlocked(false);
    setChallengeTimeLeft(0);
    try {
      const result = await chatRef.current.sendMessage({ message: "[TIEMPO_AGOTADO] No logré responder el desafío a tiempo." });
      const aiText = result.text || '';
      const aiMsg: ChatMessage = { role: 'model', parts: [{ text: aiText }], timestamp: new Date().toISOString() };
      setMessages(prev => [...prev, aiMsg]);
      messagesEndRef.current?.scrollIntoView({ behavior: 'smooth' });
    } catch (e) { console.error(e); }
  };

  useEffect(() => {
    const fetchLesson = async () => {
      const data = await getStudentData(studentUsername);
      if (data) {
        const found = data.lessons.find(l => l.id === lessonId);
        if (found) {
          setLesson(found);
          setSecondsElapsed(found.elapsedSeconds || 0);
          setValidCount(found.validInteractionsCount || 0);

          // REGLA DEL 70%
          const target = Math.ceil(found.durationMinutes * 0.7);
          setTargetInteractions(target);

          lastSavedTimeRef.current = found.elapsedSeconds || 0;
          if (found.chatHistory?.length) setMessages(found.chatHistory);

          if (!isAdminAudit) {
            startGeminiChat(found, (found.chatHistory?.length || 0) > 0);
          }
        }
      }
    };
    fetchLesson();
  }, [studentUsername, lessonId, isAdminAudit]);

  const saveProgress = async (time: number, currentMessages: ChatMessage[], currentValidCount: number) => {
    if (!lesson || isAdminAudit) return;
    try {
      const updated: Lesson = { ...lesson, elapsedSeconds: time, chatHistory: currentMessages, validInteractionsCount: currentValidCount };
      await updateLessonInStudent(studentUsername, updated);
      lastSavedTimeRef.current = time;
    } catch (err) { console.error("Error al guardar:", err); }
  };

  const handleDirectExit = async () => {
    if (isAdminAudit) { onClose(); return; }
    setIsLoading(true);
    await saveProgress(secondsElapsed, messagesRef.current, validCount);
    onClose(lesson?.date, lesson?.id);
  };

  useEffect(() => {
    if (isAdminAudit) return;
    const timer = setInterval(() => {
      if (!isPaused && !showExam && !isExamFinished && !isGeneratingExam) {
        setSecondsElapsed(prev => prev + 1);
        if (secondsElapsed - lastSavedTimeRef.current >= 60) saveProgress(secondsElapsed, messagesRef.current, validCount);
        if (!isLoading) setIdleSeconds(prev => {
          if (prev + 1 >= 180) { setIsAutoPaused(true); setIsPaused(true); return 0; }
          return prev + 1;
        });
      }
    }, 1000);
    return () => clearInterval(timer);
  }, [isPaused, showExam, isExamFinished, isLoading, isGeneratingExam, secondsElapsed, validCount, isAdminAudit]);

  const startGeminiChat = async (l: Lesson, isResuming: boolean) => {
    if (chatRef.current) return;
    setIsLoading(true);
    setLoadingText("El profesor está escribiendo...");
    try {
      const chat = await getGeminiChat(l, studentUsername, l.chatHistory);
      chatRef.current = chat;
      if (!isResuming) {
        const response = await chat.sendMessage({ message: `Iniciamos Micro-tema 1.` });
        setMessages([{ role: 'model', parts: [{ text: response.text || '' }], timestamp: new Date().toISOString() }]);
      } else {
        const lastMsg = l.chatHistory?.[l.chatHistory.length - 1];
        const hadActiveChallenge = lastMsg?.role === 'model' && lastMsg.parts[0].text.includes('[DATA_LOGICA]');

        const message = hadActiveChallenge 
          ? "[RESUMEN_RECONTEXTUALIZACION] Reanuda la clase re-explicando el desafío anterior que quedó pendiente." 
          : `Reanuda sesión. Avance actual: ${validCount} de ${targetInteractions} temas acreditados.`;

        const response = await chat.sendMessage({ message });
        setMessages(prev => [...prev, { role: 'model', parts: [{ text: response.text || '' }], timestamp: new Date().toISOString() }]);
      }
      messagesEndRef.current?.scrollIntoView({ behavior: 'smooth' });
    } catch (err) { console.error(err); } finally { setIsLoading(false); setLoadingText(''); }
  };

  const handleSend = async (manualText?: string) => {
    setIdleSeconds(0);
    if (manualText === "__UNLOCK_QUESTION__") {
      setIsUnlocked(true);
      const lastMsg = messages[messages.length - 1];
      const aiText = lastMsg?.parts[0].text || '';
      const isWritten = aiText.includes('"type": "WRITTEN"') || aiText.includes('"type":"WRITTEN"');

      if (isWritten) {
        setChallengeTimeLeft(120); // Tiempo fijo para preguntas abiertas (análisis profundo)
      } else {
        const dataMatch = aiText.match(/\[DATA_LOGICA\]([\s\S]*?)\[\/DATA_LOGICA\]/);
        let time = 20;
        if (dataMatch) {
          try {
            const json = JSON.parse(dataMatch[1].trim());
            time = calculateWordCountTime(json.question || '', json.options || []);
          } catch (e) {}
        }
        setChallengeTimeLeft(time);
      }
      return;
    }

    const userText = (manualText || input).trim();
    if (!userText || isLoading || isPaused) return;

    setIsUnlocked(false);
    setChallengeTimeLeft(undefined);

    const isButtonChoice = !!manualText && manualText !== "__UNLOCK_QUESTION__" && !manualText.startsWith("[");
    const isResponseToChallenge = isButtonChoice || isWrittenChallenge;

    const lastMsg = messages[messages.length - 1];
    if (lastMsg && lastMsg.role === 'model' && isResponseToChallenge) {
       lastMsg.selectedOption = userText;
    }

    setInput(''); 
    setIsLoading(true);
    setLoadingText(isResponseToChallenge ? "El profesor está analizando tu respuesta..." : "El profesor está escribiendo...");

    const userMsg: ChatMessage = { 
      role: 'user', 
      parts: [{ text: userText }], 
      timestamp: new Date().toISOString(),
      isSilent: isResponseToChallenge 
    };

    setMessages(prev => [...prev, userMsg]);

    try {
      const result = await chatRef.current.sendMessage({ message: userText });
      const aiText = result.text || '';

      const isValid = aiText.includes('[RESPUESTA_VALIDA]');
      const newValidCount = isValid ? validCount + 1 : validCount;
      if (isValid) {
        setValidCount(newValidCount);
        setLastValidationResult('correct');
      } else if (isResponseToChallenge) {
        setLastValidationResult('incorrect');
      }

      const aiMsg: ChatMessage = { role: 'model', parts: [{ text: aiText }], timestamp: new Date().toISOString() };

      setMessages(prev => {
        const finalMsgs = [...prev, aiMsg];
        saveProgress(secondsElapsed, finalMsgs, newValidCount);
        return finalMsgs;
      });

      messagesEndRef.current?.scrollIntoView({ behavior: 'smooth' });

      // DISPARAR EXAMEN AL LOGRAR LA DENSIDAD DEL 70%
      if (newValidCount >= targetInteractions && !isAdminAudit) {
         setIsLessonFinishedLocally(true);
         setTimeout(() => {
           initExam();
         }, 1500);
      }
    } catch (err) { console.error(err); } finally { setIsLoading(false); setLoadingText(''); }
  };

  const initExam = async () => {
    if (isAdminAudit) return;
    setIsGeneratingExam(true);
    setIsLoading(true);
    setLoadingText("Generando el examen final...");
    try {
      const data = await generateExam(lesson?.title || '', messages);
      if (data?.questions?.length > 0) {
        setExamData(data); 
        setShowExam(true); 
        setCurrentQuestionIdx(0); 
        setCorrectAnswersCount(0); 
        setShowQuestionFeedback(false); 
        setIsExamFinished(false);
        const q = data.questions[0];
        setExamTimer(calculateWordCountTime(q.text, q.options));
      }
    } catch (err) { alert("Error al generar examen."); } finally { setIsGeneratingExam(false); setIsLoading(false); setLoadingText(''); }
  };

  const handleCheckAnswer = () => {
    const q = examData.questions[currentQuestionIdx];
    const isCorrect = (currentAnswer === q.correctAnswer);
    setIsLastAnswerCorrect(isCorrect);
    setAiFeedback(q.explanation);
    if (isCorrect) setCorrectAnswersCount(prev => prev + 1);
    setShowQuestionFeedback(true);
    if (examTimerRef.current) clearInterval(examTimerRef.current);
  };

  const handleNextQuestion = () => {
    if (currentQuestionIdx < 9) {
      const nextIdx = currentQuestionIdx + 1;
      const q = examData.questions[nextIdx];
      setShowQuestionFeedback(false);
      setCurrentAnswer('');
      setCurrentQuestionIdx(nextIdx);
      setExamTimer(calculateWordCountTime(q.text, q.options));
    } else {
      finishExam();
    }
  };

  const finishExam = async () => {
    setIsExamFinished(true); 
    setShowExam(false);
    if (lesson) {
      const finalGrade = correctAnswersCount;
      const updated: Lesson = { 
        ...lesson, 
        grade: finalGrade, 
        completed: finalGrade >= 6,
        lesson_status: finalGrade >= 6 ? 'Aprobada' : 'Reprobada'
      };
      await updateLessonInStudent(studentUsername, updated);
      setTimeout(() => onClose(lesson.date, lesson.id), 2000);
    }
  };

  if (!lesson) return null;

  let sendButtonClass = "bg-indigo-600 hover:bg-indigo-700";
  if (lastValidationResult === 'correct') sendButtonClass = "bg-green-600";
  else if (lastValidationResult === 'incorrect') sendButtonClass = "bg-red-600";

  return (
    <div 
      className={`fixed inset-0 bg-white dark:bg-indigo-950 z-[500] flex flex-col font-fredoka overflow-hidden select-none ${isAdminAudit ? 'relative h-full' : ''}`}
      onCopy={(e) => e.preventDefault()}
      onContextMenu={(e) => e.preventDefault()}
    >
      <header className={`${isAdminAudit ? 'bg-slate-700' : 'bg-indigo-600'} p-4 shadow-lg flex justify-between items-center z-[1100] border-b-4 border-white/10 shrink-0`}>
          <div className="flex items-center space-x-4">
            {!isAdminAudit ? (
              <div className="bg-white/20 px-4 py-2 rounded-2xl flex flex-col items-center">
