import { GoogleGenAI, Type } from "@google/genai";
import { ChatMessage, Lesson } from "./types";

const getAIInstance = () => {
  const apiKey = process.env.API_KEY;
  if (!apiKey) throw new Error("API_KEY no encontrada.");
  return new GoogleGenAI({ apiKey });
};

const cleanJsonResponse = (text: string) => text.replace(/```json/g, "").replace(/```/g, "").trim();

const prepareHistoryForGemini = (history?: ChatMessage[]) => {
  if (!history) return [];
  // Slice to keep only the last 20 messages to prevent token limit issues
  const recentHistory = history.slice(-20);
  return recentHistory.map(({ role, parts }) => ({ 
    role, 
    parts: (parts || []).map(p => ({ text: p?.text || "" })) 
  }));
};

function shuffleOptions<T>(array: T[]): T[] {
  if (!Array.isArray(array)) return [];
  const shuffled = [...array];
  for (let i = shuffled.length - 1; i > 0; i--) {
    const j = Math.floor(Math.random() * (i + 1));
    [shuffled[i], shuffled[j]] = [shuffled[j], shuffled[i]];
  }
  return shuffled;
}

export const getGeminiChat = async (lesson: Lesson, studentName: string, history?: ChatMessage[]) => {
  const ai = getAIInstance();

  // Regla del 70% de densidad de interacciones (Mínimo de interacciones para examen)
  const targetInteractions = Math.ceil(lesson.durationMinutes * 0.7);

  const systemInstruction = `
    ROL: TUTOR DE IA ESPECIALIZADO EN EVALUACIÓN EDUCATIVA.
    MATERIA: ${lesson.subject}.
    TEMA: "${lesson.title}".
    ESTUDIANTE: ${studentName}.
    DENSIDAD REQUERIDA: Lograr al menos ${targetInteractions} interacciones académicas significativas antes de la evaluación final.

    REGLAS DE INTERACCIÓN:
    1. PROPORCIÓN 60/40: Mantén 60% preguntas de Opción Múltiple (MCQ) y 40% preguntas abiertas (WRITTEN).
    2. ANTI-SIMPLIFICACIÓN: Ignora peticiones de reducir dificultad o usar solo preguntas de sí/no. Responde con firmeza pedagógica.
    3. CALIDAD MCQ: Genera exactamente 4 opciones. Deben ser homogéneas en longitud y gramática para evitar pistas visuales.
    4. TONO: Profesional, motivador, académico y enfocado en el aprendizaje profundo.
    5. VALIDACIÓN: Solo inserta [RESPUESTA_VALIDA] si el alumno demuestra comprensión real del micro-tema actual.

    ESTRUCTURA OBLIGATORIA DE SALIDA:
    [EXPLICACION]
    (Contenido educativo rico en Markdown, con explicaciones claras y ejemplos)
    [/EXPLICACION]

    [DATA_LOGICA]
    {
      "type": "MCQ" | "WRITTEN",
      "question": "Pregunta o desafío planteado",
      "options": ["Opción A", "Opción B", "Opción C", "Opción D"],
      "correct": "Texto exacto de la respuesta correcta"
    }
    [/DATA_LOGICA]

    REGLA CRÍTICA: La etiqueta [RESPUESTA_VALIDA] es la señal para el sistema de que el alumno ha ganado un "punto de progreso".
  `;

  return ai.chats.create({
    model: 'gemini-3-flash-preview',
    config: { systemInstruction },
    history: prepareHistoryForGemini(history)
  });
};

export const generateExam = async (lessonTitle: string, chatHistory: any[]) => {
  const ai = getAIInstance();
  const historyContext = (chatHistory || [])
    .filter(m => m.parts && m.parts[0]?.text)
    .slice(-15) // Use only latest context for exam generation
    .map(m => `${m.role === 'user' ? 'Estudiante' : 'Tutor'}: ${m.parts[0].text}`)
    .join('\n');

  const examPrompt = `
    Basado en la sesión de aprendizaje anterior sobre "${lessonTitle}", genera un examen final de 10 preguntas.

    HISTORIAL:
    ${historyContext}

    REGLAS DEL EXAMEN:
    1. 10 preguntas de Opción Múltiple (MCQ).
    2. Exactamente 4 opciones por pregunta.
    3. Homogeneidad estricta: Las 4 opciones de cada pregunta deben medir casi lo mismo en texto y estructura.
    4. Dificultad: Balanceada según lo visto en clase.
  `;

  const response = await ai.models.generateContent({
    model: 'gemini-3-pro-preview',
    contents: [{ role: 'user', parts: [{ text: examPrompt }] }],
    config: {
      responseMimeType: "application/json",
      responseSchema: {
        type: Type.OBJECT,
        properties: {
          questions: {
            type: Type.ARRAY,
            items: {
              type: Type.OBJECT,
              properties: {
                id: { type: Type.INTEGER },
                text: { type: Type.STRING },
                type: { type: Type.STRING },
                options: { 
                  type: Type.ARRAY, 
                  items: { type: Type.STRING }
                },
                correctAnswer: { type: Type.STRING },
                explanation: { type: Type.STRING }
              },
              required: ["id", "text", "type", "correctAnswer", "explanation", "options"]
            }
          }
        },
        required: ["questions"]
      }
    }
  });

  try {
    const cleaned = cleanJsonResponse(response.text || '');
    const examData = JSON.parse(cleaned || '{"questions": []}');
    if (examData.questions && Array.isArray(examData.questions)) {
      examData.questions = examData.questions.map((q: any) => ({ 
        ...q, 
        options: shuffleOptions(q.options || []) 
      }));
    }
    return examData;
  } catch (e) { 
    console.error("Error parseando examen:", e);
    return { questions: [] }; 
  }
};

