-- 1. ESTRUCTURA DE LECCIONES (ASEGURAR COLUMNAS)
ALTER TABLE IF EXISTS lessons 
ADD COLUMN IF NOT EXISTS lesson_status TEXT DEFAULT 'Pendiente' 
CHECK (lesson_status IN ('Pendiente', 'En Progreso', 'Aprobada', 'Reprobada'));

ALTER TABLE IF EXISTS lessons 
ADD COLUMN IF NOT EXISTS valid_interactions_count INTEGER DEFAULT 0;

ALTER TABLE IF EXISTS lessons 
ADD COLUMN IF NOT EXISTS credits_transfered BOOLEAN DEFAULT FALSE;

-- 2. TABLAS DE BANCA CENTRAL (CUENTAS Y MOVIMIENTOS)
CREATE TABLE IF NOT EXISTS accounts (
    owner_id TEXT PRIMARY KEY,
    balance INTEGER DEFAULT 0,
    updated_at TIMESTAMPTZ DEFAULT NOW()
);

CREATE TABLE IF NOT EXISTS transactions (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    from_account TEXT NOT NULL,
    to_account TEXT NOT NULL,
    amount INTEGER NOT NULL,
    concept TEXT NOT NULL,
    created_at TIMESTAMPTZ DEFAULT NOW()
);

CREATE TABLE IF NOT EXISTS paid_lessons (
    transaction_id BIGINT REFERENCES transactions(id) ON DELETE CASCADE,
    lesson_id BIGINT REFERENCES lessons(id) ON DELETE CASCADE,
    PRIMARY KEY (transaction_id, lesson_id)
);

-- 3. POLÍTICAS DE SEGURIDAD (RLS) - REPARACIÓN PARA ERROR 406/401
ALTER TABLE accounts ENABLE ROW LEVEL SECURITY;
ALTER TABLE transactions ENABLE ROW LEVEL SECURITY;
ALTER TABLE paid_lessons ENABLE ROW LEVEL SECURITY;

-- Forzar acceso público total (Lectura/Escritura) para agilizar despliegue sin autenticación JWT compleja
DROP POLICY IF EXISTS "Public Access Accounts" ON accounts;
CREATE POLICY "Public Access Accounts" ON accounts FOR ALL USING (true) WITH CHECK (true);

DROP POLICY IF EXISTS "Public Access Transactions" ON transactions;
CREATE POLICY "Public Access Transactions" ON transactions FOR ALL USING (true) WITH CHECK (true);

DROP POLICY IF EXISTS "Public Access Paid Lessons" ON paid_lessons;
CREATE POLICY "Public Access Paid Lessons" ON paid_lessons FOR ALL USING (true) WITH CHECK (true);

-- Permisos explícitos a roles anónimos y autenticados
GRANT ALL ON TABLE accounts TO anon, authenticated, service_role;
GRANT ALL ON TABLE transactions TO anon, authenticated, service_role;
GRANT ALL ON TABLE paid_lessons TO anon, authenticated, service_role;

-- 4. FUNCIÓN RPC: transfer_credits_v2
CREATE OR REPLACE FUNCTION transfer_credits_v2(
    student_name TEXT,
    admin_name TEXT,
    transfer_amount INT,
    transfer_concept TEXT,
    lesson_ids BIGINT[]
) RETURNS VOID AS $$
DECLARE
    new_transaction_id BIGINT;
    l_id BIGINT;
BEGIN
    IF transfer_amount <= 0 THEN RAISE EXCEPTION 'El monto debe ser mayor a cero.'; END IF;
    IF array_length(lesson_ids, 1) IS NULL THEN RAISE EXCEPTION 'No hay lecciones.'; END IF;

    INSERT INTO transactions (from_account, to_account, amount, concept)
    VALUES (admin_name, student_name, transfer_amount, transfer_concept)
    RETURNING id INTO new_transaction_id;

    INSERT INTO accounts (owner_id, balance, updated_at)
    VALUES (student_name, transfer_amount, NOW())
    ON CONFLICT (owner_id) DO UPDATE 
    SET balance = accounts.balance + EXCLUDED.balance, updated_at = NOW();

    INSERT INTO accounts (owner_id, balance, updated_at)
    VALUES (admin_name, -transfer_amount, NOW())
    ON CONFLICT (owner_id) DO UPDATE 
    SET balance = accounts.balance + EXCLUDED.balance, updated_at = NOW();

    FOREACH l_id IN ARRAY lesson_ids
    LOOP
        UPDATE lessons SET credits_transfered = TRUE WHERE id = l_id;
        INSERT INTO paid_lessons (transaction_id, lesson_id) VALUES (new_transaction_id, l_id);
    END LOOP;
END;
$$ LANGUAGE plpgsql;

GRANT EXECUTE ON FUNCTION transfer_credits_v2 TO anon, authenticated, service_role;

