    await supabase.from('lessons').update({ lesson_status: 'Aprobada', completed: true }).eq('student_username', username).gte('grade', 6);
    await supabase.from('lessons').update({ lesson_status: 'Reprobada', completed: false }).eq('student_username', username).gt('grade', 0).lt('grade', 6);
    await supabase.from('lessons').update({ lesson_status: 'En Progreso' }).eq('student_username', username).or('grade.is.null,grade.eq.0').gt('valid_interactions_count', 0);
  } catch (err) {
    console.error("Error en auto-actualización de estatus:", err);
  }
};

// --- CUENTAS Y SALDOS ---

/**
 * Obtiene el saldo de la cuenta del usuario.
 * Se utiliza .select().limit(1) para evitar el Error 406 (Not Acceptable).
 * Este error suele ocurrir porque .maybeSingle() o .single() solicitan 
 * application/vnd.pgrst.object+json, lo cual es bloqueado por algunos proxies.
 */
export const getAccountBalance = async (username: string): Promise<number> => {
  try {
    const { data, error, status, statusText } = await supabase
        .from('accounts')
        .select('balance')
        .eq('owner_id', username)
        .limit(1);

    if (error) {
        console.error(`[Storage] Error ${status} (${statusText}) al obtener balance para ${username}:`, error.message);
        return 0;
    }

    // Al usar .select(), la respuesta es un array
    if (data && data.length > 0) {
      return data[0].balance;
    }

    return 0;
  } catch (err) {
    console.error("[Storage] Error crítico en getAccountBalance:", err);
    return 0;
  }
};

export const getTransactions = async (username: string): Promise<Transaction[]> => {
  const { data, error } = await supabase
    .from('transactions')
    .select('*')
    .or(`from_account.eq.${username},to_account.eq.${username}`)
    .order('created_at', { ascending: false });
  return error ? [] : (data || []);
};

export const getAllTransactions = async (): Promise<Transaction[]> => {
  const { data, error } = await supabase
    .from('transactions')
    .select('*')
    .order('created_at', { ascending: false });
  return error ? [] : (data || []);
};

export const executeCreditTransfer = async (studentUsername: string, amount: number, concept: string, lessonIds: string[]) => {
  const numericIds = lessonIds.map(id => parseInt(id, 10)).filter(id => !isNaN(id));
  if (numericIds.length === 0) throw new Error("No hay lecciones válidas.");
  const cleanAmount = Math.floor(amount);
  const { error } = await supabase.rpc('transfer_credits_v2', {
    student_name: studentUsername,
    admin_name: 'Admin',
    transfer_amount: cleanAmount,
    transfer_concept: concept,
    lesson_ids: numericIds
  });
  if (error) throw new Error(error.message);
};

