export const getStudentData = async (username: string): Promise<StudentData | null> => {
  const { data, error } = await supabase.from('lessons').select('*').eq('student_username', username);
  if (error) return null;
  const mappedLessons: Lesson[] = (data || []).map(row => {
    const rawLesson: Lesson = {
      id: row.id.toString(),
      subject: row.subject,
      title: row.topic,
      durationMinutes: row.duration_minutes,
      completed: row.completed,
      date: row.date,
      elapsedSeconds: row.elapsed_seconds || 0,
      validInteractionsCount: row.valid_interactions_count || 0,
      grade: row.grade,
      learningPrompt: row.learning_prompt,
      chatHistory: row.chat_history || [],
      credits_transfered: row.credits_transfered,
      lesson_status: row.lesson_status
    };
    return { ...rawLesson, lesson_status: calculateLessonStatus(rawLesson) };
  });
  return { username, lessons: mappedLessons };
};

export const deleteLessonFromStudent = async (lessonId: string) => {
  const idToUse = /^\d+$/.test(lessonId) ? parseInt(lessonId, 10) : lessonId;
  const { error } = await supabase.from('lessons').delete().eq('id', idToUse);
  if (error) throw error;
};

export const clearLessonChatHistory = async (lessonId: string) => {
  const idToUse = /^\d+$/.test(lessonId) ? parseInt(lessonId, 10) : lessonId;
  const { error } = await supabase
    .from('lessons')
    .update({
      chat_history: [],
      elapsed_seconds: 0,
      valid_interactions_count: 0,
      grade: null,
      completed: false,
      lesson_status: 'Pendiente'
    }).eq('id', idToUse);
  if (error) throw error;
};

export const addLessonToStudent = async (username: string, lesson: Lesson) => {
  await supabase.from('lessons').insert([{
    student_username: username,
    subject: lesson.subject,
    topic: lesson.title,
    duration_minutes: lesson.durationMinutes,
    completed: false,
    date: lesson.date,
    elapsed_seconds: 0,
    valid_interactions_count: 0,
    learning_prompt: lesson.learningPrompt || null,
    chat_history: [],
    lesson_status: 'Pendiente'
  }]);
};

export const updateLessonInStudent = async (username: string, updatedLesson: Lesson) => {
  const idToUse = /^\d+$/.test(updatedLesson.id) ? parseInt(updatedLesson.id, 10) : updatedLesson.id;
  const status = calculateLessonStatus(updatedLesson);
  const { error } = await supabase.from('lessons').update({
    subject: updatedLesson.subject,
    topic: updatedLesson.title,
    duration_minutes: updatedLesson.durationMinutes,
    completed: (status === 'Aprobada' || status === 'Completada'),
    date: updatedLesson.date,
    actual_duration_minutes: updatedLesson.actualDurationMinutes,
    elapsed_seconds: updatedLesson.elapsedSeconds,
    valid_interactions_count: updatedLesson.validInteractionsCount,
    grade: updatedLesson.grade,
    learning_prompt: updatedLesson.learningPrompt,
    chat_history: updatedLesson.chatHistory,
    credits_transfered: updatedLesson.credits_transfered,
    lesson_status: status
  }).eq('id', idToUse);
  if (error) throw error;
};

export const deleteLessonsBySubjectAndDays = async (username: string, subject: string, days: boolean[], startDate: string) => {
  const { data, error } = await supabase.from('lessons').select('id, date').eq('student_username', username).eq('subject', subject).gte('date', startDate);
  if (error || !data) return;
  const idsToDelete = data.filter(row => {
    const d = new Date(row.date + 'T12:00:00');
    return days[(d.getDay() + 6) % 7];
  }).map(row => row.id);
  if (idsToDelete.length > 0) await supabase.from('lessons').delete().in('id', idsToDelete);
};

export const updateLessonsPromptByCriteria = async (username: string, subject: string, days: boolean[], startDate: string, prompt: string) => {
  const { data, error } = await supabase.from('lessons').select('id, date').eq('student_username', username).eq('subject', subject).gte('date', startDate);
  if (error || !data) return;
  const idsToUpdate = data.filter(row => {
    const d = new Date(row.date + 'T12:00:00');
    return days[(d.getDay() + 6) % 7];
  }).map(row => row.id);
  if (idsToUpdate.length > 0) await supabase.from('lessons').update({ learning_prompt: prompt }).in('id', idsToUpdate);
};

import React, { useState, useEffect, useRef } from 'react';
import { User, Role } from './types';
import { initStorage, autoUpdateLessonStatuses, updateUser, updateUserSession, getAccountBalance } from './storage2';
import { supabase } from './supabaseClient';
import Login from './components/Login';
import AdminDashboard from './components/AdminDashboard';
import StudentDashboard from './components/StudentDashboard';
import LessonWindow from './components/LessonWindow2';

const App: React.FC = () => {
  const [currentUser, setCurrentUser] = useState<User | null>(null);
  const [activeLesson, setActiveLesson] = useState<{ studentUsername: string; lessonId: string } | null>(null);
  const [isInitializing, setIsInitializing] = useState(true);
  const [darkMode, setDarkMode] = useState(() => localStorage.getItem('theme') === 'dark');
  const [totalBalance, setTotalBalance] = useState(0);

  const [tabSessionId] = useState(() => Math.random().toString(36).substring(2, 15) + Math.random().toString(36).substring(2, 15));
  const [showDuplicateModal, setShowDuplicateModal] = useState(false);
  const sessionSubscriptionRef = useRef<any>(null);

  const [showPasswordModal, setShowPasswordModal] = useState(false);
  const [currentPass, setCurrentPass] = useState('');
  const [newPass, setNewPass] = useState('');
  const [confirmPass, setConfirmPass] = useState('');
  const [passError, setPassError] = useState('');
  const [isUpdatingPass, setIsUpdatingPass] = useState(false);

  // Estados para retorno post-lección
  const [lastFinishedLessonId, setLastFinishedLessonId] = useState<string | null>(null);
  const [lastFinishedDate, setLastFinishedDate] = useState<string | null>(null);

  const fetchUserBalance = async (username: string) => {
    try {
      const balance = await getAccountBalance(username);
      setTotalBalance(balance);
    } catch (err) {
      console.error("Error al obtener balance:", err);
    }
  };

  const setupSessionListener = (username: string) => {
    if (sessionSubscriptionRef.current) {
      supabase.removeChannel(sessionSubscriptionRef.current);
    }

    const channel = supabase
      .channel(`user-session-${username}`)
      .on(
        'postgres_changes',
        {
          event: 'UPDATE',
          schema: 'public',
          table: 'users',
          filter: `username=eq.${username}`
        },
        (payload) => {
          const remoteSessionId = payload.new.current_session_id;
          if (remoteSessionId && remoteSessionId !== tabSessionId) {
            setShowDuplicateModal(true);
          }
        }
      )
      .subscribe();

    sessionSubscriptionRef.current = channel;
  };

  useEffect(() => {
    const loadApp = async () => {
      console.log("Buensoft Education: Aplicación actualizada y lista.");
      await initStorage();
      const storedUser = localStorage.getItem('current_user');
      if (storedUser) {
        const user = JSON.parse(storedUser);
        setCurrentUser(user);
        if (user.role === Role.STUDENT) {
          await autoUpdateLessonStatuses(user.username);
          fetchUserBalance(user.username);
          setupSessionListener(user.username);
          updateUserSession(user.username, tabSessionId);
        }
      }
      setIsInitializing(false);
    };
    loadApp();

    return () => {
      if (sessionSubscriptionRef.current) {
        supabase.removeChannel(sessionSubscriptionRef.current);
      }
    };
  }, []);

  useEffect(() => {
    if (darkMode) {
      document.documentElement.classList.add('dark');
      localStorage.setItem('theme', 'dark');
    } else {
      document.documentElement.classList.remove('dark');
      localStorage.setItem('theme', 'light');
    }
  }, [darkMode]);

  const handleLogin = async (user: User) => {
    setCurrentUser(user);
    localStorage.setItem('current_user', JSON.stringify(user));
    if (user.role === Role.STUDENT) {
      await autoUpdateLessonStatuses(user.username);
      fetchUserBalance(user.username);
      setupSessionListener(user.username);
      await updateUserSession(user.username, tabSessionId);
    }
  };

  const handleLogout = () => {
    if (currentUser) {
      updateUserSession(currentUser.username, null).catch(console.error);
    }
    setCurrentUser(null);
    setTotalBalance(0);
    setShowDuplicateModal(false);
    localStorage.removeItem('current_user');
    if (sessionSubscriptionRef.current) {
      supabase.removeChannel(sessionSubscriptionRef.current);
    }
  };

  const handleResumeHere = async () => {
    if (currentUser) {
      await updateUserSession(currentUser.username, tabSessionId);
      setShowDuplicateModal(false);
    }
  };

  const startLesson = (studentUsername: string, lessonId: string) => {
    setLastFinishedLessonId(null);
    setLastFinishedDate(null);
    setActiveLesson({ studentUsername, lessonId });
  };

  const handleUpdatePassword = async (e: React.FormEvent) => {
    e.preventDefault();
    setPassError('');
    if (!currentUser) return;

    if (currentPass !== currentUser.password) {
      setPassError('La contraseña actual es incorrecta.');
      return;
    }
    if (newPass.length < 4 || newPass.length > 8) {
      setPassError('La nueva contraseña debe tener entre 4 y 8 caracteres.');
      return;
    }
    if (newPass !== confirmPass) {
      setPassError('Las contraseñas nuevas no coinciden.');
      return;
    }

    setIsUpdatingPass(true);
    try {
      const updatedUser: User = { ...currentUser, password: newPass };
      await updateUser(currentUser.username, updatedUser);
      setCurrentUser(updatedUser);
      localStorage.setItem('current_user', JSON.stringify(updatedUser));
      alert('¡Contraseña actualizada con éxito!');
      setShowPasswordModal(false);
      setCurrentPass('');
      setNewPass('');
      setConfirmPass('');
    } catch (err) {
      setPassError('Error al actualizar. Intenta más tarde.');
    } finally {
      setIsUpdatingPass(false);
    }
  };

  if (isInitializing) {
    return (
      <div className="min-h-screen flex flex-col items-center justify-center bg-sky-50 dark:bg-indigo-950 transition-colors duration-500">
        <div className="w-16 h-16 border-4 border-indigo-600 border-t-transparent rounded-full animate-spin mb-4"></div>
        <p className="text-indigo-900 dark:text-sky-100 font-bold animate-pulse text-xl">Buensoft Education se está despertando...</p>
      </div>
    );
  }

  if (activeLesson) {
    return <LessonWindow 
      studentUsername={activeLesson.studentUsername} 
      lessonId={activeLesson.lessonId} 
      onClose={(finishedDate, finishedId) => {
        setActiveLesson(null);
        if (finishedDate) setLastFinishedDate(finishedDate);
        if (finishedId) setLastFinishedLessonId(finishedId);

        if (currentUser && currentUser.role === Role.STUDENT) {
          fetchUserBalance(currentUser.username);
        }
      }} 
    />;
  }

  if (!currentUser) {
    return (
      <div className={darkMode ? 'dark' : ''}>
        <Login onLogin={handleLogin} />
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-sky-50 dark:bg-indigo-950 transition-colors duration-300">
      <nav className="bg-white dark:bg-indigo-900 shadow-md p-4 flex justify-between items-center sticky top-0 z-[100] border-b dark:border-indigo-800 transition-colors duration-300">
        <div className="flex items-center space-x-3">
          <img src="https://buensoft.com/assets/Buensoft_Education_Logo.png" alt="Buensoft Education Logo" className="w-12 h-12 md:w-14 md:h-14 object-contain rounded-xl" />
          <h1 className="text-xl md:text-2xl font-black text-indigo-900 dark:text-white uppercase tracking-tight hidden sm:block">Buensoft Education</h1>
        </div>

        <div className="flex items-center space-x-2 sm:space-x-4 md:space-x-6">
          <div className="flex flex-col items-end">
            <span className="text-indigo-600 dark:text-indigo-200 font-bold text-sm leading-none">Hola, {currentUser.username}</span>
            <button 
              onClick={() => setShowPasswordModal(true)}
              className="text-[9px] font-bold text-indigo-400 dark:text-indigo-400 hover:text-indigo-600 dark:hover:text-white uppercase tracking-tighter underline mt-1"
            >
              Seguridad 🔐
            </button>
          </div>

          {currentUser.role === Role.STUDENT && (
            <div className="flex flex-col items-center px-3 py-1 bg-amber-50 dark:bg-amber-900/20 rounded-2xl border-2 border-amber-100 dark:border-amber-800 shadow-inner">
              <span className="text-[8px] font-black text-amber-600 dark:text-amber-400 uppercase tracking-tighter">SALDO BANCARIO</span>
              <span className="text-base font-black text-amber-500 leading-none">MXN ${totalBalance.toLocaleString()}</span>
            </div>
          )}

          <button 
            onClick={() => setDarkMode(!darkMode)}
            className="flex items-center justify-center w-9 h-9 sm:w-10 sm:h-10 rounded-xl bg-indigo-50 dark:bg-indigo-800 text-indigo-600 dark:text-amber-400 hover:scale-110 active:scale-95 transition-all shadow-sm"
          >
            {darkMode ? '☀️' : '🌙'}
          </button>

          <button 
            onClick={handleLogout}
            className="bg-red-500 hover:bg-red-600 text-white px-3 sm:px-4 py-2 rounded-full transition-all text-xs font-black shadow-lg shadow-red-100 dark:shadow-none hover:scale-105"
          >
            SALIR
          </button>
        </div>
      </nav>

      <main className="container mx-auto px-4 py-8">
        {currentUser.role === Role.ADMIN ? (
          <AdminDashboard user={currentUser} />
        ) : (
          <StudentDashboard 
            user={currentUser} 
            onStartLesson={startLesson} 
            onBalanceUpdate={() => fetchUserBalance(currentUser.username)}
            initialSelectedDate={lastFinishedDate}
            lastFinishedLessonId={lastFinishedLessonId}
          />
        )}
      </main>

      {showDuplicateModal && (
        <div className="fixed inset-0 bg-indigo-900/90 backdrop-blur-md z-[1000] flex items-center justify-center p-4">
          <div className="bg-white dark:bg-indigo-900 p-10 md:p-14 rounded-[3.5rem] w-full max-w-lg shadow-2xl border-8 border-indigo-50 dark:border-indigo-800 text-center animate-in zoom-in duration-300">
            <div className="text-8xl mb-8">🚫</div>
            <h2 className="text-3xl font-black text-indigo-900 dark:text-white mb-6 uppercase tracking-tight leading-tight">Acceso Duplicado Detectado</h2>
            <p className="text-indigo-500 dark:text-indigo-300 font-bold mb-10 text-lg leading-relaxed">
              Parece que has iniciado sesión en otro dispositivo o pestaña. Por seguridad, solo permitimos una sesión activa por cuenta.
            </p>
            <div className="flex flex-col space-y-4">
              <button 
                onClick={handleResumeHere}
                className="w-full bg-indigo-600 text-white font-black py-5 rounded-2xl shadow-xl uppercase tracking-widest hover:bg-indigo-700 transition-all transform active:scale-95"
              >
                Cerrar otras y continuar aquí 🚀
              </button>
              <button 
                onClick={handleLogout}
                className="w-full bg-white dark:bg-indigo-950 text-indigo-400 font-black py-5 rounded-2xl border-4 border-indigo-50 dark:border-indigo-800 uppercase tracking-widest hover:text-red-500 transition-all"
              >
                Cerrar sesión actual 👋
              </button>
            </div>
          </div>
        </div>
      )}

      {showPasswordModal && (
        <div className="fixed inset-0 bg-indigo-900/60 backdrop-blur-sm z-[250] flex items-center justify-center p-4">
          <div className="bg-white dark:bg-indigo-900 p-8 rounded-[3rem] w-full max-md shadow-2xl border-8 border-indigo-50 dark:border-indigo-800">
            <h2 className="text-3xl font-black text-indigo-900 dark:text-white mb-6 uppercase">Seguridad 🔐</h2>
            <form onSubmit={handleUpdatePassword} className="space-y-4">
              <div>
                <label className="block text-[10px] font-black text-indigo-400 dark:text-indigo-500 uppercase tracking-widest mb-1 ml-2">Contraseña Actual</label>
                <input 
                  type="password" 
                  value={currentPass} 
                  onChange={e=>setCurrentPass(e.target.value)} 
                  className="w-full p-4 bg-indigo-50 dark:bg-indigo-950 rounded-2xl font-bold border-2 border-transparent dark:text-white focus:border-indigo-200 dark:focus:border-indigo-700 outline-none transition-all" 
                  required 
                />
              </div>
              <div className="grid grid-cols-2 gap-3">
                <div>
                  <label className="block text-[10px] font-black text-indigo-400 dark:text-indigo-500 uppercase tracking-widest mb-1 ml-2">Nueva (4-8 dig)</label>
                  <input 
                    type="password" 
                    value={newPass} 
                    onChange={e=>setNewPass(e.target.value)} 
                    className="w-full p-4 bg-indigo-50 dark:bg-indigo-950 rounded-2xl font-bold border-2 border-transparent dark:text-white focus:border-indigo-200 dark:focus:border-indigo-700 outline-none transition-all" 
                    required 
                  />
                </div>
                <div>
                  <label className="block text-[10px] font-black text-indigo-400 dark:text-indigo-500 uppercase tracking-widest mb-1 ml-2">Confirmar</label>
                  <input 
                    type="password" 
                    value={confirmPass} 
                    onChange={e=>setConfirmPass(e.target.value)} 
                    className="w-full p-4 bg-indigo-50 dark:bg-indigo-950 rounded-2xl font-bold border-2 border-transparent dark:text-white focus:border-indigo-200 dark:focus:border-indigo-700 outline-none transition-all" 
                    required 
                  />
                </div>
              </div>
              {passError && <p className="text-red-500 text-[10px] font-bold text-center bg-red-50 dark:bg-red-900/20 p-2 rounded-xl border border-red-100 dark:border-red-900/30">{passError}</p>}
              <div className="flex space-x-3 pt-4">
                <button type="button" onClick={()=>{setShowPasswordModal(false); setPassError('');}} className="flex-1 font-black text-indigo-400 dark:text-indigo-500 uppercase text-xs">CANCELAR</button>
                <button type="submit" disabled={isUpdatingPass} className="flex-1 bg-indigo-600 text-white font-black py-4 rounded-2xl shadow-lg uppercase text-xs hover:bg-indigo-700 transition-all transform active:scale-95 disabled:opacity-50">{isUpdatingPass ? 'GUARDANDO...' : 'ACTUALIZAR'}</button>
              </div>
            </form>
          </div>
        </div>
      )}
    </div>
  );
};

