        <p className="text-indigo-900 dark:text-sky-100 font-bold animate-pulse text-xl">Buensoft Education se está preparando...</p>
      </div>
    );
  }

  if (activeLesson) {
    return (
      <LessonWindow 
        studentUsername={activeLesson.studentUsername} 
        lessonId={activeLesson.lessonId} 
        onClose={(finishedDate, finishedId) => {
          setActiveLesson(null);
          if (finishedDate) setLastFinishedDate(finishedDate);
          if (finishedId) setLastFinishedLessonId(finishedId);
          if (currentUser && currentUser.role === Role.STUDENT) {
            fetchUserBalance(currentUser.username);
          }
        }} 
      />
    );
  }

  if (!currentUser) {
    return <Login onLogin={handleLogin} />;
  }

  return (
    <div className="min-h-screen bg-sky-50 dark:bg-indigo-950 transition-colors duration-300">
      <nav className="bg-white/80 dark:bg-indigo-900/80 backdrop-blur-md shadow-md p-4 flex justify-between items-center sticky top-0 z-[100] border-b dark:border-indigo-800 transition-colors duration-300">
        <div className="flex items-center space-x-3">
          <img src="https://buensoft.com/assets/Buensoft_Education_Logo.png" alt="Logo" className="w-10 h-10 md:w-12 md:h-12 object-contain rounded-lg shadow-sm" />
          <h1 className="text-lg md:text-xl font-black text-indigo-900 dark:text-white uppercase tracking-tight hidden sm:block">Buensoft Education</h1>
        </div>

        <div className="flex items-center space-x-2 sm:space-x-4">
          <div className="flex flex-col items-end">
            <span className="text-indigo-600 dark:text-indigo-200 font-bold text-xs">Hola, {currentUser.username}</span>
            <button 
              onClick={() => setShowPasswordModal(true)}
              className="text-[9px] font-black text-indigo-400 dark:text-indigo-500 hover:text-indigo-600 uppercase tracking-tighter underline flex items-center space-x-1"
            >
              <Shield size={8} /> <span>Seguridad</span>
            </button>
          </div>

          {currentUser.role === Role.STUDENT && (
            <div className="flex flex-col items-center px-4 py-1.5 bg-amber-50 dark:bg-amber-900/20 rounded-2xl border-2 border-amber-100 dark:border-amber-800 shadow-inner">
              <span className="text-[8px] font-black text-amber-600 dark:text-amber-400 uppercase flex items-center space-x-1">
                <Wallet size={8} /> <span>MI BANCO</span>
              </span>
              <span className="text-sm font-black text-amber-500 leading-none">MXN ${totalBalance.toLocaleString()}</span>
            </div>
          )}

          <button 
            onClick={() => setDarkMode(!darkMode)}
            className="flex items-center justify-center w-9 h-9 rounded-xl bg-indigo-50 dark:bg-indigo-800 text-indigo-600 dark:text-amber-400 hover:scale-105 active:scale-95 transition-all shadow-sm"
          >
            {darkMode ? <Sun size={18} /> : <Moon size={18} />}
          </button>

          <button 
            onClick={handleLogout}
            className="bg-red-500 hover:bg-red-600 text-white p-2.5 rounded-xl transition-all shadow-lg hover:scale-105 active:scale-95 flex items-center"
          >
            <LogOut size={18} />
          </button>
        </div>
      </nav>

      <main className="container mx-auto px-4 py-8 max-w-7xl">
        {currentUser.role === Role.ADMIN ? (
          <AdminDashboard user={currentUser} />
        ) : (
          <StudentDashboard 
            user={currentUser} 
            onStartLesson={startLesson} 
            onBalanceUpdate={() => fetchUserBalance(currentUser.username)}
            initialSelectedDate={lastFinishedDate}
            lastFinishedLessonId={lastFinishedLessonId}
          />
        )}
      </main>

      {/* Duplicate Session Modal */}
      {showDuplicateModal && (
        <div className="fixed inset-0 bg-indigo-900/90 backdrop-blur-md z-[1000] flex items-center justify-center p-4">
          <div className="bg-white dark:bg-indigo-900 p-10 rounded-[3rem] w-full max-w-lg shadow-2xl border-8 border-indigo-50 dark:border-indigo-800 text-center animate-in zoom-in duration-300">
            <div className="text-7xl mb-8">🚫</div>
            <h2 className="text-2xl font-black text-indigo-900 dark:text-white mb-4 uppercase">Sesión Duplicada</h2>
            <p className="text-indigo-400 dark:text-indigo-300 font-bold mb-8 text-sm">
              Se ha detectado otra sesión activa. Por seguridad, solo se permite una pestaña abierta.
            </p>
            <div className="flex flex-col space-y-3">
              <button 
                onClick={handleResumeHere}
                className="w-full bg-indigo-600 text-white font-black py-4 rounded-2xl shadow-xl uppercase text-xs hover:bg-indigo-700 transition-all"
              >
                Retomar aquí 🚀
              </button>
              <button 
                onClick={handleLogout}
                className="w-full bg-slate-100 dark:bg-indigo-950 text-indigo-400 font-black py-4 rounded-2xl uppercase text-xs transition-all"
              >
                Cerrar sesión 👋
              </button>
            </div>
          </div>
        </div>
      )}

      {/* Password Modal */}
      {showPasswordModal && (
        <div className="fixed inset-0 bg-indigo-900/60 backdrop-blur-sm z-[250] flex items-center justify-center p-4">
          <div className="bg-white dark:bg-indigo-900 p-8 rounded-[2.5rem] w-full max-w-sm shadow-2xl border-8 border-indigo-50 dark:border-indigo-800">
            <h2 className="text-2xl font-black text-indigo-900 dark:text-white mb-6 uppercase flex items-center space-x-2">
              <Shield className="text-indigo-600" /> <span>Seguridad</span>
