                  required 
                />
              </div>
              <div>
                <label className="block text-[10px] font-black text-indigo-400 dark:text-indigo-500 uppercase tracking-widest mb-1.5 ml-2">Nueva Contraseña (4-8 dígitos)</label>
                <input 
                  type="password" 
                  value={newPass} 
                  onChange={e=>setNewPass(e.target.value)} 
                  className="w-full p-4 bg-indigo-50 dark:bg-indigo-950 rounded-2xl font-bold border-2 border-transparent dark:text-white focus:border-indigo-500 outline-none transition-all" 
                  required 
                />
              </div>
              <div>
                <label className="block text-[10px] font-black text-indigo-400 dark:text-indigo-500 uppercase tracking-widest mb-1.5 ml-2">Confirmar Nueva</label>
                <input 
                  type="password" 
                  value={confirmPass} 
                  onChange={e=>setConfirmPass(e.target.value)} 
                  className="w-full p-4 bg-indigo-50 dark:bg-indigo-950 rounded-2xl font-bold border-2 border-transparent dark:text-white focus:border-indigo-500 outline-none transition-all" 
