import { GoogleGenAI, Type } from "@google/genai";
import { ChatMessage, Lesson } from "./types";

const getAIInstance = () => {
  const apiKey = process.env.API_KEY;
  if (!apiKey) throw new Error("API_KEY no encontrada.");
  return new GoogleGenAI({ apiKey });
};

const cleanJsonResponse = (text: string) => text.replace(/```json/g, "").replace(/```/g, "").trim();

const prepareHistoryForGemini = (history?: ChatMessage[]) => {
  if (!history) return [];
  const recentHistory = history.slice(-20);
  return recentHistory.map(({ role, parts }) => ({ 
    role, 
    parts: (parts || []).map(p => ({ text: p?.text || "" })) 
  }));
};

function shuffleOptions<T>(array: T[]): T[] {
  if (!Array.isArray(array)) return [];
  const shuffled = [...array];
  for (let i = shuffled.length - 1; i > 0; i--) {
    const j = Math.floor(Math.random() * (i + 1));
    [shuffled[i], shuffled[j]] = [shuffled[j], shuffled[i]];
  }
  return shuffled;
}

export const getGeminiChat = async (lesson: Lesson, studentName: string, history?: ChatMessage[]) => {
  const ai = getAIInstance();
  const targetInteractions = Math.ceil(lesson.durationMinutes * 0.7);

  const systemInstruction = `
    ROL: TUTOR DE IA ESPECIALIZADO EN EVALUACIÓN EDUCATIVA QUE ENSEÑA DE MANERA DIVERTIDA LA LECCION MENCIONANDO EL NOMBRE DEL ESTUDIANTE.
    MATERIA: ${lesson.subject}.
    TEMA: "${lesson.title}".
    ESTUDIANTE: ${studentName}.
    DENSIDAD REQUERIDA: ${targetInteractions} interacciones.

    REGLAS DE REANUDACIÓN DE SESIÓN (CRÍTICO):
    1. Si el estudiante retoma una lección (reanudación), IGNORE el historial previo para efectos de corrección, crítica, plagio o relevancia.
    2. No comentes sobre errores pasados ni menciones "como dijiste anteriormente". El historial es solo contexto de avance.
    3. PROTOCOLO DE BIENVENIDA: Inicia con un saludo cordial de bienvenida por regresar a la clase.
    4. CONTINUIDAD PROSPECTIVA: Identifica qué temas se cubrieron y procede INMEDIATAMENTE al siguiente microtema o concepto pendiente. No analices mensajes antiguos del historial.

    REGLAS DE RELEVANCIA Y PERSISTENCIA (EXTREMAS - SOLO PARA NUEVOS MENSAJES):
    1. VALIDACIÓN SEMÁNTICA: Evalúa si la respuesta del estudiante está directamente relacionada con la pregunta formulada actualmente.
    2. PROHIBICIÓN DE DESVÍO: Ignora cualquier intento de cambiar de tema, bromear o romper la lógica.
    3. BUCLE DE PREGUNTA: Si la respuesta es IRRELEVANTE, responde ÚNICAMENTE con la etiqueta [IRRELEVANTE] y repite la pregunta anterior INTEGRAMENTE.
    4. RECHAZO DE PLAGIO: Si detectas texto de otra IA en el NUEVO mensaje, responde [PLAGIO_IA].

    REGLAS DE INTERACCIÓN:
    1. PROPORCIÓN 60/40: Mantén 60% preguntas MCQ y 40% preguntas WRITTEN.
    2. RESPUESTA VÁLIDA: Inserta [RESPUESTA_VALIDA] solo si el alumno demuestra comprensión real y relevante.
    3. RESPUESTA INCORRECTA: Si el alumno responde algo relacionado pero erróneo, inserta [RESPUESTA_INCORRECTA].

    ESTRUCTURA DE SALIDA:
    [EXPLICACION] (Contenido educativo) [/EXPLICACION]
    [DATA_LOGICA] { "type": "MCQ" | "WRITTEN", "question": "...", "options": [...], "correct": "..." } [/DATA_LOGICA]
  `;

  return ai.chats.create({
    model: 'gemini-3-flash-preview',
    config: { systemInstruction },
    history: prepareHistoryForGemini(history)
  });
};

export const generateExam = async (lessonTitle: string, chatHistory: any[]) => {
  const ai = getAIInstance();
  const historyContext = (chatHistory || [])
    .filter(m => m.parts && m.parts[0]?.text)
    .slice(-15)
    .map(m => `${m.role === 'user' ? 'Estudiante' : 'Tutor'}: ${m.parts[0].text}`)
    .join('\n');

  const examPrompt = `Genera un examen final de 10 preguntas MCQ sobre "${lessonTitle}" basado en: ${historyContext}. 4 opciones por pregunta.`;

  const response = await ai.models.generateContent({
    model: 'gemini-3-pro-preview',
    contents: [{ role: 'user', parts: [{ text: examPrompt }] }],
    config: {
      responseMimeType: "application/json",
      responseSchema: {
        type: Type.OBJECT,
        properties: {
          questions: {
            type: Type.ARRAY,
            items: {
              type: Type.OBJECT,
              properties: {
                id: { type: Type.INTEGER },
                text: { type: Type.STRING },
                type: { type: Type.STRING },
                options: { type: Type.ARRAY, items: { type: Type.STRING } },
                correctAnswer: { type: Type.STRING },
                explanation: { type: Type.STRING }
              },
              required: ["id", "text", "type", "correctAnswer", "explanation", "options"]
            }
          }
        },
        required: ["questions"]
      }
    }
  });

  try {
    const cleaned = cleanJsonResponse(response.text || '');
    const examData = JSON.parse(cleaned || '{"questions": []}');
    if (examData.questions) {
      examData.questions = examData.questions.map((q: any) => ({ ...q, options: shuffleOptions(q.options || []) }));
    }
    return examData;
  } catch (e) { return { questions: [] }; }
};

import { useState, useEffect, useRef, useMemo, useCallback, memo } from 'react';
import { Lesson, ChatMessage } from '../types';
