const MarkdownComponents = {
  img: ({node, ...props}: any) => <ImageWithFallback src={props.src} alt={props.alt} />,
  a: ({node, ...props}: any) => <SafeLink {...props} />
};

interface ParsedAIResponse {
  explanation: string;
  challengeType?: 'MCQ' | 'WRITTEN';
  question?: {
    text: string;
    options?: string[];
    correct?: string;
  };
  errorInfo?: string;
  refuerzo?: string;
  isPlagio?: boolean;
  isIrrelevant?: boolean;
}

interface RichMessageProps {
  message: ChatMessage;
  onAction: (val: string) => void;
  timeLeft?: number;
  isUnlocked?: boolean;
  isAudit?: boolean;
  studentInitial?: string;
  isLessonFinished?: boolean;
  isParentLoading?: boolean;
  isHistory?: boolean;
}

const RichMessage: React.FC<RichMessageProps> = memo(({ message, onAction, timeLeft, isUnlocked = false, isAudit, studentInitial, isLessonFinished, isParentLoading, isHistory }) => {
  const [selectedOption, setSelectedOption] = useState<string | null>(message.selectedOption || null);
  const text = message.parts[0].text;
  const isUser = message.role === 'user';

  const parseResponse = (raw: string): ParsedAIResponse => {
    const isPlagio = raw.includes('[PLAGIO_IA]');
    const isIrrelevant = raw.includes('[IRRELEVANTE]');
    const dataMatch = raw.match(/\[DATA_LOGICA\]([\s\S]*?)\[\/DATA_LOGICA\]/);
    const expMatch = raw.match(/\[EXPLICACION\]([\s\S]*?)\[\/EXPLICACION\]/);
    const errorMatch = raw.match(/\[ERROR_INFO\]([\s\S]*?)(?=\[REFUERZO\]|\[EXPLICACION\]|$)/);
    const refuerzoMatch = raw.match(/\[REFUERZO\]([\s\S]*?)(?=\[EXPLICACION\]|$)/);

    let explanation = expMatch ? expMatch[1].trim() : raw;

    explanation = explanation
      .replace(/\[DATA_LOGICA\][\s\S]*?\[\/DATA_LOGICA\]/g, '')
      .replace(/\[DATA_LOGICA\][\s\S]*/g, '')
      .replace(/\[EXPLICACION\]|\[\/EXPLICACION\]|\[RESPUESTA_VALIDA\]|\[RESPUESTA_INCORRECTA\]|\[PLAGIO_IA\]|\[IRRELEVANTE\]|\[REFUERZO\]|\[ERROR_INFO\]/g, '')
      .replace(/\{[\s\S]*"type"[\s\S]*\}/g, '')
      .trim();

    let questionData;
    let challengeType;

    if (dataMatch) {
      try {
        const json = JSON.parse(dataMatch[1].trim());
        challengeType = json.type;
        questionData = { text: json.question, options: json.options, correct: json.correct };
      } catch (e) { console.error("Fuga de datos evitada:", e); }
    }

    return { explanation, challengeType, question: questionData, errorInfo: errorMatch ? errorMatch[1].trim() : undefined, refuerzo: refuerzoMatch ? refuerzoMatch[1].trim() : undefined, isPlagio, isIrrelevant };
  };

  const handleOptionClick = (opt: string) => {
    if (selectedOption || message.selectedOption || isAudit || isHistory || timeLeft === 0 || isParentLoading) return;
    setSelectedOption(opt);
    setTimeout(() => onAction(opt), 800);
  };

  if (isUser) {
    return (
      <div className="flex items-start space-x-3 justify-end w-full">
        <div className="bg-indigo-600 text-white p-5 rounded-[2.5rem] shadow-sm border-2 border-indigo-700 max-w-full w-fit ml-auto">
          <div className="prose dark:prose-invert max-w-none text-lg font-bold">{text}</div>
        </div>
        <div className="w-10 h-10 rounded-full bg-white dark:bg-indigo-800 border-2 border-indigo-200 dark:border-indigo-700 flex items-center justify-center text-indigo-600 dark:text-indigo-200 font-black shrink-0 shadow-sm">{studentInitial}</div>
      </div>
    );
  }

  const parsed = parseResponse(text);
  const activeSelection = selectedOption || message.selectedOption;
  const isExpired = timeLeft === 0 && !activeSelection;

  const showQuestionBlock = parsed.question && (isUnlocked || activeSelection || isAudit || message.is_unlocked);

  return (
    <div className={`flex items-start space-x-3 w-full animate-in fade-in slide-in-from-left-4 duration-500 ${isAudit || isHistory ? 'opacity-90' : ''}`}>
      <div className="w-10 h-10 rounded-2xl bg-indigo-50 dark:bg-indigo-800 border-2 border-indigo-100 dark:border-indigo-700 flex items-center justify-center text-xl shrink-0 shadow-sm">🤖</div>
      <div className={`p-6 rounded-[2.5rem] shadow-sm border-2 flex-1 w-full max-w-full ${parsed.isPlagio ? 'bg-red-50 border-red-500 text-red-900 dark:bg-red-900/20 dark:text-red-100' : 'bg-white dark:bg-indigo-900 text-indigo-900 dark:text-indigo-100 border-indigo-50 dark:border-indigo-800'}`}>
        <div className="flex flex-col space-y-4">
          {parsed.isPlagio && <p className="text-[10px] font-black uppercase tracking-widest text-red-600 dark:text-red-400">⚠️ ALERTA DE PLAGIO</p>}
          {parsed.isIrrelevant && <p className="text-[10px] font-black uppercase tracking-widest text-amber-600 dark:text-amber-400">⚠️ RESPUESTA FUERA DE TEMA</p>}

          <div className="pregunta-contenedor prose dark:prose-invert max-w-none text-lg">
            <ReactMarkdown remarkPlugins={[remarkGfm]} rehypePlugins={[rehypeRaw]} components={MarkdownComponents}>{parsed.refuerzo || parsed.explanation}</ReactMarkdown>

            {!isUnlocked && !activeSelection && !isAudit && !isHistory && parsed.question && !isLessonFinished && !parsed.isPlagio && (
              <div className="mt-6 animate-in fade-in duration-700">
                <button 
                  onClick={() => onAction("__UNLOCK_QUESTION__")} 
                  disabled={isParentLoading}
                  className="bg-indigo-600 text-white border-2 border-indigo-500 px-6 py-4 rounded-2xl font-black text-sm hover:bg-indigo-700 shadow-xl transition-all active:scale-95 flex items-center space-x-3 disabled:opacity-50 uppercase tracking-widest"
                >
                  <span>Ya leí y comprendí</span><span className="text-xl">🎯</span>
                </button>
              </div>
            )}

            {showQuestionBlock && !isLessonFinished && (
              <div className="animate-in zoom-in-95 duration-300 pt-6 border-t-4 border-indigo-50 dark:border-indigo-800/50 mt-6">
                <p className="texto-pregunta text-xl font-black text-indigo-900 dark:text-indigo-100 mb-6 leading-tight">{parsed.question.text}</p>

                {message.studentResponse && (
                  <div className="respuesta-feedback bg-indigo-50 dark:bg-indigo-950/50 p-5 rounded-[2rem] border-2 border-indigo-100 dark:border-indigo-800/50 mb-6 animate-in slide-in-from-top-2 duration-300">
                    <p className="respuesta-estudiante text-sm font-bold text-indigo-700 dark:text-indigo-300 italic mb-3">Tu respuesta: "{message.studentResponse}"</p>
                    <div className={`w-full py-2.5 rounded-xl text-[10px] font-black uppercase tracking-widest shadow-sm flex items-center justify-center space-x-2 ${message.validationStatus === 'correct' ? 'bg-emerald-500 text-white' : 'bg-red-600 text-white'}`}>
                      <span className="font-black">{message.validationStatus === 'correct' ? '✓ CORRECTO' : '✕ INCORRECTO'}</span>
                    </div>
                  </div>
                )}

                {parsed.challengeType === 'MCQ' && (
                  <div className="grid gap-3">
                    {Array.isArray(parsed.question.options) && parsed.question.options.map((opt, idx) => {
                      const isSelected = activeSelection === opt;
                      const isCorrect = opt === parsed.question?.correct;

                      let btnClass = "bg-white dark:bg-indigo-950 text-indigo-600 dark:text-indigo-200 border-indigo-100 dark:border-indigo-800 hover:bg-indigo-50";

                      if (activeSelection) {
                        // REGLA: Si ya tenemos estatus de validación final (historial o tutor respondió), aplicamos VERDE/ROJO
                        if (message.validationStatus) {
                          if (isCorrect) {
                            btnClass = "bg-green-600 border-green-700 text-white";
                          } else if (isSelected) {
                            btnClass = "bg-red-600 border-red-700 text-white";
                          } else {
                            btnClass = "bg-slate-50 dark:bg-indigo-900 border-indigo-50 dark:border-indigo-800 opacity-40 text-indigo-300";
                          }
                        } else {
                          // REGLA: Fase de espera de calificación (thinking phase) -> Resaltado exclusivo en AZUL
                          if (isSelected) {
                            btnClass = "bg-indigo-600 border-indigo-700 text-white shadow-lg scale-[1.02]";
                          } else {
                            btnClass = "bg-slate-50 dark:bg-indigo-900 border-indigo-50 dark:border-indigo-800 opacity-60 text-indigo-300";
                          }
                        }
                      } else if (isExpired || isAudit || isParentLoading || isHistory) {
                        btnClass = "bg-slate-200 dark:bg-indigo-950 border-slate-300 dark:border-indigo-900 opacity-50 text-slate-400 cursor-not-allowed";
                      } else if (!isAudit && !isHistory) {
                        btnClass = "bg-indigo-600 border-indigo-500 hover:bg-indigo-700 text-white";
                      }

                      return <button key={idx} onClick={() => handleOptionClick(opt)} disabled={!!activeSelection || isAudit || isHistory || isExpired || isParentLoading} className={`w-full text-left px-6 py-5 rounded-[1.5rem] font-black text-lg shadow-md transition-all active:scale-95 border-2 ${btnClass}`}>{opt}</button>;
                    })}
                  </div>
                )}
              </div>
            )}
          </div>
        </div>
      </div>
    </div>
  );
});

const LessonWindow: React.FC<LessonWindowProps> = ({ studentUsername, lessonId, onClose, isAdminAudit: forcedAudit = false }) => {
  const [lesson, setLesson] = useState<Lesson | null>(null);
  const [messages, setMessages] = useState<ChatMessage[]>([]);
  const [input, setInput] = useState('');
  const [isLoading, setIsLoading] = useState(false);
  const [loadingText, setLoadingText] = useState('');
  const [isGeneratingExam, setIsGeneratingExam] = useState(false);
  const [secondsElapsed, setSecondsElapsed] = useState(0);
  const [isPaused, setIsPaused] = useState(false);
  const [idleSeconds, setIdleSeconds] = useState(0);
  const [validCount, setValidCount] = useState(0);
  const [targetInteractions, setTargetInteractions] = useState(30);
  const [isLessonFinishedLocally, setIsLessonFinishedLocally] = useState(false);
  const [challengeTimeLeft, setChallengeTimeLeft] = useState<number | undefined>(undefined);
  const [isUnlocked, setIsUnlocked] = useState(false);
  const [isWrittenChallenge, setIsWrittenChallenge] = useState(false);
  const [historyCount, setHistoryCount] = useState(0);

  const [showExam, setShowExam] = useState(false);
  const [examData, setExamData] = useState<any>(null);
  const [currentQuestionIdx, setCurrentQuestionIdx] = useState(0);
  const [currentAnswer, setCurrentAnswer] = useState('');
  const [showQuestionFeedback, setShowQuestionFeedback] = useState(false);
  const [isLastAnswerCorrect, setIsLastAnswerCorrect] = useState(false);
  const [aiFeedback, setAiFeedback] = useState('');
  const [isExamFinished, setIsExamFinished] = useState(false);
  const [correctAnswersCount, setCorrectAnswersCount] = useState(0);
  const [examTimer, setExamTimer] = useState(0);

  const chatRef = useRef<any>(null);
  const messagesEndRef = useRef<HTMLDivElement>(null);
  const lastSavedTimeRef = useRef<number>(0);
  const messagesRef = useRef<ChatMessage[]>([]);
  const challengeTimerRef = useRef<number | null>(null);
  const examTimerRef = useRef<number | null>(null);

  const isAdminAudit = forcedAudit || (lesson?.credits_transfered === true);

  useEffect(() => { messagesRef.current = messages; }, [messages]);

  useEffect(() => {
    const lastMsg = messages[messages.length - 1];
    if (lastMsg && lastMsg.role === 'model') {
      const isWritten = lastMsg.parts[0].text.includes('"type": "WRITTEN"') || lastMsg.parts[0].text.includes('"type":"WRITTEN"');
      setIsWrittenChallenge(isWritten);
      setIsUnlocked(!!lastMsg.is_unlocked);
    } else { 
      setIsWrittenChallenge(false); 
      setIsUnlocked(false);
    }
  }, [messages]);

  useEffect(() => {
    if (!isAdminAudit && isUnlocked && challengeTimeLeft !== undefined) {
      challengeTimerRef.current = window.setInterval(() => {
        setChallengeTimeLeft(prev => {
          if (prev !== undefined && prev <= 1) { handleTimeout(); return 0; }
          return prev !== undefined ? prev - 1 : 0;
        });
      }, 1000);
    } else { if (challengeTimerRef.current) clearInterval(challengeTimerRef.current); }
    return () => { if (challengeTimerRef.current) clearInterval(challengeTimerRef.current); };
  }, [isUnlocked, challengeTimeLeft, isAdminAudit]);

  useEffect(() => {
    if (showExam && !showQuestionFeedback && examTimer > 0) {
      examTimerRef.current = window.setInterval(() => {
        setExamTimer(prev => {
          if (prev <= 1) { handleCheckAnswer(); return 0; }
          return prev - 1;
        });
      }, 1000);
    } else { if (examTimerRef.current) clearInterval(examTimerRef.current); }
    return () => { if (examTimerRef.current) clearInterval(examTimerRef.current); };
  }, [showExam, showQuestionFeedback, examTimer]);

  const handleTimeout = async () => {
    setIsUnlocked(false);
    setChallengeTimeLeft(0);
    try {
      const result = await chatRef.current.sendMessage({ message: "[TIEMPO_AGOTADO] No logré responder el desafío a tiempo." });
      setMessages(prev => [...prev, { role: 'model', parts: [{ text: result.text || '' }], timestamp: new Date().toISOString() }]);
    } catch (e) { console.error(e); }
  };

  useEffect(() => {
    const fetchLesson = async () => {
      const data = await getStudentData(studentUsername);
      if (data) {
        const found = data.lessons.find(l => l.id === lessonId);
        if (found) {
          setLesson(found);
          setSecondsElapsed(found.elapsedSeconds || 0);
          setValidCount(found.validInteractionsCount || 0);
          setTargetInteractions(Math.ceil(found.durationMinutes * 0.7));
          lastSavedTimeRef.current = found.elapsedSeconds || 0;
          if (found.chatHistory?.length) {
            setMessages(found.chatHistory);
            setHistoryCount(found.chatHistory.length);
          }
          if (!isAdminAudit) startGeminiChat(found, (found.chatHistory?.length || 0) > 0);
        }
      }
    };
    fetchLesson();
  }, [studentUsername, lessonId, isAdminAudit]);

  const saveProgress = async (time: number, currentMessages: ChatMessage[], currentValidCount: number) => {
    if (!lesson || isAdminAudit) return;
    try {
      const updated: Lesson = { ...lesson, elapsedSeconds: time, chatHistory: currentMessages, validInteractionsCount: currentValidCount };
      await updateLessonInStudent(studentUsername, updated);
      lastSavedTimeRef.current = time;
    } catch (err) { console.error(err); }
  };

  const handleDirectExit = async () => {
    if (isAdminAudit) { onClose(); return; }
    setIsLoading(true);
    await saveProgress(secondsElapsed, messagesRef.current, validCount);
    onClose(lesson?.date, lesson?.id);
  };

  useEffect(() => {
    if (isAdminAudit) return;
    const timer = setInterval(() => {
      if (!isPaused && !showExam && !isExamFinished && !isGeneratingExam) {
        setSecondsElapsed(prev => prev + 1);
        if (secondsElapsed - lastSavedTimeRef.current >= 60) saveProgress(secondsElapsed, messagesRef.current, validCount);
        if (!isLoading) setIdleSeconds(prev => {
          if (prev + 1 >= 180) { setIsPaused(true); return 0; }
          return prev + 1;
        });
      }
    }, 1000);
    return () => clearInterval(timer);
  }, [isPaused, showExam, isExamFinished, isLoading, isGeneratingExam, secondsElapsed, validCount, isAdminAudit]);

  const startGeminiChat = async (l: Lesson, isResuming: boolean) => {
    if (chatRef.current) return;
    setIsLoading(true);
    setLoadingText("El profesor está escribiendo...");
    try {
      const chat = await getGeminiChat(l, studentUsername, l.chatHistory);
      chatRef.current = chat;
      if (!isResuming) {
        const response = await chat.sendMessage({ message: `Iniciamos Micro-tema 1.` });
        setMessages([{ role: 'model', parts: [{ text: response.text || '' }], timestamp: new Date().toISOString(), is_unlocked: false }]);
      } else {
        const response = await chat.sendMessage({ message: `Retomando la lección. He avanzado ${validCount} de ${targetInteractions} interacciones. Por favor, salúdame y continuemos con el siguiente tema pendiente.` });
        setMessages(prev => [...prev, { role: 'model', parts: [{ text: response.text || '' }], timestamp: new Date().toISOString(), is_unlocked: false }]);
      }
      messagesEndRef.current?.scrollIntoView({ behavior: 'smooth' });
    } catch (err) { console.error(err); } finally { setIsLoading(false); setLoadingText(''); }
  };

  const handleSend = async (manualText?: string) => {
    setIdleSeconds(0);

    if (manualText === "__UNLOCK_QUESTION__") {
      setIsUnlocked(true);
      const lastMsgIdx = messages.length - 1;
      const lastMsg = messages[lastMsgIdx];

      if (lastMsg && lastMsg.role === 'model') {
        const newMessages = [...messages];
        newMessages[lastMsgIdx] = { ...lastMsg, is_unlocked: true };
        setMessages(newMessages);
        saveProgress(secondsElapsed, newMessages, validCount);

        const text = lastMsg.parts[0].text;
        const dataMatch = text.match(/\[DATA_LOGICA\]([\s\S]*?)\[\/DATA_LOGICA\]/);
        const countWords = (s: string) => (s || "").trim().split(/\s+/).filter(w => w.length > 0).length;

        if (dataMatch) {
          try {
            const json = JSON.parse(dataMatch[1].trim());
            const qWords = countWords(json.question);
            if (json.type === 'WRITTEN') {
              setChallengeTimeLeft(qWords * 1 + 80);
            } else {
              const options = Array.isArray(json.options) ? json.options.slice(0, 3) : [];
              const optWords = options.reduce((acc: number, opt: string) => acc + countWords(opt), 0);
              setChallengeTimeLeft((qWords + optWords) * 1 + 20);
            }
          } catch (e) {
            setChallengeTimeLeft(isWrittenChallenge ? 120 : 60);
          }
        } else {
          setChallengeTimeLeft(isWrittenChallenge ? 120 : 60);
        }
      }
      return; 
    }

    const userText = (manualText || input).trim();
    if (!userText || isLoading || isPaused) return;

    setIsUnlocked(false);
    setChallengeTimeLeft(undefined);

    const isResponseToChallenge = !!manualText && manualText !== "__UNLOCK_QUESTION__" && !manualText.startsWith("[") || isWrittenChallenge;

    setInput(''); 
    setIsLoading(true);
    setLoadingText("El profesor está escribiendo...");

    const userMsg: ChatMessage = { 
      role: 'user', 
      parts: [{ text: userText }], 
      timestamp: new Date().toISOString(), 
      isSilent: isResponseToChallenge 
    };
    setMessages(prev => [...prev, userMsg]);

    try {
      const result = await chatRef.current.sendMessage({ message: userText });
      const aiText = result.text || '';

      const isIrrelevant = aiText.includes('[IRRELEVANTE]');
      const isPlagio = aiText.includes('[PLAGIO_IA]');
      const isCorrect = aiText.includes('[RESPUESTA_VALIDA]');
      const isIncorrect = aiText.includes('[RESPUESTA_INCORRECTA]');

      let newValidCount = validCount;
      if (isCorrect) {
        newValidCount = validCount + 1;
      } else if (isPlagio) {
        newValidCount = Math.max(0, validCount - 1);
      }

      setValidCount(newValidCount);

      const aiMsg: ChatMessage = { 
        role: 'model', 
        parts: [{ text: aiText }], 
        timestamp: new Date().toISOString(),
        is_unlocked: false
      };

      setMessages(prev => {
        const msgs = [...prev];
        if (isResponseToChallenge && !isIrrelevant) {
          const lastModelMsgIdx = msgs.slice(0, -1).reduce((acc, curr, idx) => curr.role === 'model' ? idx : acc, -1);
          if (lastModelMsgIdx !== -1) {
            msgs[lastModelMsgIdx] = {
              ...msgs[lastModelMsgIdx],
              studentResponse: userText,
              validationStatus: isCorrect ? 'correct' : 'incorrect',
              selectedOption: manualText,
              is_unlocked: true
            };
          }
        }

        const finalMsgs = [...msgs, aiMsg];
        saveProgress(secondsElapsed, finalMsgs, newValidCount);
        return finalMsgs;
      });

      messagesEndRef.current?.scrollIntoView({ behavior: 'smooth' });

      if (newValidCount >= targetInteractions && !isAdminAudit) {
         setIsLessonFinishedLocally(true);
         setTimeout(() => initExam(), 1500);
      }
    } catch (err) { 
      console.error(err); 
    } finally { 
      setIsLoading(false); 
      setLoadingText(''); 
    }
  };

  const initExam = async () => {
    if (isAdminAudit) return;
    setIsGeneratingExam(true);
    setIsLoading(true);
    setLoadingText("Generando el examen final...");
    try {
      const data = await generateExam(lesson?.title || '', messages);
      if (data?.questions?.length > 0) {
        setExamData(data); setShowExam(true); setCurrentQuestionIdx(0); setCorrectAnswersCount(0); setShowQuestionFeedback(false); setIsExamFinished(false);
        setExamTimer(45);
      }
    } catch (err) { alert("Error al generar examen."); } finally { setIsGeneratingExam(false); setIsLoading(false); setLoadingText(''); }
  };

  const handleCheckAnswer = () => {
    const q = examData.questions[currentQuestionIdx];
    const isCorrect = (currentAnswer === q.correctAnswer);
    setIsLastAnswerCorrect(isCorrect);
    setAiFeedback(q.explanation);
    if (isCorrect) setCorrectAnswersCount(prev => prev + 1);
    setShowQuestionFeedback(true);
    if (examTimerRef.current) clearInterval(examTimerRef.current);
  };

  const handleNextQuestion = () => {
    if (currentQuestionIdx < 9) {
      setCurrentQuestionIdx(prev => prev + 1);
      setShowQuestionFeedback(false);
      setCurrentAnswer('');
      setExamTimer(45);
    } else { finishExam(); }
  };

  const finishExam = async () => {
    setIsExamFinished(true); setShowExam(false);
    if (lesson) {
      const finalGrade = correctAnswersCount;
      const updated: Lesson = { ...lesson, grade: finalGrade, completed: finalGrade >= 6, lesson_status: finalGrade >= 6 ? 'Aprobada' : 'Reprobada' };
      await updateLessonInStudent(studentUsername, updated);
      setTimeout(() => onClose(lesson.date, lesson.id), 2000);
    }
  };

  if (!lesson) return null;

  const lastMsg = messages[messages.length - 1];
  const lastMsgText = lastMsg?.parts[0]?.text || '';
  const lastMsgHasChallenge = lastMsgText.includes('[DATA_LOGICA]');

  return (
    <div className={`fixed inset-0 bg-white dark:bg-indigo-950 z-[500] flex flex-col font-fredoka overflow-hidden select-none ${isAdminAudit ? 'relative h-full' : ''}`} onCopy={e => e.preventDefault()} onContextMenu={e => e.preventDefault()}>
      <header className={`${isAdminAudit ? 'bg-slate-700' : 'bg-indigo-600'} p-4 shadow-lg flex justify-between items-center z-[1100] border-b-4 border-white/10 shrink-0`}>
          <div className="flex items-center space-x-4">
            {!isAdminAudit && (
              <div className="bg-white/20 px-4 py-2 rounded-2xl flex flex-col items-center">
                <span className="text-xl font-black font-mono text-white">{Math.floor(secondsElapsed / 60)}:{String(secondsElapsed % 60).padStart(2, '0')}</span>
                <button onClick={() => setIsPaused(!isPaused)} className="text-[8px] font-black uppercase tracking-tighter mt-1 bg-white text-indigo-600 px-2 rounded">{isPaused ? 'REANUDAR' : 'PAUSAR'}</button>
              </div>
            )}
            <div className="text-white">
              <h2 className="text-sm font-black uppercase truncate max-w-[200px]">{isAdminAudit ? `AUDITORÍA: ${lesson.title}` : lesson.title}</h2>
              <p className="text-[9px] font-bold opacity-70 uppercase tracking-widest">{isAdminAudit ? 'Finalizada' : `Meta: ${validCount} / ${targetInteractions}`}</p>
            </div>
          </div>
          <button handleDirectExit={handleDirectExit} className="w-10 h-10 rounded-full bg-white/10 hover:bg-red-500 transition-all flex items-center justify-center font-black text-white">✕</button>
      </header>

      <div className="flex-1 relative flex overflow-hidden">
        <div className={`flex-1 flex flex-col bg-sky-50 dark:bg-indigo-950 ${(showExam || isExamFinished || isPaused || isGeneratingExam) ? 'opacity-20 pointer-events-none transition-opacity duration-500' : ''}`}>
          <div className="flex-1 overflow-y-auto px-[4%] py-10 space-y-10 custom-scrollbar">
            {messages.filter(m => !m.isSilent).map((m, i, arr) => {
              const isMsgFromHistory = i < historyCount;
              const isLastMsg = i === arr.length - 1;

              return (
                <RichMessage 
                  key={i} 
                  message={m}
                  onAction={handleSend} 
                  timeLeft={!isAdminAudit && !isMsgFromHistory && isLastMsg && m.role === 'model' ? challengeTimeLeft : undefined} 
                  isUnlocked={isMsgFromHistory ? (m.is_unlocked || !!m.selectedOption || !!m.studentResponse) : isUnlocked} 
                  isAudit={isAdminAudit} 
                  isHistory={isMsgFromHistory && !isLastMsg}
                  studentInitial={studentUsername.charAt(0).toUpperCase()} 
                  isLessonFinished={isLessonFinishedLocally} 
                  isParentLoading={isLoading}
                />
              );
            })}
            {isLoading && loadingText && !isGeneratingExam && (
              <div className="flex justify-start w-full px-[4%]"><div className="flex items-start space-x-3 bg-white/60 p-4 rounded-2xl border-2 border-indigo-50"><p className="text-xs font-black animate-pulse">{loadingText}</p></div></div>
            )}
            <div ref={messagesEndRef} />
          </div>

          {!isAdminAudit && (
            <div className="p-6 bg-white dark:bg-indigo-900 border-t-4 border-indigo-50">
              <div className="w-full px-[4%] mx-auto flex items-center space-x-3">
                <textarea 
                  value={input} 
                  onChange={(e) => setInput(e.target.value)} 
                  onPaste={(e) => e.preventDefault()}
                  onKeyDown={(e) => e.key === 'Enter' && !e.shiftKey && (e.preventDefault(), handleSend())} 
                  className="flex-1 px-6 py-4 rounded-3xl border-4 border-indigo-50 dark:border-indigo-800 bg-white dark:bg-indigo-950 font-bold resize-none h-16 shadow-inner text-lg" 
                  placeholder={isLoading ? "El profesor está escribiendo..." : isWrittenChallenge ? "Escribe tu respuesta con tus palabras..." : lastMsgHasChallenge ? "Espera un desafío..." : "Escribe tu mensaje..."}
                  disabled={isLoading || isPaused || isLessonFinishedLocally || (lastMsg?.role === 'model' && lastMsgHasChallenge && !isUnlocked) || (isUnlocked && !isWrittenChallenge && lastMsgHasChallenge)} 
                />
                <button onClick={() => handleSend()} disabled={(lastMsgHasChallenge && !isWrittenChallenge) || isLessonFinishedLocally || isLoading} className="bg-indigo-600 text-white px-8 h-16 rounded-3xl text-xl shadow-xl transition-all disabled:opacity-30">➔</button>
              </div>
            </div>
          )}
        </div>

        {isGeneratingExam && (
          <div className="absolute inset-0 bg-white/60 backdrop-blur-sm z-[900] flex items-center justify-center p-6 animate-in fade-in zoom-in duration-300">
            <div className="bg-white p-12 rounded-[3.5rem] border-[6px] border-emerald-400 shadow-2xl text-center max-w-xl flex flex-col items-center">
              <h2 className="text-3xl md:text-4xl font-black text-emerald-600 mb-4 flex items-center space-x-3 uppercase tracking-tight">
                <span>LECCIÓN COMPLETADA</span> <span>🏆</span>
              </h2>
              <p className="text-indigo-600 dark:text-indigo-400 font-bold text-lg animate-pulse tracking-tight">
                El profesor está preparando el examen para acreditar la lección...
              </p>
            </div>
          </div>
        )}

        {showExam && !isAdminAudit && (
          <div className="absolute inset-0 bg-indigo-900/90 flex items-center justify-center p-4 z-[800] backdrop-blur-sm" onCopy={e => e.preventDefault()} onContextMenu={e => e.preventDefault()}>
            <div className="bg-white w-full max-w-2xl rounded-[3rem] p-10 border-8 border-indigo-50 shadow-2xl overflow-y-auto max-h-[95vh] flex flex-col">
              {!showQuestionFeedback ? (
                <>
                  <div className="flex justify-between items-center mb-8">
                    <div className="bg-indigo-100 text-indigo-600 px-4 py-2 rounded-2xl font-black text-[10px] uppercase tracking-widest">PREGUNTA {currentQuestionIdx + 1} DE 10</div>
                    <div className={`w-12 h-12 rounded-full border-4 flex items-center justify-center font-black text-sm ${examTimer < 10 ? 'border-red-500 text-red-500' : 'border-indigo-600 text-indigo-600'}`}>{examTimer}s</div>
                  </div>
                  <h3 className="text-2xl font-black text-indigo-900 text-center mb-10 leading-tight">{examData?.questions?.[currentQuestionIdx]?.text || ""}</h3>
                  <div className="grid gap-3">
                    {Array.isArray(examData?.questions?.[currentQuestionIdx]?.options) && examData.questions[currentQuestionIdx].options.map((opt: string) => (
                      <button key={opt} onClick={() => setCurrentAnswer(opt)} className={`p-5 rounded-3xl text-left font-bold border-4 transition-all ${currentAnswer === opt ? 'bg-indigo-600 text-white border-indigo-600 shadow-lg scale-[1.02]' : 'bg-white border-indigo-50 hover:border-indigo-400'}`}>{opt}</button>
                    ))}
                  </div>
                  <button onClick={() => handleCheckAnswer()} disabled={!currentAnswer} className="mt-10 w-full bg-indigo-600 text-white font-black py-5 rounded-[2rem] text-xl shadow-xl disabled:opacity-40 uppercase">ENVIAR</button>
                </>
              ) : (
                <div className="text-center py-6 flex flex-col items-center">
                  <div className={`text-5xl font-black mb-8 uppercase ${isLastAnswerCorrect ? 'text-green-600' : 'text-red-500'}`}>{isLastAnswerCorrect ? '¡CORRECTO!' : '¡UPS!'}</div>
                  <div className="bg-indigo-50 p-8 rounded-[2.5rem] border-4 border-indigo-100 mb-10 w-full"><p className="text-lg font-bold italic text-indigo-900 leading-relaxed">{aiFeedback}</p></div>
                  <button onClick={handleNextQuestion} className="w-full bg-indigo-600 text-white font-black py-5 rounded-[2rem] shadow-xl text-xl uppercase">SIGUIENTE</button>
                </div>
              )}
            </div>
          </div>
        )}
      </div>
      <style>{`.custom-scrollbar::-webkit-scrollbar { width: 4px; } .custom-scrollbar::-webkit-scrollbar-thumb { background: rgba(79, 70, 229, 0.2); border-radius: 10px; }`}</style>
    </div>
  );
};

export default LessonWindow;

import { useState, useEffect, useRef, useMemo, useCallback, memo } from 'react';
import { Lesson, ChatMessage } from '../types';
import { getStudentData, updateLessonInStudent } from '../storage2';
import { getGeminiChat, generateExam } from '../geminiService2';
// @ignore
import ReactMarkdown from 'react-markdown';
// @ignore
import remarkGfm from 'remark-gfm';
// @ignore
import rehypeRaw from 'rehype-raw';

interface LessonWindowProps {
  studentUsername: string;
  lessonId: string;
  onClose: (finishedDate?: string, finishedId?: string) => void;
  isAdminAudit?: boolean;
}

