/**
 * Obtiene el saldo de la cuenta del usuario de forma robusta.
 */
export const getAccountBalance = async (username: string): Promise<number> => {
  try {
    const { data, error } = await supabase
        .from('accounts')
        .select('balance')
        .eq('owner_id', username)
        .maybeSingle(); 

    if (error) {
        console.error("Error detallado en balance:", error);
        return 0;
    }
    return data?.balance || 0;
  } catch (err) {
    console.error("Error crítico en getAccountBalance:", err);
    return 0;
  }
};

export const getTransactions = async (username: string): Promise<Transaction[]> => {
  const { data, error } = await supabase
    .from('transactions')
    .select('*')
    .or(`from_account.eq.${username},to_account.eq.${username}`)
    .order('created_at', { ascending: false });
  return error ? [] : (data || []);
};

export const getAllTransactions = async (): Promise<Transaction[]> => {
  const { data, error } = await supabase
    .from('transactions')
    .select('*')
    .order('created_at', { ascending: false });
  return error ? [] : (data || []);
};

/**
 * Ejecuta la transferencia de créditos mediante el RPC 'transferir_creditos_estudiante'.
 */
export const executeCreditTransfer = async (studentUsername: string, amount: number, concept: string, lessonIds: string[]) => {
  const numericIds = lessonIds.map(id => parseInt(id, 10)).filter(id => !isNaN(id));
  if (numericIds.length === 0) throw new Error("No hay lecciones válidas.");

  const cleanAmount = Math.floor(amount);

  // Siguiendo la directiva de invocar el RPC 'transferir_creditos_estudiante'
  const { error } = await supabase.rpc('transferir_creditos_estudiante', {
    p_username: studentUsername,
    p_estudiante_id: studentUsername, // Mapeado a username por arquitectura actual
    p_admin_id: 'Admin',
    p_lecciones_ids: numericIds,
    p_monto_total: cleanAmount,
    p_concept: concept
  });

  if (error) throw new Error(error.message);
};

