CREATE OR REPLACE FUNCTION transferir_creditos_estudiante(
    p_estudiante_id UUID,
    p_admin_id UUID,
    p_lecciones_ids TEXT[],
    p_monto_total NUMERIC,
    p_username TEXT,
    p_concept TEXT -- Añadimos este parámetro para que coincida con tu llamada
) RETURNS VOID AS $$
DECLARE
    v_transaction_id UUID;
    v_auth_user_id UUID;
BEGIN
    -- 1. Seguridad: Validar usuario
    v_auth_user_id := auth.uid();
    IF v_auth_user_id IS DISTINCT FROM p_estudiante_id THEN
        RAISE EXCEPTION 'No autorizado';
    END IF;

    -- 2. Crear transacción usando el concepto enviado desde el front-end
    INSERT INTO public.transactions (from_account, to_account, amount, concept)
    VALUES (p_admin_id::text, p_estudiante_id::text, p_monto_total, p_concept)
    RETURNING id INTO v_transaction_id;

    -- 3. Actualizar balances
    UPDATE public.accounts SET balance = balance - p_monto_total, update_at = now() WHERE owner_id = p_admin_id::text;
    UPDATE public.accounts SET balance = balance + p_monto_total, update_at = now() WHERE owner_id = p_estudiante_id::text;

    -- 4. Registrar lecciones individuales
    INSERT INTO public.paid_lessons (lesson_id, transaction_id, student_username, amount, paid_at)
    SELECT id, v_transaction_id, p_username, (p_monto_total / array_length(p_lecciones_ids, 1)), now()
    FROM unnest(p_lecciones_ids) AS id;

    -- 5. Marcar como transferidas
    UPDATE public.lessons SET credits_transfered = true WHERE id = ANY(p_lecciones_ids);
END;
$$ LANGUAGE plpgsql;

