/**
 * Ejecuta la transferencia de créditos mediante el RPC 'transferir_creditos_estudiante'.
 * Envía p_estudiante_id y p_admin_id como TEXT (strings).
 */
export const executeCreditTransfer = async (studentId: string, studentUsername: string, amount: number, concept: string, lessonIds: string[]) => {
  if (lessonIds.length === 0) throw new Error("No hay lecciones seleccionadas.");

  // Obtenemos el ID del administrador.
  const { data: adminData } = await supabase.from('users').select('id').eq('role', 'ADMIN').limit(1).single();
  const adminId = adminData?.id || 'Admin';

  const cleanAmount = Math.floor(amount);

  // Invocación del RPC con mapeo exacto de parámetros como TEXT
  const { error } = await supabase.rpc('transferir_creditos_estudiante', {
    p_estudiante_id: String(studentId),       // Enviado como TEXT
    p_admin_id: String(adminId),             // Enviado como TEXT
    p_lecciones_ids: lessonIds,              // TEXT[]
    p_monto_total: cleanAmount,              // NUMERIC
    p_username: studentUsername,             // TEXT
    p_concept: concept                       // TEXT
  });

  if (error) throw new Error(error.message);
};

