/**
 * Ejecuta la transferencia de créditos mediante el RPC 'transferir_creditos_estudiante'.
 * Utiliza el UUID fijo del administrador y el UUID del estudiante.
 */
export const executeCreditTransfer = async (studentId: string, studentUsername: string, amount: number, concept: string, lessonIds: string[]) => {
  if (lessonIds.length === 0) throw new Error("No hay lecciones seleccionadas.");

  const cleanAmount = Math.floor(amount);

  // Invocación del RPC con parámetros exactos
  const { error } = await supabase.rpc('transferir_creditos_estudiante', {
    p_estudiante_id: String(studentId),       // UUID del estudiante (Session ID)
    p_admin_id: ADMIN_UUID,                  // UUID fijo del Administrador
    p_lecciones_ids: lessonIds,              // Array de IDs de lecciones
    p_monto_total: cleanAmount,              // Monto en créditos (número)
    p_username: studentUsername,             // Nombre del estudiante (texto)
    p_concept: concept                       // Concepto de la transacción (texto)
  });

  if (error) throw new Error(error.message);
};

