const calculateLessonStatus = (lesson: Partial<Lesson>): 'Pendiente' | 'En Progreso' | 'Aprobada' | 'Reprobada' | 'Completada' => {
  const interactions = lesson.validInteractionsCount || 0;
  const hasMessages = !!(lesson.chatHistory && lesson.chatHistory.length > 0);
  const grade = lesson.grade;
  const currentStatus = lesson.lesson_status;

  if (grade !== undefined && grade !== null && grade >= 6) {
    return (currentStatus === 'Completada') ? 'Completada' : 'Aprobada';
  }
  if (grade !== undefined && grade !== null && grade > 0 && grade < 6) {
    return 'Reprobada';
  }
  if ((interactions > 0 || hasMessages) && (grade === undefined || grade === null || grade === 0)) {
    return 'En Progreso';
  }
  return 'Pendiente';
};

export const autoUpdateLessonStatuses = async (username: string) => {
  try {
    await supabase.from('lessons').update({ lesson_status: 'Aprobada', completed: true }).eq('student_username', username).gte('grade', 6);
    await supabase.from('lessons').update({ lesson_status: 'Reprobada', completed: false }).eq('student_username', username).gt('grade', 0).lt('grade', 6);
    await supabase.from('lessons').update({ lesson_status: 'En Progreso' }).eq('student_username', username).or('grade.is.null,grade.eq.0').gt('valid_interactions_count', 0);
  } catch (err) {
    console.error("Error en auto-actualización de estatus:", err);
  }
};

// --- CUENTAS Y SALDOS ---

export const getAccountBalance = async (username: string): Promise<number> => {
  try {
    const { data, error } = await supabase
        .from('accounts')
        .select('balance')
        .eq('owner_id', username)
        .maybeSingle(); 

    if (error) {
        console.error("Error detallado en balance:", error);
        return 0;
    }
    return data?.balance || 0;
  } catch (err) {
    console.error("Error crítico en getAccountBalance:", err);
    return 0;
  }
};

export const getTransactions = async (username: string): Promise<Transaction[]> => {
  const { data, error } = await supabase
    .from('transactions')
    .select('*')
    .or(`from_account.eq.${username},to_account.eq.${username}`)
    .order('created_at', { ascending: false });
  return error ? [] : (data || []);
};

export const getAllTransactions = async (): Promise<Transaction[]> => {
  const { data, error } = await supabase
    .from('transactions')
    .select('*')
    .order('created_at', { ascending: false });
  return error ? [] : (data || []);
};

/**
 * Ejecuta la transferencia de créditos mediante el RPC 'transferir_creditos_estudiante'.
 * Envía IDs como TEXT para máxima compatibilidad con la función SQL.
 */
export const executeCreditTransfer = async (studentId: string, studentUsername: string, amount: number, concept: string, lessonIds: string[]) => {
  if (lessonIds.length === 0) throw new Error("No hay lecciones seleccionadas.");

  const cleanAmount = Math.floor(amount);

  const { error } = await supabase.rpc('transferir_creditos_estudiante', {
    p_estudiante_id: String(studentId),       
