                    <th className="px-4 py-4 text-[10px] font-black text-indigo-400 uppercase tracking-widest">Fecha</th>
                    <th className="px-4 py-4 text-[10px] font-black text-indigo-400 uppercase tracking-widest">Concepto</th>
                    <th className="px-4 py-4 text-[10px] font-black text-indigo-400 uppercase tracking-widest text-right">Monto</th>
                  </tr>
                </thead>
                <tbody className="divide-y divide-indigo-50 dark:divide-indigo-800">
                  {transactions.length === 0 ? (
                    <tr><td colSpan={3} className="px-4 py-10 text-center text-indigo-300 font-bold uppercase text-xs tracking-widest">Aún no hay movimientos registrados.</td></tr>
                  ) : (
                    transactions.map(t => {
                      const isIncome = t.to_account === user.username;
                      return (
                        <tr key={t.id} className="hover:bg-indigo-50/30 dark:hover:bg-indigo-800/20 transition-colors">
                          <td className="px-4 py-4 text-xs font-bold text-indigo-400">{new Date(t.created_at).toLocaleDateString()}</td>
                          <td className="px-4 py-4 text-xs font-black text-indigo-900 dark:text-white uppercase">{t.concept}</td>
                          <td className={`px-4 py-4 text-sm font-black text-right ${isIncome ? 'text-green-500' : 'text-red-500'}`}>
                            {isIncome ? '+' : '-'}${t.amount.toFixed(2)}
                          </td>
                        </tr>
                      );
                    })
                  )}
                </tbody>
              </table>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

