/**
 * Obtiene el balance de una cuenta filtrando por owner_id.
 * Retorna 0 si el registro no existe.
 */
export const getAccountBalance = async (ownerId: string): Promise<number> => {
  try {
    const { data, error } = await supabase
        .from('accounts')
        .select('balance')
        .eq('owner_id', ownerId)
        .maybeSingle(); 

    if (error) {
        console.error("Error detallado en balance:", error);
        return 0;
    }
    // Aseguramos el retorno como número
    return data ? Number(data.balance) : 0;
  } catch (err) {
    console.error("Error crítico en getAccountBalance:", err);
    return 0;
  }
};

