export const getTransactions = async (ownerId: string): Promise<Transaction[]> => {
  const { data, error } = await supabase
    .from('transactions')
    .select('*')
    .eq('to_account', ownerId)
    .order('created_at', { ascending: false });
  return error ? [] : (data || []);
};

/**
 * Obtiene el historial global (Administrador).
