/**
 * Obtiene el balance de una cuenta filtrando por owner_id (UUID).
 */
export const getAccountBalance = async (ownerId: string): Promise<number> => {
  try {
    const { data, error } = await supabase
        .from('accounts')
        .select('balance')
        .eq('owner_id', ownerId)
        .maybeSingle(); 

    if (error) {
        console.error("Error al obtener balance:", error);
        return 0;
    }
    return data ? Number(data.balance) : 0;
  } catch (err) {
    console.error("Error crítico en getAccountBalance:", err);
    return 0;
  }
};

/**
 * Obtiene las transacciones de un estudiante (donde es el destinatario).
 */
export const getTransactions = async (ownerId: string): Promise<Transaction[]> => {
  const { data, error } = await supabase
    .from('transactions')
    .select('*')
    .eq('to_account', ownerId)
    .order('created_at', { ascending: false });
  return error ? [] : (data || []);
};

