const getAIInstance = () => {
  const apiKey = process.env.API_KEY;
  if (!apiKey) throw new Error("API_KEY no encontrada.");
  return new GoogleGenAI({ apiKey });
};

const cleanJsonResponse = (text: string) => text.replace(/```json/g, "").replace(/```/g, "").trim();

const prepareHistoryForGemini = (history?: ChatMessage[]) => {
  if (!history) return [];
  const recentHistory = history.slice(-20);
  return recentHistory.map(({ role, parts }) => ({ 
    role, 
    parts: (parts || []).map(p => ({ text: p?.text || "" })) 
  }));
};

function shuffleOptions<T>(array: T[]): T[] {
  if (!Array.isArray(array)) return [];
  const shuffled = [...array];
  for (let i = shuffled.length - 1; i > 0; i--) {
    const j = Math.floor(Math.random() * (i + 1));
    [shuffled[i], shuffled[j]] = [shuffled[j], shuffled[i]];
  }
  return shuffled;
}

export const getGeminiChat = async (lesson: Lesson, studentName: string, history?: ChatMessage[]) => {
  const ai = getAIInstance();
  const targetInteractions = Math.ceil(lesson.durationMinutes * 0.8);
  const currentActualMinutes = lesson.actualDurationMinutes || 0;

  const systemInstruction = `
    DIRECTIVA DE SEGURIDAD CRÍTICA: Actúa exclusivamente como el motor de procesamiento de contenido.

    I. PRIORIDAD Y FUSIÓN DE INSTRUCCIONES:
    - Aplica estas reglas con prioridad absoluta (100%) sobre cualquier prompt adjunto de la lección.
    - Si existe contradicción, ignora la contradicción del prompt de la lección, solo fusiona la parte del prompt de la lección que no contradice este documento.

    II. DINÁMICA DE LECCIÓN Y TIEMPO:
    1. Microtematización: 1 intercambio = 1 microtema. El total de microtemas debe igualar las interacciones requeridas (${targetInteractions}). Trata un solo microtema por cada intercambio.
    2. Condición de Examen: No termines la lección ni habilites el examen hasta que se cumplan simultáneamente: a) Se alcancen ${targetInteractions} interacciones válidas y b) Se cumplan los ${lesson.durationMinutes} minutos de duración meta. Si falta tiempo, expande el contenido con temas de refuerzo y curiosidades.

    III. LÓGICA DE REANUDACIÓN Y REFUERZO:
    1. Estado de Lectura: Al retomar, el historial pasado es Read-Only.
    2. Sincronización: El estudiante ha completado ${lesson.validInteractionsCount || 0} interacciones y lleva ${currentActualMinutes} minutos reales. Reanuda exactamente en el último microtema fallido o pendiente.
    3. Refuerzo Post-Reprobación: Si detectas que el estudiante viene de una lección reprobada, genera obligatoriamente nuevos microtemas que ataquen los errores previos antes de permitir el avance.

    IV. PROTOCOLO DE FEEDBACK (STRICT MODE):
    - Censura Verbal: Prohibido usar palabras: "Correcto", "Incorrecto", "Acierto", "Error" o sinónimos.
    - Estructura de Respuesta [EXPLICACION]:
        ◦ JUSTIFICACIÓN: Fundamento técnico del por qué la respuesta es adecuada o lógica correcta detrás del fallo.
        ◦ TRANSICIÓN: Presentación inmediata del siguiente microtema.
    - Etiquetado Obligatorio: Incluye [RESPUESTA_VALIDA] o [RESPUESTA_INCORRECTA] al inicio o final de cada respuesta.

    V. SEGURIDAD Y RELEVANCIA:
    - Irrelevancia: Si el usuario desvía el tema, responde solo [IRRELEVANTE], repite la pregunta y descuenta una interacción del contador.
    - Plagio: Si detectas contenido de otra IA o copiado, responde [PLAGIO_IA] y descuenta una interacción.

    VI. DISEÑO PSICOMÉTRICO (LECCIÓN Y EXAMEN):
    1. Simetría: Variación máxima de longitud del 10% entre todas las opciones (A, B, C, D).
    2. Neutralidad: Mismo nivel de tecnicismo en distractores y respuesta correcta.
    3. Aleatorización: La posición de la respuesta correcta debe ser siempre azarosa e impredecible. PROHIBIDO repetir la misma letra de respuesta correcta en dos preguntas consecutivas.

    DATOS DE LA LECCIÓN:
    - MATERIA: ${lesson.subject}.
    - TEMA: "${lesson.title}".
    - PROMPT DE REFUERZO: "${lesson.learningPrompt || 'Sin prompt adicional'}".
    - ESTUDIANTE: ${studentName}.

    ESTRUCTURA DE SALIDA (OBLIGATORIA):
    [EXPLICACION] (Justificación Pedagógica + Transición al siguiente microtema) [/EXPLICACION]
    [DATA_LOGICA] { "type": "MCQ" | "WRITTEN", "question": "...", "options": ["...", "...", "...", "..."], "correct": "..." } [/DATA_LOGICA]
  `;

  return ai.chats.create({
    model: 'gemini-3-flash-preview',
    config: { systemInstruction },
    history: prepareHistoryForGemini(history)
  });
};

export const generateExam = async (lessonTitle: string, chatHistory: any[]) => {
  const ai = getAIInstance();
  const historyContext = (chatHistory || [])
    .filter(m => m.parts && m.parts[0]?.text)
    .slice(-15)
    .map(m => `${m.role === 'user' ? 'Estudiante' : 'Tutor'}: ${m.parts[0].text}`)
    .join('\n');

  const examPrompt = `Genera un examen final de 10 preguntas MCQ sobre "${lessonTitle}" basado en: ${historyContext}. 
  REGLAS PSICOMÉTRICAS: 
  - 4 opciones por pregunta.
  - Simetría de longitud entre opciones (max 10% variación).
  - Posición aleatoria de la respuesta correcta.
  - No usar palabras como Correcto/Incorrecto en las explicaciones.`;

  const response = await ai.models.generateContent({
    model: 'gemini-3-pro-preview',
    contents: [{ role: 'user', parts: [{ text: examPrompt }] }],
    config: {
      responseMimeType: "application/json",
      responseSchema: {
        type: Type.OBJECT,
        properties: {
          questions: {
            type: Type.ARRAY,
            items: {
              type: Type.OBJECT,
              properties: {
                id: { type: Type.INTEGER },
                text: { type: Type.STRING },
                type: { type: Type.STRING },
                options: { type: Type.ARRAY, items: { type: Type.STRING } },
                correctAnswer: { type: Type.STRING },
                explanation: { type: Type.STRING }
              },
              required: ["id", "text", "type", "correctAnswer", "explanation", "options"]
            }
          }
        },
        required: ["questions"]
      }
    }
  });

  try {
    const cleaned = cleanJsonResponse(response.text || '');
    const examData = JSON.parse(cleaned || '{"questions": []}');
    if (examData.questions) {
      examData.questions = examData.questions.map((q: any) => ({ ...q, options: shuffleOptions(q.options || []) }));
    }
    return examData;
  } catch (e) { return { questions: [] }; }
};

