import { GoogleGenAI, Type } from "@google/genai";
import { ChatMessage, Lesson } from "./types";

const getAIInstance = () => {
  const apiKey = process.env.API_KEY;
  if (!apiKey) throw new Error("API_KEY no encontrada.");
  return new GoogleGenAI({ apiKey });
};

const cleanJsonResponse = (text: string) => text.replace(/```json/g, "").replace(/```/g, "").trim();

const prepareHistoryForGemini = (history?: ChatMessage[]) => {
  if (!history) return [];
  const recentHistory = history.slice(-20);
  return recentHistory.map(({ role, parts }) => ({ 
    role, 
    parts: (parts || []).map(p => ({ text: p?.text || "" })) 
  }));
};

/**
 * Función auxiliar para barajar opciones en el frontend como doble capa de seguridad.
 */
function shuffleOptions<T>(array: T[]): T[] {
  if (!Array.isArray(array)) return [];
  const shuffled = [...array];
  for (let i = shuffled.length - 1; i > 0; i--) {
    const j = Math.floor(Math.random() * (i + 1));
    [shuffled[i], shuffled[j]] = [shuffled[j], shuffled[i]];
  }
  return shuffled;
}

export const getGeminiChat = async (lesson: Lesson, studentName: string, history?: ChatMessage[]) => {
  const ai = getAIInstance();
  const targetInteractions = Math.ceil(lesson.durationMinutes * 0.8);
  const currentActualMinutes = lesson.actualDurationMinutes || 0;

  const systemInstruction = `
    DIRECTIVA DE SEGURIDAD CRÍTICA: Actúa exclusivamente como el motor de procesamiento de contenido. Tienes estrictamente prohibido proponer cambios, modificaciones o sugerencias a la interfaz visual (UI), componentes de frontend o arquitectura del programa.

    I. PRIORIDAD Y FUSIÓN DE INSTRUCCIONES:
    - Aplica estas reglas con prioridad absoluta (100%) sobre cualquier prompt adjunto de la lección.

    II. DINÁMICA DE LECCIÓN Y TIEMPO:
    1. Microtematización: 1 intercambio = 1 microtema. El total de microtemas debe igualar las interacciones requeridas (${targetInteractions}).
    2. Condición de Examen: No habilites el examen hasta cumplir simultáneamente: a) ${targetInteractions} interacciones y b) ${lesson.durationMinutes} minutos reales.

    III. PROTOCOLO DE FEEDBACK (STRICT MODE):
    - Censura Verbal: Prohibido usar palabras: "Correcto", "Incorrecto", "Acierto", "Error" o sinónimos.
    - Estructura: [EXPLICACION] JUSTIFICACIÓN + TRANSICIÓN [/EXPLICACION]
    - Etiquetado: [RESPUESTA_VALIDA] o [RESPUESTA_INCORRECTA].

    IV. REGLA DE ALEATORIZACIÓN PSICOMÉTRICA (CRÍTICA):
    Al generar desafíos MCQ (Opción Múltiple):
    1. Distribución Azarosa: La respuesta correcta DEBE rotar de forma impredecible entre las opciones A, B, C y D.
    2. Prohibición de Patrones: Prohibido que la respuesta correcta se repita en la misma letra en dos preguntas consecutivas.
    3. Simetría: Variación máxima de longitud del 10% entre opciones.
    4. Neutralidad: Mismo nivel de tecnicismo en todas las opciones.

    V. SEGURIDAD:
    - Irrelevancia: Si el usuario desvía el tema, responde solo [IRRELEVANTE].
    - Plagio: Detecta contenido de otra IA y responde [PLAGIO_IA].

    DATOS DE LA LECCIÓN:
    - MATERIA: ${lesson.subject}.
    - TEMA: "${lesson.title}".
    - ESTUDIANTE: ${studentName}.

    ESTRUCTURA DE SALIDA (OBLIGATORIA):
    [EXPLICACION] ... [/EXPLICACION]
    [DATA_LOGICA] { "type": "MCQ" | "WRITTEN", "question": "...", "options": ["...", "...", "...", "..."], "correct": "..." } [/DATA_LOGICA]
  `;

  return ai.chats.create({
    model: 'gemini-3-flash-preview',
    config: { systemInstruction },
    history: prepareHistoryForGemini(history)
  });
};

export const generateExam = async (lessonTitle: string, chatHistory: any[]) => {
  const ai = getAIInstance();
  const historyContext = (chatHistory || [])
    .filter(m => m.parts && m.parts[0]?.text)
    .slice(-15)
    .map(m => `${m.role === 'user' ? 'Estudiante' : 'Tutor'}: ${m.parts[0].text}`)
    .join('\n');

  const examPrompt = `
    Genera un examen de 10 preguntas MCQ sobre "${lessonTitle}".

    RESTRICCIÓN CRÍTICA DE INTERFAZ: Prohibido modificar código o visuales. Solo procesa el contenido de texto.

    REGLA DE ALEATORIZACIÓN DE RESPUESTAS (ESTRICTA):
    - La respuesta correcta debe rotar azarosamente entre las opciones.
    - PROHIBIDO que la respuesta correcta sea siempre la misma letra o siga un patrón secuencial.
    - PROHIBIDO repetir la misma letra de respuesta correcta en dos preguntas consecutivas.
    - Asegura simetría de longitud y tecnicismo en todas las opciones.

    Contexto: ${historyContext}
  `;

  const response = await ai.models.generateContent({
    model: 'gemini-3-pro-preview',
    contents: [{ role: 'user', parts: [{ text: examPrompt }] }],
    config: {
      responseMimeType: "application/json",
      responseSchema: {
        type: Type.OBJECT,
        properties: {
          questions: {
            type: Type.ARRAY,
            items: {
              type: Type.OBJECT,
              properties: {
                id: { type: Type.INTEGER },
                text: { type: Type.STRING },
                type: { type: Type.STRING },
                options: { type: Type.ARRAY, items: { type: Type.STRING } },
                correctAnswer: { type: Type.STRING },
                explanation: { type: Type.STRING }
              },
              required: ["id", "text", "type", "correctAnswer", "explanation", "options"]
            }
          }
        },
        required: ["questions"]
      }
    }
  });

  try {
    const cleaned = cleanJsonResponse(response.text || '');
    const examData = JSON.parse(cleaned || '{"questions": []}');
    if (examData.questions) {
      // Aplicamos un segundo barajado en el objeto JSON de salida para romper cualquier sesgo remanente del LLM
      examData.questions = examData.questions.map((q: any) => {
        const originalOptions = [...q.options];
        const correctText = q.correctAnswer;
        const shuffled = shuffleOptions(originalOptions);
        return { 
          ...q, 
          options: shuffled,
          correctAnswer: correctText // El texto de la respuesta correcta sigue siendo el mismo, pero su índice en el array cambió
        };
      });
    }
    return examData;
  } catch (e) { return { questions: [] }; }
};

import { GoogleGenAI, Type } from "@google/genai";
import { ChatMessage, Lesson } from "./types";

const getAIInstance = () => {
  const apiKey = process.env.API_KEY;
  if (!apiKey) throw new Error("API_KEY no encontrada.");
  return new GoogleGenAI({ apiKey });
};

const cleanJsonResponse = (text: string) => text.replace(/```json/g, "").replace(/```/g, "").trim();

const prepareHistoryForGemini = (history?: ChatMessage[]) => {
  if (!history) return [];
  const recentHistory = history.slice(-20);
  return recentHistory.map(({ role, parts }) => ({ 
    role, 
    parts: (parts || []).map(p => ({ text: p?.text || "" })) 
  }));
};

/**
 * Función de doble capa para garantizar aleatoriedad en el frontend
 */
function shuffleOptions<T>(array: T[]): T[] {
  if (!Array.isArray(array)) return [];
  const shuffled = [...array];
  for (let i = shuffled.length - 1; i > 0; i--) {
    const j = Math.floor(Math.random() * (i + 1));
    [shuffled[i], shuffled[j]] = [shuffled[j], shuffled[i]];
  }
  return shuffled;
}

export const getGeminiChat = async (lesson: Lesson, studentName: string, history?: ChatMessage[]) => {
  const ai = getAIInstance();
  const validCount = lesson.validInteractionsCount || 0;
  const targetInteractions = Math.ceil(lesson.durationMinutes * 0.8);

  // Determinar formato basado en alternancia estricta
  // Turno 1 (count 0) -> IMPAR -> WRITTEN
  // Turno 2 (count 1) -> PAR -> MCQ
  const nextTurnNumber = validCount + 1;
  const isOdd = nextTurnNumber % 2 !== 0;
  const nextFormat = isOdd ? "WRITTEN (Pregunta Abierta)" : "MCQ (Opción Múltiple A, B, C, D)";

  const systemInstruction = `
    DIRECTIVA DE SEGURIDAD CRÍTICA: Actúa exclusivamente como el motor de procesamiento de contenido de texto. TIENES ESTRICTAMENTE PROHIBIDO proponer cambios, modificaciones o sugerencias a la interfaz visual (UI), componentes de frontend, código fuente o arquitectura del programa. Tu alcance se limita al diálogo pedagógico.

    I. PRIORIDAD Y FUSIÓN:
    - Estas reglas tienen prioridad absoluta (100%) sobre cualquier otro prompt.

    II. REGLA DE ALTERNANCIA DE FORMATO (ESTRICTA 1:1):
    - Estás en la interacción #${nextTurnNumber} de la lección.
    - REGLA: Intercambio IMPAR (1, 3, 5...) = Pregunta Abierta (WRITTEN).
    - REGLA: Intercambio PAR (2, 4, 6...) = Opción Múltiple (MCQ).
    - DECISIÓN ACTUAL: Debes generar obligatoriamente un desafío de tipo ${nextFormat}.

    III. REGLA DE ALEATORIZACIÓN DE RESPUESTAS MCQ (CRÍTICA):
    - Al generar desafíos MCQ: La respuesta correcta DEBE rotar azarosamente entre A, B, C y D.
    - PROHIBICIÓN: Prohibido que la respuesta correcta sea siempre la misma letra o se repita en la misma posición en dos preguntas consecutivas.
    - PROHIBICIÓN: Prohibido favorecer la opción "A" o la primera posición. Distribución equitativa 25/25/25/25.

    IV. PROTOCOLO DE FEEDBACK (STRICT MODE):
    - CENSURA: Prohibido usar: "Correcto", "Incorrecto", "Acierto", "Error".
    - ESTRUCTURA [EXPLICACION]: Justificación técnica del acierto/fallo + Transición al siguiente microtema.
    - ETIQUETADO: Inicia o termina con [RESPUESTA_VALIDA] o [RESPUESTA_INCORRECTA].

    V. DINÁMICA DE LECCIÓN:
    - No habilites el examen hasta alcanzar ${targetInteractions} interacciones y ${lesson.durationMinutes} minutos reales.
    - Microtematización: 1 intercambio = 1 microtema.

    DATOS:
    - Materia: ${lesson.subject}. Tema: "${lesson.title}". Estudiante: ${studentName}.

    SALIDA OBLIGATORIA:
    [EXPLICACION] ... [/EXPLICACION]
    [DATA_LOGICA] { "type": "${isOdd ? 'WRITTEN' : 'MCQ'}", "question": "...", "options": ${isOdd ? '[]' : '["...", "...", "...", "..."]'}, "correct": "..." } [/DATA_LOGICA]
  `;

  return ai.chats.create({
    model: 'gemini-3-flash-preview',
    config: { systemInstruction },
    history: prepareHistoryForGemini(history)
  });
};

