  const idsToUpdate = data.filter(row => {
    const d = new Date(row.date + 'T12:00:00');
    return days[(d.getDay() + 6) % 7];
  }).map(row => row.id);
  if (idsToUpdate.length > 0) await supabase.from('lessons').update({ learning_prompt: prompt }).in('id', idsToUpdate);
};

import { useState, useEffect, useMemo } from 'react';
import { User, StudentData, Lesson, Transaction } from '../types';
import { 
  getStudentData, 
  executeCreditTransfer, 
  getTransactions, 
  getAccountBalance, 
  autoUpdateLessonStatuses,
  updateLessonInStudent,
  deleteLessonFromStudent,
  clearLessonChatHistory
} from '../storage2';
import Calendar from './Calendar';

interface StudentDashboardProps {
  user: User;
  onStartLesson: (username: string, lessonId: string) => void;
  onBalanceUpdate?: () => void;
  isAdminView?: boolean;
  onAuditLesson?: (lesson: Lesson) => void;
  onEditLessonDetails?: (lesson: Lesson) => void;
  initialSelectedDate?: string | null;
  lastFinishedLessonId?: string | null;
}

const StudentDashboard: React.FC<StudentDashboardProps> = ({ 
  user, 
  onStartLesson, 
  onBalanceUpdate,
  isAdminView = false,
  onAuditLesson,
  onEditLessonDetails,
  initialSelectedDate,
  lastFinishedLessonId: propsLastFinishedId
}) => {
  const [activeSubTab, setActiveSubTab] = useState<'aula' | 'banco'>('aula');
  const [data, setData] = useState<StudentData | null>(null);
  const [transactions, setTransactions] = useState<Transaction[]>([]);
  const [currentBalance, setCurrentBalance] = useState(0);

  const [quickEditLessonId, setQuickEditLessonId] = useState<string | null>(null);
  const [isUpdating, setIsUpdating] = useState(false);

  const getLocalDateStr = (d: Date = new Date()) => {
    const year = d.getFullYear();
    const month = String(d.getMonth() + 1).padStart(2, '0');
    const day = String(d.getDate()).padStart(2, '0');
    return `${year}-${month}-${day}`;
  };

  const [selectedDay, setSelectedDay] = useState<string | null>(initialSelectedDate || getLocalDateStr());
  const [dayLessons, setDayLessons] = useState<Lesson[]>([]);
  const [isLoading, setIsLoading] = useState(true);
  const [isTransferring, setIsTransferring] = useState(false);

  const getMonday = (d: Date) => {
    const date = new Date(d);
    const day = date.getDay();
    const diff = date.getDate() - day + (day === 0 ? -6 : 1);
    const monday = new Date(date.setDate(diff));
    monday.setHours(0, 0, 0, 0); 
    return monday;
  };
  const [weekStart, setWeekStart] = useState(() => getMonday(new Date()));

  const fetchData = async () => {
    setIsLoading(true);
    try {
      if (!isAdminView) await autoUpdateLessonStatuses(user.username);

      const ownerId = user.id || user.username;
      const [studentData, history, balance] = await Promise.all([
        getStudentData(user.username),
        getTransactions(ownerId),
        getAccountBalance(ownerId)
      ]);
      setData(studentData);
      setTransactions(history);
      setCurrentBalance(balance);
    } catch (error) {
      console.error("Error cargando datos:", error);
    } finally {
      setIsLoading(false);
    }
  };

  useEffect(() => { fetchData(); }, [user.username]);

  useEffect(() => {
    if (data && selectedDay) {
      const lessons = data.lessons.filter(l => l.date === selectedDay) || [];
      setDayLessons(lessons);
    }
  }, [selectedDay, data]);

  const currentWeekLessons = useMemo(() => {
    if (!data) return [];
    const monday = new Date(weekStart);
    const sunday = new Date(monday);
    sunday.setDate(monday.getDate() + 6);
    sunday.setHours(23, 59, 59, 999);

    return data.lessons.filter(l => {
      const lDate = new Date(l.date + 'T12:00:00');
      return lDate >= monday && lDate <= sunday;
    });
  }, [data, weekStart]);

  const creditsTransferable = useMemo(() => {
    return currentWeekLessons
      .filter(l => (l.lesson_status === 'Aprobada' || l.lesson_status === 'Completada' || (l.grade && l.grade >= 6)) && !l.credits_transfered)
      .reduce((acc, l) => acc + (l.grade || 0), 0);
  }, [currentWeekLessons]);

  const creditsToWin = useMemo(() => {
    return currentWeekLessons
      .filter(l => (l.lesson_status !== 'Aprobada' && l.lesson_status !== 'Completada' && (!l.grade || l.grade < 6)) && !l.credits_transfered)
      .length * 10;
  }, [currentWeekLessons]);

  const dayCredits = useMemo(() => {
    return dayLessons.reduce((acc, l) => acc + (l.grade || 0), 0);
  }, [dayLessons]);

  const weeklyStats = useMemo(() => {
    return currentWeekLessons.reduce((acc, l) => {
      const status = (l.lesson_status || 'Pendiente').toLowerCase();
      if (status === 'aprobada' || status === 'completada') acc.passed += 1;
      else if (status === 'reprobada') acc.failed += 1;
      else if (status === 'en progreso') acc.inProgress += 1;
      else acc.pending += 1;
      acc.total += 1;
      return acc;
    }, { passed: 0, failed: 0, inProgress: 0, pending: 0, total: 0 });
  }, [currentWeekLessons]);

  const handleTransfer = async () => {
    if (creditsTransferable <= 0 || isTransferring || isAdminView) return;

    const pendingLessons = currentWeekLessons.filter(l => 
      (l.lesson_status === 'Aprobada' || l.lesson_status === 'Completada' || (l.grade && l.grade >= 6)) 
      && !l.credits_transfered
    );

    const realSum = pendingLessons.reduce((acc, l) => acc + (l.grade || 0), 0);

    if (realSum !== creditsTransferable) {
      alert("No se pueden transferir créditos en este momento debido a una discrepancia de datos. Por favor, contacte a soporte.");
      return;
    }

    const Balance_Perdido = (pendingLessons.length * 10) - realSum;

    if (Balance_Perdido > 0) {
      const confirmUpsell = window.confirm(
        `Aún tienes un balance de ${Balance_Perdido} créditos que podrías haber generado en estas clases. ¿Deseas retomar las clases para maximizar tus créditos o prefieres transferir el monto actual ahora?`
      );
      if (!confirmUpsell) return;
    } else {
      const confirmFinal = window.confirm(`¿Confirmas la transferencia de $${realSum} a tu cuenta bancaria?`);
      if (!confirmFinal) return;
    }

    setIsTransferring(true);
    try {
      const lessonIds = pendingLessons.map(l => l.id);
      const weekStr = weekStart.toISOString().split('T')[0];
      const concept = `Créditos ganados por semana de estudio [${weekStr}]`;

      const studentId = user.id || user.username;
      await executeCreditTransfer(studentId, user.username, realSum, concept, lessonIds);

      alert("¡Transferencia exitosa! Tus créditos han sido enviados a tu cuenta bancaria de la plataforma.");

      if (data) {
        const updatedLessons = data.lessons.map(l => 
          lessonIds.includes(l.id) ? { ...l, credits_transfered: true } : l
        );
        setData({ ...data, lessons: updatedLessons });
      }

      await fetchData();
      if (onBalanceUpdate) onBalanceUpdate();
    } catch (err: any) {
      alert(`Error en la transferencia: ${err.message || "Error desconocido"}`);
    } finally {
      setIsTransferring(false);
    }
  };

  const formatElapsedTime = (seconds: number) => {
    const mins = Math.floor(seconds / 60);
    const secs = seconds % 60;
    return `${mins}:${secs.toString().padStart(2, '0')}`;
  };

  const getLessonUIConfig = (status: string, isTransfered: boolean) => {
    const s = (status || 'Pendiente').toLowerCase();

    let config = { 
      color: 'bg-blue-600', 
      label: 'PENDIENTE', 
      btnText: isAdminView ? 'AUDITAR CLASE' : 'TOMAR CLASE 🚀',
      textColor: 'text-white'
    };

    if (s === 'aprobada' || s === 'completada') {
      config = isTransfered 
        ? { color: 'bg-green-800', label: (s === 'completada' ? 'COMPLETADA' : 'APROBADA') + ' (PAGADA)', btnText: 'AUDITAR LECCIÓN ✨', textColor: 'text-white' }
        : { color: 'bg-green-600', label: s === 'completada' ? 'COMPLETADA' : 'APROBADA', btnText: 'REPASAR LECCIÓN ✨', textColor: 'text-white' };
    } 
    else if (s === 'reprobada') {
      config = { color: 'bg-red-600', label: 'REPROBADA', btnText: isAdminView ? 'AUDITAR RESULTADO' : 'MEJORAR NOTA 🔁', textColor: 'text-white' };
    } 
    else if (s === 'en progreso') {
      config = { color: 'bg-orange-500', label: 'EN PROGRESO', btnText: isAdminView ? 'AUDITAR AVANCE' : 'RETOMAR CLASE 📚', textColor: 'text-white' };
    }

    return config;
  };

  const handleQuickUpdate = async (lesson: Lesson, updates: Partial<Lesson>) => {
    if (!isAdminView || isUpdating) return;
    setIsUpdating(true);
    try {
      const finalLesson = { ...lesson, ...updates };
      await updateLessonInStudent(user.username, finalLesson);
      await fetchData();
    } catch (err) {
      alert("Error al actualizar lección.");
    } finally {
      setIsUpdating(false);
    }
  };

  const handleDeleteLesson = async (lessonId: string) => {
    if (!isAdminView || isUpdating || !confirm("¿Eliminar esta lección permanentemente?")) return;
    setIsUpdating(true);
    try {
      await deleteLessonFromStudent(lessonId);
      await fetchData();
    } catch (err) {
      alert("Error al eliminar lección.");
    } finally {
      setIsUpdating(false);
    }
  };

  const handleClearHistory = async (lessonId: string) => {
    if (!isAdminView || isUpdating || !confirm("¿Borrar historial de chat y reiniciar progreso de esta lección?")) return;
    setIsUpdating(true);
    try {
      await clearLessonChatHistory(lessonId);
      await fetchData();
    } catch (err) {
      alert("Error al limpiar historial.");
    } finally {
      setIsUpdating(false);
    }
  };

  if (isLoading) return (
    <div className="flex flex-col items-center justify-center py-24">
      <div className="w-12 h-12 border-4 border-indigo-600 border-t-transparent rounded-full animate-spin mb-4"></div>
      <p className="text-indigo-900 dark:text-sky-100 font-bold">Espejando aula...</p>
    </div>
  );

  return (
    <div className="space-y-6 font-fredoka animate-in fade-in duration-500">
      <div className="flex bg-white dark:bg-indigo-900 p-2 rounded-2xl border-4 border-indigo-50 dark:border-indigo-800 shadow-sm w-fit">
        <button 
          onClick={() => setActiveSubTab('aula')} 
          className={`px-6 py-2 rounded-xl font-black text-xs uppercase transition-all flex items-center space-x-2 ${activeSubTab === 'aula' ? 'bg-indigo-600 text-white shadow-md' : 'text-indigo-400 hover:text-indigo-600'}`}
        >
          <span>Aula Virtual</span> <span>📚</span>
        </button>
        <button 
          onClick={() => setActiveSubTab('banco')} 
          className={`px-6 py-2 rounded-xl font-black text-xs uppercase transition-all flex items-center space-x-2 ${activeSubTab === 'banco' ? 'bg-amber-500 text-white shadow-md' : 'text-amber-500 hover:text-amber-600'}`}
        >
          <span>Estado de Cuenta</span> <span>🏦</span>
        </button>
      </div>

      {activeSubTab === 'aula' ? (
        <div className="space-y-6 animate-in slide-in-from-bottom-4 duration-500">
          <div className="bg-white dark:bg-indigo-900 p-6 rounded-[2.5rem] shadow-sm border-4 border-indigo-50 dark:border-indigo-800 flex flex-col md:flex-row items-center gap-6">
            <div className="flex items-center space-x-8 shrink-0">
               <div className="bg-amber-50 dark:bg-amber-900/30 px-6 py-4 rounded-2xl border-2 border-amber-100 dark:border-amber-800 shadow-inner flex flex-col items-center min-w-[160px]">
                  <p className="text-[10px] font-black text-amber-600 dark:text-amber-400 uppercase tracking-widest mb-1 text-center">CRÉDITOS TRANSFERIBLES</p>
                  <p className="text-3xl font-black text-amber-500 leading-none mb-2">⭐ {creditsTransferable}</p>
                  {!isAdminView && (
                    <button 
                      onClick={handleTransfer}
                      disabled={creditsTransferable <= 0 || isTransferring}
                      className={`text-[11px] font-black uppercase underline transition-all ${creditsTransferable > 0 && !isTransferring ? 'text-indigo-600 hover:text-indigo-800 cursor-pointer' : 'text-indigo-300 cursor-not-allowed'}`}
                    >
                      {isTransferring ? 'PROCESANDO...' : 'Transferir créditos al banco'}
                    </button>
                  )}
               </div>

               <div className="bg-indigo-50 dark:bg-indigo-950 px-6 py-4 rounded-2xl border-2 border-indigo-100 dark:border-indigo-800/50 shadow-inner flex flex-col items-center min-w-[160px]">
                  <p className="text-[10px] font-black text-indigo-400 dark:text-indigo-500 uppercase tracking-widest mb-1 text-center">CRÉDITOS POR GANAR</p>
                  <p className="text-3xl font-black text-indigo-300 dark:text-indigo-600 leading-none">⭐ {creditsToWin}</p>
               </div>
            </div>

            <div className="flex-1 w-full space-y-2">
              <div className="flex justify-between items-end px-1">
                <span className="text-[10px] font-black text-indigo-400 dark:text-indigo-500 uppercase tracking-widest">PROGRESO DE LA SEMANA</span>
                <div className="flex flex-wrap gap-3">
                  <span className="text-[9px] font-bold text-blue-600 dark:text-blue-400 uppercase flex items-center"><div className="w-2 h-2 rounded-full bg-blue-600 mr-1"></div> {weeklyStats.total > 0 ? Math.round((weeklyStats.pending/weeklyStats.total)*100) : 0}% Pendientes</span>
                  <span className="text-[9px] font-bold text-orange-500 uppercase flex items-center"><div className="w-2 h-2 rounded-full bg-orange-500 mr-1"></div> {weeklyStats.total > 0 ? Math.round((weeklyStats.inProgress/weeklyStats.total)*100) : 0}% En Progreso</span>
                  <span className="text-[9px] font-bold text-green-600 dark:text-green-400 uppercase flex items-center"><div className="w-2 h-2 rounded-full bg-green-600 mr-1"></div> {weeklyStats.total > 0 ? Math.round((weeklyStats.passed/weeklyStats.total)*100) : 0}% Aprobadas</span>
                  <span className="text-[9px] font-bold text-red-600 dark:text-red-400 uppercase flex items-center"><div className="w-2 h-2 rounded-full bg-red-600 mr-1"></div> {weeklyStats.total > 0 ? Math.round((weeklyStats.failed/weeklyStats.total)*100) : 0}% Reprobadas</span>
                </div>
              </div>
              <div className="h-7 w-full bg-indigo-50 dark:bg-indigo-950 rounded-full flex overflow-hidden border-2 border-indigo-100 dark:border-indigo-800 shadow-inner">
                <div style={{ width: `${weeklyStats.total > 0 ? (weeklyStats.pending / weeklyStats.total) * 100 : 0}%` }} className="h-full bg-blue-600 transition-all duration-700 ease-out"></div>
                <div style={{ width: `${weeklyStats.total > 0 ? (weeklyStats.inProgress / weeklyStats.total) * 100 : 0}%` }} className="h-full bg-orange-500 transition-all duration-700 ease-out"></div>
                <div style={{ width: `${weeklyStats.total > 0 ? (weeklyStats.passed / weeklyStats.total) * 100 : 0}%` }} className="h-full bg-green-600 transition-all duration-700 ease-out"></div>
                <div style={{ width: `${weeklyStats.total > 0 ? (weeklyStats.failed / weeklyStats.total) * 100 : 0}%` }} className="h-full bg-red-600 transition-all duration-700 ease-out"></div>
              </div>
            </div>
          </div>

          <div className="grid lg:grid-cols-3 gap-8">
            <div className="lg:col-span-2">
              <div className="bg-white dark:bg-indigo-900 p-6 rounded-[3rem] shadow-sm border-4 border-indigo-50 dark:border-indigo-800 transition-colors">
                <Calendar 
                  lessons={data?.lessons || []} 
                  selectedDate={selectedDay} 
                  onDayClick={setSelectedDay} 
                  weekStart={weekStart}
                  onWeekStartChange={setWeekStart}
                  isAdmin={isAdminView}
                />
              </div>
            </div>

            <div className="bg-white dark:bg-indigo-900 p-8 rounded-[3rem] shadow-sm border-4 border-indigo-50 dark:border-indigo-800 h-fit sticky top-24 transition-colors">
              <div className="flex justify-between items-start mb-2">
                <div>
                  <h3 className="text-2xl font-black text-indigo-900 dark:text-white uppercase leading-tight">Clases para este día</h3>
                  <p className="text-[10px] font-black text-indigo-300 dark:text-indigo-500 uppercase tracking-[0.2em] mt-1">Historial de Calificaciones</p>
                </div>
                {dayCredits > 0 && (
                  <div className="bg-amber-400 px-4 py-2 rounded-2xl shadow-lg border-2 border-amber-500 flex items-center space-x-2">
                    <span className="text-xl">⭐</span>
                    <span className="text-indigo-900 font-black text-sm">{dayCredits}</span>
                  </div>
                )}
              </div>

              <div className="mt-8 space-y-6">
                {dayLessons.length === 0 ? (
                  <div className="flex flex-col items-center justify-center py-12 px-4 text-center text-indigo-300">
                    <div className="text-5xl mb-4">🏖️</div>
                    <p className="font-bold uppercase text-xs tracking-widest">No hay lecciones asignadas.</p>
                  </div>
                ) : (
                  dayLessons.map(lesson => {
                    const status = lesson.lesson_status || 'Pendiente';
                    const grade = lesson.grade !== undefined && lesson.grade !== null ? lesson.grade : null;
                    const hasHistory = (lesson.chatHistory?.length || 0) > 0;
                    const isTransfered = !!lesson.credits_transfered;
                    const isSelected = quickEditLessonId === lesson.id;
                    const isJustFinished = lesson.id === propsLastFinishedId;

                    const ui = getLessonUIConfig(status, isTransfered);

                    return (
                      <div 
                        key={lesson.id} 
                        className={`p-6 rounded-[2.5rem] border-4 transition-all bg-white dark:bg-indigo-950 border-indigo-50 dark:border-indigo-800 shadow-sm relative overflow-hidden ${isSelected ? 'ring-4 ring-amber-400 ring-offset-4 dark:ring-offset-indigo-900 scale-[1.02]' : ''} ${isJustFinished ? 'ring-4 ring-emerald-400 ring-offset-4' : ''}`}
                      >
                        {isAdminView && isSelected && (
                          <div className="absolute inset-0 bg-white/95 dark:bg-indigo-900/95 z-[50] flex flex-col p-4 space-y-3 animate-in fade-in zoom-in duration-200">
                             <div className="flex justify-between items-center mb-1">
                                <span className="text-[10px] font-black text-indigo-400 uppercase">Gestión Administrativa</span>
                                <button onClick={() => setQuickEditLessonId(null)} className="text-red-500 font-black text-sm p-1">✕</button>
                             </div>

                             <div className="grid grid-cols-2 gap-2">
                                <div>
                                   <label className="text-[8px] font-black text-indigo-300 uppercase block mb-1 ml-1">Estatus</label>
                                   <select 
                                      value={status} 
                                      onChange={(e) => handleQuickUpdate(lesson, { lesson_status: e.target.value as any })}
                                      className="w-full bg-indigo-50 dark:bg-indigo-950 p-2 rounded-xl text-[10px] font-black outline-none border-2 border-indigo-100 dark:border-indigo-800"
                                   >
                                      <option value="Pendiente">Pendiente</option>
                                      <option value="En Progreso">En Progreso</option>
                                      <option value="Aprobada">Aprobada</option>
                                      <option value="Reprobada">Reprobada</option>
                                      <option value="Completada">Completada</option>
                                   </select>
                                </div>
                                <div>
                                   <label className="text-[8px] font-black text-indigo-300 uppercase block mb-1 ml-1">Créditos (0-10)</label>
                                   <input 
                                      type="number" min="0" max="10"
                                      value={grade !== null ? grade : ''}
                                      onChange={(e) => handleQuickUpdate(lesson, { grade: parseInt(e.target.value) || 0 })}
                                      className="w-full bg-indigo-50 dark:bg-indigo-950 p-2 rounded-xl text-[10px] font-black outline-none border-2 border-indigo-100 dark:border-indigo-800"
                                      placeholder="Puntos"
                                   />
                                </div>
                             </div>

                             <div className="grid grid-cols-2 gap-2 mt-2">
                                <button 
                                  onClick={() => handleClearHistory(lesson.id)}
                                  className="py-2 bg-amber-100 dark:bg-amber-900/30 text-amber-600 dark:text-amber-400 text-[9px] font-black rounded-xl uppercase border-2 border-amber-200 dark:border-amber-800 hover:bg-amber-500 hover:text-white transition-all"
                                >
                                  Limpiar Chat 🫧
                                </button>
                                <button 
                                  onClick={() => {
                                    setQuickEditLessonId(null);
                                    if (onEditLessonDetails) onEditLessonDetails(lesson);
                                  }}
                                  className="py-2 bg-indigo-100 dark:bg-indigo-800 text-indigo-600 dark:text-indigo-200 text-[9px] font-black rounded-xl uppercase border-2 border-indigo-200 dark:border-indigo-700 hover:bg-indigo-600 hover:text-white transition-all"
                                >
                                  Editar Datos ✏️
                                </button>
                             </div>

                             <button 
                               onClick={() => handleDeleteLesson(lesson.id)}
                               className="w-full py-2 bg-red-50 dark:bg-red-900/20 text-red-500 text-[9px] font-black rounded-xl uppercase border-2 border-red-100 dark:border-red-900/50 hover:bg-red-500 hover:text-white transition-all"
                             >
                               Eliminar Lección 🗑️
                             </button>
                          </div>
                        )}

                        <div className="flex justify-between items-center mb-4">
                          <span className={`${ui.color} ${ui.textColor} text-[9px] font-black px-4 py-1.5 rounded-full uppercase tracking-wider`}>
                            {lesson.subject} • {ui.label}
                          </span>
                          <div className="flex items-center space-x-2">
                            {grade !== null && (
                              <div className="flex items-center space-x-1">
                                 <span className="text-amber-500 text-lg">⭐</span>
                                 <span className={`text-sm font-black ${grade >= 6 ? 'text-green-600' : 'text-red-500'}`}>{grade}/10</span>
                              </div>
                            )}
                            {isAdminView && !isSelected && (
                              <button 
                                onClick={(e) => { e.stopPropagation(); setQuickEditLessonId(lesson.id); }}
                                className="w-8 h-8 rounded-full bg-slate-100 dark:bg-indigo-800 flex items-center justify-center text-indigo-400 hover:bg-indigo-600 hover:text-white transition-all shadow-sm"
                                title="Gestión de Lección"
                              >
                                ⚙️
                              </button>
                            )}
                          </div>
                        </div>

                        <h4 className="text-lg font-black text-indigo-900 dark:text-white uppercase mb-2 leading-tight">
                          🧠 {lesson.title}
                        </h4>

                        {isTransfered && (
                          <p className="text-[10px] font-bold text-green-700 dark:text-green-400 italic mb-4 animate-in fade-in slide-in-from-left-1">
                            ✓ Créditos transferidos al banco
                          </p>
                        )}

                        <div className="flex flex-wrap gap-2 mb-6">
                           <div className="bg-indigo-50 dark:bg-indigo-900/50 px-3 py-1.5 rounded-xl flex items-center space-x-1">
                              <span className="text-xs">⏱️</span>
                              <span className="text-[9px] font-black text-indigo-400 uppercase">Meta: {lesson.durationMinutes} min</span>
                           </div>
                           {(lesson.elapsedSeconds || 0) > 0 && (
                             <div className="bg-amber-50 dark:bg-amber-900/50 px-3 py-1.5 rounded-xl flex items-center space-x-1">
                                <span className="text-xs">⌛</span>
                                <span className="text-[9px] font-black text-amber-600 uppercase">Real: {formatElapsedTime(lesson.elapsedSeconds || 0)}</span>
                             </div>
                           )}
                        </div>

                        <div className="flex items-center space-x-3">
                          {isAdminView || isTransfered ? (
                            <button 
                              disabled={!hasHistory && !isTransfered}
                              onClick={() => {
                                if (isTransfered && onAuditLesson) onAuditLesson(lesson);
                                else if (isAdminView && onAuditLesson) onAuditLesson(lesson);
                              }} 
                              className={`flex-1 py-4 rounded-2xl font-black text-xs shadow-xl transition-all active:scale-95 text-white ${
                                hasHistory || isTransfered 
                                  ? (isTransfered ? 'bg-green-800 hover:bg-green-900' : 'bg-indigo-600 hover:bg-indigo-700') 
                                  : 'bg-slate-300 dark:bg-indigo-800 cursor-not-allowed'
                              } uppercase tracking-widest`}
                            >
                              {ui.btnText}
                            </button>
                          ) : (
                            <button 
                              onClick={() => onStartLesson(user.username, lesson.id)} 
                              className={`flex-1 py-4 rounded-2xl font-black text-xs shadow-xl transition-all active:scale-95 ${ui.color} ${ui.textColor} hover:opacity-90 uppercase tracking-widest`}
                            >
                              {ui.btnText}
                            </button>
                          )}
                        </div>
                      </div>
                    );
                  })
                )}
              </div>
            </div>
          </div>
        </div>
      ) : (
        <div className="space-y-6 animate-in slide-in-from-bottom-4 duration-500">
          <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
            <div className="bg-white dark:bg-indigo-900 p-8 rounded-[3rem] border-4 border-amber-100 dark:border-amber-900/30 flex items-center space-x-6 shadow-sm">
              <div className="w-20 h-20 bg-amber-100 dark:bg-amber-900/50 rounded-full flex items-center justify-center text-4xl shadow-inner">🏦</div>
              <div>
                <p className="text-xs font-black text-amber-600 dark:text-amber-500 uppercase tracking-widest mb-1">Saldo en Cuenta</p>
                <p className="text-4xl font-black text-amber-500 leading-none">MXN ${currentBalance.toFixed(2)}</p>
              </div>
            </div>
          </div>

          <div className="bg-white dark:bg-indigo-900 p-6 rounded-[3rem] border-4 border-indigo-50 dark:border-indigo-800 shadow-sm overflow-hidden">
            <h3 className="text-xl font-black text-indigo-900 dark:text-white uppercase mb-6 px-4">Historial de Movimientos</h3>
            <div className="overflow-x-auto">
              <table className="w-full text-left">
                <thead>
                  <tr className="border-b-2 border-indigo-50 dark:border-indigo-800">
                    <th className="px-4 py-4 text-[10px] font-black text-indigo-400 uppercase tracking-widest">Fecha</th>
                    <th className="px-4 py-4 text-[10px] font-black text-indigo-400 uppercase tracking-widest">Concepto</th>
                    <th className="px-4 py-4 text-[10px] font-black text-indigo-400 uppercase tracking-widest text-right">Monto</th>
                  </tr>
                </thead>
                <tbody className="divide-y divide-indigo-50 dark:divide-indigo-800">
                  {transactions.length === 0 ? (
                    <tr><td colSpan={3} className="px-4 py-10 text-center text-indigo-300 font-bold uppercase text-xs tracking-widest">No hay transferencias registradas.</td></tr>
                  ) : (
                    transactions.map(t => {
                      return (
                        <tr key={t.id} className="hover:bg-indigo-50/30 dark:hover:bg-indigo-800/20 transition-colors">
                          <td className="px-4 py-4 text-xs font-bold text-indigo-400">{new Date(t.created_at).toLocaleDateString()}</td>
                          <td className="px-4 py-4 text-xs font-black text-indigo-900 dark:text-white uppercase">{t.concept}</td>
                          <td className="px-4 py-4 text-sm font-black text-right text-green-500">
                            +${t.amount.toFixed(2)}
                          </td>
                        </tr>
                      );
                    })
                  )}
                </tbody>
              </table>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default StudentDashboard;

