        {showResultModal && !isAdminAudit && (
          <div className="absolute inset-0 bg-indigo-900/95 flex items-center justify-center p-6 z-[1200] backdrop-blur-md animate-in fade-in duration-300">
            <div className="bg-white w-full max-w-lg rounded-[3.5rem] p-12 border-8 border-indigo-50 shadow-2xl text-center transform animate-in zoom-in duration-500">
              {correctAnswersCount >= 6 ? (
                <>
                  <div className="text-7xl mb-6">🏆</div>
                  <h2 className="text-4xl font-black text-emerald-600 mb-4 uppercase tracking-tight">¡Felicidades!</h2>
                  <p className="text-indigo-900 font-bold text-lg mb-8 leading-relaxed">
                    ¡Has acreditado la lección con éxito! Tu esfuerzo y dedicación han dado grandes resultados. ¡Sigue así!
                  </p>
                </>
              ) : (
                <>
                  <div className="text-7xl mb-6">📚</div>
                  <h2 className="text-4xl font-black text-red-600 mb-4 uppercase tracking-tight">Inténtalo de nuevo</h2>
                  <p className="text-indigo-900 font-bold text-lg mb-8 leading-relaxed">
                    No has alcanzado la nota mínima en esta ocasión, pero no te preocupes. ¡Repasa los temas y vuelve a intentarlo, tú puedes lograrlo!
                  </p>
