                <p className="text-sm font-black uppercase tracking-widest mb-1">Calificación Final</p>
                <p className="text-5xl font-black">{correctAnswersCount}.0 / 10</p>
              </div>

              <button 
                onClick={handleFinalizeLesson}
                className="w-full bg-indigo-600 text-white font-black py-6 rounded-3xl shadow-xl hover:bg-indigo-700 transition-all transform active:scale-95 text-xl uppercase tracking-widest"
              >
