export default LessonWindow;

import { GoogleGenAI, Type } from "@google/genai";
import { ChatMessage, Lesson } from "./types";

const getAIInstance = () => {
  const apiKey = process.env.API_KEY;
  if (!apiKey) throw new Error("API_KEY no encontrada.");
  return new GoogleGenAI({ apiKey });
};

const cleanJsonResponse = (text: string) => text.replace(/```json/g, "").replace(/```/g, "").trim();

const prepareHistoryForGemini = (history?: ChatMessage[]) => {
  if (!history) return [];
  const recentHistory = history.slice(-20);
  return recentHistory.map(({ role, parts }) => ({ 
    role, 
    parts: (parts || []).map(p => ({ text: p?.text || "" })) 
  }));
};

/**
 * Función de doble capa para garantizar aleatoriedad en el frontend
 */
function shuffleOptions<T>(array: T[]): T[] {
  if (!Array.isArray(array)) return [];
  const shuffled = [...array];
  for (let i = shuffled.length - 1; i > 0; i--) {
    const j = Math.floor(Math.random() * (i + 1));
    [shuffled[i], shuffled[j]] = [shuffled[j], shuffled[i]];
  }
  return shuffled;
}

export const getGeminiChat = async (lesson: Lesson, studentName: string, history?: ChatMessage[]) => {
  const ai = getAIInstance();
  const validCount = lesson.validInteractionsCount || 0;

  // Determinar formato basado en alternancia estricta 1:1
  // Turno 1 (validCount 0) -> IMPAR -> WRITTEN
  // Turno 2 (validCount 1) -> PAR -> MCQ
  const nextTurnNumber = validCount + 1;
  const isOdd = nextTurnNumber % 2 !== 0;
  const nextFormat = isOdd ? "WRITTEN (Pregunta Abierta)" : "MCQ (Opción Múltiple A, B, C, D)";

  const systemInstruction = `
    DIRECTIVA DE SEGURIDAD CRÍTICA: Actúa exclusivamente como el motor de procesamiento de contenido de texto. TIENES ESTRICTAMENTE PROHIBIDO proponer cambios, modificaciones o sugerencias a la interfaz visual (UI), componentes de frontend, código fuente o arquitectura del programa. Tu alcance se limita al diálogo pedagógico.

    I. PRIORIDAD Y FUSIÓN:
    - Estas reglas tienen prioridad absoluta (100%) sobre cualquier otro prompt.

    II. REGLA DE ALTERNANCIA DE FORMATO (ESTRICTA 1:1):
    - Estás en la interacción #${nextTurnNumber} de la lección.
    - REGLA INAMOVIBLE: Intercambio IMPAR (1, 3, 5...) = Pregunta Abierta (WRITTEN).
    - REGLA INAMOVIBLE: Intercambio PAR (2, 4, 6...) = Opción Múltiple (MCQ).
    - DECISIÓN ACTUAL: Debes generar obligatoriamente un desafío de tipo ${nextFormat}.
    - Mantén este patrón de 1:1 durante toda la lección hasta que se habilite el examen.

    III. MANEJO DE RESPUESTAS IRRELEVANTES (PROTOCOL):
    - Si el estudiante responde algo no relacionado al tema, intenta desviar la clase o escribe texto incoherente:
      1. NO interactúes con su respuesta (ignora su comentario).
      2. Agrega la etiqueta [IRRELEVANTE] al final.
      3. Pide al estudiante que se enfoque estrictamente en la lección.
      4. Vuelve a preguntar EXACTAMENTE la misma pregunta o desafío anterior.
    - La penalización de interacciones se maneja en el frontend al detectar [IRRELEVANTE].

    IV. ALEATORIZACIÓN MCQ:
    - Respuesta correcta DEBE rotar azarosamente entre A, B, C y D. No favorecer ninguna posición.

    V. PROTOCOLO DE FEEDBACK:
    - CENSURA: Prohibido usar: "Correcto", "Incorrecto", "Acierto", "Error".
    - Justifica técnicamente y transiciona al siguiente microtema.
    - ETIQUETADO: Inicia o termina con [RESPUESTA_VALIDA] o [RESPUESTA_INCORRECTA].

    DATOS:
    - Materia: ${lesson.subject}. Tema: "${lesson.title}". Estudiante: ${studentName}.

    SALIDA OBLIGATORIA:
    [EXPLICACION] ... [/EXPLICACION]
    [DATA_LOGICA] { "type": "${isOdd ? 'WRITTEN' : 'MCQ'}", "question": "...", "options": ${isOdd ? '[]' : '["...", "...", "...", "..."]'}, "correct": "..." } [/DATA_LOGICA]
  `;

  return ai.chats.create({
    model: 'gemini-3-flash-preview',
    config: { systemInstruction },
    history: prepareHistoryForGemini(history)
  });
};

export const generateExam = async (lessonTitle: string, chatHistory: any[]) => {
  const ai = getAIInstance();
  const historyContext = (chatHistory || [])
    .filter(m => m.parts && m.parts[0]?.text)
    .slice(-15)
    .map(m => `${m.role === 'user' ? 'Estudiante' : 'Tutor'}: ${m.parts[0].text}`)
    .join('\n');

  const examPrompt = `
    Genera un examen de 10 preguntas MCQ sobre "${lessonTitle}".
    Procesamiento de texto puro. Sin cambios de UI.

    REGLA DE EXPLICACIÓN (PEDAGOGÍA ESTRICTA):
    - El campo 'explanation' DEBE ser una justificación técnica completa.
    - Debe explicar por qué la respuesta correcta es válida.
    - Debe explicar por qué las otras opciones (distractores) son incorrectas o en qué contexto se suelen confundir.

    REGLA DE ALEATORIZACIÓN DE RESPUESTAS (ESTRICTA):
    1. Distribución Azarosa del contenido para que la correcta pueda ser A, B, C o D.
    2. Sin patrones consecutivos.

    Contexto: ${historyContext}
  `;

  const response = await ai.models.generateContent({
    model: 'gemini-3-pro-preview',
    contents: [{ role: 'user', parts: [{ text: examPrompt }] }],
    config: {
      responseMimeType: "application/json",
      responseSchema: {
        type: Type.OBJECT,
        properties: {
          questions: {
            type: Type.ARRAY,
            items: {
              type: Type.OBJECT,
              properties: {
                id: { type: Type.INTEGER },
                text: { type: Type.STRING },
                type: { type: Type.STRING },
                options: { type: Type.ARRAY, items: { type: Type.STRING } },
                correctAnswer: { type: Type.STRING },
                explanation: { type: Type.STRING }
              },
              required: ["id", "text", "type", "correctAnswer", "explanation", "options"]
            }
          }
        },
        required: ["questions"]
      }
    }
  });

  try {
    const cleaned = cleanJsonResponse(response.text || '');
    const examData = JSON.parse(cleaned || '{"questions": []}');
    if (examData.questions) {
      examData.questions = examData.questions.map((q: any) => {
        const cleanStr = (s: string) => (typeof s === 'string') ? s.replace(/^[A-Z]\)\s*/, '') : s;
        const correctText = cleanStr(q.correctAnswer);
        const shuffled = shuffleOptions(q.options.map(cleanStr));
        return { 
          ...q, 
          options: shuffled,
          correctAnswer: correctText
        };
      });
    }
    return examData;
  } catch (e) { return { questions: [] }; }
};

