const calculateLessonStatus = (lesson: Partial<Lesson>): 'Pendiente' | 'En Progreso' | 'Aprobada' | 'Reprobada' | 'Completada' => {
  const interactions = lesson.validInteractionsCount || 0;
  const hasMessages = !!(lesson.chatHistory && lesson.chatHistory.length > 0);
  const grade = lesson.grade;
  const currentStatus = lesson.lesson_status;

  if (grade !== undefined && grade !== null && grade >= 6) {
    return (currentStatus === 'Completada') ? 'Completada' : 'Aprobada';
  }
  if (grade !== undefined && grade !== null && grade > 0 && grade < 6) {
    return 'Reprobada';
  }
  if ((interactions > 0 || hasMessages) && (grade === undefined || grade === null || grade === 0)) {
    return 'En Progreso';
  }
  return 'Pendiente';
};

export const autoUpdateLessonStatuses = async (username: string) => {
  try {
    await supabase.from('lessons').update({ lesson_status: 'Aprobada', completed: true }).eq('student_username', username).gte('grade', 6);
    await supabase.from('lessons').update({ lesson_status: 'Reprobada', completed: false }).eq('student_username', username).gt('grade', 0).lt('grade', 6);
    await supabase.from('lessons').update({ lesson_status: 'En Progreso' }).eq('student_username', username).or('grade.is.null,grade.eq.0').gt('valid_interactions_count', 0);
  } catch (err) {
    console.error("Error en auto-actualización de estatus:", err);
  }
};

