// --- LECCIONES ASIGNADAS ---
export const getStudentData = async (username: string): Promise<StudentData | null> => {
  const { data, error } = await supabase.from('lessons').select('*').eq('student_username', username);
  if (error) return null;
  const mappedLessons: Lesson[] = (data || []).map(row => {
    // Correct mapping of DB snake_case columns to camelCase properties of Lesson interface
    const rawLesson: Lesson = {
      id: row.id.toString(),
      subject: row.subject,
      title: row.topic,
      durationMinutes: row.duration_minutes,
      completed: row.completed,
      date: row.date,
      elapsedSeconds: row.elapsed_seconds || 0,
      actualDurationMinutes: row.actual_duration_minutes || 0, 
      validInteractionsCount: row.valid_interactions_count || 0,
      grade: row.grade,
      learningPrompt: row.learning_prompt,
      chatHistory: row.chat_history || [],
      credits_transfered: row.credits_transfered,
      lesson_status: row.lesson_status
    };
    return { ...rawLesson, lesson_status: calculateLessonStatus(rawLesson) };
  });
  return { username, lessons: mappedLessons };
};

export const deleteLessonFromStudent = async (lessonId: string) => {
  const idToUse = /^\d+$/.test(lessonId) ? parseInt(lessonId, 10) : lessonId;
  const { error } = await supabase.from('lessons').delete().eq('id', idToUse);
  if (error) throw error;
};

export const clearLessonChatHistory = async (lessonId: string) => {
  const idToUse = /^\d+$/.test(lessonId) ? parseInt(lessonId, 10) : lessonId;
  const { error } = await supabase
    .from('lessons')
    .update({
      chat_history: [],
      elapsed_seconds: 0,
      actual_duration_minutes: 0,
      valid_interactions_count: 0,
      grade: null,
      completed: false,
      lesson_status: 'Pendiente'
    }).eq('id', idToUse);
  if (error) throw error;
};

export const addLessonToStudent = async (username: string, lesson: Lesson) => {
  // Correctly access lesson properties (camelCase) when preparing insert for Supabase (snake_case columns)
  await supabase.from('lessons').insert([{
    student_username: username,
    subject: lesson.subject,
    topic: lesson.title,
    duration_minutes: lesson.durationMinutes,
    completed: false,
    date: lesson.date,
    elapsed_seconds: 0,
    actual_duration_minutes: 0,
    valid_interactions_count: 0,
    learning_prompt: lesson.learningPrompt || null,
    chat_history: [],
    lesson_status: 'Pendiente'
  }]);
};

export const updateLessonInStudent = async (username: string, updatedLesson: Lesson) => {
  const idToUse = /^\d+$/.test(updatedLesson.id) ? parseInt(updatedLesson.id, 10) : updatedLesson.id;
  const status = calculateLessonStatus(updatedLesson);
  // Correctly access updatedLesson properties (camelCase) when preparing update for Supabase (snake_case columns)
  const { error } = await supabase.from('lessons').update({
    subject: updatedLesson.subject,
    topic: updatedLesson.title,
    duration_minutes: updatedLesson.durationMinutes,
    completed: (status === 'Aprobada' || status === 'Completada'),
    date: updatedLesson.date,
    actual_duration_minutes: updatedLesson.actualDurationMinutes,
    elapsed_seconds: updatedLesson.elapsedSeconds,
    valid_interactions_count: updatedLesson.validInteractionsCount,
    grade: updatedLesson.grade,
    learning_prompt: updatedLesson.learningPrompt,
    chat_history: updatedLesson.chatHistory,
    credits_transfered: updatedLesson.credits_transfered,
    lesson_status: status
  }).eq('id', idToUse);
  if (error) throw error;
};

export const deleteLessonsBySubjectAndDays = async (username: string, subject: string, days: boolean[], startDate: string) => {
  const { data, error } = await supabase.from('lessons').select('id, date').eq('student_username', username).eq('subject', subject).gte('date', startDate);
  if (error || !data) return;
  const idsToDelete = data.filter(row => {
    const d = new Date(row.date + 'T12:00:00');
    return days[(d.getDay() + 6) % 7];
  }).map(row => row.id);
  if (idsToDelete.length > 0) await supabase.from('lessons').delete().in('id', idsToDelete);
};

export const updateLessonsPromptByCriteria = async (username: string, subject: string, days: boolean[], startDate: string, prompt: string) => {
  const { data, error } = await supabase.from('lessons').select('id, date').eq('student_username', username).eq('subject', subject).gte('date', startDate);
  if (error || !data) return;
  const idsToUpdate = data.filter(row => {
    const d = new Date(row.date + 'T12:00:00');
    return days[(d.getDay() + 6) % 7];
  }).map(row => row.id);
  if (idsToUpdate.length > 0) await supabase.from('lessons').update({ learning_prompt: prompt }).in('id', idsToUpdate);
};

import React, { useState, useEffect, useMemo } from 'react';
import { User, StudentData, Lesson, Transaction, Role } from '../types';
import { 
  getStudentData, 
  executeCreditTransfer, 
  getTransactions, 
  getAccountBalance, 
  autoUpdateLessonStatuses,
  updateLessonInStudent,
  deleteLessonFromStudent,
  clearLessonChatHistory,
  getUsers,
  executeStudentTransfer
} from '../storage2';
import Calendar from './Calendar';

interface StudentDashboardProps {
  user: User;
  onStartLesson: (username: string, lessonId: string) => void;
  onBalanceUpdate?: () => void;
  isAdminView?: boolean;
  onAuditLesson?: (lesson: Lesson) => void;
  onEditLessonDetails?: (lesson: Lesson) => void;
  initialSelectedDate?: string | null;
  lastFinishedLessonId?: string | null;
}

const StudentDashboard: React.FC<StudentDashboardProps> = ({ 
  user, 
  onStartLesson, 
  onBalanceUpdate,
  isAdminView = false,
  onAuditLesson,
  onEditLessonDetails,
  initialSelectedDate,
  lastFinishedLessonId: propsLastFinishedId
}) => {
  const [activeSubTab, setActiveSubTab] = useState<'aula' | 'banco'>('aula');
  const [data, setData] = useState<StudentData | null>(null);
  const [transactions, setTransactions] = useState<Transaction[]>([]);
  const [currentBalance, setCurrentBalance] = useState(0);

  const [quickEditLessonId, setQuickEditLessonId] = useState<string | null>(null);
  const [isUpdating, setIsUpdating] = useState(false);

  // Estados para transferencia entre estudiantes
  const [otherStudents, setOtherStudents] = useState<User[]>([]);
  const [transferTo, setTransferTo] = useState('');
  const [transferAmount, setTransferAmount] = useState('');
  const [transferConcept, setTransferConcept] = useState('');
  const [isTransferringFunds, setIsTransferringFunds] = useState(false);

  const ADMIN_UUID = '6a6db323-6229-42e3-a8b8-3ccfa177dfd7';

  const getLocalDateStr = (d: Date = new Date()) => {
    const year = d.getFullYear();
    const month = String(d.getMonth() + 1).padStart(2, '0');
    const day = String(d.getDate()).padStart(2, '0');
    return `${year}-${month}-${day}`;
  };

  const [selectedDay, setSelectedDay] = useState<string | null>(initialSelectedDate || getLocalDateStr());
  const [dayLessons, setDayLessons] = useState<Lesson[]>([]);
  const [isLoading, setIsLoading] = useState(true);
  const [isTransferring, setIsTransferring] = useState(false);

  const getMonday = (d: Date) => {
    const date = new Date(d);
    const day = date.getDay();
    const diff = date.getDate() - day + (day === 0 ? -6 : 1);
    const monday = new Date(date.setDate(diff));
    monday.setHours(0, 0, 0, 0); 
    return monday;
  };
  const [weekStart, setWeekStart] = useState(() => getMonday(new Date()));

  const fetchData = async () => {
    setIsLoading(true);
    try {
      if (!isAdminView) await autoUpdateLessonStatuses(user.username);

      const ownerId = user.id || user.username;
      const [studentData, history, balance, allUsers] = await Promise.all([
        getStudentData(user.username),
        getTransactions(ownerId),
        getAccountBalance(ownerId),
        getUsers()
      ]);
      setData(studentData);
      setTransactions(history);
      setCurrentBalance(balance);
      setOtherStudents(allUsers.filter(u => (u.id || u.username) !== ownerId && u.role === Role.STUDENT));
    } catch (error) {
      console.error("Error cargando datos:", error);
    } finally {
      setIsLoading(false);
    }
  };

  useEffect(() => { fetchData(); }, [user.username]);

  useEffect(() => {
    if (data && selectedDay) {
      const lessons = data.lessons.filter(l => l.date === selectedDay) || [];
      setDayLessons(lessons);
    }
  }, [selectedDay, data]);

  const currentWeekLessons = useMemo(() => {
    if (!data) return [];
    const monday = new Date(weekStart);
    const sunday = new Date(monday);
    sunday.setDate(monday.getDate() + 6);
    sunday.setHours(23, 59, 59, 999);

    return data.lessons.filter(l => {
      const lDate = new Date(l.date + 'T12:00:00');
      return lDate >= monday && lDate <= sunday;
    });
  }, [data, weekStart]);

  const creditsTransferable = useMemo(() => {
    return currentWeekLessons
      .filter(l => (l.lesson_status === 'Aprobada' || l.lesson_status === 'Completada' || (l.grade && l.grade >= 6)) && !l.credits_transfered)
      .reduce((acc, l) => acc + (l.grade || 0), 0);
  }, [currentWeekLessons]);

  const creditsToWin = useMemo(() => {
    return currentWeekLessons
      .filter(l => (l.lesson_status !== 'Aprobada' && l.lesson_status !== 'Completada' && (!l.grade || l.grade < 6)) && !l.credits_transfered)
      .length * 10;
  }, [currentWeekLessons]);

  const dayCredits = useMemo(() => {
    return dayLessons.reduce((acc, l) => acc + (l.grade || 0), 0);
  }, [dayLessons]);

  const weeklyStats = useMemo(() => {
    return currentWeekLessons.reduce((acc, l) => {
      const status = (l.lesson_status || 'Pendiente').toLowerCase();
      if (status === 'aprobada' || status === 'completada') acc.passed += 1;
      else if (status === 'reprobada') acc.failed += 1;
      else if (status === 'en progreso') acc.inProgress += 1;
      else acc.pending += 1;
      acc.total += 1;
      return acc;
    }, { passed: 0, failed: 0, inProgress: 0, pending: 0, total: 0 });
  }, [currentWeekLessons]);

  const handleTransfer = async () => {
    if (creditsTransferable <= 0 || isTransferring || isAdminView) return;

    // Restricción de fin de semana: Sábados (6) o Domingos (0)
    const today = new Date();
    const dayOfWeek = today.getDay();
    const isWeekend = dayOfWeek === 0 || dayOfWeek === 6;

    if (!isWeekend) {
      alert("¡Hola! Recuerda que solo puedes transferir tus créditos al banco los fines de semana (Sábados y Domingos). ¡Sigue esforzándote en tus clases para ganar más!");
      return;
    }

    // NUEVA REGLA: Verificar que todas las lecciones de la semana visible estén Aprobadas o Completadas
    const hasIncompleteLessons = currentWeekLessons.some(l => 
      l.lesson_status !== 'Aprobada' && l.lesson_status !== 'Completada'
    );

    if (hasIncompleteLessons) {
      alert("Necesitas completar todas las lecciones de tu semana para poder transferir tus créditos al banco.");
      return;
    }

    const pendingLessons = currentWeekLessons.filter(l => 
      (l.lesson_status === 'Aprobada' || l.lesson_status === 'Completada' || (l.grade && l.grade >= 6)) 
      && !l.credits_transfered
    );

    const realSum = pendingLessons.reduce((acc, l) => acc + (l.grade || 0), 0);

    if (realSum !== creditsTransferable) {
      alert("No se pueden transferir créditos en este momento debido a una discrepancia de datos. Por favor, contacte a soporte.");
      return;
    }

    const Balance_Perdido = (pendingLessons.length * 10) - realSum;

    if (Balance_Perdido > 0) {
      const confirmUpsell = window.confirm(
        `Aún tienes un balance de ${Balance_Perdido} créditos que podrías haber generado en estas clases. ¿Deseas retomar las clases para maximizar tus créditos o prefieres transferir el monto actual ahora?`
      );
      if (!confirmUpsell) return;
    } else {
      const confirmFinal = window.confirm(`¿Confirmas la transferencia de $${realSum} a tu cuenta bancaria?`);
      if (!confirmFinal) return;
    }

    setIsTransferring(true);
    try {
      const lessonIds = pendingLessons.map(l => l.id);
      const weekStr = weekStart.toISOString().split('T')[0];
      const concept = `Créditos ganados por semana de estudio [${weekStr}]`;

      const studentId = user.id || user.username;
      await executeCreditTransfer(studentId, user.username, realSum, concept, lessonIds);

      alert("¡Transferencia exitosa! Tus créditos han sido enviados a tu cuenta bancaria de la plataforma.");

      if (data) {
        const updatedLessons = data.lessons.map(l => 
          lessonIds.includes(l.id) ? { ...l, credits_transfered: true } : l
        );
        setData({ ...data, lessons: updatedLessons });
      }

      await fetchData();
      if (onBalanceUpdate) onBalanceUpdate();
    } catch (err: any) {
      alert(`Error en la transferencia: ${err.message || "Error desconocido"}`);
    } finally {
      setIsTransferring(false);
    }
  };

  const handleFundsTransfer = async (e: React.FormEvent) => {
    e.preventDefault();
    if (isAdminView || isTransferringFunds) return;

    const amount = parseFloat(transferAmount);
    if (!transferTo || isNaN(amount) || amount <= 0 || !transferConcept) {
      alert("Por favor, completa todos los campos correctamente.");
      return;
    }

    if (amount > currentBalance) {
      alert(`Lo sentimos, no tienes fondos suficientes. Tu saldo actual es de $${currentBalance.toFixed(2)}.`);
      return;
    }

    const recipientName = transferTo === ADMIN_UUID ? 'el Banco (Administrador)' : (otherStudents.find(s => (s.id || s.username) === transferTo)?.username || 'un estudiante');
    if (!window.confirm(`¿Deseas transferir $${amount.toFixed(2)} a ${recipientName}?`)) return;

    setIsTransferringFunds(true);
    try {
      const fromId = user.id || user.username;
      await executeStudentTransfer(fromId, transferTo, amount, transferConcept);
      alert("¡Transferencia enviada con éxito!");
      setTransferAmount('');
      setTransferConcept('');
      setTransferTo('');
      await fetchData();
      if (onBalanceUpdate) onBalanceUpdate();
    } catch (err: any) {
      alert(`Error al realizar transferencia: ${err.message || "Error desconocido"}`);
    } finally {
      setIsTransferringFunds(false);
    }
  };

  const formatElapsedTime = (seconds: number) => {
    const mins = Math.floor(seconds / 60);
    const secs = seconds % 60;
    return `${mins}:${secs.toString().padStart(2, '0')}`;
  };

  const getLessonUIConfig = (status: string, isTransfered: boolean) => {
    const s = (status || 'Pendiente').toLowerCase();

    let config = { 
      color: 'bg-blue-600', 
      label: 'PENDIENTE', 
      btnText: isAdminView ? 'AUDITAR CLASE' : 'TOMAR CLASE 🚀',
      textColor: 'text-white'
    };

    if (s === 'aprobada' || s === 'completada') {
      config = isTransfered 
        ? { color: 'bg-green-800', label: (s === 'completada' ? 'COMPLETADA' : 'APROBADA') + ' (PAGADA)', btnText: 'AUDITAR LECCIÓN ✨', textColor: 'text-white' }
        : { color: 'bg-green-600', label: s === 'completada' ? 'COMPLETADA' : 'APROBADA', btnText: 'REPASAR LECCIÓN ✨', textColor: 'text-white' };
    } 
    else if (s === 'reprobada') {
      config = { color: 'bg-red-600', label: 'REPROBADA', btnText: isAdminView ? 'AUDITAR RESULTADO' : 'MEJORAR NOTA 🔁', textColor: 'text-white' };
    } 
    else if (s === 'en progreso') {
      config = { color: 'bg-orange-500', label: 'EN PROGRESO', btnText: isAdminView ? 'AUDITAR AVANCE' : 'RETOMAR CLASE 📚', textColor: 'text-white' };
    }

    return config;
  };

  const handleQuickUpdate = async (lesson: Lesson, updates: Partial<Lesson>) => {
    if (!isAdminView || isUpdating) return;
    setIsUpdating(true);
    try {
      const finalLesson = { ...lesson, ...updates };
      await updateLessonInStudent(user.username, finalLesson);
      await fetchData();
    } catch (err) {
      alert("Error al actualizar lección.");
    } finally {
      setIsUpdating(false);
    }
  };

  const handleDeleteLesson = async (lessonId: string) => {
    if (!isAdminView || isUpdating || !confirm("¿Eliminar esta lección permanentemente?")) return;
    setIsUpdating(true);
    try {
      await deleteLessonFromStudent(lessonId);
      await fetchData();
    } catch (err) {
      alert("Error al eliminar lección.");
    } finally {
      setIsUpdating(false);
    }
  };

  const handleClearHistory = async (lessonId: string) => {
    if (!isAdminView || isUpdating || !confirm("¿Borrar historial de chat y reiniciar progreso de esta lección?")) return;
    setIsUpdating(true);
    try {
      await clearLessonChatHistory(lessonId);
      await fetchData();
    } catch (err) {
      alert("Error al limpiar historial.");
    } finally {
      setIsUpdating(false);
    }
  };

  if (isLoading) return (
    <div className="flex flex-col items-center justify-center py-24">
      <div className="w-12 h-12 border-4 border-indigo-600 border-t-transparent rounded-full animate-spin mb-4"></div>
      <p className="text-indigo-900 dark:text-sky-100 font-bold">Espejando aula...</p>
    </div>
  );

  return (
    <div className="space-y-6 font-fredoka animate-in fade-in duration-500">
      <div className="flex bg-white dark:bg-indigo-900 p-2 rounded-2xl border-4 border-indigo-50 dark:border-indigo-800 shadow-sm w-fit">
        <button 
          onClick={() => setActiveSubTab('aula')} 
          className={`px-6 py-2 rounded-xl font-black text-xs uppercase transition-all flex items-center space-x-2 ${activeSubTab === 'aula' ? 'bg-indigo-600 text-white shadow-md' : 'text-indigo-400 hover:text-indigo-600'}`}
        >
          <span>Aula Virtual</span> <span>📚</span>
        </button>
        <button 
          onClick={() => setActiveSubTab('banco')} 
          className={`px-6 py-2 rounded-xl font-black text-xs uppercase transition-all flex items-center space-x-2 ${activeSubTab === 'banco' ? 'bg-amber-500 text-white shadow-md' : 'text-amber-500 hover:text-amber-600'}`}
        >
          <span>Estado de Cuenta</span> <span>🏦</span>
        </button>
      </div>

      {activeSubTab === 'aula' ? (
        <div className="space-y-6 animate-in slide-in-from-bottom-4 duration-500">
          <div className="bg-white dark:bg-indigo-900 p-6 rounded-[2.5rem] shadow-sm border-4 border-indigo-50 dark:border-indigo-800 flex flex-col md:flex-row items-center gap-6">
            <div className="flex items-center space-x-8 shrink-0">
               <div className="bg-amber-50 dark:bg-amber-900/30 px-6 py-4 rounded-2xl border-2 border-amber-100 dark:border-amber-800 shadow-inner flex flex-col items-center min-w-[160px]">
                  <p className="text-[10px] font-black text-amber-600 dark:text-amber-400 uppercase tracking-widest mb-1 text-center">CRÉDITOS TRANSFERIBLES</p>
                  <p className="text-3xl font-black text-amber-500 leading-none mb-2">⭐ {creditsTransferable}</p>
                  {!isAdminView && (
                    <button 
                      onClick={handleTransfer}
                      disabled={creditsTransferable <= 0 || isTransferring}
                      className={`text-[11px] font-black uppercase underline transition-all ${creditsTransferable > 0 && !isTransferring ? 'text-indigo-600 hover:text-indigo-800 cursor-pointer' : 'text-indigo-300 cursor-not-allowed'}`}
                    >
                      {isTransferring ? 'PROCESANDO...' : 'Transferir créditos al banco'}
                    </button>
                  )}
               </div>

               <div className="bg-indigo-50 dark:bg-indigo-950 px-6 py-4 rounded-2xl border-2 border-indigo-100 dark:border-indigo-800/50 shadow-inner flex flex-col items-center min-w-[160px]">
                  <p className="text-[10px] font-black text-indigo-400 dark:text-indigo-500 uppercase tracking-widest mb-1 text-center">CRÉDITOS POR GANAR</p>
                  <p className="text-3xl font-black text-indigo-300 dark:text-indigo-600 leading-none">⭐ {creditsToWin}</p>
               </div>
            </div>

            <div className="flex-1 w-full space-y-2">
              <div className="flex justify-between items-end px-1">
                <span className="text-[10px] font-black text-indigo-400 dark:text-indigo-500 uppercase tracking-widest">PROGRESO DE LA SEMANA</span>
                <div className="flex flex-wrap gap-3">
                  <span className="text-[9px] font-bold text-blue-600 dark:text-blue-400 uppercase flex items-center"><div className="w-2 h-2 rounded-full bg-blue-600 mr-1"></div> {weeklyStats.total > 0 ? Math.round((weeklyStats.pending/weeklyStats.total)*100) : 0}% Pendientes</span>
