import { User, Role, StudentData, Lesson, SubjectGuide, Transaction } from './types.ts';
import { supabase } from './supabaseClient.ts';

// ID del administrador central
const ADMIN_UUID = '6a6db323-6229-42e3-a8b8-3ccfa177dfd7';

export const initStorage = async () => {
  console.log("Supabase storage initialized (storage2)");
};

const calculateLessonStatus = (lesson: Partial<Lesson>): 'Pendiente' | 'En Progreso' | 'Aprobada' | 'Reprobada' | 'Completada' => {
  const interactions = lesson.validInteractionsCount || 0;
  const hasMessages = !!(lesson.chatHistory && lesson.chatHistory.length > 0);
  const grade = lesson.grade;
  const currentStatus = lesson.lesson_status;

  if (grade !== undefined && grade !== null && grade >= 6) {
    return (currentStatus === 'Completada') ? 'Completada' : 'Aprobada';
  }
  if (grade !== undefined && grade !== null && grade > 0 && grade < 6) {
    return 'Reprobada';
  }
  if ((interactions > 0 || hasMessages) && (grade === undefined || grade === null || grade === 0)) {
    return 'En Progreso';
  }
  return 'Pendiente';
};

export const autoUpdateLessonStatuses = async (username: string) => {
  try {
    await supabase.from('lessons').update({ lesson_status: 'Aprobada', completed: true }).eq('student_username', username).gte('grade', 6);
    await supabase.from('lessons').update({ lesson_status: 'Reprobada', completed: false }).eq('student_username', username).gt('grade', 0).lt('grade', 6);
    await supabase.from('lessons').update({ lesson_status: 'En Progreso' }).eq('student_username', username).or('grade.is.null,grade.eq.0').gt('valid_interactions_count', 0);
  } catch (err) {
    console.error("Error en auto-actualización de estatus:", err);
  }
};

// --- CUENTAS Y SALDOS ---

/**
 * Obtiene el balance de una cuenta filtrando por owner_id (UUID).
 */
export const getAccountBalance = async (ownerId: string): Promise<number> => {
  try {
    const { data, error } = await supabase
        .from('accounts')
        .select('balance')
        .eq('owner_id', ownerId)
        .maybeSingle(); 

    if (error) {
        console.error("Error al obtener balance:", error);
        return 0;
    }
    return data ? Number(data.balance) : 0;
  } catch (err) {
    console.error("Error crítico en getAccountBalance:", err);
    return 0;
  }
};

/**
 * Obtiene las transacciones de un estudiante (donde es el destinatario).
 */
export const getTransactions = async (ownerId: string): Promise<Transaction[]> => {
  const { data, error } = await supabase
    .from('transactions')
    .select('*')
    .or(`to_account.eq.${ownerId},from_account.eq.${ownerId}`)
    .order('created_at', { ascending: false });
  return error ? [] : (data || []);
};

/**
 * Obtiene el historial global de transacciones (para el Administrador).
 */
export const getAllTransactions = async (): Promise<Transaction[]> => {
  const { data, error } = await supabase
    .from('transactions')
    .select('*')
    .order('created_at', { ascending: false });
  return error ? [] : (data || []);
};

/**
 * Ejecuta la transferencia de créditos mediante el RPC 'transferir_creditos_estudiante'.
 */
export const executeCreditTransfer = async (studentId: string, studentUsername: string, amount: number, concept: string, lessonIds: string[]) => {
  if (lessonIds.length === 0) throw new Error("No hay lecciones seleccionadas.");

  const cleanAmount = Math.floor(amount);

  const { error } = await supabase.rpc('transferir_creditos_estudiante', {
    p_estudiante_id: String(studentId),       
    p_admin_id: ADMIN_UUID,                  
    p_lecciones_ids: lessonIds,              
    p_monto_total: cleanAmount,              
    p_username: studentUsername,             
    p_concept: concept                       
  });

  if (error) throw new Error(error.message);
};

/**
 * Ejecuta una transferencia manual (Ingreso o Egreso) para un estudiante.
 */
export const executeManualTransfer = async (studentId: string, amount: number, concept: string, isIncomeForStudent: boolean) => {
  const { error } = await supabase.rpc('transferencia_manual_admin', {
    p_estudiante_id: String(studentId),
    p_admin_id: ADMIN_UUID,
    p_monto: amount,
    p_concept: concept,
    p_es_ingreso: isIncomeForStudent
  });

  if (error) throw new Error(error.message);
};

/**
 * Ejecuta una transferencia desde la cuenta del estudiante a otro destino.
 */
export const executeStudentTransfer = async (fromId: string, toId: string, amount: number, concept: string) => {
  const { error } = await supabase.rpc('transferencia_estudiante', {
    p_from_id: String(fromId),
    p_to_id: String(toId),
    p_monto: Number(amount),
    p_concept: String(concept)
  });

  if (error) throw new Error(error.message);
};

// --- USUARIOS ---
export const getUsers = async (): Promise<User[]> => {
  const { data, error } = await supabase.from('users').select('*');
  return error ? [] : (data || []);
};

export const saveUser = async (user: User) => {
  const { error } = await supabase.from('users').insert([user]);
  if (error) throw error;
};

export const updateUser = async (originalUsername: string, updatedUser: User) => {
  const { error } = await supabase.from('users').update({
    username: updatedUser.username,
    email: updatedUser.email,
    password: updatedUser.password
  }).eq('username', originalUsername);
  if (error) throw error;
};

export const updateUserSession = async (username: string, sessionId: string | null) => {
  const { error } = await supabase.from('users').update({ current_session_id: sessionId }).eq('username', username);
  if (error) throw error;
};

export const deleteUser = async (username: string) => {
  await supabase.from('lessons').delete().eq('student_username', username);
  const { error } = await supabase.from('users').delete().eq('username', username);
  if (error) throw error;
};

// --- GUÍA DE MATERIAS ---
export const getSubjectsGuide = async (): Promise<SubjectGuide[]> => {
  const { data, error } = await supabase.from('subjects').select('*').order('name');
  return error ? [] : (data || []);
};

export const saveSubjectGuide = async (name: string, lessonsList: string, learning_prompt?: string) => {
  const { error } = await supabase.from('subjects').insert([{ name, lessons_list: lessonsList, learning_prompt }]);
  if (error) throw error;
};

export const updateSubjectGuide = async (id: string, name: string, lessonsList: string, learning_prompt?: string) => {
  const { error } = await supabase.from('subjects').update({ name, lessons_list: lessonsList, learning_prompt }).eq('id', id);
  if (error) throw error;
};

export const deleteSubjectGuide = async (id: string) => {
  const { error } = await supabase.from('subjects').delete().eq('id', id);
  if (error) throw error;
};

// --- LECCIONES ASIGNADAS ---
export const getStudentData = async (username: string): Promise<StudentData | null> => {
  const { data, error } = await supabase.from('lessons').select('*').eq('student_username', username);
  if (error) return null;
  const mappedLessons: Lesson[] = (data || []).map(row => {
    // Correct mapping of DB snake_case columns to camelCase properties of Lesson interface
    const rawLesson: Lesson = {
      id: row.id.toString(),
      subject: row.subject,
      title: row.topic,
      durationMinutes: row.duration_minutes,
      completed: row.completed,
      date: row.date,
      elapsedSeconds: row.elapsed_seconds || 0,
      actualDurationMinutes: row.actual_duration_minutes || 0, 
      validInteractionsCount: row.valid_interactions_count || 0,
      grade: row.grade,
      learningPrompt: row.learning_prompt,
      chatHistory: row.chat_history || [],
      credits_transfered: row.credits_transfered,
      lesson_status: row.lesson_status
    };
    return { ...rawLesson, lesson_status: calculateLessonStatus(rawLesson) };
  });
  return { username, lessons: mappedLessons };
};

export const deleteLessonFromStudent = async (lessonId: string) => {
  const idToUse = /^\d+$/.test(lessonId) ? parseInt(lessonId, 10) : lessonId;
  const { error } = await supabase.from('lessons').delete().eq('id', idToUse);
  if (error) throw error;
};

export const clearLessonChatHistory = async (lessonId: string) => {
  const idToUse = /^\d+$/.test(lessonId) ? parseInt(lessonId, 10) : lessonId;
  const { error } = await supabase
    .from('lessons')
    .update({
      chat_history: [],
      elapsed_seconds: 0,
      actual_duration_minutes: 0,
      valid_interactions_count: 0,
      grade: null,
      completed: false,
      lesson_status: 'Pendiente'
    }).eq('id', idToUse);
  if (error) throw error;
};

export const addLessonToStudent = async (username: string, lesson: Lesson) => {
  // Correctly access lesson properties (camelCase) when preparing insert for Supabase (snake_case columns)
  await supabase.from('lessons').insert([{
    student_username: username,
    subject: lesson.subject,
    topic: lesson.title,
    duration_minutes: lesson.durationMinutes,
    completed: false,
    date: lesson.date,
    elapsed_seconds: 0,
    actual_duration_minutes: 0,
    valid_interactions_count: 0,
    learning_prompt: lesson.learningPrompt || null,
    chat_history: [],
    lesson_status: 'Pendiente'
  }]);
};

export const updateLessonInStudent = async (username: string, updatedLesson: Lesson) => {
  const idToUse = /^\d+$/.test(updatedLesson.id) ? parseInt(updatedLesson.id, 10) : updatedLesson.id;
  const status = calculateLessonStatus(updatedLesson);
  // Correctly access updatedLesson properties (camelCase) when preparing update for Supabase (snake_case columns)
  const { error } = await supabase.from('lessons').update({
    subject: updatedLesson.subject,
    topic: updatedLesson.title,
    duration_minutes: updatedLesson.durationMinutes,
    completed: (status === 'Aprobada' || status === 'Completada'),
    date: updatedLesson.date,
    actual_duration_minutes: updatedLesson.actualDurationMinutes,
    elapsed_seconds: updatedLesson.elapsedSeconds,
    valid_interactions_count: updatedLesson.validInteractionsCount,
    grade: updatedLesson.grade,
    learning_prompt: updatedLesson.learningPrompt,
    chat_history: updatedLesson.chatHistory,
    credits_transfered: updatedLesson.credits_transfered,
    lesson_status: status
  }).eq('id', idToUse);
  if (error) throw error;
};

export const deleteLessonsBySubjectAndDays = async (username: string, subject: string, days: boolean[], startDate: string) => {
  const { data, error } = await supabase.from('lessons').select('id, date').eq('student_username', username).eq('subject', subject).gte('date', startDate);
  if (error || !data) return;
  const idsToDelete = data.filter(row => {
    const d = new Date(row.date + 'T12:00:00');
    return days[(d.getDay() + 6) % 7];
  }).map(row => row.id);
  if (idsToDelete.length > 0) await supabase.from('lessons').delete().in('id', idsToDelete);
};

export const updateLessonsPromptByCriteria = async (username: string, subject: string, days: boolean[], startDate: string, prompt: string) => {
  const { data, error } = await supabase.from('lessons').select('id, date').eq('student_username', username).eq('subject', subject).gte('date', startDate);
  if (error || !data) return;
  const idsToUpdate = data.filter(row => {
    const d = new Date(row.date + 'T12:00:00');
    return days[(d.getDay() + 6) % 7];
  }).map(row => row.id);
  if (idsToUpdate.length > 0) await supabase.from('lessons').update({ learning_prompt: prompt }).in('id', idsToUpdate);
};

