import AdminDashboard from './components/AdminDashboard.tsx';
import StudentDashboard from './components/StudentDashboard.tsx';
import LessonWindow from './components/LessonWindow2.tsx';
import { Moon, Sun, Shield, LogOut, Wallet } from 'lucide-react';

const App: React.FC = () => {
  const [currentUser, setCurrentUser] = useState<User | null>(null);
  const [activeLesson, setActiveLesson] = useState<{ studentUsername: string; lessonId: string; isAudit?: boolean } | null>(null);
  const [isInitializing, setIsInitializing] = useState(true);
  const [darkMode, setDarkMode] = useState(() => localStorage.getItem('theme') === 'dark');
  const [totalBalance, setTotalBalance] = useState(0);

  const [tabSessionId] = useState(() => Math.random().toString(36).substring(2, 15));
  const [showDuplicateModal, setShowDuplicateModal] = useState(false);
  const sessionSubscriptionRef = useRef<any>(null);

  const [showPasswordModal, setShowPasswordModal] = useState(false);
  const [currentPass, setCurrentPass] = useState('');
  const [newPass, setNewPass] = useState('');
  const [confirmPass, setConfirmPass] = useState('');
  const [passError, setPassError] = useState('');
  const [isUpdatingPass, setIsUpdatingPass] = useState(false);

  const [lastFinishedLessonId, setLastFinishedLessonId] = useState<string | null>(null);
  const [lastFinishedDate, setLastFinishedDate] = useState<string | null>(null);

  /**
   * Función para obtener el balance actual del estudiante.
   * Utiliza el ID (UUID) si está disponible, sino el username.
   */
  const fetchUserBalance = async (user: User) => {
    try {
      const ownerId = user.id || user.username;
      const balance = await getAccountBalance(ownerId);
      setTotalBalance(balance);
      return balance;
    } catch (err) {
      console.error("Error al obtener balance:", err);
      return 0;
    }
  };

  const setupSessionListener = (username: string) => {
    if (sessionSubscriptionRef.current) {
      supabase.removeChannel(sessionSubscriptionRef.current);
    }

    const channel = supabase
      .channel(`user-session-${username}`)
      .on(
        'postgres_changes',
        {
          event: 'UPDATE',
          schema: 'public',
          table: 'users',
          filter: `username=eq.${username}`
        },
        (payload) => {
          const remoteSessionId = payload.new.current_session_id;
          if (remoteSessionId && remoteSessionId !== tabSessionId) {
            setShowDuplicateModal(true);
          }
        }
      )
      .subscribe();

    sessionSubscriptionRef.current = channel;
  };

  // Escucha de cambios en tiempo real en la tabla USERS para el balance
  useEffect(() => {
    if (currentUser && currentUser.role === Role.STUDENT) {
      const filter = currentUser.id 
        ? `id=eq.${currentUser.id}` 
        : `username=eq.${currentUser.username}`;

      const channel = supabase
        .channel(`user-balance-changes-${currentUser.username}`)
        .on(
          'postgres_changes',
          {
            event: 'UPDATE',
            schema: 'public',
            table: 'users',
            filter: filter
          },
          (payload) => {
            // Si el balance cambió, actualizamos el estado local
            if (payload.new && typeof payload.new.balance !== 'undefined') {
              setTotalBalance(Number(payload.new.balance));
            }
          }
        )
        .subscribe();

      return () => {
        supabase.removeChannel(channel);
      };
    }
  }, [currentUser]);

  useEffect(() => {
    const loadApp = async () => {
      await initStorage();
      const storedUser = localStorage.getItem('current_user');
      if (storedUser) {
        const user = JSON.parse(storedUser);
        setCurrentUser(user);
        if (user.role === Role.STUDENT) {
          await autoUpdateLessonStatuses(user.username);
          fetchUserBalance(user);
          setupSessionListener(user.username);
          updateUserSession(user.username, tabSessionId);
        }
      }
      setIsInitializing(false);
    };
    loadApp();

    return () => {
      if (sessionSubscriptionRef.current) {
        supabase.removeChannel(sessionSubscriptionRef.current);
      }
    };
  }, []);

  useEffect(() => {
    if (darkMode) {
      document.documentElement.classList.add('dark');
      localStorage.setItem('theme', 'dark');
    } else {
      document.documentElement.classList.remove('dark');
      localStorage.setItem('theme', 'light');
    }
  }, [darkMode]);

  const handleLogin = async (user: User) => {
    setCurrentUser(user);
    localStorage.setItem('current_user', JSON.stringify(user));
    if (user.role === Role.STUDENT) {
      await autoUpdateLessonStatuses(user.username);
      fetchUserBalance(user);
      setupSessionListener(user.username);
      await updateUserSession(user.username, tabSessionId);
    }
  };

  const handleLogout = () => {
    if (currentUser) {
      updateUserSession(currentUser.username, null).catch(console.error);
    }
    setCurrentUser(null);
    setTotalBalance(0);
    setShowDuplicateModal(false);
    localStorage.removeItem('current_user');
    if (sessionSubscriptionRef.current) {
      supabase.removeChannel(sessionSubscriptionRef.current);
    }
  };

  const handleResumeHere = async () => {
    if (currentUser) {
      await updateUserSession(currentUser.username, tabSessionId);
      setShowDuplicateModal(false);
    }
  };

  const startLesson = (studentUsername: string, lessonId: string, isAudit: boolean = false) => {
    setLastFinishedLessonId(null);
    setLastFinishedDate(null);
    setActiveLesson({ studentUsername, lessonId, isAudit });
  };

  const handleUpdatePassword = async (e: React.FormEvent) => {
    e.preventDefault();
    setPassError('');
    if (!currentUser) return;

    if (currentPass !== currentUser.password) {
      setPassError('La contraseña actual es incorrecta.');
      return;
    }
    if (newPass.length < 4 || newPass.length > 8) {
      setPassError('La nueva contraseña debe tener entre 4 y 8 caracteres.');
      return;
    }
    if (newPass !== confirmPass) {
      setPassError('Las contraseñas nuevas no coinciden.');
      return;
    }

    setIsUpdatingPass(true);
    try {
      const updatedUser: User = { ...currentUser, password: newPass };
      await updateUser(currentUser.username, updatedUser);
      setCurrentUser(updatedUser);
      localStorage.setItem('current_user', JSON.stringify(updatedUser));
      setShowPasswordModal(false);
      setCurrentPass('');
      setNewPass('');
      setConfirmPass('');
      alert('¡Contraseña actualizada con éxito!');
    } catch (err) {
      setPassError('Error al actualizar. Intenta más tarde.');
    } finally {
      setIsUpdatingPass(false);
    }
  };

  if (isInitializing) {
    return (
      <div className="min-h-screen flex flex-col items-center justify-center bg-sky-50 dark:bg-indigo-950 transition-colors duration-500">
        <div className="w-16 h-16 border-4 border-indigo-600 border-t-transparent rounded-full animate-spin mb-4"></div>
        <p className="text-indigo-900 dark:text-sky-100 font-bold animate-pulse text-xl">Buensoft Education se está preparando...</p>
      </div>
    );
  }

  if (activeLesson) {
    return (
      <LessonWindow 
        studentUsername={activeLesson.studentUsername} 
        lessonId={activeLesson.lessonId}
        isAdminAudit={activeLesson.isAudit}
        onClose={(finishedDate, finishedId) => {
          setActiveLesson(null);
          if (finishedDate) setLastFinishedDate(finishedDate);
          if (finishedId) setLastFinishedLessonId(finishedId);
          if (currentUser && currentUser.role === Role.STUDENT) {
            fetchUserBalance(currentUser);
          }
        }} 
      />
    );
  }

  if (!currentUser) {
    return <Login onLogin={handleLogin} />;
  }

  return (
    <div className="min-h-screen bg-sky-50 dark:bg-indigo-950 transition-colors duration-300">
      <nav className="bg-white/80 dark:bg-indigo-900/80 backdrop-blur-md shadow-md p-4 flex justify-between items-center sticky top-0 z-[100] border-b dark:border-indigo-800 transition-colors duration-300">
        <div className="flex items-center space-x-3">
          <img src="https://buensoft.com/assets/Buensoft_Education_Logo.png" alt="Logo" className="w-10 h-10 md:w-12 md:h-12 object-contain rounded-lg shadow-sm" />
          <h1 className="text-lg md:text-xl font-black text-indigo-900 dark:text-white uppercase tracking-tight hidden sm:block">Buensoft Education</h1>
        </div>

        <div className="flex items-center space-x-2 sm:space-x-4">
          <div className="flex flex-col items-end">
            <span className="text-indigo-600 dark:text-indigo-200 font-bold text-xs">Hola, {currentUser.username}</span>
            <button 
              onClick={() => setShowPasswordModal(true)}
              className="text-[9px] font-black text-indigo-400 dark:text-indigo-500 hover:text-indigo-600 uppercase tracking-tighter underline flex items-center space-x-1"
            >
              <Shield size={8} /> <span>Seguridad</span>
            </button>
          </div>

          {currentUser.role === Role.STUDENT && (
            <div className="flex flex-col items-center px-4 py-1.5 bg-amber-50 dark:bg-amber-900/20 rounded-2xl border-2 border-amber-100 dark:border-amber-800 shadow-inner">
              <span className="text-[8px] font-black text-amber-600 dark:text-amber-400 uppercase flex items-center space-x-1">
                <Wallet size={8} /> <span>MI BANCO</span>
              </span>
              <span className="text-sm font-black text-amber-500 leading-none">MXN ${totalBalance.toFixed(2)}</span>
            </div>
          )}

          <button 
            onClick={() => setDarkMode(!darkMode)}
            className="flex items-center justify-center w-9 h-9 rounded-xl bg-indigo-50 dark:bg-indigo-800 text-indigo-600 dark:text-amber-400 hover:scale-105 active:scale-95 transition-all shadow-sm"
          >
            {darkMode ? <Sun size={18} /> : <Moon size={18} />}
          </button>

          <button 
            onClick={handleLogout}
            className="bg-red-500 hover:bg-red-600 text-white p-2.5 rounded-xl transition-all shadow-lg hover:scale-105 active:scale-95 flex items-center"
          >
            <LogOut size={18} />
          </button>
        </div>
      </nav>

      <main className="container mx-auto px-4 py-8 max-w-7xl">
        {currentUser.role === Role.ADMIN ? (
          <AdminDashboard user={currentUser} />
        ) : (
          <StudentDashboard 
            user={currentUser} 
            onStartLesson={startLesson} 
            onAuditLesson={(lesson) => startLesson(currentUser.username, lesson.id, true)}
            onBalanceUpdate={() => fetchUserBalance(currentUser)}
            initialSelectedDate={lastFinishedDate}
            lastFinishedLessonId={lastFinishedLessonId}
          />
        )}
      </main>

      {/* Duplicate Session Modal */}
      {showDuplicateModal && (
        <div className="fixed inset-0 bg-indigo-900/90 backdrop-blur-md z-[1000] flex items-center justify-center p-4">
          <div className="bg-white dark:bg-indigo-900 p-10 rounded-[3rem] w-full max-w-lg shadow-2xl border-8 border-indigo-50 dark:border-indigo-800 text-center animate-in zoom-in duration-300">
            <div className="text-7xl mb-8">🚫</div>
            <h2 className="text-2xl font-black text-indigo-900 dark:text-white mb-4 uppercase">Sesión Duplicada</h2>
            <p className="text-indigo-400 dark:text-indigo-300 font-bold mb-8 text-sm">
              Se ha detectado otra sesión activa. Por seguridad, solo se permite una pestaña abierta.
            </p>
            <div className="flex flex-col space-y-3">
              <button 
                onClick={handleResumeHere}
                className="w-full bg-indigo-600 text-white font-black py-4 rounded-2xl shadow-xl uppercase text-xs hover:bg-indigo-700 transition-all"
              >
                Retomar aquí 🚀
              </button>
              <button 
                onClick={handleLogout}
                className="w-full bg-slate-100 dark:bg-indigo-950 text-indigo-400 font-black py-4 rounded-2xl uppercase text-xs transition-all"
              >
                Cerrar sesión 👋
              </button>
            </div>
          </div>
        </div>
      )}

      {/* Password Modal */}
      {showPasswordModal && (
        <div className="fixed inset-0 bg-indigo-900/60 backdrop-blur-sm z-[250] flex items-center justify-center p-4">
          <div className="bg-white dark:bg-indigo-900 p-8 rounded-[2.5rem] w-full max-w-sm shadow-2xl border-8 border-indigo-50 dark:border-indigo-800">
            <h2 className="text-2xl font-black text-indigo-900 dark:text-white mb-6 uppercase flex items-center space-x-2">
              <Shield className="text-indigo-600" /> <span>Seguridad</span>
            </h2>
            <form onSubmit={handleUpdatePassword} className="space-y-4">
              <div>
                <label className="block text-[10px] font-black text-indigo-400 dark:text-indigo-500 uppercase tracking-widest mb-1.5 ml-2">Contraseña Actual</label>
                <input 
                  type="password" 
                  value={currentPass} 
                  onChange={e=>setCurrentPass(e.target.value)} 
                  className="w-full p-4 bg-indigo-50 dark:bg-indigo-950 rounded-2xl font-bold border-2 border-transparent dark:text-white focus:border-indigo-500 outline-none transition-all" 
                  required 
                />
              </div>
              <div>
                <label className="block text-[10px] font-black text-indigo-400 dark:text-indigo-500 uppercase tracking-widest mb-1.5 ml-2">Nueva Contraseña (4-8 dígitos)</label>
                <input 
                  type="password" 
                  value={newPass} 
                  onChange={e=>setNewPass(e.target.value)} 
                  className="w-full p-4 bg-indigo-50 dark:bg-indigo-950 rounded-2xl font-bold border-2 border-transparent dark:text-white focus:border-indigo-500 outline-none transition-all" 
                  required 
                />
              </div>
              <div>
                <label className="block text-[10px] font-black text-indigo-400 dark:text-indigo-500 uppercase tracking-widest mb-1.5 ml-2">Confirmar Nueva</label>
                <input 
                  type="password" 
                  value={confirmPass} 
                  onChange={e=>setConfirmPass(e.target.value)} 
                  className="w-full p-4 bg-indigo-50 dark:bg-indigo-950 rounded-2xl font-bold border-2 border-transparent dark:text-white focus:border-indigo-500 outline-none transition-all" 
                  required 
                />
              </div>
              {passError && <p className="text-red-500 text-[10px] font-bold text-center bg-red-50 p-2 rounded-xl">{passError}</p>}
              <div className="flex space-x-3 pt-4">
                <button type="button" onClick={()=>setShowPasswordModal(false)} className="flex-1 font-black text-indigo-400 uppercase text-xs">CANCELAR</button>
                <button type="submit" disabled={isUpdatingPass} className="flex-1 bg-indigo-600 text-white font-black py-4 rounded-2xl shadow-lg uppercase text-xs hover:bg-indigo-700 transition-all active:scale-95 disabled:opacity-50">
                  {isUpdatingPass ? 'GUARDANDO...' : 'ACTUALIZAR'}
                </button>
              </div>
            </form>
          </div>
        </div>
      )}
    </div>
  );
};

export default App;

import { User, Role, StudentData, Lesson, SubjectGuide, Transaction } from './types.ts';
import { supabase } from './supabaseClient.ts';

// ID del administrador central
const ADMIN_UUID = '6a6db323-6229-42e3-a8b8-3ccfa177dfd7';

export const initStorage = async () => {
  console.log("Supabase storage initialized (storage2)");
};

const calculateLessonStatus = (lesson: Partial<Lesson>): 'Pendiente' | 'En Progreso' | 'Aprobada' | 'Reprobada' | 'Completada' => {
  const interactions = lesson.validInteractionsCount || 0;
  const hasMessages = !!(lesson.chatHistory && lesson.chatHistory.length > 0);
  const grade = lesson.grade;
  const currentStatus = lesson.lesson_status;

  if (grade !== undefined && grade !== null && grade >= 6) {
    return (currentStatus === 'Completada') ? 'Completada' : 'Aprobada';
  }
  if (grade !== undefined && grade !== null && grade > 0 && grade < 6) {
    return 'Reprobada';
  }
  if ((interactions > 0 || hasMessages) && (grade === undefined || grade === null || grade === 0)) {
    return 'En Progreso';
  }
  return 'Pendiente';
};

export const autoUpdateLessonStatuses = async (username: string) => {
  try {
    await supabase.from('lessons').update({ lesson_status: 'Aprobada', completed: true }).eq('student_username', username).gte('grade', 6);
    await supabase.from('lessons').update({ lesson_status: 'Reprobada', completed: false }).eq('student_username', username).gt('grade', 0).lt('grade', 6);
    await supabase.from('lessons').update({ lesson_status: 'En Progreso' }).eq('student_username', username).or('grade.is.null,grade.eq.0').gt('valid_interactions_count', 0);
  } catch (err) {
    console.error("Error en auto-actualización de estatus:", err);
  }
};

// --- CUENTAS Y SALDOS (CENTRALIZADOS EN TABLA USERS) ---

/**
 * Obtiene el balance de un usuario directamente desde la tabla 'users'.
 */
export const getAccountBalance = async (ownerId: string): Promise<number> => {
  try {
    const { data, error } = await supabase
        .from('users')
        .select('balance')
        .or(`id.eq.${ownerId},username.eq.${ownerId}`)
        .maybeSingle(); 

    if (error) {
        console.error("Error al obtener balance:", error);
        return 0;
    }
    return data ? Number(data.balance || 0) : 0;
  } catch (err) {
    console.error("Error crítico en getAccountBalance:", err);
    return 0;
  }
};

/**
 * Obtiene las transacciones de un estudiante (donde es el destinatario o emisor).
 */
export const getTransactions = async (ownerId: string): Promise<Transaction[]> => {
  const { data, error } = await supabase
    .from('transactions')
    .select('*')
    .or(`to_account.eq.${ownerId},from_account.eq.${ownerId}`)
    .order('created_at', { ascending: false });
  return error ? [] : (data || []);
};

/**
 * Obtiene el historial global de transacciones (para el Administrador).
 */
export const getAllTransactions = async (): Promise<Transaction[]> => {
  const { data, error } = await supabase
    .from('transactions')
    .select('*')
    .order('created_at', { ascending: false });
  return error ? [] : (data || []);
};

/**
 * Ejecuta la transferencia de créditos mediante el RPC 'transferir_creditos_estudiante'.
 */
export const executeCreditTransfer = async (studentId: string, studentUsername: string, amount: number, concept: string, lessonIds: string[]) => {
  if (lessonIds.length === 0) throw new Error("No hay lecciones seleccionadas.");

  const cleanAmount = Math.floor(amount);

  const { error } = await supabase.rpc('transferir_creditos_estudiante', {
    p_estudiante_id: String(studentId),       
    p_admin_id: ADMIN_UUID,                  
    p_lecciones_ids: lessonIds,              
    p_monto_total: cleanAmount,              
    p_username: studentUsername,             
    p_concept: concept                       
  });

  if (error) throw new Error(error.message);
};

/**
 * Ejecuta una transferencia manual (Ingreso o Egreso) para un estudiante.
 */
export const executeManualTransfer = async (studentId: string, amount: number, concept: string, isIncomeForStudent: boolean) => {
  const { error } = await supabase.rpc('transferencia_manual_admin', {
    p_estudiante_id: String(studentId),
    p_admin_id: ADMIN_UUID,
    p_monto: amount,
    p_concept: concept,
    p_es_ingreso: isIncomeForStudent
  });

  if (error) throw new Error(error.message);
};

/**
 * Ejecuta una transferencia desde la cuenta del estudiante a otro destino.
 */
export const executeStudentTransfer = async (fromId: string, toId: string, amount: number, concept: string) => {
  const { error } = await supabase.rpc('transferencia_estudiante', {
    p_from_id: String(fromId),
    p_to_id: String(toId),
    p_monto: Number(amount),
    p_concept: String(concept)
  });

  if (error) throw new Error(error.message);
};

// --- USUARIOS ---
export const getUsers = async (): Promise<User[]> => {
  const { data, error } = await supabase.from('users').select('*');
  return error ? [] : (data || []);
};

export const saveUser = async (user: User) => {
  const { error } = await supabase.from('users').insert([user]);
  if (error) throw error;
};

export const updateUser = async (originalUsername: string, updatedUser: User) => {
  const { error } = await supabase.from('users').update({
    username: updatedUser.username,
    email: updatedUser.email,
    password: updatedUser.password
  }).eq('username', originalUsername);
  if (error) throw error;
};

export const updateUserSession = async (username: string, sessionId: string | null) => {
  const { error } = await supabase.from('users').update({ current_session_id: sessionId }).eq('username', username);
  if (error) throw error;
};

export const deleteUser = async (username: string) => {
  await supabase.from('lessons').delete().eq('student_username', username);
  const { error } = await supabase.from('users').delete().eq('username', username);
  if (error) throw error;
};

