                                 <span className="text-amber-500 text-lg">⭐</span>
                                 <span className={`text-sm font-black ${grade >= 6 ? 'text-green-600' : 'text-red-500'}`}>{grade}/10</span>
                              </div>
                            )}
                            {isAdminView && !isSelected && (
                              <button 
                                onClick={(e) => { e.stopPropagation(); setQuickEditLessonId(lesson.id); }}
                                className="w-8 h-8 rounded-full bg-slate-100 dark:bg-indigo-800 flex items-center justify-center text-indigo-400 hover:bg-indigo-600 hover:text-white transition-all shadow-sm"
                                title="Gestión de Lección"
                              >
                                ⚙️
                              </button>
                            )}
                          </div>
                        </div>

                        <h4 className="text-lg font-black text-indigo-900 dark:text-white uppercase mb-2 leading-tight">
                          🧠 {lesson.title}
                        </h4>

                        {isTransfered && (
                          <p className="text-[10px] font-bold text-green-700 dark:text-green-400 italic mb-4 animate-in fade-in slide-in-from-left-1">
                            ✓ Créditos transferidos al banco
                          </p>
                        )}

                        <div className="flex flex-wrap gap-2 mb-6">
                           <div className="bg-indigo-50 dark:bg-indigo-900/50 px-3 py-1.5 rounded-xl flex items-center space-x-1">
                              <span className="text-xs">⏱️</span>
                              <span className="text-[9px] font-black text-indigo-400 uppercase">Meta: {lesson.durationMinutes} min</span>
