                        onChange={e => setTransferTo(e.target.value)}
                        className="w-full p-3 bg-indigo-50 dark:bg-indigo-950 rounded-xl font-bold text-xs dark:text-white outline-none border-2 border-transparent focus:border-indigo-500"
                        required
                      >
                        <option value="">-- Elige un destino --</option>
                        <option value={ADMIN_UUID}>🏦 BANCO (ADMINISTRADOR)</option>
                        {otherStudents.map(s => (
                          <option key={s.id || s.username} value={s.id || s.username}>👨‍🎓 {s.username.toUpperCase()}</option>
                        ))}
                      </select>
                    </div>
                    <div>
                      <label className="block text-[8px] font-black text-indigo-400 uppercase tracking-widest mb-1 ml-2">CANTIDAD (MXN):</label>
                      <input 
                        type="number" 
                        step="0.01" 
                        min="0.01"
                        value={transferAmount}
                        onChange={e => setTransferAmount(e.target.value)}
                        placeholder="0.00"
                        className="w-full p-3 bg-indigo-50 dark:bg-indigo-950 rounded-xl font-bold text-xs dark:text-white outline-none border-2 border-transparent focus:border-indigo-500"
                        required
                      />
                    </div>
                  </div>
                  <div>
                    <label className="block text-[8px] font-black text-indigo-400 uppercase tracking-widest mb-1 ml-2">CONCEPTO:</label>
                    <input 
                      type="text" 
                      value={transferConcept}
                      onChange={e => setTransferConcept(e.target.value)}
                      placeholder="Ej. Pago de deuda, Regalo, Ahorro..."
                      className="w-full p-3 bg-indigo-50 dark:bg-indigo-950 rounded-xl font-bold text-xs dark:text-white outline-none border-2 border-transparent focus:border-indigo-500"
                      required
                    />
                  </div>
                  <button 
                    type="submit"
                    disabled={isTransferringFunds}
                    className="w-full py-4 bg-amber-500 text-white font-black rounded-2xl shadow-xl hover:bg-amber-600 transition-all uppercase text-[10px] tracking-widest disabled:opacity-50"
                  >
                    {isTransferringFunds ? 'PROCESANDO...' : 'REALIZAR TRANSFERENCIA 🚀'}
                  </button>
                </form>
              </div>
            )}
          </div>

          <div className="bg-white dark:bg-indigo-900 p-6 rounded-[3rem] border-4 border-indigo-50 dark:border-indigo-800 shadow-sm overflow-hidden">
            <h3 className="text-xl font-black text-indigo-900 dark:text-white uppercase mb-6 px-4">Historial de Movimientos</h3>
            <div className="overflow-x-auto">
              <table className="w-full text-left">
                <thead>
                  <tr className="border-b-2 border-indigo-50 dark:border-indigo-800">
                    <th className="px-4 py-4 text-[10px] font-black text-indigo-400 uppercase tracking-widest">Fecha</th>
                    <th className="px-4 py-4 text-[10px] font-black text-indigo-400 uppercase tracking-widest">Tipo</th>
                    <th className="px-4 py-4 text-[10px] font-black text-indigo-400 uppercase tracking-widest">Destino</th>
                    <th className="px-4 py-4 text-[10px] font-black text-indigo-400 uppercase tracking-widest">Concepto</th>
                    <th className="px-4 py-4 text-[10px] font-black text-indigo-400 uppercase tracking-widest text-right">Monto</th>
                  </tr>
                </thead>
                <tbody className="divide-y divide-indigo-50 dark:divide-indigo-800">
                  {transactions.length === 0 ? (
                    <tr><td colSpan={5} className="px-4 py-10 text-center text-indigo-300 font-bold uppercase text-xs tracking-widest">No hay transferencias registradas.</td></tr>
                  ) : (
                    transactions.map(t => {
                      const ownerId = user.id || user.username;
                      const isOutcome = t.from_account === ownerId;

                      // Determinar el nombre del "otro" en la transacción
                      const otherId = isOutcome ? t.to_account : t.from_account;
                      let otherName = otherId;

                      if (otherId === ADMIN_UUID) {
                        otherName = 'BANCO (ADMIN)';
                      } else {
                        // Buscar en la lista de otros estudiantes (que ya se cargó en fetchData)
                        const foundStudent = otherStudents.find(s => (s.id || s.username) === otherId);
                        if (foundStudent) {
                          otherName = foundStudent.username.toUpperCase();
                        } else if (otherId === user.id || otherId === user.username) {
                          otherName = 'MÍ MISMO';
                        }
                      }

                      return (
                        <tr key={t.id} className="hover:bg-indigo-50/30 dark:hover:bg-indigo-800/20 transition-colors">
                          <td className="px-4 py-4 text-xs font-bold text-indigo-400">{new Date(t.created_at).toLocaleDateString()}</td>
                          <td className="px-4 py-4 text-[9px] font-black uppercase">
                            <span className={isOutcome ? 'text-amber-600' : 'text-emerald-600'}>
                              {isOutcome ? 'ENVÍO 📤' : 'RECIBIDO 📥'}
                            </span>
                          </td>
                          <td className="px-4 py-4 text-[9px] font-black text-indigo-600 dark:text-indigo-400 uppercase truncate max-w-[150px]">
                            {otherName}
                          </td>
                          <td className="px-4 py-4 text-xs font-black text-indigo-900 dark:text-white uppercase">{t.concept}</td>
                          <td className={`px-4 py-4 text-sm font-black text-right ${isOutcome ? 'text-red-500' : 'text-green-500'}`}>
                            {isOutcome ? '-' : '+'}${t.amount.toFixed(2)}
                          </td>
                        </tr>
                      );
                    })
                  )}
                </tbody>
              </table>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default StudentDashboard;

