                        <tr key={t.id} className="hover:bg-indigo-50/30 dark:hover:bg-indigo-800/20 transition-colors">
                          <td className="px-4 py-4 text-xs font-bold text-indigo-400">{new Date(t.created_at).toLocaleDateString()}</td>
                          <td className="px-4 py-4 text-[10px] font-black text-indigo-600 dark:text-indigo-400 uppercase">{fromName}</td>
                          <td className="px-4 py-4 text-[10px] font-black text-indigo-600 dark:text-indigo-400 uppercase">{toName}</td>
                          <td className="px-4 py-4 text-xs font-black text-indigo-900 dark:text-white uppercase truncate max-w-[200px]">{t.concept}</td>
                          <td className={`px-4 py-4 text-sm font-black text-right ${isExpenseForAdmin ? 'text-red-500' : 'text-green-500'}`}>
                            {isExpenseForAdmin ? '-' : '+'}${t.amount.toFixed(2)}
                          </td>
                        </tr>
                      );
                    })
                  )}
                </tbody>
              </table>
            </div>
          </div>
        </section>
      )}

      {activeTab === 'dynamic' && (
        <section className="bg-white dark:bg-indigo-900 p-8 rounded-[3rem] shadow-sm border-4 border-indigo-50 dark:border-indigo-800 animate-in fade-in duration-500">
          <h2 className="text-3xl font-black text-indigo-900 dark:text-white uppercase mb-8">⚡ Asignación Masiva</h2>
          <form onSubmit={handleDynamicAssignment} className="grid grid-cols-1 lg:grid-cols-2 gap-8">
            <div className="space-y-6">
              <select value={dynStudent} onChange={e=>setDynStudent(e.target.value)} className="w-full p-4 bg-indigo-50 dark:bg-indigo-950 rounded-2xl font-bold dark:text-white outline-none" required>
                <option value="">-- Elige Estudiante --</option>
                {students.map(s => <option key={s.username} value={s.username}>{s.username}</option>)}
              </select>
              <select value={dynSubject} onChange={e => handleDynSubjectChange(e.target.value)} className="w-full p-4 bg-indigo-50 dark:bg-indigo-950 rounded-2xl font-bold dark:text-white outline-none" required>
                <option value="">-- Materia de la Guía --</option>
                {subjectsGuide.map(s => <option key={s.id} value={s.name}>{s.name}</option>)}
              </select>
              <textarea value={dynLessonsText} onChange={e=>setDynLessonsText(e.target.value)} placeholder="Lección 1: Intro..." className="w-full p-4 bg-indigo-50 dark:bg-indigo-950 rounded-2xl font-bold min-h-[250px] dark:text-white outline-none resize-none" required />
            </div>
            <div className="space-y-6">
              <div className="flex justify-between gap-1">
                {dayNamesShort.map((day, idx) => (
                  <button key={idx} type="button" onClick={() => { const n = [...dynDays]; n[idx] = !n[idx]; setDynDays(n); }} className={`flex-1 aspect-square rounded-xl font-black text-sm transition-all border-2 ${dynDays[idx] ? 'bg-indigo-600 text-white border-indigo-700 shadow-md' : 'bg-white dark:bg-indigo-950 text-indigo-300 border-indigo-50'}`}>{day}</button>
                ))}
              </div>
              <div className="grid grid-cols-2 gap-4">
                <input type="number" value={dynDuration} onChange={e=>setDynDuration(parseInt(e.target.value))} className="w-full p-4 bg-indigo-50 dark:bg-indigo-950 rounded-2xl font-bold dark:text-white outline-none" required />
                <input type="date" value={dynStartDate} onChange={e=>setDynStartDate(e.target.value)} className="w-full p-4 bg-indigo-50 dark:bg-indigo-950 rounded-2xl font-bold dark:text-white outline-none" required />
              </div>
              <textarea value={dynAiPrompt} onChange={e=>setDynAiPrompt(e.target.value)} placeholder="Prompt de la IA..." className="w-full p-4 bg-indigo-50 dark:bg-indigo-950 rounded-2xl font-bold min-h-[100px] dark:text-white outline-none" />
              <button type="submit" disabled={isLoading} className="w-full bg-indigo-600 text-white font-black py-6 rounded-[2rem] shadow-xl hover:bg-indigo-700 transition-all transform active:scale-95 text-xl uppercase tracking-widest">
                {isLoading ? 'ASIGNANDO...' : 'DISTRIBUIR MATERIA 🚀'}
              </button>
            </div>
          </form>
        </section>
      )}

      {/* MODALS */}
      {showUserModal && (
        <div className="fixed inset-0 bg-indigo-900/60 backdrop-blur-sm z-[250] flex items-center justify-center p-4">
          <div className="bg-white dark:bg-indigo-900 p-8 rounded-[3rem] w-full max-w-md shadow-2xl border-8 border-indigo-50">
            <h2 className="text-3xl font-black text-indigo-900 dark:text-white mb-6 uppercase tracking-tight">{editingUser ? 'Editar Estudiante' : 'Nuevo Estudiante'}</h2>
            <form onSubmit={handleSaveUser} className="space-y-4">
              <input type="text" value={userName} onChange={e=>setUserName(e.target.value)} placeholder="Usuario" className="w-full p-4 bg-indigo-50 rounded-2xl font-bold outline-none" required />
              <input type="password" value={userPassword} onChange={e=>setUserPassword(e.target.value)} placeholder="Contraseña" className="w-full p-4 bg-indigo-50 rounded-2xl font-bold outline-none" required />
              <div className="flex space-x-3 pt-4">
                <button type="button" onClick={()=>setShowUserModal(false)} className="flex-1 font-black text-indigo-400 text-xs">CANCELAR</button>
                <button type="submit" className="flex-1 bg-indigo-600 text-white font-black py-4 rounded-2xl shadow-lg uppercase text-xs">GUARDAR</button>
              </div>
            </form>
          </div>
        </div>
      )}

      {showSubjectModal && (
        <div className="fixed inset-0 bg-indigo-900/60 backdrop-blur-sm z-[250] flex items-center justify-center p-4">
          <div className="bg-white dark:bg-indigo-900 p-8 rounded-[3rem] w-full max-w-xl shadow-2xl border-8 border-indigo-50 overflow-y-auto max-h-[90vh]">
            <h2 className="text-3xl font-black text-indigo-900 dark:text-white mb-6 uppercase tracking-tight">{editingSubject ? 'Editar Materia' : 'Nueva Materia'}</h2>
            <form onSubmit={handleSaveSubjectGuide} className="space-y-4">
              <input type="text" value={subjectName} onChange={e=>setSubjectName(e.target.value)} placeholder="Nombre de la Materia" className="w-full p-4 bg-indigo-50 rounded-2xl font-bold outline-none" required />
              <textarea value={subjectLessons} onChange={e=>setSubjectLessons(e.target.value)} placeholder="Lista de lecciones..." className="w-full p-4 bg-indigo-50 rounded-2xl font-bold min-h-[150px] outline-none" required />
              <textarea value={subjectPrompt} onChange={e=>setSubjectPrompt(e.target.value)} placeholder="Prompt Maestro para la IA..." className="w-full p-4 bg-amber-50 rounded-2xl font-bold min-h-[100px] outline-none" />
              <div className="flex space-x-3 pt-4">
                <button type="button" onClick={()=>setShowSubjectModal(false)} className="flex-1 font-black text-indigo-400 text-xs">CANCELAR</button>
                <button type="submit" className="flex-1 bg-indigo-600 text-white font-black py-4 rounded-2xl shadow-lg uppercase text-xs">GUARDAR</button>
              </div>
            </form>
          </div>
        </div>
      )}

      {showLessonModal && (
        <div className="fixed inset-0 bg-indigo-900/60 backdrop-blur-sm z-[250] flex items-center justify-center p-4">
          <div className="bg-white dark:bg-indigo-900 p-8 rounded-[3rem] w-full max-w-xl shadow-2xl border-8 border-indigo-50 overflow-y-auto max-h-[90vh]">
            <h2 className="text-3xl font-black text-indigo-900 dark:text-white mb-6 uppercase tracking-tight">{editingLessonId ? 'Editar Lección' : 'Asignar Lección'}</h2>
            <form onSubmit={handleSaveLesson} className="space-y-4">
              <div className="flex space-x-2">
                <input type="text" value={lessonSubject} onChange={e=>setLessonSubject(e.target.value)} placeholder="Materia" className="flex-1 p-4 bg-indigo-50 rounded-2xl font-bold outline-none" required />
                <button type="button" onClick={() => setShowSubjectPicker(true)} className="bg-indigo-600 text-white w-14 rounded-2xl font-black">⋯</button>
              </div>
              <input type="text" value={lessonTitle} onChange={e=>setLessonTitle(e.target.value)} placeholder="Título de la lección" className="w-full p-4 bg-indigo-50 rounded-2xl font-bold outline-none" required />
              <div className="grid grid-cols-2 gap-4">
                <input type="number" value={lessonDuration} onChange={e=>setLessonDuration(parseInt(e.target.value))} placeholder="Minutos" className="w-full p-4 bg-indigo-50 rounded-2xl font-bold" required />
                <input type="date" value={lessonDate} onChange={e=>setLessonDate(e.target.value)} className="w-full p-4 bg-indigo-50 rounded-2xl font-bold" required />
              </div>
              <textarea value={lessonPrompt} onChange={e=>setLessonPrompt(e.target.value)} placeholder="Guía específica para la IA..." className="w-full p-4 bg-indigo-50 rounded-2xl font-bold min-h-[100px] outline-none" />
              <div className="flex space-x-3 pt-4">
                <button type="button" onClick={()=>setShowLessonModal(false)} className="flex-1 font-black text-indigo-400 text-xs">CANCELAR</button>
                <button type="submit" className="flex-1 bg-indigo-600 text-white font-black py-4 rounded-2xl shadow-lg uppercase text-xs">CONFIRMAR</button>
              </div>
            </form>
          </div>
        </div>
      )}

      {showSubjectPicker && (
        <div className="fixed inset-0 bg-indigo-900/80 backdrop-blur-md z-[300] flex items-center justify-center p-4">
          <div className="bg-white dark:bg-indigo-900 p-8 rounded-[3rem] w-full max-w-lg shadow-2xl border-8 border-white">
            <h2 className="text-2xl font-black text-indigo-900 dark:text-white mb-6 uppercase text-center">Elegir de Guía</h2>
            <div className="grid grid-cols-1 gap-2 max-h-[60vh] overflow-y-auto pr-2">
              {subjectsGuide.map(s => (
                <button key={s.id} onClick={() => { setLessonSubject(s.name); setLessonPrompt(s.learning_prompt || ''); setShowSubjectPicker(false); }} className="p-4 bg-indigo-50 dark:bg-indigo-950 hover:bg-indigo-600 hover:text-white rounded-2xl text-left font-black transition-all">
                  {s.name}
                </button>
              ))}
            </div>
            <button onClick={()=>setShowSubjectPicker(false)} className="w-full mt-6 font-black text-indigo-400 uppercase text-xs tracking-widest">CERRAR</button>
          </div>
        </div>
      )}

      {viewingFullLesson && (
        <div className="fixed inset-0 bg-indigo-900/80 backdrop-blur-md z-[1000] flex items-center justify-center p-4">
          <div className="bg-white dark:bg-indigo-950 w-full max-w-4xl h-[90vh] rounded-[3rem] shadow-2xl flex flex-col border-8 border-white overflow-hidden">
            <header className="bg-indigo-600 p-6 text-white flex justify-between items-center">
              <div>
                <h2 className="text-xl font-black uppercase tracking-tight">{viewingFullLesson.title}</h2>
                <p className="text-[10px] font-bold opacity-80 uppercase tracking-widest">{viewingFullLesson.subject} • AUDITORÍA DE CHAT (LECTURA)</p>
              </div>
              <button onClick={() => setViewingFullLesson(null)} className="w-10 h-10 flex items-center justify-center rounded-xl bg-white/10 text-2xl font-black">✕</button>
            </header>
            <div className="flex-1 bg-sky-50 dark:bg-indigo-950 relative overflow-hidden">
               <LessonWindow 
                 studentUsername={selectedStudent} 
                 lessonId={viewingFullLesson.id} 
                 onClose={() => setViewingFullLesson(null)} 
                 isAdminAudit={true} 
               />
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default AdminDashboard;

import React, { useState, useEffect, useMemo } from 'react';
import { User, Role, StudentData, Lesson, SubjectGuide, Transaction } from '../types';
import { 
  getUsers, 
  saveUser, 
  updateUser, 
  deleteUser, 
  getStudentData, 
  addLessonToStudent, 
  deleteLessonFromStudent, 
  updateLessonInStudent,
  getSubjectsGuide,
  saveSubjectGuide,
  updateSubjectGuide,
  deleteSubjectGuide,
  deleteLessonsBySubjectAndDays,
  updateLessonsPromptByCriteria,
  getAccountBalance,
  getAllTransactions,
  executeManualTransfer
} from '../storage2';
import { getSchoolDayStatus } from '../utils/schoolCalendar';
import StudentDashboard from './StudentDashboard';
import LessonWindow from './LessonWindow2';

interface AdminDashboardProps {
  user: User;
}

const AdminDashboard: React.FC<AdminDashboardProps> = ({ user }) => {
  const [activeTab, setActiveTab] = useState<'students' | 'subjects' | 'dynamic' | 'removal' | 'promptUpdate' | 'banca'>('students');
  const [students, setStudents] = useState<User[]>([]);
  const [subjectsGuide, setSubjectsGuide] = useState<SubjectGuide[]>([]);
  const [selectedStudent, setSelectedStudent] = useState<string>('');
  const [selectedUserObj, setSelectedUserObj] = useState<User | null>(null);
  const [studentData, setStudentData] = useState<StudentData | null>(null);

  // Helper para obtener fecha local en formato YYYY-MM-DD
  const getLocalDateStr = (d: Date = new Date()) => {
    const year = d.getFullYear();
    const month = String(d.getMonth() + 1).padStart(2, '0');
    const day = String(d.getDate()).padStart(2, '0');
    return `${year}-${month}-${day}`;
  };

  const [selectedDate, setSelectedDate] = useState<string>(() => getLocalDateStr());
  const [isLoading, setIsLoading] = useState(false);

  // --- ESTADOS DE BANCA CENTRAL ---
  const [adminBalance, setAdminBalance] = useState(0);
  const [allTransactions, setAllTransactions] = useState<Transaction[]>([]);

  // Estados para transacción manual
  const [manualAmount, setManualAmount] = useState<string>('');
  const [manualStudentId, setManualStudentId] = useState<string>('');
  const [manualConcept, setManualConcept] = useState<string>('');
  const [manualType, setManualType] = useState<'ingreso' | 'egreso'>('ingreso');
  const [isProcessingManual, setIsProcessingManual] = useState(false);

  // UUID del Administrador centralizado
  const ADMIN_BALANCE_UUID = '6a6db323-6229-42e3-a8b8-3ccfa177dfd7';

  // --- ESTADOS DE FORMULARIOS ---
  const [showUserModal, setShowUserModal] = useState(false);
  const [editingUser, setEditingUser] = useState<User | null>(null);
  const [userName, setUserName] = useState('');
  const [userPassword, setUserPassword] = useState('');
  const [userEmail, setUserEmail] = useState('');

  const [showSubjectModal, setShowSubjectModal] = useState(false);
  const [editingSubject, setEditingSubject] = useState<SubjectGuide | null>(null);
  const [subjectName, setSubjectName] = useState('');
  const [subjectLessons, setSubjectLessons] = useState('');
  const [subjectPrompt, setSubjectPrompt] = useState('');

  const [showLessonModal, setShowLessonModal] = useState(false);
  const [editingLessonId, setEditingLessonId] = useState<string | null>(null);
  const [lessonSubject, setLessonSubject] = useState('');
  const [lessonTitle, setLessonTitle] = useState('');
  const [lessonPrompt, setLessonPrompt] = useState('');
  const [lessonDuration, setLessonDuration] = useState(30);
  const [lessonDate, setLessonDate] = useState(selectedDate);
  const [showSubjectPicker, setShowSubjectPicker] = useState(false);

  const [viewingFullLesson, setViewingFullLesson] = useState<Lesson | null>(null);

  // Asignación Dinámica
  const [dynStudent, setDynStudent] = useState('');
  const [dynSubject, setDynSubject] = useState('');
  const [dynLessonsText, setDynLessonsText] = useState('');
  const [dynDays, setDynDays] = useState<boolean[]>([true, true, true, true, true, false, false]);
  const [dynDuration, setDynDuration] = useState(30);
  const [dynStartDate, setDynStartDate] = useState(new Date().toISOString().split('T')[0]);
  const [dynAiPrompt, setDynAiPrompt] = useState('');

  // Desasignación Dinámica
  const [remStudent, setRemStudent] = useState('');
  const [remSubject, setRemSubject] = useState('');
  const [remDays, setRemDays] = useState<boolean[]>([true, true, true, true, true, false, false]);
  const [remStartDate, setRemStartDate] = useState(new Date().toISOString().split('T')[0]);
  const [remStudentSubjects, setRemStudentSubjects] = useState<string[]>([]);

  // Actualización Dinámica de Prompt
  const [updStudent, setUpdStudent] = useState('');
  const [updSubject, setUpdSubject] = useState('');
  const [updDays, setUpdDays] = useState<boolean[]>([true, true, true, true, true, false, false]);
  const [updStartDate, setUpdStartDate] = useState(new Date().toISOString().split('T')[0]);
  const [updPrompt, setUpdPrompt] = useState('');
  const [updStudentSubjects, setUpdStudentSubjects] = useState<string[]>([]);

  const dayNamesShort = ['L', 'M', 'M', 'J', 'V', 'S', 'D'];

  const fetchData = async () => {
    setIsLoading(true);
    try {
      const [allUsers, allSubjects, balance, transactionsList] = await Promise.all([
        getUsers(),
        getSubjectsGuide(),
        getAccountBalance(ADMIN_BALANCE_UUID),
        getAllTransactions()
      ]);
      setStudents(allUsers.filter(u => u.role === Role.STUDENT));
      setSubjectsGuide(allSubjects);
      setAdminBalance(balance);
      setAllTransactions(transactionsList);
    } catch (err) {
      console.error("Error fetching initial data:", err);
    } finally {
      setIsLoading(false);
    }
  };

  useEffect(() => {
    fetchData();
  }, []);

  useEffect(() => {
    if (remStudent) {
      getStudentData(remStudent).then(data => {
        if (data) {
          const uniqueSubjects = Array.from(new Set(data.lessons.map(l => l.subject)));
          setRemStudentSubjects(uniqueSubjects);
        }
      });
    } else {
      setRemStudentSubjects([]);
    }
  }, [remStudent]);

  useEffect(() => {
    if (updStudent) {
      getStudentData(updStudent).then(data => {
        if (data) {
          const uniqueSubjects = Array.from(new Set(data.lessons.map(l => l.subject)));
          setUpdStudentSubjects(uniqueSubjects);
        }
      });
    } else {
      setUpdStudentSubjects([]);
    }
  }, [updStudent]);

  useEffect(() => {
    if (selectedStudent) {
      const u = students.find(s => s.username === selectedStudent);
      if (u) setSelectedUserObj(u);
      refreshStudentLessons();
    } else {
      setStudentData(null);
      setSelectedUserObj(null);
    }
  }, [selectedStudent, students]);

  const refreshStudentLessons = async () => {
    if (selectedStudent) {
      setIsLoading(true);
      try {
        const data = await getStudentData(selectedStudent);
        setStudentData(data);
      } catch (err) {
        console.error("Error al cargar lecciones:", err);
      } finally {
        setIsLoading(false);
      }
    }
  };

  const handleSaveUser = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!userName || !userPassword) return;
    setIsLoading(true);
    try {
      const userData: User = { username: userName, password: userPassword, email: userEmail, role: Role.STUDENT };
      if (editingUser) await updateUser(editingUser.username, userData);
      else await saveUser(userData);
      await fetchData();
      setShowUserModal(false);
    } catch (err) { alert("Error al guardar estudiante."); } finally { setIsLoading(false); }
  };

  const handleDeleteStudent = async (username: string) => {
    if (!confirm(`¿Eliminar a ${username}?`)) return;
    setIsLoading(true);
    try {
      await deleteUser(username);
      if (selectedStudent === username) setSelectedStudent('');
      await fetchData();
    } catch (err) { alert("Error al eliminar."); } finally { setIsLoading(false); }
  };

  const handleSaveSubjectGuide = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!subjectName || !subjectLessons) return;
    setIsLoading(true);
    try {
      if (editingSubject) await updateSubjectGuide(editingSubject.id, subjectName, subjectLessons, subjectPrompt);
      else await saveSubjectGuide(subjectName, subjectLessons, subjectPrompt);
      await fetchData();
      setShowSubjectModal(false);
    } catch (err) { alert("Error al guardar materia."); } finally { setIsLoading(false); }
  };

  const handleDeleteSubjectFromGuide = async (id: string) => {
    if (!confirm("¿Eliminar materia de la guía?")) return;
    setIsLoading(true);
    try {
      await deleteSubjectGuide(id);
      await fetchData();
    } catch (err) { alert("Error al eliminar."); } finally { setIsLoading(false); }
  };

  const handleSaveLesson = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!selectedStudent || !lessonSubject || !lessonTitle) return;
    setIsLoading(true);
    try {
      // Corrected Lesson object literal to use camelCase property names
      const lessonData: Lesson = {
        id: editingLessonId || 'temp-' + Date.now(),
        subject: lessonSubject,
        title: lessonTitle,
        learningPrompt: lessonPrompt,
        durationMinutes: lessonDuration,
        date: lessonDate,
        completed: editingLessonId ? (studentData?.lessons.find(l => l.id === editingLessonId)?.completed || false) : false
      };
      if (editingLessonId && !editingLessonId.startsWith('temp-')) {
        const original = studentData?.lessons.find(l => l.id === editingLessonId);
        await updateLessonInStudent(selectedStudent, { ...original, ...lessonData });
      } else {
        await addLessonToStudent(selectedStudent, lessonData);
      }
      await refreshStudentLessons();
      setShowLessonModal(false);
    } catch (err) { alert("Error al guardar lección."); } finally { setIsLoading(false); }
  };

  const handleDynSubjectChange = (name: string) => {
    setDynSubject(name);
    const selected = subjectsGuide.find(s => s.name === name);
    if (selected) {
      setDynLessonsText(selected.lessons_list);
      setDynAiPrompt(selected.learning_prompt || '');
    }
  };

  const handleDynamicAssignment = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!dynStudent || !dynSubject || !dynLessonsText) return;
    const lessonParts = dynLessonsText.split(/(?=(?:Lección|Sesión|Tema|Clase)\s+\d+[:.\s])/gi).filter(p => p.trim().length > 0);
    setIsLoading(true);
    try {
      let currentDate = new Date(dynStartDate + 'T12:00:00');
      let assignedCount = 0;
      while (assignedCount < lessonParts.length) {
        const dateStr = currentDate.toISOString().split('T')[0];
        const dayOfWeek = (currentDate.getDay() + 6) % 7;
        if (dynDays[dayOfWeek] && getSchoolDayStatus(dateStr).isSchoolDay) {
          // Corrected Lesson object literal to use camelCase property names
          await addLessonToStudent(dynStudent, {
            id: 'temp-' + Date.now() + '-' + assignedCount,
            subject: dynSubject,
            title: lessonParts[assignedCount].trim(),
            learningPrompt: dynAiPrompt,
            durationMinutes: dynDuration,
            date: dateStr,
            completed: false
          });
          assignedCount++;
        }
        currentDate.setDate(currentDate.getDate() + 1);
        if (currentDate.getFullYear() > 2027) break;
      }
      alert(`¡Se asignaron ${assignedCount} lecciones con éxito!`);
      if (selectedStudent === dynStudent) refreshStudentLessons();
    } catch (err) { alert("Error en asignación masiva."); } finally { setIsLoading(false); }
  };

  const handleDynamicRemoval = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!remStudent || !remSubject) return;
    if (!confirm(`¿Estás seguro de eliminar "${remSubject}" para ${remStudent}?`)) return;
    setIsLoading(true);
    try {
      await deleteLessonsBySubjectAndDays(remStudent, remSubject, remDays, remStartDate);
      alert("Lecciones eliminadas correctamente.");
      if (selectedStudent === remStudent) refreshStudentLessons();
    } catch (err) { alert("Error al eliminar."); } finally { setIsLoading(false); }
  };

  const handlePromptUpdate = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!updStudent || !updSubject || !updPrompt) return;
    setIsLoading(true);
    try {
      await updateLessonsPromptByCriteria(updStudent, updSubject, updDays, updStartDate, updPrompt);
      alert("Prompts actualizados correctamente.");
      if (selectedStudent === updStudent) refreshStudentLessons();
    } catch (err) { alert("Error al actualizar."); } finally { setIsLoading(false); }
  };

  const handleManualTransfer = async (e: React.FormEvent) => {
    e.preventDefault();
    const amount = parseFloat(manualAmount);
