                  key={i} 
                  message={m}
                  onAction={handleSend} 
                  timeLeft={!isAdminAudit && !isMsgFromHistory && i === arr.length - 1 && m.role === 'model' ? challengeTimeLeft : undefined} 
                  isUnlocked={isMsgFromHistory ? (m.is_unlocked || !!m.selectedOption || !!m.studentResponse) : isUnlocked} 
                  isAudit={isAdminAudit} 
                  isHistory={isMsgFromHistory && !isLastMsg}
                  studentInitial={studentUsername.charAt(0).toUpperCase()} 
                  isLessonFinished={isLessonFinishedLocally} 
                  isParentLoading={isLoading}
