export const deleteLessonsBySubjectAndDays = async (studentUsername: string, subject: string, days: boolean[], startDate: string) => {
  const { data, error } = await supabase.from('lessons').select('id, date').eq('student_username', studentUsername).eq('subject', subject).gte('date', startDate);
  if (error || !data) return;
  const idsToDelete = data.filter(l => {
    const d = new Date(l.date + 'T12:00:00');
    const dayOfWeek = (d.getDay() + 6) % 7;
    return days[dayOfWeek];
  }).map(l => l.id);
  if (idsToDelete.length > 0) await supabase.from('lessons').delete().in('id', idsToDelete);
};

export const updateLessonsPromptByCriteria = async (studentUsername: string, subject: string, days: boolean[], startDate: string, newPrompt: string) => {
  const { data, error } = await supabase.from('lessons').select('id, date').eq('student_username', studentUsername).eq('subject', subject).gte('date', startDate);
  if (error || !data) return;
  const idsToUpdate = data.filter(l => {
    const d = new Date(l.date + 'T12:00:00');
    const dayOfWeek = (d.getDay() + 6) % 7;
    return days[dayOfWeek];
  }).map(l => l.id);
  if (idsToUpdate.length > 0) await supabase.from('lessons').update({ learning_prompt: newPrompt }).in('id', idsToUpdate);
};

