  const [dynLessonsText, setDynLessonsText] = useState('');
  const [dynDays, setDynDays] = useState<boolean[]>([true, true, true, true, true, false, false]);
  const [dynDuration, setDynDuration] = useState(30);
  const [dynStartDate, setDynStartDate] = useState(new Date().toISOString().split('T')[0]);
  const [dynAiPrompt, setDynAiPrompt] = useState('');

  const [remStudent, setRemStudent] = useState('');
  const [remSubject, setRemSubject] = useState('');
  const [remDays, setRemDays] = useState<boolean[]>([true, true, true, true, true, false, false]);
  const [remStartDate, setRemStartDate] = useState(new Date().toISOString().split('T')[0]);
  const [remStudentSubjects, setRemStudentSubjects] = useState<string[]>([]);

  const [updStudent, setUpdStudent] = useState('');
  const [updSubject, setUpdSubject] = useState('');
  const [updDays, setUpdDays] = useState<boolean[]>([true, true, true, true, true, false, false]);
  const [updStartDate, setUpdStartDate] = useState(new Date().toISOString().split('T')[0]);
  const [updPrompt, setUpdPrompt] = useState('');
  const [updStudentSubjects, setUpdStudentSubjects] = useState<string[]>([]);

  const dayNamesShort = ['L', 'M', 'M', 'J', 'V', 'S', 'D'];

  const fetchData = async () => {
    setIsLoading(true);
    try {
      const [allUsers, allSubjects, balance, transactionsList] = await Promise.all([
        getUsers(),
        getSubjectsGuide(),
        getAccountBalance(ADMIN_BALANCE_UUID),
        getAllTransactions()
      ]);
      setStudents(allUsers.filter(u => u.role === Role.STUDENT));
      setSubjectsGuide(allSubjects);
      setAdminBalance(balance);
      setAllTransactions(transactionsList);
    } catch (err) {
      console.error("Error fetching initial data:", err);
    } finally {
      setIsLoading(false);
    }
  };

  useEffect(() => { fetchData(); }, []);

  useEffect(() => {
    if (remStudent) {
      getStudentData(remStudent).then(data => {
        if (data) {
          const uniqueSubjects = Array.from(new Set(data.lessons.map(l => l.subject)));
          setRemStudentSubjects(uniqueSubjects);
        }
      });
    } else { setRemStudentSubjects([]); }
  }, [remStudent]);

  useEffect(() => {
    if (updStudent) {
      getStudentData(updStudent).then(data => {
        if (data) {
          const uniqueSubjects = Array.from(new Set(data.lessons.map(l => l.subject)));
          setUpdStudentSubjects(uniqueSubjects);
        }
      });
    } else { setUpdStudentSubjects([]); }
  }, [updStudent]);

  useEffect(() => {
    if (selectedStudent) {
      const u = students.find(s => s.username === selectedStudent);
      if (u) setSelectedUserObj(u);
      refreshStudentLessons();
    } else {
      setStudentData(null);
      setSelectedUserObj(null);
    }
  }, [selectedStudent, students]);

  const refreshStudentLessons = async () => {
    if (selectedStudent) {
      setIsLoading(true);
      try {
        const data = await getStudentData(selectedStudent);
        setStudentData(data);
      } catch (err) {
        console.error("Error al cargar lecciones:", err);
      } finally {
        setIsLoading(false);
      }
    }
  };

  const handleSaveUser = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!userName || !userPassword) return;
    setIsLoading(true);
    try {
      const userData: User = { username: userName, password: userPassword, email: userEmail, role: Role.STUDENT };
      if (editingUser) await updateUser(editingUser.username, userData);
      else await saveUser(userData);
      await fetchData();
      setShowUserModal(false);
    } catch (err) { alert("Error al guardar estudiante."); } finally { setIsLoading(false); }
  };

  const handleDeleteStudent = async (username: string) => {
    if (!confirm(`¿Eliminar a ${username}?`)) return;
    setIsLoading(true);
    try {
      await deleteUser(username);
      if (selectedStudent === username) setSelectedStudent('');
      await fetchData();
    } catch (err) { alert("Error al eliminar."); } finally { setIsLoading(false); }
  };

  const handleSaveSubjectGuide = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!subjectName || !subjectLessons) return;
    setIsLoading(true);
    try {
      if (editingSubject) await updateSubjectGuide(editingSubject.id, subjectName, subjectLessons, subjectPrompt);
      else await saveSubjectGuide(subjectName, subjectLessons, subjectPrompt);
      await fetchData();
      setShowSubjectModal(false);
    } catch (err) { alert("Error al guardar materia."); } finally { setIsLoading(false); }
  };

  const handleDeleteSubjectFromGuide = async (id: string) => {
    if (!confirm("¿Eliminar materia de la guía?")) return;
    setIsLoading(true);
    try {
      await deleteSubjectGuide(id);
      await fetchData();
    } catch (err) { alert("Error al eliminar."); } finally { setIsLoading(false); }
  };

  const handleSaveLesson = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!selectedStudent || !lessonSubject || !lessonTitle) return;

    let parsedQuestions = null;
    if (lessonQuestions.trim()) {
      try {
        parsedQuestions = JSON.parse(lessonQuestions);
      } catch (err) {
        alert("¡Error de formato! El campo 'Questions' debe ser un JSON válido. Revisa paréntesis y comas.");
        return;
      }
    }

    setIsLoading(true);
    try {
      const lessonData: Lesson = {
        id: editingLessonId || 'temp-' + Date.now(),
        subject: lessonSubject,
        title: lessonTitle,
        learningPrompt: lessonPrompt,
        durationMinutes: lessonDuration,
        date: lessonDate,
        completed: editingLessonId ? (studentData?.lessons.find(l => l.id === editingLessonId)?.completed || false) : false,
        questions: parsedQuestions
      };
      if (editingLessonId && !editingLessonId.startsWith('temp-')) {
        const original = studentData?.lessons.find(l => l.id === editingLessonId);
        await updateLessonInStudent(selectedStudent, { ...original, ...lessonData });
      } else {
        await addLessonToStudent(selectedStudent, lessonData);
      }
      await refreshStudentLessons();
      setShowLessonModal(false);
    } catch (err) { alert("Error al guardar lección."); } finally { setIsLoading(false); }
  };

  const handleDynSubjectChange = (name: string) => {
    setDynSubject(name);
    const selected = subjectsGuide.find(s => s.name === name);
    if (selected) {
      setDynLessonsText(selected.lessons_list);
      setDynAiPrompt(selected.learning_prompt || '');
    }
  };

  const handleDynamicAssignment = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!dynStudent || !dynSubject || !dynLessonsText) return;
    const lessonParts = dynLessonsText.split(/(?=(?:Lección|Sesión|Tema|Clase)\s+\d+[:.\s])/gi).filter(p => p.trim().length > 0);
    setIsLoading(true);
    try {
      let currentDate = new Date(dynStartDate + 'T12:00:00');
      let assignedCount = 0;
      while (assignedCount < lessonParts.length) {
        const dateStr = currentDate.toISOString().split('T')[0];
        const dayOfWeek = (currentDate.getDay() + 6) % 7;
        if (dynDays[dayOfWeek] && getSchoolDayStatus(dateStr).isSchoolDay) {
          await addLessonToStudent(dynStudent, {
            id: 'temp-' + Date.now() + '-' + assignedCount,
            subject: dynSubject,
            title: lessonParts[assignedCount].trim(),
            learningPrompt: dynAiPrompt,
            durationMinutes: dynDuration,
            date: dateStr,
            completed: false
          });
          assignedCount++;
        }
        currentDate.setDate(currentDate.getDate() + 1);
        if (currentDate.getFullYear() > 2027) break;
      }
      alert(`¡Se asignaron ${assignedCount} lecciones con éxito!`);
      if (selectedStudent === dynStudent) refreshStudentLessons();
    } catch (err) { alert("Error en asignación masiva."); } finally { setIsLoading(false); }
  };

  const handleDynamicRemoval = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!remStudent || !remSubject) return;
    if (!confirm(`¿Estás seguro de eliminar "${remSubject}" para ${remStudent}?`)) return;
    setIsLoading(true);
    try {
      await deleteLessonsBySubjectAndDays(remStudent, remSubject, remDays, remStartDate);
      alert("Lecciones eliminadas correctamente.");
      if (selectedStudent === remStudent) refreshStudentLessons();
    } catch (err) { alert("Error al eliminar."); } finally { setIsLoading(false); }
  };

  const handlePromptUpdate = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!updStudent || !updSubject || !updPrompt) return;
    setIsLoading(true);
    try {
      await updateLessonsPromptByCriteria(updStudent, updSubject, updDays, updStartDate, updPrompt);
      alert("Prompts actualizados correctamente.");
      if (selectedStudent === updStudent) refreshStudentLessons();
    } catch (err) { alert("Error al actualizar."); } finally { setIsLoading(false); }
  };

  const handleManualTransfer = async (e: React.FormEvent) => {
    e.preventDefault();
    const amount = parseFloat(manualAmount);
    if (!manualStudentId || isNaN(amount) || amount <= 0 || !manualConcept) {
      alert("Por favor completa todos los campos correctamente.");
      return;
    }
    const confirmMsg = manualType === 'ingreso' ? `¿Confirmas el ingreso de $${amount}?` : `¿Confirmas el egreso de $${amount}?`;
    if (!confirm(confirmMsg)) return;
    setIsProcessingManual(true);
    try {
      const isIncome = manualType === 'ingreso';
      await executeManualTransfer(manualStudentId, amount, manualConcept, isIncome);
      alert("Transacción realizada con éxito.");
      setManualAmount(''); setManualConcept('');
      fetchData();
    } catch (err: any) { alert(`Error: ${err.message}`); } finally { setIsProcessingManual(false); }
  };

  const openLessonEditor = (lesson: Lesson) => {
    setEditingLessonId(lesson.id);
    setLessonSubject(lesson.subject);
    setLessonTitle(lesson.title);
    setLessonPrompt(lesson.learningPrompt || '');
    setLessonQuestions(lesson.questions ? JSON.stringify(lesson.questions, null, 2) : '');
    setLessonDuration(lesson.durationMinutes);
    setLessonDate(lesson.date);
    setShowLessonModal(true);
  };

  return (
    <div className="space-y-8 pb-20 font-fredoka">
      <div className="flex flex-col md:flex-row md:items-end md:justify-between gap-4 border-b-4 border-indigo-50 dark:border-indigo-800">
        <div className="flex flex-wrap gap-2">
          {[
            { id: 'students', label: '👨‍🎓 Estudiantes', color: 'indigo' },
            { id: 'subjects', label: '📚 Guía Materias', color: 'indigo' },
            { id: 'dynamic', label: '⚡ Asignación', color: 'indigo' },
            { id: 'promptUpdate', label: '🪄 Act. Prompt', color: 'amber' },
            { id: 'removal', label: '🧹 Desasignación', color: 'red' },
            { id: 'banca', label: 'Banca Central 🏦', color: 'amber' }
          ].map(tab => (
            <button
              key={tab.id}
              onClick={() => setActiveTab(tab.id as any)}
              className={`px-6 md:px-8 py-3 md:py-4 font-black text-xs md:text-sm uppercase transition-all rounded-t-3xl ${
                activeTab === tab.id 
                ? `bg-${tab.color === 'red' ? 'red-600' : tab.color === 'amber' ? 'amber-500' : 'indigo-600'} text-white shadow-lg` 
                : `bg-white dark:bg-indigo-900/50 text-${tab.color === 'red' ? 'red-400' : tab.color === 'amber' ? 'amber-500' : 'indigo-400'} hover:text-${tab.color === 'red' ? 'red-600' : tab.color === 'amber' ? 'amber-600' : 'indigo-600'}`
              }`}
            >
              {tab.label}
            </button>
          ))}
        </div>
      </div>

      {activeTab === 'students' && (
        <section className="space-y-8 animate-in fade-in duration-500">
          <div className="bg-white dark:bg-indigo-900 p-6 rounded-[2.5rem] shadow-sm border-4 border-indigo-50 dark:border-indigo-800">
            <div className="flex justify-between items-center mb-6">
              <h2 className="text-2xl font-black text-indigo-900 dark:text-white uppercase">Lista de Estudiantes</h2>
              <button 
                onClick={() => { setEditingUser(null); setUserName(''); setUserPassword(''); setUserEmail(''); setShowUserModal(true); }}
                className="bg-indigo-600 text-white px-6 py-3 rounded-full font-black text-xs shadow-lg hover:bg-indigo-700 transition-all"
              >
                + NUEVO ESTUDIANTE
              </button>
            </div>
            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4">
              {students.map(s => (
                <div key={s.username} className={`p-4 rounded-2xl border-4 transition-all flex items-center justify-between ${selectedStudent === s.username ? 'bg-indigo-50 dark:bg-indigo-800 border-indigo-200 dark:border-indigo-700' : 'bg-white dark:bg-indigo-950 border-indigo-50 hover:border-indigo-100'}`}>
                  <button onClick={() => setSelectedStudent(s.username)} className="flex-1 text-left">
                    <p className={`font-black uppercase text-lg ${selectedStudent === s.username ? 'text-indigo-900 dark:text-white' : 'text-indigo-400'}`}>{s.username}</p>
                  </button>
                  <div className="flex space-x-1">
                    <button onClick={() => { setEditingUser(s); setUserName(s.username); setUserPassword(s.password || ''); setUserEmail(s.email || ''); setShowUserModal(true); }} className="p-2 hover:bg-indigo-100 rounded-lg">✏️</button>
                    <button onClick={() => handleDeleteStudent(s.username)} className="p-2 text-red-500 hover:bg-red-50 rounded-lg">🗑️</button>
                  </div>
                </div>
              ))}
            </div>
          </div>

          {selectedStudent && selectedUserObj && (
            <div className="bg-white dark:bg-indigo-900 p-8 rounded-[3rem] shadow-sm border-4 border-indigo-50 dark:border-indigo-800 animate-in slide-in-from-bottom-4 duration-500">
              <div className="flex justify-between items-center mb-6 border-b-4 border-indigo-50 dark:border-indigo-800 pb-4">
                <div>
                  <h2 className="text-3xl font-black text-indigo-900 dark:text-white uppercase tracking-tight leading-tight">MODO ESPEJO: {selectedStudent}</h2>
                  <p className="text-xs font-bold text-indigo-400 dark:text-indigo-500">Visualizando réplica exacta de la interfaz del estudiante (Modo Gestión)</p>
                </div>
                <div className="flex space-x-3">
                  <button 
                    onClick={() => { setEditingLessonId(null); setLessonSubject(''); setLessonTitle(''); setLessonPrompt(''); setLessonQuestions(''); setLessonDate(selectedDate); setShowLessonModal(true); }}
                    className="bg-amber-400 text-indigo-900 px-6 py-3 rounded-full font-black text-xs shadow-lg hover:bg-amber-500 transition-all"
                  >
                    + ASIGNAR LECCIÓN
                  </button>
                  <button onClick={() => setSelectedStudent('')} className="bg-slate-100 dark:bg-indigo-800 text-indigo-400 px-6 py-3 rounded-full font-black text-xs uppercase">Cerrar Espejo</button>
                </div>
              </div>
              <StudentDashboard 
                user={selectedUserObj} 
                isAdminView={true}
                onStartLesson={() => {}} 
                onAuditLesson={(lesson) => setViewingFullLesson(lesson)}
                onBalanceUpdate={fetchData}
                onEditLessonDetails={openLessonEditor}
              />
            </div>
          )}
        </section>
      )}

      {activeTab === 'subjects' && (
        <section className="bg-white dark:bg-indigo-900 p-6 rounded-[2.5rem] shadow-sm border-4 border-indigo-50 dark:border-indigo-800 animate-in fade-in duration-500">
          <div className="flex justify-between items-center mb-6">
            <h2 className="text-2xl font-black text-indigo-900 dark:text-white uppercase">Guía Maestra de Materias</h2>
            <button onClick={() => { setEditingSubject(null); setSubjectName(''); setSubjectLessons(''); setSubjectPrompt(''); setShowSubjectModal(true); }} className="bg-indigo-600 text-white px-6 py-2 rounded-full font-black text-xs">+ NUEVA MATERIA</button>
          </div>
          <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
            {subjectsGuide.map(s => (
              <div key={s.id} className="p-6 bg-white dark:bg-indigo-950 rounded-3xl border-4 border-indigo-50 dark:border-indigo-800 shadow-sm hover:border-indigo-600 transition-all flex flex-col">
                <h3 className="text-xl font-black text-indigo-900 dark:text-white uppercase mb-4">{s.name}</h3>
                <div className="p-3 bg-sky-50 dark:bg-indigo-900/40 rounded-xl text-[10px] font-bold text-indigo-600 dark:text-indigo-200 max-h-32 overflow-y-auto mb-4 border border-indigo-100 dark:border-indigo-800 custom-scrollbar">{s.lessons_list}</div>
                <p className="text-[10px] font-black text-amber-600 dark:text-amber-500 uppercase tracking-widest mb-1 mt-2">PROMPT IA CONFIGURADO ✨</p>
                <div className="p-3 bg-amber-50 dark:bg-amber-900/20 rounded-xl text-[10px] font-medium text-amber-800 dark:text-amber-200 min-h-[60px] max-h-24 overflow-y-auto border border-amber-100 dark:border-amber-800 italic custom-scrollbar">{s.learning_prompt || "No hay prompt configurado."}</div>
                <div className="flex space-x-2 mt-6">
                  <button onClick={() => { setEditingSubject(s); setSubjectName(s.name); setSubjectLessons(s.lessons_list); setSubjectPrompt(s.learning_prompt || ''); setShowSubjectModal(true); }} className="flex-1 bg-indigo-50 dark:bg-indigo-800 text-indigo-600 dark:text-indigo-200 font-black py-4 rounded-xl text-xs hover:bg-indigo-600 transition-all">EDITAR</button>
                  <button onClick={() => handleDeleteSubjectFromGuide(s.id)} className="p-4 text-red-500 hover:bg-red-50 rounded-xl bg-slate-50 dark:bg-indigo-900 border border-slate-100 shadow-sm">🗑️</button>
                </div>
              </div>
            ))}
          </div>
        </section>
      )}

      {/* MODALS */}
      {showLessonModal && (
        <div className="fixed inset-0 bg-indigo-900/60 backdrop-blur-sm z-[250] flex items-center justify-center p-4">
          <div className="bg-white dark:bg-indigo-900 p-8 rounded-[3rem] w-full max-w-xl shadow-2xl border-8 border-indigo-50 overflow-y-auto max-h-[95vh] custom-scrollbar">
            <h2 className="text-3xl font-black text-indigo-900 dark:text-white mb-6 uppercase tracking-tight">{editingLessonId ? 'Editar Lección' : 'Asignar Lección'}</h2>
            <form onSubmit={handleSaveLesson} className="space-y-4">
              <div className="flex flex-col space-y-1">
                <label className="text-[10px] font-black text-indigo-400 uppercase ml-2">Materia</label>
                <div className="flex space-x-2">
                  <input type="text" value={lessonSubject} onChange={e=>setLessonSubject(e.target.value)} placeholder="Materia" className="flex-1 p-4 bg-indigo-50 rounded-2xl font-bold outline-none" required />
                  <button type="button" onClick={() => setShowSubjectPicker(true)} className="bg-indigo-600 text-white w-14 rounded-2xl font-black">⋯</button>
                </div>
              </div>

              <div className="flex flex-col space-y-1">
                <label className="text-[10px] font-black text-indigo-400 uppercase ml-2">Lección</label>
                <textarea rows={3} value={lessonTitle} onChange={e=>setLessonTitle(e.target.value)} placeholder="Descripción de la lección" className="w-full p-4 bg-indigo-50 rounded-2xl font-bold outline-none resize-y min-h-[80px]" required />
              </div>

              <div className="grid grid-cols-2 gap-4">
                <div className="flex flex-col space-y-1">
                  <label className="text-[10px] font-black text-indigo-400 uppercase ml-2">Minutos</label>
                  <input type="number" value={lessonDuration} onChange={e=>setLessonDuration(parseInt(e.target.value))} placeholder="Minutos" className="w-full p-4 bg-indigo-50 rounded-2xl font-bold" required />
                </div>
                <div className="flex flex-col space-y-1">
                  <label className="text-[10px] font-black text-indigo-400 uppercase ml-2">Fecha</label>
                  <input type="date" value={lessonDate} onChange={e=>setLessonDate(e.target.value)} className="w-full p-4 bg-indigo-50 rounded-2xl font-bold" required />
                </div>
              </div>

              <div className="flex flex-col space-y-1">
                <label className="text-[10px] font-black text-indigo-400 uppercase ml-2">Prompt</label>
                <textarea rows={3} value={lessonPrompt} onChange={e=>setLessonPrompt(e.target.value)} placeholder="Guía IA..." className="w-full p-4 bg-indigo-50 rounded-2xl font-bold outline-none resize-y min-h-[80px]" />
              </div>

              <div className="flex flex-col space-y-1">
                <label className="text-[10px] font-black text-indigo-400 uppercase ml-2">Questions (JSON)</label>
                <textarea rows={3} value={lessonQuestions} onChange={e=>setLessonQuestions(e.target.value)} placeholder='[{"type": "multiple_choice", "question": "...", "correct_answer": "..."}]' className="w-full p-4 bg-indigo-50 rounded-2xl font-mono text-xs outline-none border-2 border-dashed border-indigo-200 resize-y min-h-[80px]" />
              </div>

              <div className="flex space-x-3 pt-4 pb-2">
                <button type="button" onClick={()=>setShowLessonModal(false)} className="flex-1 font-black text-indigo-400 text-xs uppercase tracking-widest">CANCELAR</button>
                <button type="submit" className="flex-1 bg-indigo-600 text-white font-black py-5 rounded-2xl shadow-lg uppercase text-xs tracking-widest">CONFIRMAR</button>
              </div>
            </form>
          </div>
        </div>
      )}

      {/* Picker de materias, vista espejo, etc. se mantienen sin cambios funcionales */}
      {showSubjectPicker && (
        <div className="fixed inset-0 bg-indigo-900/80 backdrop-blur-md z-[300] flex items-center justify-center p-4">
          <div className="bg-white dark:bg-indigo-900 p-8 rounded-[3rem] w-full max-w-lg shadow-2xl border-8 border-white">
            <h2 className="text-2xl font-black text-indigo-900 dark:text-white mb-6 uppercase text-center">Elegir de Guía</h2>
            <div className="grid grid-cols-1 gap-2 max-h-[60vh] overflow-y-auto pr-2">
              {subjectsGuide.map(s => (
                <button key={s.id} onClick={() => { setLessonSubject(s.name); setLessonPrompt(s.learning_prompt || ''); setShowSubjectPicker(false); }} className="p-4 bg-indigo-50 dark:bg-indigo-950 hover:bg-indigo-600 hover:text-white rounded-2xl text-left font-black transition-all">
                  {s.name}
                </button>
              ))}
            </div>
            <button onClick={()=>setShowSubjectPicker(false)} className="w-full mt-6 font-black text-indigo-400 uppercase text-xs tracking-widest">CERRAR</button>
          </div>
        </div>
      )}

      {viewingFullLesson && (
        <div className="fixed inset-0 bg-indigo-900/80 backdrop-blur-md z-[1000] flex items-center justify-center p-4">
          <div className="bg-white dark:bg-indigo-950 w-full max-w-4xl h-[90vh] rounded-[3rem] shadow-2xl flex flex-col border-8 border-white overflow-hidden">
            <header className="bg-indigo-600 p-6 text-white flex justify-between items-center">
              <div>
                <h2 className="text-xl font-black uppercase tracking-tight">{viewingFullLesson.title}</h2>
                <p className="text-[10px] font-bold opacity-80 uppercase tracking-widest">{viewingFullLesson.subject} • AUDITORÍA DE CHAT (LECTURA)</p>
              </div>
              <button onClick={() => setViewingFullLesson(null)} className="w-10 h-10 flex items-center justify-center rounded-xl bg-white/10 text-2xl font-black">✕</button>
            </header>
            <div className="flex-1 bg-sky-50 dark:bg-indigo-950 relative overflow-hidden">
               <LessonWindow studentUsername={selectedStudent} lessonId={viewingFullLesson.id} onClose={() => setViewingFullLesson(null)} isAdminAudit={true} />
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default AdminDashboard;

import React, { useState, useEffect, useMemo } from 'react';
import { User, StudentData, Lesson, Transaction, Role } from '../types';
import { 
  getStudentData, 
  executeCreditTransfer, 
  getTransactions, 
  getAccountBalance, 
  autoUpdateLessonStatuses,
  updateLessonInStudent,
  deleteLessonFromStudent,
  clearLessonChatHistory,
  getUsers,
  executeStudentTransfer
} from '../storage2';
import Calendar from './Calendar';

interface StudentDashboardProps {
  user: User;
  onStartLesson: (username: string, lessonId: string, isAccreditation?: boolean) => void;
  onBalanceUpdate?: () => void;
  isAdminView?: boolean;
  onAuditLesson?: (lesson: Lesson) => void;
  onEditLessonDetails?: (lesson: Lesson) => void;
  initialSelectedDate?: string | null;
  lastFinishedLessonId?: string | null;
}

const StudentDashboard: React.FC<StudentDashboardProps> = ({ 
  user, 
  onStartLesson, 
  onBalanceUpdate,
  isAdminView = false,
  onAuditLesson,
  onEditLessonDetails,
  initialSelectedDate,
  lastFinishedLessonId: propsLastFinishedId
}) => {
  const [activeSubTab, setActiveSubTab] = useState<'aula' | 'banco'>('aula');
  const [data, setData] = useState<StudentData | null>(null);
  const [transactions, setTransactions] = useState<Transaction[]>([]);
  const [currentBalance, setCurrentBalance] = useState(0);
  const [isLoading, setIsLoading] = useState(true);
  const [isTransferring, setIsTransferring] = useState(false);
  const [quickEditLessonId, setQuickEditLessonId] = useState<string | null>(null);
  const [isUpdating, setIsUpdating] = useState(false);

  // Estados para el Interceptor de Ruta
  const [showChoiceModal, setShowChoiceModal] = useState(false);
  const [pendingLesson, setPendingLesson] = useState<Lesson | null>(null);

  const [otherStudents, setOtherStudents] = useState<User[]>([]);
  const [transferTo, setTransferTo] = useState('');
  const [transferAmount, setTransferAmount] = useState('');
  const [transferConcept, setTransferConcept] = useState('');
  const [isTransferringFunds, setIsTransferringFunds] = useState(false);

  const ADMIN_UUID = '6a6db323-6229-42e3-a8b8-3ccfa177dfd7';

  const getLocalDateStr = (d: Date = new Date()) => {
    const year = d.getFullYear();
    const month = String(d.getMonth() + 1).padStart(2, '0');
    const day = String(d.getDate()).padStart(2, '0');
    return `${year}-${month}-${day}`;
  };

  const [selectedDay, setSelectedDay] = useState<string | null>(initialSelectedDate || getLocalDateStr());
  const [dayLessons, setDayLessons] = useState<Lesson[]>([]);

  const getMonday = (d: Date) => {
    const date = new Date(d);
    const day = date.getDay();
    const diff = date.getDate() - day + (day === 0 ? -6 : 1);
    const monday = new Date(date.setDate(diff));
    monday.setHours(0, 0, 0, 0); 
    return monday;
  };
  const [weekStart, setWeekStart] = useState(() => getMonday(new Date()));

  const fetchData = async () => {
    setIsLoading(true);
    try {
      if (!isAdminView) await autoUpdateLessonStatuses(user.username);
      const ownerId = user.id || user.username;
      const [studentData, history, balance, allUsers] = await Promise.all([
        getStudentData(user.username),
        getTransactions(ownerId),
        getAccountBalance(ownerId),
        getUsers()
      ]);
      setData(studentData);
      setTransactions(history);
      setCurrentBalance(balance);
      setOtherStudents(allUsers.filter(u => (u.id || u.username) !== ownerId && u.role === Role.STUDENT));
    } catch (error) { console.error(error); } finally { setIsLoading(false); }
  };

  useEffect(() => { fetchData(); }, [user.username]);

  useEffect(() => {
    if (data && selectedDay) {
      setDayLessons(data.lessons.filter(l => l.date === selectedDay) || []);
    }
  }, [selectedDay, data]);

  const currentWeekLessons = useMemo(() => {
    if (!data) return [];
    const monday = new Date(weekStart);
    const sunday = new Date(monday);
    sunday.setDate(monday.getDate() + 6);
    sunday.setHours(23, 59, 59, 999);
    return data.lessons.filter(l => {
      const lDate = new Date(l.date + 'T12:00:00');
      return lDate >= monday && lDate <= sunday;
    });
  }, [data, weekStart]);

  const creditsTransferable = useMemo(() => {
    return currentWeekLessons.filter(l => (l.lesson_status === 'Aprobada' || l.lesson_status === 'Completada' || (l.grade && l.grade >= 6)) && !l.credits_transfered).reduce((acc, l) => acc + (l.grade || 0), 0);
  }, [currentWeekLessons]);

  const creditsToWin = useMemo(() => {
    return currentWeekLessons.filter(l => (l.lesson_status !== 'Aprobada' && l.lesson_status !== 'Completada' && (!l.grade || l.grade < 6)) && !l.credits_transfered).length * 10;
  }, [currentWeekLessons]);

  const weeklyStats = useMemo(() => {
    return currentWeekLessons.reduce((acc, l) => {
      const status = (l.lesson_status || 'Pendiente').toLowerCase();
      if (status === 'aprobada' || status === 'completada') acc.passed += 1;
      else if (status === 'reprobada') acc.failed += 1;
      else if (status === 'en progreso') acc.inProgress += 1;
      else acc.pending += 1;
      acc.total += 1;
      return acc;
    }, { passed: 0, failed: 0, inProgress: 0, pending: 0, total: 0 });
  }, [currentWeekLessons]);

  const handleTransfer = async () => {
    if (creditsTransferable <= 0 || isTransferring || isAdminView) return;
    const today = new Date();
    const isWeekend = today.getDay() === 0 || today.getDay() === 6;
    if (!isWeekend) { alert("Solo puedes transferir créditos los fines de semana."); return; }
    const hasIncomplete = currentWeekLessons.some(l => l.lesson_status !== 'Aprobada' && l.lesson_status !== 'Completada');
    if (hasIncomplete) { alert("Completa todas las lecciones de la semana primero."); return; }
    const pending = currentWeekLessons.filter(l => (l.lesson_status === 'Aprobada' || l.lesson_status === 'Completada' || (l.grade && l.grade >= 6)) && !l.credits_transfered);
    const realSum = pending.reduce((acc, l) => acc + (l.grade || 0), 0);
    if (!window.confirm(`¿Confirmas transferencia de $${realSum}?`)) return;
    setIsTransferring(true);
    try {
      const lessonIds = pending.map(l => l.id);
      const studentId = user.id || user.username;
      await executeCreditTransfer(studentId, user.username, realSum, `Semana [${weekStart.toISOString().split('T')[0]}]`, lessonIds);
      alert("¡Transferencia exitosa!"); fetchData(); if (onBalanceUpdate) onBalanceUpdate();
    } catch (err: any) { alert(err.message); } finally { setIsTransferring(false); }
  };

  const handleFundsTransfer = async (e: React.FormEvent) => {
    e.preventDefault();
    const amount = parseFloat(transferAmount);
    if (!transferTo || isNaN(amount) || amount <= 0 || !transferConcept) return;
    if (amount > currentBalance) { alert("Fondos insuficientes."); return; }
    if (!window.confirm(`¿Transferir $${amount.toFixed(2)}?`)) return;
    setIsTransferringFunds(true);
    try {
      await executeStudentTransfer(user.id || user.username, transferTo, amount, transferConcept);
      alert("¡Éxito!"); setTransferAmount(''); setTransferConcept(''); setTransferTo(''); fetchData(); if (onBalanceUpdate) onBalanceUpdate();
    } catch (err: any) { alert(err.message); } finally { setIsTransferringFunds(false); }
  };

  // Interceptor de acción al intentar entrar a una lección
  const onHandleLessonClick = (lesson: Lesson) => {
    if (isAdminView) {
      if (onAuditLesson) onAuditLesson(lesson);
      return;
    }
    setPendingLesson(lesson);
    setShowChoiceModal(true);
  };

  const proceedWithRoute = (isAccreditation: boolean) => {
    if (!pendingLesson) return;
    onStartLesson(user.username, pendingLesson.id, isAccreditation);
    setShowChoiceModal(false);
    setPendingLesson(null);
  };

  const getLessonUIConfig = (status: string, isTransfered: boolean) => {
    const s = (status || 'Pendiente').toLowerCase();
    let config = { color: 'bg-blue-600', label: 'PENDIENTE', btnText: isAdminView ? 'AUDITAR CLASE' : 'TOMAR CLASE 🚀', textColor: 'text-white' };
    if (s === 'aprobada' || s === 'completada') {
      config = isTransfered ? { color: 'bg-green-800', label: (s === 'completada' ? 'COMPLETADA' : 'APROBADA') + ' (PAGADA)', btnText: 'AUDITAR LECCIÓN ✨', textColor: 'text-white' }
      : { color: 'bg-green-600', label: s === 'completada' ? 'COMPLETADA' : 'APROBADA', btnText: 'REPASAR LECCIÓN ✨', textColor: 'text-white' };
    } else if (s === 'reprobada') config = { color: 'bg-red-600', label: 'REPROBADA', btnText: isAdminView ? 'AUDITAR RESULTADO' : 'MEJORAR NOTA 🔁', textColor: 'text-white' };
    else if (s === 'en progreso') config = { color: 'bg-orange-500', label: 'EN PROGRESO', btnText: isAdminView ? 'AUDITAR AVANCE' : 'RETOMAR CLASE 📚', textColor: 'text-white' };
    return config;
  };

  const handleQuickUpdate = async (lesson: Lesson, updates: Partial<Lesson>) => {
    if (!isAdminView || isUpdating) return;
    setIsUpdating(true);
    try { await updateLessonInStudent(user.username, { ...lesson, ...updates }); await fetchData(); } catch (err) { alert(err); } finally { setIsUpdating(false); }
  };

  const handleDeleteLesson = async (lessonId: string) => {
    if (!isAdminView || !confirm("¿Eliminar?")) return;
    setIsUpdating(true); try { await deleteLessonFromStudent(lessonId); await fetchData(); } catch (err) { alert(err); } finally { setIsUpdating(false); }
  };

  const handleClearHistory = async (lessonId: string) => {
    if (!isAdminView || !confirm("¿Reiniciar?")) return;
    setIsUpdating(true); try { await clearLessonChatHistory(lessonId); await fetchData(); } catch (err) { alert(err); } finally { setIsUpdating(false); }
  };

  if (isLoading) return <div className="py-24 text-center"><div className="animate-spin w-12 h-12 border-4 border-indigo-600 border-t-transparent rounded-full mx-auto mb-4"></div><p>Cargando...</p></div>;

  return (
    <div className="space-y-6 font-fredoka animate-in fade-in">
      <div className="flex bg-white dark:bg-indigo-900 p-2 rounded-2xl border-4 border-indigo-50 dark:border-indigo-800 w-fit shadow-sm">
        <button onClick={() => setActiveSubTab('aula')} className={`px-6 py-2 rounded-xl font-black text-xs uppercase transition-all ${activeSubTab === 'aula' ? 'bg-indigo-600 text-white shadow-md' : 'text-indigo-400'}`}>Aula Virtual 📚</button>
        <button onClick={() => setActiveSubTab('banco')} className={`px-6 py-2 rounded-xl font-black text-xs uppercase transition-all ${activeSubTab === 'banco' ? 'bg-amber-500 text-white shadow-md' : 'text-amber-500'}`}>Estado de Cuenta 🏦</button>
      </div>

      {activeSubTab === 'aula' ? (
        <div className="space-y-6">
          <div className="bg-white dark:bg-indigo-900 p-6 rounded-[2.5rem] shadow-sm border-4 border-indigo-50 dark:border-indigo-800 flex flex-col md:flex-row items-center gap-6">
            <div className="flex space-x-8">
               <div className="bg-amber-50 dark:bg-amber-900/30 px-6 py-4 rounded-2xl border-2 border-amber-100 flex flex-col items-center min-w-[160px]">
                  <p className="text-[10px] font-black text-amber-600 uppercase mb-1">TRANSFERIBLES</p>
                  <p className="text-3xl font-black text-amber-500 leading-none mb-2">⭐ {creditsTransferable}</p>
                  {!isAdminView && <button onClick={handleTransfer} disabled={creditsTransferable <= 0} className="text-[11px] font-black uppercase underline text-indigo-600 disabled:opacity-30">Transferir</button>}
               </div>
               <div className="bg-indigo-50 dark:bg-indigo-950 px-6 py-4 rounded-2xl border-2 border-indigo-100 flex flex-col items-center min-w-[160px]">
                  <p className="text-[10px] font-black text-indigo-400 uppercase mb-1">POR GANAR</p>
                  <p className="text-3xl font-black text-indigo-300 leading-none">⭐ {creditsToWin}</p>
               </div>
            </div>
            <div className="flex-1 w-full h-7 bg-indigo-50 dark:bg-indigo-950 rounded-full flex overflow-hidden border-2 border-indigo-100 shadow-inner">
                <div style={{ width: `${weeklyStats.total > 0 ? (weeklyStats.pending/weeklyStats.total)*100 : 0}%` }} className="bg-blue-600 transition-all duration-700"></div>
                <div style={{ width: `${weeklyStats.total > 0 ? (weeklyStats.inProgress/weeklyStats.total)*100 : 0}%` }} className="bg-orange-500 transition-all duration-700"></div>
                <div style={{ width: `${weeklyStats.total > 0 ? (weeklyStats.passed/weeklyStats.total)*100 : 0}%` }} className="bg-green-600 transition-all duration-700"></div>
                <div style={{ width: `${weeklyStats.total > 0 ? (weeklyStats.failed/weeklyStats.total)*100 : 0}%` }} className="bg-red-600 transition-all duration-700"></div>
            </div>
          </div>

          <div className="grid lg:grid-cols-3 gap-8">
            <div className="lg:col-span-2">
              <div className="bg-white dark:bg-indigo-900 p-6 rounded-[3rem] border-4 border-indigo-50 dark:border-indigo-800">
                <Calendar lessons={data?.lessons || []} selectedDate={selectedDay} onDayClick={setSelectedDay} weekStart={weekStart} onWeekStartChange={setWeekStart} isAdmin={isAdminView} />
              </div>
            </div>

            <div className="bg-white dark:bg-indigo-900 p-8 rounded-[3rem] border-4 border-indigo-50 dark:border-indigo-800 h-fit">
              <h3 className="text-2xl font-black text-indigo-900 dark:text-white uppercase mb-8">Clases del día</h3>
              <div className="space-y-6">
                {dayLessons.length === 0 ? <p className="text-center text-indigo-300 italic uppercase text-xs">Sin lecciones.</p> : dayLessons.map(lesson => {
                  const status = lesson.lesson_status || 'Pendiente';
                  const ui = getLessonUIConfig(status, !!lesson.credits_transfered);
                  const isSelected = quickEditLessonId === lesson.id;
                  return (
                    <div key={lesson.id} className={`p-6 rounded-[2.5rem] border-4 bg-white dark:bg-indigo-950 border-indigo-50 dark:border-indigo-800 relative ${isSelected ? 'ring-4 ring-amber-400' : ''}`}>
                      {isAdminView && isSelected && (
                        <div className="absolute inset-0 bg-white/95 dark:bg-indigo-900/95 z-50 flex flex-col p-4 space-y-3 rounded-[2.5rem]">
                           <div className="flex justify-between items-center"><span className="text-[10px] font-black text-indigo-400">ADMIN</span><button onClick={()=>setQuickEditLessonId(null)} className="text-red-500">✕</button></div>
                           <select value={status} onChange={(e)=>handleQuickUpdate(lesson, {lesson_status: e.target.value as any})} className="bg-indigo-50 dark:bg-indigo-950 p-2 rounded-xl text-[10px] font-black border-2 border-indigo-100">
                              <option value="Pendiente">Pendiente</option><option value="En Progreso">En Progreso</option><option value="Aprobada">Aprobada</option><option value="Reprobada">Reprobada</option><option value="Completada">Completada</option>
                           </select>
                           <input type="number" value={lesson.grade || ''} onChange={(e)=>handleQuickUpdate(lesson, {grade: parseInt(e.target.value)||0})} className="bg-indigo-50 dark:bg-indigo-950 p-2 rounded-xl text-[10px] font-black border-2 border-indigo-100" placeholder="Nota" />
                           <div className="grid grid-cols-2 gap-2"><button onClick={()=>handleClearHistory(lesson.id)} className="py-2 bg-amber-100 text-amber-600 text-[9px] font-black rounded-xl uppercase">Limpiar 🫧</button><button onClick={()=>{setQuickEditLessonId(null); onEditLessonDetails?.(lesson)}} className="py-2 bg-indigo-100 text-indigo-600 text-[9px] font-black rounded-xl uppercase">Editar ✏️</button></div>
                           <button onClick={()=>handleDeleteLesson(lesson.id)} className="w-full py-2 bg-red-50 text-red-500 text-[9px] font-black rounded-xl uppercase">Eliminar 🗑️</button>
                        </div>
                      )}
                      <div className="flex justify-between items-center mb-4">
                        <span className={`${ui.color} ${ui.textColor} text-[9px] font-black px-4 py-1.5 rounded-full uppercase tracking-wider`}>{lesson.subject} • {ui.label}</span>
                        {isAdminView && !isSelected && <button onClick={()=>setQuickEditLessonId(lesson.id)} className="w-8 h-8 rounded-full bg-slate-100 text-indigo-400 hover:bg-indigo-600 hover:text-white">⚙️</button>}
                      </div>
                      <h4 className="text-lg font-black text-indigo-900 dark:text-white uppercase mb-4 leading-tight">🧠 {lesson.title}</h4>
                      <button onClick={() => onHandleLessonClick(lesson)} className={`w-full py-4 rounded-2xl font-black text-xs shadow-xl active:scale-95 ${ui.color} ${ui.textColor} uppercase`}>{ui.btnText}</button>
                    </div>
                  );
                })}
              </div>
            </div>
          </div>
        </div>
      ) : (
        <div className="space-y-6">
          <div className="bg-white dark:bg-indigo-900 p-8 rounded-[3rem] border-4 border-amber-100 flex items-center space-x-6">
            <div className="w-20 h-20 bg-amber-100 rounded-full flex items-center justify-center text-4xl">🏦</div>
            <div><p className="text-xs font-black text-amber-600 uppercase mb-1">Saldo Bancario</p><p className="text-4xl font-black text-amber-500">MXN ${currentBalance.toFixed(2)}</p></div>
          </div>
          {/* Formulario de transferencia bancaria se mantiene */}
          {!isAdminView && (
            <div className="bg-white dark:bg-indigo-900 p-8 rounded-[3rem] border-4 border-indigo-50 shadow-sm">
                <h3 className="text-xl font-black text-indigo-900 dark:text-white uppercase mb-6">Transferir Fondos 💸</h3>
                <form onSubmit={handleFundsTransfer} className="grid grid-cols-1 md:grid-cols-2 gap-4">
                    <select value={transferTo} onChange={e=>setTransferTo(e.target.value)} className="p-3 bg-indigo-50 dark:bg-indigo-950 rounded-xl font-bold dark:text-white" required>
                        <option value="">Destino...</option><option value={ADMIN_UUID}>🏦 BANCO (ADMIN)</option>
                        {otherStudents.map(s => <option key={s.id || s.username} value={s.id || s.username}>👨‍🎓 {s.username.toUpperCase()}</option>)}
                    </select>
                    <input type="number" step="0.01" min="0.01" value={transferAmount} onChange={e=>setTransferAmount(e.target.value)} placeholder="0.00" className="p-3 bg-indigo-50 dark:bg-indigo-950 rounded-xl font-bold dark:text-white" required />
                    <input type="text" value={transferConcept} onChange={e=>setTransferConcept(e.target.value)} placeholder="Concepto..." className="md:col-span-2 p-3 bg-indigo-50 dark:bg-indigo-950 rounded-xl font-bold dark:text-white" required />
                    <button type="submit" disabled={isTransferringFunds} className="md:col-span-2 py-4 bg-amber-500 text-white font-black rounded-2xl shadow-xl uppercase disabled:opacity-50">Transferir Fondos</button>
                </form>
            </div>
          )}
        </div>
      )}

      {/* Modal Interceptor: Elección de Ruta */}
      {showChoiceModal && (
        <div className="fixed inset-0 bg-indigo-900/90 backdrop-blur-md z-[1000] flex items-center justify-center p-6">
          <div className="bg-white dark:bg-indigo-900 p-10 rounded-[3.5rem] w-full max-w-lg shadow-2xl border-8 border-indigo-50 dark:border-indigo-800 text-center animate-in zoom-in duration-300">
            <div className="text-7xl mb-8">🎯</div>
            <h2 className="text-3xl font-black text-indigo-900 dark:text-white mb-4 uppercase leading-none">Ruta de Aprendizaje</h2>
            <p className="text-indigo-400 dark:text-indigo-300 font-bold mb-10 text-sm">¿Cómo deseas acceder a "{pendingLesson?.title}"?</p>

            <div className="grid gap-4">
              <button 
                onClick={() => proceedWithRoute(false)}
                className="w-full bg-indigo-600 text-white font-black py-6 rounded-3xl shadow-xl hover:bg-indigo-700 transition-all text-lg uppercase tracking-tight flex items-center justify-center space-x-3"
              >
                <span>Tomar la lección</span> <span>📚</span>
              </button>

              <button 
                onClick={() => proceedWithRoute(true)}
                disabled={!pendingLesson?.questions || pendingLesson.questions.length < 10}
                className="w-full bg-amber-400 text-indigo-900 font-black py-6 rounded-3xl shadow-xl hover:bg-amber-500 transition-all text-lg uppercase tracking-tight flex items-center justify-center space-x-3 disabled:opacity-40 disabled:grayscale"
              >
                <span>Examen de Acreditación</span> <span>🎯</span>
              </button>

              {!pendingLesson?.questions || pendingLesson.questions.length < 10 ? (
                <p className="text-[10px] font-black text-red-500 uppercase mt-2">No hay suficientes preguntas para acreditar esta lección.</p>
              ) : null}

              <button 
                onClick={() => {setShowChoiceModal(false); setPendingLesson(null);}}
                className="mt-4 text-xs font-black text-indigo-300 uppercase underline"
              >
                Regresar al aula
              </button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default StudentDashboard;

import React, { useState, useEffect, useRef, useMemo, useCallback, memo } from 'react';
import { Lesson, ChatMessage } from '../types';
import { getStudentData, updateLessonInStudent } from '../storage2';
import { getGeminiChat, generateExam } from '../geminiService2';
// @ignore
import ReactMarkdown from 'react-markdown';
// @ignore
import remarkGfm from 'remark-gfm';
// @ignore
import rehypeRaw from 'rehype-raw';

interface LessonWindowProps {
  studentUsername: string;
  lessonId: string;
  onClose: (finishedDate?: string, finishedId?: string) => void;
  isAdminAudit?: boolean;
  isAccreditationMode?: boolean;
}

const ImageWithFallback: React.FC<{ src: string; alt: string }> = ({ src, alt }) => {
  const [error, setError] = useState(false);
  if (error) {
    return (
      <div className="my-4 p-6 rounded-[2rem] bg-indigo-50 dark:bg-indigo-900/30 border-4 border-dashed border-indigo-100 flex flex-col items-center text-center">
        <span className="text-4xl mb-4">🖼️</span>
        <p className="text-xs font-black text-indigo-900 dark:text-indigo-100 uppercase mb-1">Recurso</p>
        <a href={src} target="_blank" rel="noopener noreferrer" className="px-6 py-3 bg-indigo-600 text-white text-[10px] font-black rounded-2xl uppercase">Ver original ↗</a>
      </div>
    );
  }
  return <div className="relative group my-4"><img src={src} alt={alt} crossOrigin="anonymous" onError={() => setError(true)} className="max-w-full h-auto rounded-3xl border-4 border-white shadow-sm" /></div>;
};

const SafeLink: React.FC<any> = ({ children, href }) => <a href={href} target="_blank" rel="noopener noreferrer" className="text-indigo-600 dark:text-indigo-400 font-black underline decoration-2">{children} <span className="ml-1 text-[8px]">↗</span></a>;

const MarkdownComponents = {
  img: ({node, ...props}: any) => <ImageWithFallback src={props.src} alt={props.alt} />,
  a: ({node, ...props}: any) => <SafeLink {...props} />
};

interface ParsedAIResponse {
  explanation: string;
  challengeType?: 'MCQ' | 'WRITTEN';
  question?: { text: string; options?: string[]; correct?: string; };
  errorInfo?: string;
  refuerzo?: string;
  isPlagio?: boolean;
  isIrrelevant?: boolean;
}

interface RichMessageProps {
  message: ChatMessage;
  onAction: (val: string) => void;
  timeLeft?: number;
  isUnlocked?: boolean;
  isAudit?: boolean;
  studentInitial?: string;
  isLessonFinished?: boolean;
  isParentLoading?: boolean;
  isHistory?: boolean;
}

const RichMessage: React.FC<RichMessageProps> = memo(({ message, onAction, timeLeft, isUnlocked = false, isAudit, studentInitial, isLessonFinished, isParentLoading, isHistory }) => {
  const [selectedOption, setSelectedOption] = useState<string | null>(message.selectedOption || null);
  const text = message.parts[0].text;
  const isUser = message.role === 'user';
  const formatTime = (iso?: string) => iso ? new Date(iso).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit', hour12: false }) : '';

  const parseResponse = (raw: string): ParsedAIResponse => {
    const isPlagio = raw.includes('[PLAGIO_IA]');
    const isIrrelevant = raw.includes('[IRRELEVANTE]');
    const dataMatch = raw.match(/\[DATA_LOGICA\]([\s\S]*?)\[\/DATA_LOGICA\]/);
    const expMatch = raw.match(/\[EXPLICACION\]([\s\S]*?)\[\/EXPLICACION\]/);
    const errorMatch = raw.match(/\[ERROR_INFO\]([\s\S]*?)(?=\[REFUERZO\]|\[EXPLICACION\]|$)/);
    const refuerzoMatch = raw.match(/\[REFUERZO\]([\s\S]*?)(?=\[EXPLICACION\]|$)/);

    let explanation = expMatch ? expMatch[1].trim() : raw.replace(/\[DATA_LOGICA\][\s\S]*/g, '').replace(/\[EXPLICACION\]|\[\/EXPLICACION\]|\[RESPUESTA_VALIDA\]|\[RESPUESTA_INCORRECTA\]|\[PLAGIO_IA\]|\[IRRELEVANTE\]|\[REFUERZO\]|\[ERROR_INFO\]/g, '').trim();

    let questionData; let challengeType;
    if (dataMatch) {
      try {
        const json = JSON.parse(dataMatch[1].trim());
        challengeType = json.type;
        const cleanStr = (s: string) => (typeof s === 'string') ? s.replace(/^[A-Z]\)\s*/, '') : s;
        questionData = { text: json.question, options: Array.isArray(json.options) ? json.options.map(cleanStr) : [], correct: cleanStr(json.correct) };
      } catch (e) { console.error(e); }
    }
    return { explanation, challengeType, question: questionData, errorInfo: errorMatch ? errorMatch[1].trim() : undefined, refuerzo: refuerzoMatch ? refuerzoMatch[1].trim() : undefined, isPlagio, isIrrelevant };
  };

  const handleOptionClick = (opt: string) => {
    if (selectedOption || message.selectedOption || isAudit || isHistory || timeLeft === 0 || isParentLoading) return;
    setSelectedOption(opt); setTimeout(() => onAction(opt), 800);
  };

  if (isUser) {
    return (
      <div className="flex items-start space-x-3 justify-end w-full animate-in fade-in slide-in-from-right-4 duration-300">
        <div className="bg-indigo-600 text-white p-5 rounded-[2.5rem] shadow-sm border-2 border-indigo-700 max-w-full w-fit ml-auto relative pb-8 min-w-[100px]">
          <div className="prose dark:prose-invert max-w-none text-lg font-bold">{text}</div>
          <div className="absolute bottom-2.5 right-6 text-[9px] font-black opacity-60 uppercase tracking-tighter">{formatTime(message.timestamp)}</div>
        </div>
        <div className="w-10 h-10 rounded-full bg-white dark:bg-indigo-800 border-2 border-indigo-200 flex items-center justify-center text-indigo-600 font-black shrink-0">{studentInitial}</div>
      </div>
    );
  }

  const parsed = parseResponse(text);
  const activeSelection = selectedOption || message.selectedOption;
  const showQuestionBlock = parsed.question && (isUnlocked || activeSelection || isAudit || message.is_unlocked || message.studentResponse);

  return (
    <div className={`flex items-start space-x-3 w-full animate-in fade-in slide-in-from-left-4 duration-500`}>
      <div className="w-10 h-10 rounded-2xl bg-indigo-50 dark:bg-indigo-800 border-2 border-indigo-100 flex items-center justify-center text-xl shrink-0">🤖</div>
      <div className={`p-6 rounded-[2.5rem] shadow-sm border-2 flex-1 w-full max-w-full relative pb-10 ${parsed.isPlagio ? 'bg-red-50 border-red-500 text-red-900' : 'bg-white dark:bg-indigo-900 text-indigo-900 dark:text-indigo-100 border-indigo-50'}`}>
        <div className="flex flex-col space-y-4">
          {parsed.isPlagio && <p className="text-[10px] font-black uppercase text-red-600">⚠️ ALERTA DE PLAGIO</p>}
          {parsed.isIrrelevant && (
            <div className="bg-amber-50 dark:bg-amber-900/20 border-l-4 border-amber-500 p-4 rounded-r-2xl animate-in zoom-in-95 duration-300">
              <p className="text-[10px] font-black uppercase text-amber-600 mb-1">🎯 ¡Hey, concéntrate!</p>
              <p className="text-sm font-bold">Parece que nos estamos desviando. Vuelve a la lección para continuar.</p>
            </div>
          )}
          <div className="pregunta-contenedor prose dark:prose-invert max-w-none text-lg">
            <ReactMarkdown remarkPlugins={[remarkGfm]} rehypePlugins={[rehypeRaw]} components={MarkdownComponents}>{parsed.refuerzo || parsed.explanation}</ReactMarkdown>
            {!isUnlocked && !activeSelection && !isAudit && !isHistory && parsed.question && !isLessonFinished && !parsed.isPlagio && !message.studentResponse && (
              <div className="mt-6"><button onClick={() => onAction("__UNLOCK_QUESTION__")} disabled={isParentLoading} className="bg-indigo-600 text-white border-2 border-indigo-500 px-6 py-4 rounded-2xl font-black text-sm hover:bg-indigo-700 shadow-xl uppercase tracking-widest disabled:opacity-50">Ya leí y comprendí 🎯</button></div>
            )}
            {showQuestionBlock && !isLessonFinished && (
              <div className="animate-in zoom-in-95 pt-6 border-t-4 border-indigo-50 mt-6">
                <p className="texto-pregunta text-xl font-black mb-6 leading-tight">{parsed.question.text}</p>
                {message.studentResponse && <div className={`p-6 rounded-[1.5rem] font-black text-lg shadow-md border-2 mb-6 ${message.validationStatus === 'correct' ? 'bg-green-500 border-green-600 text-white' : message.validationStatus === 'incorrect' ? 'bg-red-500 border-red-600 text-white' : 'bg-blue-600 border-blue-700 text-white'}`}><p className="text-[10px] font-black uppercase mb-2 opacity-80">Tu Respuesta</p>{message.studentResponse}</div>}
                {parsed.challengeType === 'MCQ' && (
                  <div className="grid gap-3">
                    {parsed.question.options?.map((opt, idx) => {
                      const isSelected = activeSelection === opt; const isCorrect = opt === parsed.question?.correct;
                      let btnClass = "bg-white dark:bg-indigo-950 text-indigo-600 border-indigo-100 hover:bg-indigo-50";
                      if (activeSelection) {
                        if (message.validationStatus) {
                          if (isSelected) btnClass = message.validationStatus === 'correct' ? "bg-green-500 text-white border-green-600 shadow-lg" : "bg-red-500 text-white border-red-600 shadow-lg";
                          else if (isCorrect && message.validationStatus === 'incorrect') btnClass = "bg-green-500 text-white border-green-600 shadow-md animate-pulse";
                          else btnClass = "bg-slate-50 border-indigo-50 opacity-40 text-indigo-300";
                        } else { btnClass = isSelected ? "bg-blue-600 text-white border-blue-700 shadow-lg" : "bg-slate-50 border-indigo-50 opacity-60 text-indigo-300"; }
                      } else if (!isAudit && !isHistory) btnClass = "bg-indigo-600 border-indigo-500 hover:bg-indigo-700 text-white";
                      return <button key={idx} onClick={() => handleOptionClick(opt)} disabled={!!activeSelection || isAudit || isHistory || isParentLoading} className={`w-full text-left px-6 py-5 rounded-[1.5rem] font-black text-lg shadow-md transition-all active:scale-95 border-2 ${btnClass}`}>{String.fromCharCode(65 + idx)}) {opt}</button>;
                    })}
                  </div>
                )}
              </div>
            )}
          </div>
        </div>
        <div className="absolute bottom-3 right-8 text-[9px] font-black opacity-30 uppercase tracking-tighter text-indigo-400">{formatTime(message.timestamp)}</div>
      </div>
    </div>
  );
});

const LessonWindow: React.FC<LessonWindowProps> = ({ studentUsername, lessonId, onClose, isAdminAudit: forcedAudit = false, isAccreditationMode = false }) => {
  const [lesson, setLesson] = useState<Lesson | null>(null);
  const [messages, setMessages] = useState<ChatMessage[]>([]);
  const [input, setInput] = useState('');
  const [isLoading, setIsLoading] = useState(false);
  const [loadingText, setLoadingText] = useState('');
  const [secondsElapsed, setSecondsElapsed] = useState(0);
  const [isPaused, setIsPaused] = useState(false);
  const [idleSeconds, setIdleSeconds] = useState(0);
  const [validCount, setValidCount] = useState(0);
  const [targetInteractions, setTargetInteractions] = useState(30);
  const [isUnlocked, setIsUnlocked] = useState(false);
  const [isWrittenChallenge, setIsWrittenChallenge] = useState(false);
  const [challengeTimeLeft, setChallengeTimeLeft] = useState<number | undefined>(undefined);

  const [showExam, setShowExam] = useState(false);
  const [examData, setExamData] = useState<any>(null);
  const [currentQuestionIdx, setCurrentQuestionIdx] = useState(0);
  const [currentAnswer, setCurrentAnswer] = useState('');
  const [showQuestionFeedback, setShowQuestionFeedback] = useState(false);
  const [isLastAnswerCorrect, setIsLastAnswerCorrect] = useState(false);
  const [aiFeedback, setAiFeedback] = useState('');
  const [isExamFinished, setIsExamFinished] = useState(false);
  const [correctAnswersCount, setCorrectAnswersCount] = useState(0);
  const [examTimer, setExamTimer] = useState(0);
  const [showResultModal, setShowResultModal] = useState(false);
  const [studentExamAnswers, setStudentExamAnswers] = useState<any[]>([]);

  const chatRef = useRef<any>(null);
  const messagesEndRef = useRef<HTMLDivElement>(null);
  const messagesRef = useRef<ChatMessage[]>([]);
  const challengeTimerRef = useRef<number | null>(null);
  const examTimerRef = useRef<number | null>(null);

  const isAdminAudit = forcedAudit || (lesson?.credits_transfered === true);
  const timeMet = useMemo(() => Math.floor(secondsElapsed / 60) >= (lesson?.durationMinutes || 0), [secondsElapsed, lesson]);

  useEffect(() => { messagesRef.current = messages; }, [messages]);

  useEffect(() => {
    if (showExam && !showQuestionFeedback && examTimer > 0) {
      examTimerRef.current = window.setInterval(() => {
        setExamTimer(prev => { if (prev <= 1) { handleCheckAnswer(); return 0; } return prev - 1; });
      }, 1000);
    } else if (examTimerRef.current) clearInterval(examTimerRef.current);
    return () => { if (examTimerRef.current) clearInterval(examTimerRef.current); };
  }, [showExam, showQuestionFeedback, examTimer]);

  useEffect(() => {
    const fetchLesson = async () => {
      const res = await getStudentData(studentUsername);
      if (res) {
        const found = res.lessons.find(l => l.id === lessonId);
        if (found) {
          setLesson(found);
          setSecondsElapsed(found.elapsedSeconds || 0);
          setValidCount(found.validInteractionsCount || 0);
          setTargetInteractions(Math.ceil(found.durationMinutes * 0.8));
          if (found.chatHistory?.length) setMessages(found.chatHistory);

          if (isAccreditationMode) {
            initAccreditationExam(found);
          } else if (!isAdminAudit) {
            startGeminiChat(found, (found.chatHistory?.length || 0) > 0);
          }
        }
      }
    };
    fetchLesson();
  }, [studentUsername, lessonId]);

  const initAccreditationExam = (l: Lesson) => {
    if (!l.questions || !Array.isArray(l.questions)) return;

    // Filtrar pools
    const mcqPool = l.questions.filter(q => q.type === 'multiple_choice');
    const openPool = l.questions.filter(q => q.type === 'open');
    const tfPool = l.questions.filter(q => q.type === 'true_false');

    const shuffle = (arr: any[]) => arr.sort(() => 0.5 - Math.random());
    const mcqs = shuffle([...mcqPool]).slice(0, 4);
    const opens = shuffle([...openPool]).slice(0, 4);
    const tfs = shuffle([...tfPool]).slice(0, 2);

    // Construir patrón: MCQ, Abierta, MCQ, Abierta, TF...
    const finalQuestions: any[] = [];
    for (let i = 0; i < 2; i++) {
        finalQuestions.push(mcqs[i*2], opens[i*2], mcqs[i*2+1], opens[i*2+1], tfs[i]);
    }

    setExamData({ questions: finalQuestions.map((q, i) => ({
        id: i,
        text: q.question,
        type: q.type,
        options: q.type === 'multiple_choice' ? q.options : q.type === 'true_false' ? ['Verdadero', 'Falso'] : [],
        correctAnswer: q.correct_answer,
        acceptableAnswers: q.acceptable_answers,
        explanation: q.explanation
    }))});

    setShowExam(true);
    setCurrentQuestionIdx(0);
    setCorrectAnswersCount(0);
    setExamTimer(60);
  };

  const startGeminiChat = async (l: Lesson, isResuming: boolean) => {
    if (chatRef.current) return;
    setIsLoading(true); setLoadingText("El profesor está escribiendo...");
    try {
      const chat = await getGeminiChat(l, studentUsername, l.chatHistory);
      chatRef.current = chat;
      const response = await chat.sendMessage({ message: isResuming ? `[RESUME_MODE]` : `START_LESSON` });
      setMessages(prev => [...prev, { role: 'model', parts: [{ text: response.text || '' }], timestamp: new Date().toISOString(), is_unlocked: false }]);
    } catch (err) { console.error(err); } finally { setIsLoading(false); }
  };

  const handleSend = async (manualText?: string) => {
    if (isAdminAudit) return;
    if (manualText === "__UNLOCK_QUESTION__") {
        setIsUnlocked(true);
        setMessages(prev => {
            const last = [...prev];
            const idx = last.length - 1;
            if (last[idx].role === 'model') last[idx].is_unlocked = true;
            return last;
        });
        return;
    }
    const userText = (manualText || input).trim();
    if (!userText || isLoading) return;

    setInput(''); setIsLoading(true);
    const userMsg: ChatMessage = { role: 'user', parts: [{ text: userText }], timestamp: new Date().toISOString() };
    setMessages(prev => [...prev, userMsg]);

    try {
      const result = await chatRef.current.sendMessage({ message: userText });
      const aiMsg: ChatMessage = { role: 'model', parts: [{ text: result.text || '' }], timestamp: new Date().toISOString(), is_unlocked: false };
      setMessages(prev => [...prev, aiMsg]);
    } catch (err) { console.error(err); } finally { setIsLoading(false); }
  };

  const handleCheckAnswer = () => {
    const q = examData.questions[currentQuestionIdx];
    let isCorrect = false;

    if (q.type === 'multiple_choice' || q.type === 'true_false') {
        isCorrect = (currentAnswer === q.correctAnswer);
    } else {
        // Validación de respuestas abiertas
        const clean = (s: string) => s.toLowerCase().trim();
        isCorrect = q.acceptableAnswers?.some((ans: string) => clean(currentAnswer).includes(clean(ans))) || false;
    }

    setIsLastAnswerCorrect(isCorrect);
    setAiFeedback(q.explanation);
    setStudentExamAnswers(prev => [...prev, { question: q.text, answer: currentAnswer || "[SIN RESPUESTA]", correct: q.correctAnswer, isCorrect }]);
    if (isCorrect) setCorrectAnswersCount(prev => prev + 1);
    setShowQuestionFeedback(true);
    if (examTimerRef.current) clearInterval(examTimerRef.current);
  };

  const handleNextQuestion = () => {
    if (currentQuestionIdx < 9) {
      setCurrentQuestionIdx(prev => prev + 1);
      setShowQuestionFeedback(false);
      setCurrentAnswer('');
      setExamTimer(60);
    } else finishExam();
  };

  const finishExam = async () => {
    setShowExam(false);
    if (lesson) {
      const finalGrade = correctAnswersCount;
      const updated: Lesson = { ...lesson, grade: finalGrade, completed: finalGrade >= 6, lesson_status: finalGrade >= 6 ? 'Aprobada' : 'Reprobada' };
      await updateLessonInStudent(studentUsername, updated);
      setShowResultModal(true);
    }
  };

  if (!lesson) return null;

  return (
    <div className={`fixed inset-0 bg-white dark:bg-indigo-950 z-[500] flex flex-col font-fredoka overflow-hidden select-none ${isAdminAudit ? 'relative h-full' : ''}`} onCopy={e => e.preventDefault()} onContextMenu={e => e.preventDefault()}>
      <header className={`${isAdminAudit ? 'bg-slate-700' : 'bg-indigo-600'} p-4 shadow-lg flex flex-col z-[1100] border-b-4 border-white/10 shrink-0`}>
          <div className="flex justify-between items-center w-full">
            <div className="flex items-center space-x-4">
              {!isAdminAudit && !isAccreditationMode && (
                <div className="bg-white/20 px-4 py-2 rounded-2xl flex flex-col items-center">
                  <span className="text-xl font-black font-mono text-white">{Math.floor(secondsElapsed / 60)}:{String(secondsElapsed % 60).padStart(2, '0')}</span>
                </div>
              )}
              <div className="text-white">
                <h2 className="text-sm font-black uppercase truncate">{isAccreditationMode ? 'EXAMEN DE ACREDITACIÓN' : lesson.title}</h2>
                <p className="text-[9px] font-bold opacity-70 uppercase">{lesson.subject}</p>
              </div>
            </div>
            <button onClick={() => onClose()} className="w-10 h-10 rounded-full bg-white/10 hover:bg-red-500 transition-all flex items-center justify-center font-black text-white">✕</button>
          </div>
      </header>

      <div className="flex-1 relative flex overflow-hidden">
        <div className={`flex-1 flex flex-col bg-sky-50 dark:bg-indigo-950 ${(showExam || isExamFinished || isPaused || showResultModal) ? 'opacity-20 pointer-events-none' : ''}`}>
          <div className="flex-1 overflow-y-auto px-[4%] py-10 space-y-10 custom-scrollbar">
            {messages.map((m, i) => (
              <RichMessage key={i} message={m} onAction={handleSend} studentInitial={studentUsername.charAt(0).toUpperCase()} isLessonFinished={isExamFinished} isParentLoading={isLoading} />
            ))}
            {isLoading && <div className="p-4 bg-white/60 rounded-2xl animate-pulse text-xs font-black">{loadingText}</div>}
            <div ref={messagesEndRef} />
          </div>
          {!isAdminAudit && (
            <div className="p-6 bg-white dark:bg-indigo-900 border-t-4 border-indigo-50">
              <div className="w-full flex items-center space-x-3">
                <textarea value={input} onChange={(e) => setInput(e.target.value)} onKeyDown={(e) => e.key === 'Enter' && !e.shiftKey && (e.preventDefault(), handleSend())} className="flex-1 px-6 py-4 rounded-3xl border-4 border-indigo-50 dark:bg-indigo-950 font-bold resize-none h-16 shadow-inner text-lg" placeholder="Escribe tu mensaje..." disabled={isLoading} />
                <button onClick={() => handleSend()} disabled={isLoading} className="bg-indigo-600 text-white px-8 h-16 rounded-3xl text-xl shadow-xl transition-all">➔</button>
              </div>
            </div>
          )}
        </div>

        {showExam && (
          <div className="absolute inset-0 bg-indigo-900/90 flex items-center justify-center p-4 z-[800] backdrop-blur-sm">
            <div className="bg-white w-full max-w-2xl rounded-[3rem] p-10 border-8 border-indigo-50 shadow-2xl overflow-y-auto max-h-[95vh] flex flex-col">
              {!showQuestionFeedback ? (
                <>
                  <div className="flex justify-between items-center mb-8">
                    <div className="bg-indigo-100 text-indigo-600 px-4 py-2 rounded-2xl font-black text-[10px] uppercase">PREGUNTA {currentQuestionIdx + 1} DE 10</div>
                    <div className={`w-12 h-12 rounded-full border-4 flex items-center justify-center font-black text-sm ${examTimer < 10 ? 'border-red-500 text-red-500' : 'border-indigo-600 text-indigo-600'}`}>{examTimer}s</div>
                  </div>
                  <h3 className="text-2xl font-black text-indigo-900 text-center mb-10 leading-tight">{examData.questions[currentQuestionIdx].text}</h3>

                  {examData.questions[currentQuestionIdx].type === 'open' ? (
                    <textarea 
                        value={currentAnswer} 
                        onChange={(e)=>setCurrentAnswer(e.target.value)} 
                        placeholder="Escribe tu respuesta analítica aquí..." 
                        className="w-full p-6 bg-indigo-50 rounded-3xl font-bold min-h-[150px] border-4 border-transparent focus:border-indigo-200 outline-none"
                    />
                  ) : (
                    <div className="grid gap-3">
                        {examData.questions[currentQuestionIdx].options.map((opt: string, idx: number) => (
                        <button key={idx} onClick={() => setCurrentAnswer(opt)} className={`p-5 rounded-3xl text-left font-bold border-4 transition-all ${currentAnswer === opt ? 'bg-indigo-600 text-white border-indigo-600 shadow-lg' : 'bg-white border-indigo-50 hover:border-indigo-400'}`}>
                            {String.fromCharCode(65 + idx)}) {opt}
                        </button>
                        ))}
                    </div>
                  )}
                  <button onClick={handleCheckAnswer} disabled={!currentAnswer.trim()} className="mt-10 w-full bg-indigo-600 text-white font-black py-5 rounded-[2rem] text-xl shadow-xl uppercase">ENVIAR RESPUESTA</button>
                </>
              ) : (
                <div className="text-center py-6 flex flex-col items-center">
                  <div className={`text-5xl font-black mb-8 uppercase ${isLastAnswerCorrect ? 'text-green-600' : 'text-red-500'}`}>{isLastAnswerCorrect ? '¡CORRECTO!' : '¡SIGUE ADELANTE!'}</div>
                  <div className="bg-indigo-50 dark:bg-indigo-900/50 p-8 rounded-[2.5rem] border-4 border-indigo-100 mb-10 w-full text-left">
                    <p className="text-[10px] uppercase opacity-70 mb-2 font-black text-indigo-400">Explicación Técnica:</p>
                    <p className="text-lg font-bold italic text-indigo-900 dark:text-indigo-100 leading-relaxed">{aiFeedback}</p>
                  </div>
                  <button onClick={handleNextQuestion} className="w-full bg-indigo-600 text-white font-black py-5 rounded-[2rem] shadow-xl text-xl uppercase tracking-widest">CONTINUAR</button>
                </div>
              )}
            </div>
          </div>
        )}

        {showResultModal && (
          <div className="absolute inset-0 bg-indigo-900/95 flex items-center justify-center p-6 z-[1200] backdrop-blur-md">
            <div className="bg-white w-full max-w-lg rounded-[3.5rem] p-12 border-8 border-indigo-50 shadow-2xl text-center">
              <div className="text-7xl mb-6">{correctAnswersCount >= 6 ? '🏆' : '📚'}</div>
              <h2 className="text-4xl font-black text-indigo-900 mb-4 uppercase">{correctAnswersCount >= 6 ? '¡ACREDITADO!' : 'CASI LO LOGRAS'}</h2>
              <div className={`inline-block px-10 py-5 rounded-[2rem] border-4 mb-10 ${correctAnswersCount >= 6 ? 'bg-emerald-50 border-emerald-500 text-emerald-600' : 'bg-red-50 border-red-500 text-red-600'}`}>
                <p className="text-5xl font-black">{correctAnswersCount}.0 / 10</p>
              </div>
              <button onClick={() => onClose()} className="w-full bg-indigo-600 text-white font-black py-6 rounded-3xl shadow-xl uppercase">FINALIZAR 🚀</button>
            </div>
          </div>
        )}
      </div>
    </div>
  );
};
export default LessonWindow;

