  const [confirmPass, setConfirmPass] = useState('');
  const [passError, setPassError] = useState('');
  const [isUpdatingPass, setIsUpdatingPass] = useState(false);

  const [lastFinishedLessonId, setLastFinishedLessonId] = useState<string | null>(null);
  const [lastFinishedDate, setLastFinishedDate] = useState<string | null>(null);

  /**
   * Función para obtener el balance actual del estudiante.
   * Utiliza el ID (UUID) si está disponible, sino el username.
   */
  const fetchUserBalance = async (user: User) => {
    try {
      const ownerId = user.id || user.username;
      const balance = await getAccountBalance(ownerId);
      setTotalBalance(balance);
      return balance;
    } catch (err) {
      console.error("Error al obtener balance:", err);
      return 0;
    }
  };

  const setupSessionListener = (username: string) => {
    if (sessionSubscriptionRef.current) {
      supabase.removeChannel(sessionSubscriptionRef.current);
    }

    const channel = supabase
      .channel(`user-session-${username}`)
      .on(
        'postgres_changes',
        {
          event: 'UPDATE',
          schema: 'public',
          table: 'users',
          filter: `username=eq.${username}`
        },
        (payload) => {
          const remoteSessionId = payload.new.current_session_id;
          if (remoteSessionId && remoteSessionId !== tabSessionId) {
            setShowDuplicateModal(true);
          }
        }
      )
      .subscribe();

    sessionSubscriptionRef.current = channel;
  };

  // Escucha de cambios en tiempo real en la tabla USERS para el balance
  useEffect(() => {
    if (currentUser && currentUser.role === Role.STUDENT) {
      const filter = currentUser.id 
        ? `id=eq.${currentUser.id}` 
        : `username=eq.${currentUser.username}`;

      const channel = supabase
        .channel(`user-balance-changes-${currentUser.username}`)
        .on(
          'postgres_changes',
          {
            event: 'UPDATE',
            schema: 'public',
            table: 'users',
            filter: filter
          },
          (payload) => {
            // Si el balance cambió, actualizamos el estado local
            if (payload.new && typeof payload.new.balance !== 'undefined') {
              setTotalBalance(Number(payload.new.balance));
            }
          }
        )
        .subscribe();

      return () => {
        supabase.removeChannel(channel);
      };
    }
  }, [currentUser]);

  useEffect(() => {
    const loadApp = async () => {
      await initStorage();
      const storedUser = localStorage.getItem('current_user');
      if (storedUser) {
        const user = JSON.parse(storedUser);
        setCurrentUser(user);
        if (user.role === Role.STUDENT) {
          await autoUpdateLessonStatuses(user.username);
          fetchUserBalance(user);
          setupSessionListener(user.username);
          updateUserSession(user.username, tabSessionId);
        }
      }
      setIsInitializing(false);
    };
    loadApp();

    return () => {
      if (sessionSubscriptionRef.current) {
        supabase.removeChannel(sessionSubscriptionRef.current);
      }
    };
  }, []);

  useEffect(() => {
    if (darkMode) {
      document.documentElement.classList.add('dark');
      localStorage.setItem('theme', 'dark');
    } else {
      document.documentElement.classList.remove('dark');
      localStorage.setItem('theme', 'light');
    }
  }, [darkMode]);

  const handleLogin = async (user: User) => {
    setCurrentUser(user);
    localStorage.setItem('current_user', JSON.stringify(user));
    if (user.role === Role.STUDENT) {
      await autoUpdateLessonStatuses(user.username);
      fetchUserBalance(user);
      setupSessionListener(user.username);
      await updateUserSession(user.username, tabSessionId);
    }
  };

  const handleLogout = () => {
    if (currentUser) {
      updateUserSession(currentUser.username, null).catch(console.error);
    }
    setCurrentUser(null);
    setTotalBalance(0);
    setShowDuplicateModal(false);
    localStorage.removeItem('current_user');
    if (sessionSubscriptionRef.current) {
      supabase.removeChannel(sessionSubscriptionRef.current);
    }
  };

  const handleResumeHere = async () => {
    if (currentUser) {
      await updateUserSession(currentUser.username, tabSessionId);
      setShowDuplicateModal(false);
    }
  };

  const startLesson = (studentUsername: string, lessonId: string, isAccreditation: boolean = false, isAudit: boolean = false) => {
    setLastFinishedLessonId(null);
    setLastFinishedDate(null);
    setActiveLesson({ studentUsername, lessonId, isAccreditation, isAudit });
  };

  const handleUpdatePassword = async (e: React.FormEvent) => {
    e.preventDefault();
    setPassError('');
    if (!currentUser) return;

    if (currentPass !== currentUser.password) {
      setPassError('La contraseña actual es incorrecta.');
      return;
    }
    if (newPass.length < 4 || newPass.length > 8) {
      setPassError('La nueva contraseña debe tener entre 4 y 8 caracteres.');
      return;
    }
    if (newPass !== confirmPass) {
      setPassError('Las contraseñas nuevas no coinciden.');
      return;
    }

    setIsUpdatingPass(true);
    try {
      const updatedUser: User = { ...currentUser, password: newPass };
      await updateUser(currentUser.username, updatedUser);
      setCurrentUser(updatedUser);
      localStorage.setItem('current_user', JSON.stringify(updatedUser));
      setShowPasswordModal(false);
      setCurrentPass('');
      setNewPass('');
      setConfirmPass('');
      alert('¡Contraseña actualizada con éxito!');
    } catch (err) {
      setPassError('Error al actualizar. Intenta más tarde.');
    } finally {
      setIsUpdatingPass(false);
    }
  };

  if (isInitializing) {
    return (
      <div className="min-h-screen flex flex-col items-center justify-center bg-sky-50 dark:bg-indigo-950 transition-colors duration-500">
        <div className="w-16 h-16 border-4 border-indigo-600 border-t-transparent rounded-full animate-spin mb-4"></div>
        <p className="text-indigo-900 dark:text-sky-100 font-bold animate-pulse text-xl">Buensoft Education se está preparando...</p>
      </div>
    );
  }

  if (activeLesson) {
    return (
      <LessonWindow 
        studentUsername={activeLesson.studentUsername} 
        lessonId={activeLesson.lessonId}
        isAdminAudit={activeLesson.isAudit}
        isAccreditationMode={activeLesson.isAccreditation}
        onClose={(finishedDate, finishedId) => {
          setActiveLesson(null);
          if (finishedDate) setLastFinishedDate(finishedDate);
          if (finishedId) setLastFinishedLessonId(finishedId);
          if (currentUser && currentUser.role === Role.STUDENT) {
            fetchUserBalance(currentUser);
          }
        }} 
      />
    );
  }

  if (!currentUser) {
    return <Login onLogin={handleLogin} />;
  }

  return (
    <div className="min-h-screen bg-sky-50 dark:bg-indigo-950 transition-colors duration-300">
      <nav className="bg-white/80 dark:bg-indigo-900/80 backdrop-blur-md shadow-md p-4 flex justify-between items-center sticky top-0 z-[100] border-b dark:border-indigo-800 transition-colors duration-300">
        <div className="flex items-center space-x-3">
          <img src="https://buensoft.com/assets/Buensoft_Education_Logo.png" alt="Logo" className="w-10 h-10 md:w-12 md:h-12 object-contain rounded-lg shadow-sm" />
          <h1 className="text-lg md:text-xl font-black text-indigo-900 dark:text-white uppercase tracking-tight hidden sm:block">Buensoft Education</h1>
        </div>

        <div className="flex items-center space-x-2 sm:space-x-4">
          <div className="flex flex-col items-end">
            <span className="text-indigo-600 dark:text-indigo-200 font-bold text-xs">Hola, {currentUser.username}</span>
            <button 
              onClick={() => setShowPasswordModal(true)}
              className="text-[9px] font-black text-indigo-400 dark:text-indigo-500 uppercase tracking-widest hover:text-indigo-600 transition-colors"
            >
              Cambiar Contraseña
            </button>
          </div>

          <button 
            onClick={() => setDarkMode(!darkMode)}
            className="p-2 rounded-xl bg-indigo-50 dark:bg-indigo-800 text-indigo-600 dark:text-indigo-200 transition-all"
          >
            {darkMode ? <Sun size={20} /> : <Moon size={20} />}
          </button>

          {currentUser.role === Role.STUDENT && (
            <div className="flex items-center space-x-2 bg-amber-50 dark:bg-amber-900/30 px-3 py-2 rounded-xl border border-amber-100 dark:border-amber-800">
              <Wallet className="w-4 h-4 text-amber-500" />
              <span className="text-xs font-black text-amber-600 dark:text-amber-400">
                ${totalBalance.toFixed(2)}
              </span>
            </div>
          )}

          <button 
            onClick={handleLogout}
            className="p-2 rounded-xl bg-red-50 dark:bg-red-900/30 text-red-500 hover:bg-red-100 dark:hover:bg-red-900/50 transition-all"
          >
            <LogOut size={20} />
          </button>
        </div>
      </nav>

      <main className="max-w-7xl mx-auto px-4 py-8">
        {currentUser.role === Role.ADMIN ? (
          <AdminDashboard user={currentUser} />
        ) : (
          <StudentDashboard 
            user={currentUser} 
            onStartLesson={startLesson}
            lastFinishedLessonId={lastFinishedLessonId}
            initialSelectedDate={lastFinishedDate}
          />
        )}
      </main>

      {/* Duplicate Session Modal */}
      {showDuplicateModal && (
        <div className="fixed inset-0 bg-indigo-900/80 backdrop-blur-md z-[1000] flex items-center justify-center p-4">
          <div className="bg-white dark:bg-indigo-900 p-8 rounded-[3rem] w-full max-w-md shadow-2xl border-8 border-indigo-50 text-center">
            <Shield className="w-20 h-20 text-indigo-600 mx-auto mb-6" />
            <h2 className="text-2xl font-black text-indigo-900 dark:text-white uppercase mb-4">Sesión Duplicada</h2>
            <p className="text-indigo-400 dark:text-indigo-300 font-bold mb-8">Parece que tienes otra pestaña abierta con este usuario.</p>
            <div className="space-y-3">
              <button 
                onClick={handleResumeHere}
                className="w-full bg-indigo-600 text-white font-black py-4 rounded-2xl shadow-xl uppercase tracking-widest"
              >
                Continuar aquí 🚀
              </button>
              <button 
                onClick={handleLogout}
                className="w-full text-indigo-400 font-black py-2 uppercase text-xs"
              >
                Cerrar sesión
              </button>
            </div>
          </div>
        </div>
      )}

      {/* Password Update Modal */}
      {showPasswordModal && (
        <div className="fixed inset-0 bg-indigo-900/80 backdrop-blur-md z-[1000] flex items-center justify-center p-4">
          <div className="bg-white dark:bg-indigo-900 p-8 rounded-[3rem] w-full max-w-md shadow-2xl border-8 border-indigo-50">
            <h2 className="text-2xl font-black text-indigo-900 dark:text-white uppercase mb-6 text-center">Actualizar Contraseña</h2>
            <form onSubmit={handleUpdatePassword} className="space-y-4">
              <div>
                <label className="block text-[10px] font-black text-indigo-400 uppercase mb-2 ml-2">Contraseña Actual</label>
                <input 
                  type="password" 
                  value={currentPass}
                  onChange={(e) => setCurrentPass(e.target.value)}
                  className="w-full p-4 bg-indigo-50 dark:bg-indigo-950 rounded-2xl font-bold border-2 border-transparent focus:border-indigo-500 outline-none"
                  required
                />
              </div>
              <div>
                <label className="block text-[10px] font-black text-indigo-400 uppercase mb-2 ml-2">Nueva Contraseña</label>
                <input 
                  type="password" 
                  value={newPass}
                  onChange={(e) => setNewPass(e.target.value)}
                  className="w-full p-4 bg-indigo-50 dark:bg-indigo-950 rounded-2xl font-bold border-2 border-transparent focus:border-indigo-500 outline-none"
                  required
                />
              </div>
              <div>
                <label className="block text-[10px] font-black text-indigo-400 uppercase mb-2 ml-2">Confirmar Nueva Contraseña</label>
                <input 
                  type="password" 
                  value={confirmPass}
                  onChange={(e) => setConfirmPass(e.target.value)}
                  className="w-full p-4 bg-indigo-50 dark:bg-indigo-950 rounded-2xl font-bold border-2 border-transparent focus:border-indigo-500 outline-none"
                  required
                />
              </div>
              {passError && <p className="text-red-500 text-[10px] font-black uppercase text-center">{passError}</p>}
              <div className="flex space-x-3 pt-4">
                <button 
                  type="button" 
                  onClick={() => setShowPasswordModal(false)}
                  className="flex-1 text-indigo-400 font-black uppercase text-xs"
                >
                  Cancelar
                </button>
                <button 
                  type="submit" 
                  disabled={isUpdatingPass}
                  className="flex-1 bg-indigo-600 text-white font-black py-4 rounded-2xl shadow-xl uppercase text-xs disabled:opacity-50"
                >
                  {isUpdatingPass ? 'Actualizando...' : 'Guardar ✨'}
                </button>
              </div>
            </form>
          </div>
        </div>
      )}
    </div>
  );
};

export default App;

import React, { useState, useEffect, useMemo } from 'react';
import { User, Role, StudentData, Lesson, SubjectGuide, Transaction } from '../types';
import { 
  getUsers, 
  saveUser, 
  updateUser, 
  deleteUser, 
  getStudentData, 
  addLessonToStudent, 
  deleteLessonFromStudent, 
  updateLessonInStudent,
  getSubjectsGuide,
  saveSubjectGuide,
  updateSubjectGuide,
  deleteSubjectGuide,
  deleteLessonsBySubjectAndDays,
  updateLessonsPromptByCriteria,
  getAccountBalance,
  getAllTransactions,
  executeManualTransfer
} from '../storage2';
import { getSchoolDayStatus } from '../utils/schoolCalendar';
import StudentDashboard from './StudentDashboard';
// Fix: Changed default import of LessonWindow to a named import to resolve the "no default export" error.
import { LessonWindow } from './LessonWindow2';

interface AdminDashboardProps {
  user: User;
}

const AdminDashboard: React.FC<AdminDashboardProps> = ({ user }) => {
  const [activeTab, setActiveTab] = useState<'students' | 'subjects' | 'dynamic' | 'removal' | 'promptUpdate' | 'banca'>('students');
  const [students, setStudents] = useState<User[]>([]);
  const [subjectsGuide, setSubjectsGuide] = useState<SubjectGuide[]>([]);
  const [selectedStudent, setSelectedStudent] = useState<string>('');
  const [selectedUserObj, setSelectedUserObj] = useState<User | null>(null);
  const [studentData, setStudentData] = useState<StudentData | null>(null);

  const getLocalDateStr = (d: Date = new Date()) => {
    const year = d.getFullYear();
    const month = String(d.getMonth() + 1).padStart(2, '0');
    const day = String(d.getDate()).padStart(2, '0');
    return `${year}-${month}-${day}`;
  };

  const [selectedDate, setSelectedDate] = useState<string>(() => getLocalDateStr());
  const [isLoading, setIsLoading] = useState(false);

  const [adminBalance, setAdminBalance] = useState(0);
  const [allTransactions, setAllTransactions] = useState<Transaction[]>([]);
  const [manualAmount, setManualAmount] = useState<string>('');
  const [manualStudentId, setManualStudentId] = useState<string>('');
  const [manualConcept, setManualConcept] = useState<string>('');
  const [manualType, setManualType] = useState<'ingreso' | 'egreso'>('ingreso');
  const [isProcessingManual, setIsProcessingManual] = useState(false);

  const ADMIN_BALANCE_UUID = '6a6db323-6229-42e3-a8b8-3ccfa177dfd7';

  const [showUserModal, setShowUserModal] = useState(false);
  const [editingUser, setEditingUser] = useState<User | null>(null);
  const [userName, setUserName] = useState('');
  const [userPassword, setUserPassword] = useState('');
  const [userEmail, setUserEmail] = useState('');

  const [showSubjectModal, setShowSubjectModal] = useState(false);
  const [editingSubject, setEditingSubject] = useState<SubjectGuide | null>(null);
  const [subjectName, setSubjectName] = useState('');
  const [subjectLessons, setSubjectLessons] = useState('');
  const [subjectPrompt, setSubjectPrompt] = useState('');

  const [showLessonModal, setShowLessonModal] = useState(false);
  const [editingLessonId, setEditingLessonId] = useState<string | null>(null);
  const [lessonSubject, setLessonSubject] = useState('');
  const [lessonTitle, setLessonTitle] = useState('');
  const [lessonPrompt, setLessonPrompt] = useState('');
  const [lessonQuestions, setLessonQuestions] = useState('');
  const [lessonDuration, setLessonDuration] = useState(30);
  const [lessonDate, setLessonDate] = useState(selectedDate);
  const [showSubjectPicker, setShowSubjectPicker] = useState(false);

  const [viewingFullLesson, setViewingFullLesson] = useState<Lesson | null>(null);

  const [dynStudent, setDynStudent] = useState('');
  const [dynSubject, setDynSubject] = useState('');
  const [dynLessonsText, setDynLessonsText] = useState('');
  const [dynDays, setDynDays] = useState<boolean[]>([true, true, true, true, true, false, false]);
  const [dynDuration, setDynDuration] = useState(30);
  const [dynStartDate, setDynStartDate] = useState(new Date().toISOString().split('T')[0]);
  const [dynAiPrompt, setDynAiPrompt] = useState('');

  const [remStudent, setRemStudent] = useState('');
  const [remSubject, setRemSubject] = useState('');
  const [remDays, setRemDays] = useState<boolean[]>([true, true, true, true, true, false, false]);
  const [remStartDate, setRemStartDate] = useState(new Date().toISOString().split('T')[0]);
  const [remStudentSubjects, setRemStudentSubjects] = useState<string[]>([]);

  const [updStudent, setUpdStudent] = useState('');
  const [updSubject, setUpdSubject] = useState('');
  const [updDays, setUpdDays] = useState<boolean[]>([true, true, true, true, true, false, false]);
  const [updStartDate, setUpdStartDate] = useState(new Date().toISOString().split('T')[0]);
  const [updPrompt, setUpdPrompt] = useState('');
  const [updStudentSubjects, setUpdStudentSubjects] = useState<string[]>([]);

  const dayNamesShort = ['L', 'M', 'M', 'J', 'V', 'S', 'D'];

  const fetchData = async () => {
    setIsLoading(true);
    try {
      const [allUsers, allSubjects, balance, transactionsList] = await Promise.all([
        getUsers(),
        getSubjectsGuide(),
        getAccountBalance(ADMIN_BALANCE_UUID),
        getAllTransactions()
      ]);
      setStudents(allUsers.filter(u => u.role === Role.STUDENT));
      setSubjectsGuide(allSubjects);
      setAdminBalance(balance);
      setAllTransactions(transactionsList);
    } catch (err) {
      console.error("Error fetching initial data:", err);
    } finally {
      setIsLoading(false);
    }
  };

  useEffect(() => { fetchData(); }, []);

  useEffect(() => {
    if (remStudent) {
      getStudentData(remStudent).then(data => {
        if (data) {
          const uniqueSubjects = Array.from(new Set(data.lessons.map(l => l.subject)));
          setRemStudentSubjects(uniqueSubjects);
        }
      });
    } else { setRemStudentSubjects([]); }
  }, [remStudent]);

  useEffect(() => {
    if (updStudent) {
      getStudentData(updStudent).then(data => {
        if (data) {
          const uniqueSubjects = Array.from(new Set(data.lessons.map(l => l.subject)));
          setUpdStudentSubjects(uniqueSubjects);
        }
      });
    } else { setUpdStudentSubjects([]); }
  }, [updStudent]);

  useEffect(() => {
    if (selectedStudent) {
      const u = students.find(s => s.username === selectedStudent);
      if (u) setSelectedUserObj(u);
      refreshStudentLessons();
    } else {
      setStudentData(null);
      setSelectedUserObj(null);
    }
  }, [selectedStudent, students]);

  const refreshStudentLessons = async () => {
    if (selectedStudent) {
      setIsLoading(true);
      try {
        const data = await getStudentData(selectedStudent);
        setStudentData(data);
      } catch (err) {
        console.error("Error al cargar lecciones:", err);
      } finally {
        setIsLoading(false);
      }
    }
  };

  const handleSaveUser = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!userName || !userPassword) return;
    setIsLoading(true);
    try {
      const userData: User = { username: userName, password: userPassword, email: userEmail, role: Role.STUDENT };
      if (editingUser) await updateUser(editingUser.username, userData);
      else await saveUser(userData);
      await fetchData();
      setShowUserModal(false);
    } catch (err) { alert("Error al guardar estudiante."); } finally { setIsLoading(false); }
  };

  const handleDeleteStudent = async (username: string) => {
    if (!confirm(`¿Eliminar a ${username}?`)) return;
    setIsLoading(true);
    try {
      await deleteUser(username);
      if (selectedStudent === username) setSelectedStudent('');
      await fetchData();
    } catch (err) { alert("Error al eliminar."); } finally { setIsLoading(false); }
  };

  const handleSaveSubjectGuide = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!subjectName || !subjectLessons) return;
    setIsLoading(true);
    try {
      if (editingSubject) await updateSubjectGuide(editingSubject.id, subjectName, subjectLessons, subjectPrompt);
      else await saveSubjectGuide(subjectName, subjectLessons, subjectPrompt);
      await fetchData();
      setShowSubjectModal(false);
    } catch (err) { alert("Error al guardar materia."); } finally { setIsLoading(false); }
  };

  const handleDeleteSubjectFromGuide = async (id: string) => {
    if (!confirm("¿Eliminar materia de la guía?")) return;
    setIsLoading(true);
    try {
      await deleteSubjectGuide(id);
      await fetchData();
    } catch (err) { alert("Error al eliminar."); } finally { setIsLoading(false); }
  };

  const handleSaveLesson = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!selectedStudent || !lessonSubject || !lessonTitle) return;

    let parsedQuestions = null;
    if (lessonQuestions.trim()) {
      try {
        parsedQuestions = JSON.parse(lessonQuestions);
      } catch (err) {
        alert("¡Error de formato! El campo 'Questions' debe ser un JSON válido. Revisa paréntesis y comas.");
        return;
      }
    }

    setIsLoading(true);
    try {
      const lessonData: Lesson = {
        id: editingLessonId || 'temp-' + Date.now(),
        subject: lessonSubject,
        title: lessonTitle,
        learningPrompt: lessonPrompt,
        durationMinutes: lessonDuration,
        date: lessonDate,
        completed: editingLessonId ? (studentData?.lessons.find(l => l.id === editingLessonId)?.completed || false) : false,
        questions: parsedQuestions
      };
      if (editingLessonId && !editingLessonId.startsWith('temp-')) {
        const original = studentData?.lessons.find(l => l.id === editingLessonId);
        await updateLessonInStudent(selectedStudent, { ...original, ...lessonData });
      } else {
        await addLessonToStudent(selectedStudent, lessonData);
      }
      await refreshStudentLessons();
      setShowLessonModal(false);
    } catch (err) { alert("Error al guardar lección."); } finally { setIsLoading(false); }
  };

  const handleDynSubjectChange = (name: string) => {
    setDynSubject(name);
    const selected = subjectsGuide.find(s => s.name === name);
    if (selected) {
      setDynLessonsText(selected.lessons_list);
      setDynAiPrompt(selected.learning_prompt || '');
    }
  };

  const handleDynamicAssignment = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!dynStudent || !dynSubject || !dynLessonsText) return;
    const lessonParts = dynLessonsText.split(/(?=(?:Lección|Sesión|Tema|Clase)\s+\d+[:.\s])/gi).filter(p => p.trim().length > 0);
    setIsLoading(true);
    try {
      let currentDate = new Date(dynStartDate + 'T12:00:00');
      let assignedCount = 0;
      while (assignedCount < lessonParts.length) {
        const dateStr = currentDate.toISOString().split('T')[0];
        const dayOfWeek = (currentDate.getDay() + 6) % 7;
        if (dynDays[dayOfWeek] && getSchoolDayStatus(dateStr).isSchoolDay) {
          await addLessonToStudent(dynStudent, {
            id: 'temp-' + Date.now() + '-' + assignedCount,
            subject: dynSubject,
            title: lessonParts[assignedCount].trim(),
            learningPrompt: dynAiPrompt,
            durationMinutes: dynDuration,
            date: dateStr,
            completed: false
          });
          assignedCount++;
        }
        currentDate.setDate(currentDate.getDate() + 1);
        if (currentDate.getFullYear() > 2027) break;
      }
      alert(`¡Se asignaron ${assignedCount} lecciones con éxito!`);
      if (selectedStudent === dynStudent) refreshStudentLessons();
    } catch (err) { alert("Error en asignación masiva."); } finally { setIsLoading(false); }
  };

  const handleDynamicRemoval = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!remStudent || !remSubject) return;
    if (!confirm(`¿Estás seguro de eliminar "${remSubject}" para ${remStudent}?`)) return;
    setIsLoading(true);
    try {
      await deleteLessonsBySubjectAndDays(remStudent, remSubject, remDays, remStartDate);
      alert("Lecciones eliminadas correctamente.");
      if (selectedStudent === remStudent) refreshStudentLessons();
    } catch (err) { alert("Error al eliminar."); } finally { setIsLoading(false); }
  };

  const handlePromptUpdate = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!updStudent || !updSubject || !updPrompt) return;
    setIsLoading(true);
    try {
      await updateLessonsPromptByCriteria(updStudent, updSubject, updDays, updStartDate, updPrompt);
      alert("Prompts actualizados correctamente.");
      if (selectedStudent === updStudent) refreshStudentLessons();
    } catch (err) { alert("Error al actualizar."); } finally { setIsLoading(false); }
  };

  const handleManualTransfer = async (e: React.FormEvent) => {
    e.preventDefault();
    const amount = parseFloat(manualAmount);
    if (!manualStudentId || isNaN(amount) || amount <= 0 || !manualConcept) {
      alert("Por favor completa todos los campos correctamente.");
      return;
    }
    const confirmMsg = manualType === 'ingreso' ? `¿Confirmas el ingreso de $${amount}?` : `¿Confirmas el egreso de $${amount}?`;
    if (!confirm(confirmMsg)) return;
    setIsProcessingManual(true);
    try {
      const isIncome = manualType === 'ingreso';
      await executeManualTransfer(manualStudentId, amount, manualConcept, isIncome);
      alert("Transacción realizada con éxito.");
      setManualAmount(''); setManualConcept('');
      fetchData();
