      <header className={`${isAdminAudit ? 'bg-slate-700' : 'bg-indigo-600'} p-4 shadow-lg flex justify-between items-center z-[1100] border-b-4 border-white/10 shrink-0`}>
          <div className="flex items-center space-x-6">
            {!isAdminAudit && !isAccreditationMode && (
              <div className="flex space-x-3">
                <div className="bg-white/10 px-3 py-1.5 rounded-2xl flex flex-col items-center min-w-[100px] border border-white/10">
                  <span className="text-[8px] font-black text-white/60 uppercase">TIEMPO</span>
                  <span className="text-sm font-black text-white font-mono">{Math.floor(secondsElapsed / 60)}m / {lesson.durationMinutes}m</span>
                </div>
                <div className="bg-white/10 px-3 py-1.5 rounded-2xl flex flex-col items-center min-w-[100px] border border-white/10">
                  <span className="text-[8px] font-black text-white/60 uppercase">INTERACCIONES</span>
                  <span className="text-sm font-black text-white font-mono">{validCount} / {targetInteractions}</span>
                </div>
              </div>
            )}
            <div className="text-white">
              <h2 className="text-sm font-black uppercase truncate">{isAccreditationMode ? 'EXAMEN DE ACREDITACIÓN' : lesson.title}</h2>
              <p className="text-[9px] font-bold opacity-70 uppercase">{lesson.subject}</p>
            </div>
