                  <div className={`text-5xl font-black mb-8 uppercase ${isLastAnswerCorrect ? 'text-green-600' : 'text-red-500'}`}>{isLastAnswerCorrect ? '¡CORRECTO!' : 'FALLASTE'}</div>
                  <div className="bg-indigo-50 p-8 rounded-[2.5rem] border-4 border-indigo-100 mb-10 w-full text-left">
                    {!isLastAnswerCorrect && <p className="text-sm font-black text-red-500 mb-2 uppercase">Lo correcto era: {examData.questions[currentQuestionIdx].correctAnswer}</p>}
                    <p className="text-lg font-bold italic text-indigo-900 leading-relaxed">{aiFeedback}</p>
                  </div>
                  <button onClick={handleNextQuestion} className="w-full bg-indigo-600 text-white font-black py-5 rounded-[2rem] shadow-xl text-xl uppercase tracking-widest">SIGUIENTE</button>
