                            <td className={`py-4 pr-4 font-black ${isOutgoing ? 'text-red-500' : 'text-green-500'}`}>
                              {isOutgoing ? '-' : '+'} ${tx.amount.toFixed(2)}
                            </td>
                            <td className="py-4 truncate max-w-[150px]">{tx.concept}</td>
                          </tr>
                        );
                      })
                    )}
                  </tbody>
                </table>
              </div>
            </div>
          </div>
        </div>
      )}

      {/* Modal Interceptor: Elección de Ruta */}
      {showChoiceModal && (
        <div className="fixed inset-0 bg-indigo-900/90 backdrop-blur-md z-[1000] flex items-center justify-center p-6">
          <div className="bg-white dark:bg-indigo-900 p-10 rounded-[3.5rem] w-full max-w-lg shadow-2xl border-8 border-indigo-50 dark:border-indigo-800 text-center animate-in zoom-in duration-300">
            <div className="text-7xl mb-8">🎯</div>
            <h2 className="text-3xl font-black text-indigo-900 dark:text-white mb-4 uppercase leading-none">Ruta de Aprendizaje</h2>
            <p className="text-indigo-400 dark:text-indigo-300 font-bold mb-10 text-sm">¿Cómo deseas acceder a "{pendingLesson?.title}"?</p>

            <div className="grid gap-4">
              <button 
                onClick={() => proceedWithRoute(false)}
                className="w-full bg-indigo-600 text-white font-black py-6 rounded-3xl shadow-xl hover:bg-indigo-700 transition-all text-lg uppercase tracking-tight flex items-center justify-center space-x-3"
              >
                <span>Tomar la lección</span> <span>📚</span>
              </button>

              <div className="flex flex-col">
                <button 
                  onClick={() => proceedWithRoute(true)}
                  className="w-full bg-amber-400 text-indigo-900 font-black py-6 rounded-3xl shadow-xl hover:bg-amber-500 transition-all text-lg uppercase tracking-tight flex items-center justify-center space-x-3"
                >
                  <span>Examen de Acreditación Directa</span> <span>🎯</span>
                </button>
                <p className="text-[10px] font-black text-amber-600 uppercase mt-2">El profesor debe de estar presente</p>
              </div>

              <button 
                onClick={() => {setShowChoiceModal(false); setPendingLesson(null);}}
                className="mt-4 text-xs font-black text-indigo-300 uppercase underline"
              >
                Regresar al aula
              </button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default StudentDashboard;

import { GoogleGenAI, Type } from "@google/genai";
import { ChatMessage, Lesson } from "./types";

const getAIInstance = () => {
  const apiKey = process.env.API_KEY;
  if (!apiKey) throw new Error("API_KEY no encontrada.");
  return new GoogleGenAI({ apiKey });
};

const cleanJsonResponse = (text: string) => text.replace(/```json/g, "").replace(/```/g, "").trim();

const prepareHistoryForGemini = (history?: ChatMessage[]) => {
  if (!history) return [];
  // Filtramos mensajes silenciosos o puramente lógicos para el contexto de la IA
  const recentHistory = history
    .filter(m => m.parts && m.parts[0]?.text && !m.isSilent)
    .slice(-15);
  return recentHistory.map(({ role, parts }) => ({ 
    role, 
    parts: (parts || []).map(p => ({ text: p?.text || "" })) 
  }));
};

function shuffleOptions<T>(array: T[]): T[] {
  if (!Array.isArray(array)) return [];
  const shuffled = [...array];
  for (let i = shuffled.length - 1; i > 0; i--) {
    const j = Math.floor(Math.random() * (i + 1));
    [shuffled[i], shuffled[j]] = [shuffled[j], shuffled[i]];
  }
  return shuffled;
}

export const getGeminiChat = async (lesson: Lesson, studentName: string, history?: ChatMessage[]) => {
  const ai = getAIInstance();
  const validCount = lesson.validInteractionsCount || 0;
  const nextTurnNumber = validCount + 1;
  const isOdd = nextTurnNumber % 2 !== 0;

  const systemInstruction = `
    ROL: Tutor académico experto. Materia: ${lesson.subject}. Tema: "${lesson.title}". Estudiante: ${studentName}.

    PROTOCOLO DE ENSEÑANZA:
    1. INICIO: Si recibes "START_LESSON", presenta el primer micro-tema de forma breve y técnica.
    2. CONTINUACIÓN: Si recibes "[RESUME_MODE]", analiza el historial previo, haz un brevísimo resumen de donde se quedaron y continúa con la siguiente parte del tema.
    3. INTERACCIÓN 1:1: En cada turno, explica un concept (micro-tema) y haz UNA sola pregunta técnica.
    4. EVALUACIÓN: 
       - Si la respuesta del alumno demuestra que comprendió el micro-tema actual, incluye el tag [RESPUESTA_VALIDA].
       - Si la respuesta es incorrecta o insuficiente, incluye el tag [RESPUESTA_INCORRECTA].
    5. IRRELEVANCIA: Si el alumno intenta cambiar de tema o escribe algo fuera de contexto académico, responde ÚNICAMENTE "[IRRELEVANTE]".

    FORMATO DE RESPUESTA OBLIGATORIO:
    [EXPLICACION] Feedback técnico sobre la respuesta anterior y explicación del siguiente micro-tema. [/EXPLICACION]
    [DATA_LOGICA] {"type":"${isOdd ? 'WRITTEN' : 'MCQ'}", "question":"...", "options":${isOdd ? '[]' : '["...","...","...","..."]'}, "correct":"..."} [/DATA_LOGICA]

    REGLA MCQ: Las 4 opciones DEBEN tener una longitud, complejidad y estructura gramatical casi idéntica para evitar que se adivine la respuesta por su extensión. No facilites la clase.
  `;

  return ai.chats.create({
    model: 'gemini-3-flash-preview',
    config: { systemInstruction },
    history: prepareHistoryForGemini(history)
  });
};

export const generateExam = async (lessonTitle: string, chatHistory: any[]) => {
  const ai = getAIInstance();
  const historyContext = (chatHistory || [])
    .filter(m => m.parts && m.parts[0]?.text && !m.parts[0].text.includes('[') && !m.parts[0].text.includes(']'))
    .slice(-10)
    .map(m => `${m.role === 'user' ? 'E' : 'T'}: ${m.parts[0].text}`)
    .join('\n');

  const examPrompt = `Genera un examen final de 10 preguntas de opción múltiple sobre "${lessonTitle}". 
  Contexto de lo enseñado: ${historyContext}.
