import { GoogleGenAI, Type, Modality } from "@google/genai";
import { ChatMessage, Lesson } from "./types";

const getAIInstance = () => {
  const apiKey = process.env.API_KEY;
  if (!apiKey) throw new Error("API_KEY no encontrada.");
  return new GoogleGenAI({ apiKey });
};

const cleanJsonResponse = (text: string) => text.replace(/```json/g, "").replace(/```/g, "").trim();

const prepareHistoryForGemini = (history?: ChatMessage[]) => {
  if (!history) return [];
  // Filtramos mensajes silenciosos o puramente lógicos para el contexto de la IA
  const recentHistory = history
    .filter(m => m.parts && m.parts[0]?.text && !m.isSilent)
    .slice(-15);
  return recentHistory.map(({ role, parts }) => ({ 
    role, 
    parts: (parts || []).map(p => ({ text: p?.text || "" })) 
  }));
};

function shuffleOptions<T>(array: T[]): T[] {
  if (!Array.isArray(array)) return [];
  const shuffled = [...array];
  for (let i = shuffled.length - 1; i > 0; i--) {
    const j = Math.floor(Math.random() * (i + 1));
    [shuffled[i], shuffled[j]] = [shuffled[j], shuffled[i]];
  }
  return shuffled;
}

export const getGeminiChat = async (lesson: Lesson, studentName: string, history?: ChatMessage[]) => {
  const ai = getAIInstance();
  const validCount = lesson.validInteractionsCount || 0;
  const targetInteractions = Math.ceil(lesson.durationMinutes * 0.8);
  const timeGoalSeconds = lesson.durationMinutes * 60;

  // Determinamos el tipo de pregunta basado en el conteo para alternar
  const nextTurnNumber = validCount + 1;
  const isOdd = nextTurnNumber % 2 !== 0;

  const systemInstruction = `
    ROL: Tutor académico experto de Buensoft Education. 
    MATERIA: ${lesson.subject}. 
    TEMA PRINCIPAL: "${lesson.title}". 
    ESTUDIANTE: ${studentName}.
    META DE INTERACCIONES VÁLIDAS: ${targetInteractions}.
    META DE TIEMPO: ${lesson.durationMinutes} minutos.

    PROTOCOLO PEDAGÓGICO OBLIGATORIO:
    1. PLANIFICACIÓN: Divide el TEMA PRINCIPAL en aproximadamente ${targetInteractions} micro-temas progresivos. Debes cubrir la totalidad del temario de forma granular.
    2. ESTRUCTURA POR TURNO: En cada respuesta debes presentar UN SOLO micro-tema de forma técnica y concisa, seguido de UNA pregunta de comprobación.
    3. ALTERNANCIA: Alterna estrictamente entre preguntas de Opción Múltiple (MCQ) y preguntas Abiertas (WRITTEN).
    4. FLUJO DE APROBACIÓN:
       - Si el estudiante responde CORRECTAMENTE: Incluye [RESPUESTA_VALIDA] y avanza al SIGUIENTE micro-tema en el próximo turno.
       - Si el estudiante se EQUIVOCA: Incluye [RESPUESTA_INCORRECTA]. Debes dar una explicación breve de por qué falló y volver a explicar el MISMO micro-tema. En el próximo turno, vuelve a preguntar sobre el MISMO concepto pero con una pregunta diferente. NO avances de micro-tema hasta que el estudiante demuestre comprensión.
    5. MODO REFUERZO: Si has cubierto todos los micro-temas pero el estudiante aún no alcanza las ${targetInteractions} interacciones o el tiempo de estudio requerido, entra en "Modo Refuerzo". Re-evalúa los conceptos donde el estudiante tuvo dudas o fallos previos con mayor profundidad.
    6. IRRELEVANCIA: Si el estudiante se desvía del tema, responde únicamente "[IRRELEVANTE]".

    REGLA DE DISEÑO MCQ:
    - Debes generar exactamente 4 opciones.
    - Las 4 opciones DEBEN tener una longitud, complejidad gramatical y nivel de detalle casi idéntico.
    - La respuesta correcta no debe destacar visualmente por ser más larga o corta.
    - El orden de las opciones debe ser aleatorio en cada generación.

    FORMATO DE RESPUESTA:
    [EXPLICACION] (Tu feedback y la explicación del micro-tema actual) [/EXPLICACION]
    [DATA_LOGICA] {"type":"(MCQ o WRITTEN)", "question":"...", "options":["...","...","...","..."], "correct":"..."} [/DATA_LOGICA]
  `;

  return ai.chats.create({
    model: 'gemini-3-flash-preview',
    config: { systemInstruction },
    history: prepareHistoryForGemini(history)
  });
};

export const generateExam = async (lessonTitle: string, chatHistory: any[]) => {
  const ai = getAIInstance();
  const historyContext = (chatHistory || [])
    .filter(m => m.parts && m.parts[0]?.text && !m.parts[0].text.includes('[') && !m.parts[0].text.includes(']'))
    .slice(-10)
    .map(m => `${m.role === 'user' ? 'E' : 'T'}: ${m.parts[0].text}`)
    .join('\n');

  const examPrompt = `Genera un examen final de 10 preguntas de opción múltiple sobre "${lessonTitle}". 
  Contexto de lo enseñado: ${historyContext}.
  REGLA CRÍTICA DE DISEÑO: Las 4 opciones (A, B, C, D) de cada pregunta DEBEN tener una longitud y estructura gramatical muy similar entre sí. La respuesta correcta NO debe ser más larga ni más detallada que los distractores. Las opciones deben presentarse en orden aleatorio.
  Devuelve JSON con preguntas id, text, options(4), correctAnswer y explanation técnico.`;

  const response = await ai.models.generateContent({
    model: 'gemini-3-flash-preview',
    contents: [{ role: 'user', parts: [{ text: examPrompt }] }],
    config: {
      responseMimeType: "application/json",
      responseSchema: {
        type: Type.OBJECT,
        properties: {
          questions: {
            type: Type.ARRAY,
            items: {
              type: Type.OBJECT,
              properties: {
                id: { type: Type.INTEGER },
                text: { type: Type.STRING },
                type: { type: Type.STRING },
                options: { type: Type.ARRAY, items: { type: Type.STRING } },
                correctAnswer: { type: Type.STRING },
                explanation: { type: Type.STRING }
              },
              required: ["id", "text", "type", "correctAnswer", "explanation", "options"]
            }
          }
        },
        required: ["questions"]
      }
    }
  });

  try {
    const cleaned = cleanJsonResponse(response.text || '');
    const examData = JSON.parse(cleaned);
    if (examData.questions) {
      examData.questions = examData.questions.map((q: any) => {
        const cleanStr = (s: string) => (typeof s === 'string') ? s.replace(/^[A-Z]\)\s*/, '') : s;
        const shuffled = shuffleOptions(q.options.map(cleanStr));
        return { ...q, options: shuffled, correctAnswer: cleanStr(q.correctAnswer) };
      });
    }
    return examData;
  } catch (e) { return { questions: [] }; }
};

export const generateQuestionBank = async (subject: string, topic: string) => {
  const ai = getAIInstance();
  const prompt = `Actúa como diseñador instruccional. Genera un banco de preguntas (JSON) basado únicamente en el tema: "${topic}" de la materia "${subject}".
  Genera exactamente 50 preguntas variadas:
  - 20 Opción Múltiple (multiple_choice) con 4 opciones (3 distractores, 1 correcta). REGLA CRÍTICA: Las 4 opciones DEBEN tener una longitud, complejidad y estructura gramatical similar para evitar que la respuesta correcta destaque.
  - 20 Abiertas (open) con acceptable_answers.
  - 10 Verdadero/Falso (true_false) con correct_answer "TRUE" o "FALSE".
  Dificultad equilibrada. JSON estricto.`;

  const response = await ai.models.generateContent({
    model: 'gemini-3-flash-preview',
    contents: [{ role: 'user', parts: [{ text: prompt }] }],
    config: {
      responseMimeType: "application/json",
      responseSchema: {
        type: Type.OBJECT,
        properties: {
          questions: {
            type: Type.ARRAY,
            items: {
              type: Type.OBJECT,
              properties: {
                id: { type: Type.STRING },
                type: { type: Type.STRING },
                question: { type: Type.STRING },
                options: { type: Type.ARRAY, items: { type: Type.STRING }, description: "Solo para multiple_choice" },
                correct_answer: { type: Type.STRING },
                acceptable_answers: { type: Type.ARRAY, items: { type: Type.STRING }, description: "Solo para open" },
                explanation: { type: Type.STRING }
              },
              required: ["id", "type", "question", "correct_answer", "explanation"]
            }
          }
        },
        required: ["questions"]
      }
    }
  });

  try {
    const text = response.text || '';
    const cleaned = cleanJsonResponse(text);
    const parsed = JSON.parse(cleaned);
    if (parsed.questions) {
        parsed.questions = parsed.questions.map((q: any) => ({
            ...q,
            options: shuffleOptions(q.options || []),
            acceptable_answers: q.acceptable_answers || []
        }));
    }
    return parsed;
  } catch (e) {
    console.error("Error al generar banco de preguntas:", e);
    throw e;
  }
};

export const validateOpenAnswer = async (question: string, acceptableAnswers: string[], studentAnswer: string): Promise<boolean> => {
  const ai = getAIInstance();
  const prompt = `Evalúa la respuesta del estudiante.
  Pregunta: "${question}"
  Respuestas Correctas: ${JSON.stringify(acceptableAnswers)}
  Respuesta Estudiante: "${studentAnswer}"
  Responde únicamente TRUE si es semánticamente correcta o FALSE si no lo es.`;

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: [{ role: 'user', parts: [{ text: prompt }] }],
      config: { temperature: 0.1 }
    });
    return response.text.trim().toUpperCase().includes("TRUE");
  } catch (e) { return false; }
};

export const generateSpeech = async (text: string) => {
  const ai = getAIInstance();
  try {
    const response = await ai.models.generateContent({
      model: "gemini-2.5-flash-preview-tts",
      contents: [{ parts: [{ text }] }],
      config: {
        responseModalities: [Modality.AUDIO],
        speechConfig: {
          voiceConfig: {
            prebuiltVoiceConfig: { voiceName: 'Kore' },
          },
        },
      },
    });
    return response.candidates?.[0]?.content?.parts?.[0]?.inlineData?.data;
  } catch (e) {
    console.error("Error generating speech:", e);
    return null;
  }
};

export function decode(base64: string) {
  const binaryString = atob(base64);
  const len = binaryString.length;
  const bytes = new Uint8Array(len);
  for (let i = 0; i < len; i++) {
    bytes[i] = binaryString.charCodeAt(i);
  }
  return bytes;
}

export async function decodeAudioData(
  data: Uint8Array,
  ctx: AudioContext,
  sampleRate: number,
  numChannels: number,
): Promise<AudioBuffer> {
  const dataInt16 = new Int16Array(data.buffer);
  const frameCount = dataInt16.length / numChannels;
  const buffer = ctx.createBuffer(numChannels, frameCount, sampleRate);

  for (let channel = 0; channel < numChannels; channel++) {
    const channelData = buffer.getChannelData(channel);
    for (let i = 0; i < frameCount; i++) {
      channelData[i] = dataInt16[i * numChannels + channel] / 32768.0;
    }
  }
  return buffer;
}

