interface ParsedAIResponse {
  explanation: string;
  challengeType?: 'MCQ' | 'WRITTEN';
  question?: { text: string; options?: string[]; correct?: string; };
  errorInfo?: string;
  refuerzo?: string;
  isPlagio?: boolean;
  isIrrelevant?: boolean;
}

interface RichMessageProps {
  message: ChatMessage;
  onAction: (val: string) => void;
  timeLeft?: number;
  isUnlocked?: boolean;
  isAudit?: boolean;
  studentInitial?: string;
  isLessonFinished?: boolean;
  isParentLoading?: boolean;
  isHistory?: boolean;
  isPlaying?: boolean;
  isAudioLoading?: boolean;
}

const RichMessage: React.FC<RichMessageProps> = memo(({ message, onAction, timeLeft, isUnlocked = false, isAudit, studentInitial, isLessonFinished, isParentLoading, isHistory, isPlaying, isAudioLoading }) => {
  const [selectedOption, setSelectedOption] = useState<string | null>(message.selectedOption || null);
  const text = message.parts[0].text;
  const isUser = message.role === 'user';
  const isSystemLog = text.startsWith('📢');
  const formatTime = (iso?: string) => iso ? new Date(iso).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit', hour12: false }) : '';

  const parseResponse = (raw: string): ParsedAIResponse => {
    const isPlagio = raw.includes('[PLAGIO_IA]');
    const isIrrelevant = raw.includes('[IRRELEVANTE]');
    const dataMatch = raw.match(/\[DATA_LOGICA\]([\s\S]*?)\[\/DATA_LOGICA\]/);
    const expMatch = raw.match(/\[EXPLICACION\]([\s\S]*?)\[\/EXPLICACION\]/);

    let explanation = expMatch ? expMatch[1].trim() : raw.replace(/\[DATA_LOGICA\][\s\S]*/g, '').replace(/\[EXPLICACION\]|\[\/EXPLICACION\]|\[RESPUESTA_VALIDA\]|\[RESPUESTA_INCORRECTA\]|\[PLAGIO_IA\]|\[IRRELEVANTE\]|\[REFUERZO\]|\[ERROR_INFO\]/g, '').trim();

    let questionData; let challengeType;
    if (dataMatch) {
      try {
        const json = JSON.parse(dataMatch[1].trim());
        challengeType = json.type;
        const cleanStr = (s: string) => (typeof s === 'string') ? s.replace(/^[A-Z]\)\s*/, '') : s;
        questionData = { text: json.question, options: Array.isArray(json.options) ? json.options.map(cleanStr) : [], correct: cleanStr(json.correct) };
      } catch (e) { console.error(e); }
    }
    return { explanation, challengeType, question: questionData, isPlagio, isIrrelevant };
  };

  const handleOptionClick = (opt: string) => {
    if (selectedOption || message.selectedOption || isAudit || isHistory || timeLeft === 0 || isParentLoading) return;
    setSelectedOption(opt); 
    setTimeout(() => onAction(opt), 800);
  };

  if (isUser) {
    return (
      <div className="flex items-start space-x-3 justify-end w-full animate-in fade-in slide-in-from-right-4 duration-300">
        <div className="bg-indigo-600 text-white p-5 rounded-[2.5rem] shadow-sm border-2 border-indigo-700 max-w-full w-fit ml-auto relative pb-10 min-w-[100px]">
          <div className="prose dark:prose-invert max-w-none text-lg font-bold">{text}</div>
          <div className="absolute bottom-3 right-8 text-xs font-black opacity-80 uppercase tracking-tighter">{formatTime(message.timestamp)}</div>
        </div>
        <div className="w-10 h-10 rounded-full bg-white dark:bg-indigo-800 border-2 border-indigo-200 flex items-center justify-center text-indigo-600 font-black shrink-0">{studentInitial}</div>
      </div>
    );
  }

  if (isSystemLog) {
    return (
      <div className="flex justify-center my-2 animate-in fade-in zoom-in duration-300">
        <div className="bg-slate-100 dark:bg-indigo-900/50 text-indigo-400 dark:text-indigo-300 px-6 py-2 rounded-2xl text-[10px] font-black uppercase tracking-widest border border-indigo-50 dark:border-indigo-800 shadow-sm flex items-center space-x-2">
          <span>{text}</span>
          <span className="opacity-50">•</span>
          <span className="opacity-50">{formatTime(message.timestamp)}</span>
        </div>
      </div>
    );
  }

  const parsed = parseResponse(text);
  const activeSelection = selectedOption || message.selectedOption;
  const showQuestionBlock = parsed.question && (isUnlocked || activeSelection || isAudit || message.is_unlocked || message.studentResponse);

  return (
    <div className={`flex items-start space-x-3 w-full animate-in fade-in slide-in-from-left-4 duration-500`}>
      <div className="w-10 h-10 rounded-2xl bg-indigo-50 dark:bg-indigo-800 border-2 border-indigo-100 flex items-center justify-center text-xl shrink-0">🤖</div>
      <div className={`p-6 rounded-[2.5rem] shadow-sm border-2 flex-1 w-full max-w-full relative pb-12 ${parsed.isIrrelevant ? 'bg-amber-50 border-amber-300' : 'bg-white dark:bg-indigo-900 border-indigo-50'}`}>
        {!isAudit && !isHistory && !parsed.isIrrelevant && (
          <button 
            onClick={() => onAction("__SPEAK__" + parsed.explanation + "||" + message.timestamp)} 
            disabled={isAudioLoading && !isPlaying}
            className={`absolute top-4 right-4 transition-all p-2 rounded-xl z-10 disabled:opacity-30 ${isPlaying ? 'text-indigo-600 bg-indigo-50 scale-110' : 'text-indigo-300 hover:text-indigo-600 hover:bg-indigo-50'}`}
            title={isPlaying ? "Pausar" : "Escuchar lección"}
          >
            {isPlaying ? '⏸️' : isAudioLoading ? '⌛' : '🔊'}
          </button>
        )}
        <div className="flex flex-col space-y-4">
          {parsed.isIrrelevant ? (
            <div className="prose dark:prose-invert max-w-none text-lg font-bold text-amber-700">
              ⚠️ ¡Vuelve al tema! Tu respuesta está fuera de contexto. Por favor, enfócate en la lección para poder avanzar.
            </div>
          ) : (
            <div className="pregunta-contenedor prose dark:prose-invert max-w-none text-lg">
              <ReactMarkdown remarkPlugins={[remarkGfm]} rehypePlugins={[rehypeRaw]} components={MarkdownComponents}>{parsed.explanation}</ReactMarkdown>
              {!isUnlocked && !activeSelection && !isAudit && !isHistory && parsed.question && !isLessonFinished && !message.studentResponse && !message.is_unlocked && (
                <div className="mt-6"><button onClick={() => onAction("__UNLOCK_QUESTION__")} disabled={isParentLoading} className="bg-indigo-600 text-white border-2 border-indigo-500 px-6 py-4 rounded-2xl font-black text-sm hover:bg-indigo-700 shadow-xl uppercase tracking-widest disabled:opacity-50 transform active:scale-95 transition-all active:bg-indigo-800">Ya leí y comprendí 🎯</button></div>
              )}
              {showQuestionBlock && !isLessonFinished && (
                <div className="animate-in zoom-in-95 pt-6 border-t-4 border-indigo-50 mt-6">
                  <p className="texto-pregunta text-xl font-black mb-6 leading-tight">{parsed.question.text}</p>
                  {message.studentResponse && <div className={`p-6 rounded-[1.5rem] font-black text-lg shadow-md border-2 mb-6 ${message.validationStatus === 'correct' ? 'bg-green-500 border-green-600 text-white' : message.validationStatus === 'incorrect' ? 'bg-red-500 border-red-600 text-white' : 'bg-blue-600 border-blue-700 text-white'}`}><p className="text-[10px] font-black uppercase mb-2 opacity-80">Tu Respuesta</p>{message.studentResponse}</div>}
                  {parsed.challengeType === 'MCQ' && (
                    <div className="grid gap-3">
                      {parsed.question.options?.map((opt, idx) => {
                        const isSelected = activeSelection === opt; const isCorrect = opt === parsed.question?.correct;
                        let btnClass = "bg-white dark:bg-indigo-950 text-indigo-600 border-indigo-100 hover:bg-indigo-50";
                        if (activeSelection) {
                          if (message.validationStatus) {
                            if (isSelected) btnClass = message.validationStatus === 'correct' ? "bg-green-500 text-white border-green-600 shadow-lg" : "bg-red-500 text-white border-red-600 shadow-lg";
                            else if (isCorrect && message.validationStatus === 'incorrect') btnClass = "bg-green-500 text-white border-green-600 shadow-md animate-pulse";
                            else btnClass = "bg-slate-50 border-indigo-50 opacity-40 text-indigo-300";
                          } else { 
                            btnClass = isSelected ? "bg-blue-600 text-white border-blue-700 shadow-lg" : "bg-slate-50 border-indigo-50 opacity-60 text-indigo-300"; 
                          }
                        } else if (!isAudit && !isHistory) btnClass = "bg-indigo-600 border-indigo-500 hover:bg-indigo-700 text-white active:bg-indigo-800";
                        return <button key={idx} onClick={() => handleOptionClick(opt)} disabled={!!activeSelection || isAudit || isHistory || isParentLoading} className={`w-full text-left px-6 py-5 rounded-[1.5rem] font-black text-lg shadow-md transition-all active:scale-95 border-2 ${btnClass}`}>{String.fromCharCode(65 + idx)}) {opt}</button>;
                      })}
                    </div>
                  )}
                </div>
              )}
            </div>
          )}
        </div>
        <div className="absolute bottom-3 right-8 text-xs font-black opacity-60 uppercase tracking-tighter text-indigo-400">{formatTime(message.timestamp)}</div>
      </div>
    </div>
  );
});

const DateDivider: React.FC<{ date: string }> = ({ date }) => {
  const d = new Date(date);
  const options: Intl.DateTimeFormatOptions = { weekday: 'long', day: 'numeric', month: 'long', year: 'numeric' };
  const formattedDate = d.toLocaleDateString('es-ES', options);
  const today = new Date().toDateString();
  const msgDate = d.toDateString();
  const label = today === msgDate ? 'Hoy' : formattedDate;
  return (
    <div className="flex justify-center my-6">
      <div className="bg-indigo-100 dark:bg-indigo-900/50 text-indigo-600 dark:text-indigo-200 px-6 py-2 rounded-full text-[10px] font-black uppercase tracking-widest border border-indigo-200 dark:border-indigo-800 shadow-sm">
        {label}
      </div>
    </div>
  );
};

export const LessonWindow: React.FC<LessonWindowProps> = ({ studentUsername, lessonId, onClose, isAdminAudit: forcedAudit = false, isAccreditationMode = false }) => {
  const [lesson, setLesson] = useState<Lesson | null>(null);
  const [messages, setMessages] = useState<ChatMessage[]>([]);
  const [input, setInput] = useState('');
  const [isLoading, setIsLoading] = useState(false);
  const [isTyping, setIsTyping] = useState(false);
  const [isPaused, setIsPaused] = useState(false);
  const [loadingText, setLoadingText] = useState('');
  const [secondsElapsed, setSecondsElapsed] = useState(0);
  const [validCount, setValidCount] = useState(0);
  const [targetInteractions, setTargetInteractions] = useState(30);
  const [isUnlocked, setIsUnlocked] = useState(false);

  const [showExam, setShowExam] = useState(false);
  const [examData, setExamData] = useState<any>(null);
  const [currentQuestionIdx, setCurrentQuestionIdx] = useState(0);
  const [currentAnswer, setCurrentAnswer] = useState('');
  const [showQuestionFeedback, setShowQuestionFeedback] = useState(false);
  const [isLastAnswerCorrect, setIsLastAnswerCorrect] = useState(false);
  const [aiFeedback, setAiFeedback] = useState('');
  const [isExamFinished, setIsExamFinished] = useState(false);
  const [correctAnswersCount, setCorrectAnswersCount] = useState(0);
  const [examTimer, setExamTimer] = useState(0);
  const [showResultModal, setShowResultModal] = useState(false);
  const [isValidatingAI, setIsValidatingAI] = useState(false);
  const [playingMsgId, setPlayingMsgId] = useState<string | null>(null);
  const [isAudioLoading, setIsAudioLoading] = useState(false);

  const [showAdminVerifyModal, setShowAdminVerifyModal] = useState(false);
  const [adminPassInput, setAdminPassInput] = useState('');
  const [adminPassAttempts, setAdminPassAttempts] = useState(3);
  const [isVerifyingPass, setIsVerifyingPass] = useState(false);

  const chatRef = useRef<any>(null);
  const messagesEndRef = useRef<HTMLDivElement>(null);
  const messagesRef = useRef<ChatMessage[]>([]);
  const audioRef = useRef<{ context: AudioContext | null, source: AudioBufferSourceNode | null }>({ context: null, source: null });

  const loggedTimeGoal = useRef(false);
  const loggedInteractionsGoal = useRef(false);

  // Ref para rastrear la última actividad y pausar por inactividad
  const lastActivityRef = useRef<number>(Date.now());

  const isAdminAudit = forcedAudit || (lesson?.credits_transfered === true);
  const timeMet = useMemo(() => Math.floor(secondsElapsed / 60) >= (lesson?.durationMinutes || 0), [secondsElapsed, lesson]);
  const interactionsMet = validCount >= targetInteractions;

  useEffect(() => { messagesRef.current = messages; }, [messages]);

  // Temporizador principal de lección e inactividad
  useEffect(() => {
    if (!showExam && !isLoading && !isPaused && !isAdminAudit && !isAccreditationMode && !isExamFinished && lesson) {
      const timer = setInterval(() => {
        setSecondsElapsed(prev => prev + 1);

        // Chequeo de inactividad (3 minutos = 180 segundos)
        const now = Date.now();
        const inactiveTime = (now - lastActivityRef.current) / 1000;
        if (inactiveTime >= 180) {
          handleAutoPause();
        }
      }, 1000);
      return () => clearInterval(timer);
    }
  }, [showExam, isLoading, isPaused, isAdminAudit, isAccreditationMode, isExamFinished, lesson]);

  const addLogMessage = (text: string) => {
    const msg: ChatMessage = {
      role: 'model',
      parts: [{ text: `📢 ${text}` }],
      timestamp: new Date().toISOString(),
      is_unlocked: true,
      isSilent: true 
    };
    setMessages(prev => [...prev, msg]);
  };

  const handleAutoPause = () => {
    if (isPaused || showExam || isAdminAudit) return;

    // Descontar 3 minutos (180 segundos)
    setSecondsElapsed(prev => Math.max(0, prev - 180));

    // Pausar
    setIsPaused(true);

    // Log
    addLogMessage(`${studentUsername} no mostró actividad por más de 3 minutos. La lección se ha pausado automáticamente y se han descontado 3 minutos del tiempo transcurrido.`);

    // Reiniciar ref de actividad para evitar bucle inmediato
    lastActivityRef.current = Date.now();

    // Guardar estado
    if (lesson) {
      const updated: Lesson = {
        ...lesson,
        chatHistory: messagesRef.current,
        elapsedSeconds: Math.max(0, secondsElapsed - 180),
        validInteractionsCount: validCount
      };
      updateLessonInStudent(studentUsername, updated);
    }
  };

  const updateActivity = () => {
    lastActivityRef.current = Date.now();
  };

  useEffect(() => {
    if (timeMet && !loggedTimeGoal.current && !isAdminAudit && !isAccreditationMode) {
      addLogMessage(`${studentUsername} completo el tiempo requerido de estudio de esta lección`);
      loggedTimeGoal.current = true;
    }
  }, [timeMet, isAdminAudit, isAccreditationMode, studentUsername]);

  useEffect(() => {
    if (interactionsMet && !loggedTimeGoal.current && !isAdminAudit && !isAccreditationMode) {
      addLogMessage(`${studentUsername} completo las interacciónes requeridas de esta lección`);
      loggedInteractionsGoal.current = true;
    }
  }, [interactionsMet, isAdminAudit, isAccreditationMode, studentUsername]);

  // Temporizador de examen
  useEffect(() => {
    let timer: any;
    if (showExam && !showQuestionFeedback && !isExamFinished) {
      if (examTimer > 0) {
        timer = setInterval(() => {
          setExamTimer(prev => prev - 1);
        }, 1000);
      } else {
        handleCheckAnswer();
      }
    }
    return () => clearInterval(timer);
  }, [showExam, showQuestionFeedback, examTimer, isExamFinished]);

  useEffect(() => {
    const fetchLesson = async () => {
      const res = await getStudentData(studentUsername);
      if (res) {
        const found = res.lessons.find(l => l.id === lessonId);
        if (found) {
          setLesson(found);
          setSecondsElapsed(found.elapsedSeconds || 0);
          setValidCount(found.validInteractionsCount || 0);
          setTargetInteractions(Math.ceil(found.durationMinutes * 0.8));
          if (found.chatHistory?.length) setMessages(found.chatHistory);

          if (isAccreditationMode) {
            await initAccreditationExam(found);
          } else if (!isAdminAudit) {
            startGeminiChat(found, (found.chatHistory?.length || 0) > 0);
          }
        }
      }
    };
    fetchLesson();
  }, [studentUsername, lessonId, isAccreditationMode]);

  const scrollToBottom = () => {
    messagesEndRef.current?.scrollIntoView({ behavior: 'smooth' });
  };

  useEffect(() => { scrollToBottom(); }, [messages, isTyping]);

  const formatSeconds = (s: number) => {
    const mins = Math.floor(s / 60);
    const secs = String(s % 60).padStart(2, '0');
    return `${mins}:${secs}`;
  };

  const initAccreditationExam = async (l: Lesson) => {
    setIsLoading(true);
    setLoadingText("Generando banco de preguntas especializado...");
    try {
      let questionsPayload = l.questions;
      const hasQuestions = questionsPayload && questionsPayload.questions && Array.isArray(questionsPayload.questions) && questionsPayload.questions.length >= 50;

      if (!hasQuestions) {
        const generated = await generateQuestionBank(l.subject, l.title);
        questionsPayload = generated;
        const updatedLesson = { ...l, questions: generated };
        await updateLessonInStudent(studentUsername, updatedLesson);
        setLesson(updatedLesson);
      }

      const shuffle = (arr: any[]) => [...arr].sort(() => 0.5 - Math.random());
      const randomSelection = shuffle(questionsPayload.questions).slice(0, 25);

      setExamData({ questions: randomSelection.map((q, i) => {
          const type = q.type || 'multiple_choice';
          const isTF = type === 'true_false';
          return {
            id: i,
            text: q.question,
            type: type,
            options: isTF ? ["VERDADERO", "FALSO"] : (q.options || []),
            correctAnswer: isTF 
              ? (String(q.correct_answer).toUpperCase().includes("TRUE") || String(q.correct_answer).toUpperCase().includes("VERDADERO") ? "VERDADERO" : "FALSO")
              : q.correct_answer,
            acceptableAnswers: q.acceptable_answers || [],
            explanation: q.explanation || "Información validada académica."
          };
      })});

      setShowExam(true);
      setCurrentQuestionIdx(0);
      setCorrectAnswersCount(0);
      setExamTimer(60);
    } catch (err) { 
      console.error(err);
      onClose();
    } finally { setIsLoading(false); }
  };

  const startGeminiChat = async (l: Lesson, isResuming: boolean) => {
    if (chatRef.current) return;
    setIsTyping(true);
    try {
      if (isResuming) {
        addLogMessage(`${studentUsername} esta retomando la lección`);
      }
      const chat = await getGeminiChat(l, studentUsername, l.chatHistory);
      chatRef.current = chat;
      const response = await chat.sendMessage({ message: isResuming ? `[RESUME_MODE]` : `START_LESSON` });
      setMessages(prev => [...prev, { role: 'model', parts: [{ text: response.text || '' }], timestamp: new Date().toISOString(), is_unlocked: false }]);
    } catch (err) { console.error(err); } finally { setIsTyping(false); }
  };

  const stopCurrentAudio = () => {
    if (audioRef.current.source) {
      try {
        audioRef.current.source.stop();
      } catch (e) { }
      audioRef.current.source = null;
    }
  };

  const handleSpeak = async (text: string, msgId: string) => {
    if (isTyping || isLoading || isAudioLoading) return;

    if (playingMsgId === msgId) {
      stopCurrentAudio();
      setPlayingMsgId(null);
      return;
    }

    stopCurrentAudio();
    setIsAudioLoading(true);
    setPlayingMsgId(msgId);

    try {
      const base64Audio = await generateSpeech(text);
      if (!base64Audio) {
        setPlayingMsgId(null);
        setIsAudioLoading(false);
        return;
      }

      if (!audioRef.current.context) {
        audioRef.current.context = new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 24000 });
      }

      const arrayBuffer = decode(base64Audio);
      const audioBuffer = await decodeAudioData(arrayBuffer, audioRef.current.context, 24000, 1);

      const source = audioRef.current.context.createBufferSource();
      source.buffer = audioBuffer;
      source.connect(audioRef.current.context.destination);

      source.onended = () => {
        setPlayingMsgId(current => (current === msgId ? null : current));
      };

      source.start();
      audioRef.current.source = source;
    } catch (err) {
      console.error("Error al reproducir audio:", err);
      setPlayingMsgId(null);
    } finally {
      setIsAudioLoading(false);
    }
  };

  const handleSend = async (manualText?: string) => {
    updateActivity();
    if (isAdminAudit || isTyping || isPaused) return;

    if (manualText === "__UNLOCK_QUESTION__") {
        setIsUnlocked(true);
        setMessages(prev => {
            const updated = [...prev];
            for (let i = updated.length - 1; i >= 0; i--) {
                if (updated[i].role === 'model' && updated[i].parts[0].text.includes('[DATA_LOGICA]')) {
                    updated[i].is_unlocked = true;
                    break;
                }
            }
            return updated;
        });
        return;
    }

    if (manualText?.startsWith("__SPEAK__")) {
      const parts = manualText.replace("__SPEAK__", "").split("||");
      const textToSpeak = parts[0];
      const msgId = parts[1];
      handleSpeak(textToSpeak, msgId);
      return;
    }

    const userText = (manualText || input).trim();
    if (!userText) return;

    const isMcqSelection = !!manualText && manualText !== "__UNLOCK_QUESTION__";

    setInput('');
    setIsTyping(true);
    const userMsg: ChatMessage = { role: 'user', parts: [{ text: userText }], timestamp: new Date().toISOString() };

    setMessages(prev => {
      const updated = [...prev];
      if (isMcqSelection) {
        let lastQuestionIdx = -1;
        for (let i = updated.length - 1; i >= 0; i--) {
          if (updated[i].role === 'model' && updated[i].parts[0].text.includes('[DATA_LOGICA]')) {
            lastQuestionIdx = i;
            break;
          }
        }
        if (lastQuestionIdx !== -1) {
          updated[lastQuestionIdx] = {
            ...updated[lastQuestionIdx],
            selectedOption: userText,
            validationStatus: undefined 
          };
        }
      }
      return [...updated, userMsg];
    });

    try {
      const result = await chatRef.current.sendMessage({ message: userText });
      const text = result.text || '';

      const isIrrelevant = text.includes('[IRRELEVANTE]');
      const isValid = text.includes('[RESPUESTA_VALIDA]');

      if (!isIrrelevant && isValid) {
        setValidCount(prev => prev + 1);
      }

      const aiMsg: ChatMessage = { 
        role: 'model', 
        parts: [{ text }], 
        timestamp: new Date().toISOString(), 
        is_unlocked: false,
        validationStatus: isIrrelevant ? 'irrelevant' : (isValid ? 'correct' : 'incorrect')
      };

      setMessages(prev => {
        const updated = [...prev];
        let lastQuestionIdx = -1;
        for (let i = updated.length - 2; i >= 0; i--) {
          if (updated[i].role === 'model' && updated[i].parts[0].text.includes('[DATA_LOGICA]')) {
            lastQuestionIdx = i;
            break;
          }
        }

        if (lastQuestionIdx !== -1) {
          updated[lastQuestionIdx] = {
            ...updated[lastQuestionIdx],
            selectedOption: isMcqSelection ? userText : undefined,
            studentResponse: !isMcqSelection ? userText : undefined,
            validationStatus: isIrrelevant ? 'irrelevant' : (isValid ? 'correct' : 'incorrect')
          };
        }

        return [...updated, aiMsg];
      });
      setIsUnlocked(false);
    } catch (err) { console.error(err); } finally { setIsTyping(false); }
  };

  const handleTogglePause = async () => {
    updateActivity();
    const nextPause = !isPaused;
    setIsPaused(nextPause);

    const logText = nextPause ? `${studentUsername} pausó la lección` : `${studentUsername} renaudó la lección`;
    addLogMessage(logText);

    if (lesson && !isAdminAudit) {
      const updated: Lesson = {
        ...lesson,
        chatHistory: messagesRef.current,
        elapsedSeconds: secondsElapsed,
        validInteractionsCount: validCount
      };
      await updateLessonInStudent(studentUsername, updated);
    }
  };

  const handleExit = async () => {
    setIsLoading(true);
    setLoadingText("Guardando historial...");
    stopCurrentAudio();
    try {
      if (lesson && !isAdminAudit) {
        let finalMessages = [...messagesRef.current];

        if (showExam && !isExamFinished) {
          const totalQ = isAccreditationMode ? 25 : 10;
          finalMessages.push({
            role: 'model',
            parts: [{ text: `📢 ${studentUsername} salio del examen sin terminarlo en la pregunta ${currentQuestionIdx + 1} de ${totalQ}` }],
            timestamp: new Date().toISOString(),
            isSilent: true,
            is_unlocked: true
          });
        } else if (!lesson.completed && !isAccreditationMode && !isExamFinished) {
          finalMessages.push({
            role: 'model',
            parts: [{ text: `📢 ${studentUsername} salio de la lección sin terminar` }],
            timestamp: new Date().toISOString(),
            isSilent: true,
            is_unlocked: true
          });
        }

        const updated: Lesson = {
          ...lesson,
          chatHistory: finalMessages,
          elapsedSeconds: secondsElapsed,
          validInteractionsCount: validCount
        };
        await updateLessonInStudent(studentUsername, updated);
      }
    } catch (err) {
      console.error("Error al guardar historial al salir:", err);
    } finally {
      onClose();
    }
  };

  const handleCheckAnswer = async () => {
    updateActivity();
    if (!examData) return;
    const q = examData.questions[currentQuestionIdx];
    let isCorrect = false;

    if (q.type === 'multiple_choice' || q.type === 'true_false') {
        isCorrect = (currentAnswer === q.correctAnswer);
    } else {
        const clean = (s: string) => s.toLowerCase().trim();
        const studentAnsClean = clean(currentAnswer);
        isCorrect = q.acceptableAnswers?.some((ans: string) => studentAnsClean.includes(clean(ans))) || false;

        if (!isCorrect && studentAnsClean.length > 0) {
            setIsValidatingAI(true);
            try {
                isCorrect = await validateOpenAnswer(q.text, q.acceptableAnswers, currentAnswer);
            } catch (e) { 
                console.error("Error validando con IA:", e);
                isCorrect = false; 
            } finally { 
                setIsValidatingAI(false); 
            }
        }
    }

    setIsLastAnswerCorrect(isCorrect);
    setAiFeedback(q.explanation);
    if (isCorrect) setCorrectAnswersCount(prev => prev + 1);
    setShowQuestionFeedback(true);
  };

  const handleNextQuestion = () => {
    updateActivity();
    const total = isAccreditationMode ? 25 : 10;
    if (currentQuestionIdx < total - 1) {
      setCurrentQuestionIdx(prev => prev + 1);
      setShowQuestionFeedback(false);
      setCurrentAnswer('');
      setExamTimer(60);
    } else finishExam();
  };

  const startLessonExam = async () => {
    if (!lesson) return;
    updateActivity();
    setIsLoading(true);
    setLoadingText("Preparando evaluación final...");
    try {
      let questionsPayload = lesson.questions;
      const hasQuestions = questionsPayload && questionsPayload.questions && Array.isArray(questionsPayload.questions) && questionsPayload.questions.length >= 50;

      if (!hasQuestions) {
        const generated = await generateQuestionBank(lesson.subject, lesson.title);
        questionsPayload = generated;
        const updatedLesson = { ...lesson, questions: generated };
        await updateLessonInStudent(studentUsername, updatedLesson);
        setLesson(updatedLesson);
      }

      const shuffle = (arr: any[]) => [...arr].sort(() => 0.5 - Math.random());
      const randomSelection = shuffle(questionsPayload.questions).slice(0, 10);

      setExamData({ questions: randomSelection.map((q, i) => {
          const type = q.type || 'multiple_choice';
          const isTF = type === 'true_false';
          return {
            id: i,
            text: q.question,
            type: type,
            options: isTF ? ["VERDADERO", "FALSO"] : (q.options || []),
            correctAnswer: isTF 
              ? (String(q.correct_answer).toUpperCase().includes("TRUE") || String(q.correct_answer).toUpperCase().includes("VERDADERO") ? "VERDADERO" : "FALSO")
              : q.correct_answer,
            acceptableAnswers: q.acceptable_answers || [],
            explanation: q.explanation || "Información validada académica."
          };
      })});

      addLogMessage(`${studentUsername} solicito el examen de evalución de esta lección`);
      setShowExam(true);
      setCurrentQuestionIdx(0);
      setCorrectAnswersCount(0);
      setExamTimer(60);
    } catch (err) { 
      console.error(err);
    } finally { 
      setIsLoading(false); 
    }
  };

  const finishExam = async () => {
    setShowExam(false);
    const passingThreshold = isAccreditationMode ? 15 : 6;
    if (isAccreditationMode && correctAnswersCount >= passingThreshold) {
      setShowAdminVerifyModal(true);
    } else {
      await accreditAndShowResults(correctAnswersCount);
    }
  };

  const accreditAndShowResults = async (gradeCount: number) => {
    if (lesson) {
      const normalizedGrade = isAccreditationMode 
        ? Math.round((gradeCount / 25) * 10)
        : gradeCount;

      const isPassed = normalizedGrade >= 6;
      const statusText = isPassed ? 'Aprobada' : 'Reprobada';
      const resultAction = isPassed ? "aprobó" : "reprobó";
      const totalQuestions = isAccreditationMode ? 25 : 10;
      addLogMessage(`${studentUsername} ${resultAction} el examen de esta lección con ${gradeCount} de ${totalQuestions} correctas`);

      const updated: Lesson = { 
        ...lesson, 
        grade: normalizedGrade, 
        completed: isPassed, 
        lesson_status: statusText as any,
        chatHistory: messagesRef.current,
        elapsedSeconds: secondsElapsed,
        validInteractionsCount: validCount
      };
      await updateLessonInStudent(studentUsername, updated);
      setLesson(updated);
      setShowResultModal(true);
    }
  };

  const handleVerifyAdminPass = async () => {
    setIsVerifyingPass(true);
    try {
      const users = await getUsers();
      const admin = users.find(u => u.role === Role.ADMIN);
      const reversedPass = (admin?.password || '').split('').reverse().join('');
      if (adminPassInput === reversedPass) {
        setShowAdminVerifyModal(false);
        await accreditAndShowResults(correctAnswersCount);
      } else {
        setAdminPassAttempts(prev => prev - 1);
        setAdminPassInput('');
        if (adminPassAttempts <= 1) onClose();
      }
    } catch (err) { alert("Error"); } finally { setIsVerifyingPass(false); }
  };

  if (!lesson) return null;

  return (
    <div className={`fixed inset-0 bg-white dark:bg-indigo-950 z-[500] flex flex-col font-fredoka overflow-hidden select-none ${isAdminAudit ? 'relative h-full' : ''}`}>
      {isLoading && (
        <div className="fixed inset-0 bg-indigo-900/95 z-[2000] flex flex-col items-center justify-center p-8 text-center">
          <div className="w-24 h-24 border-8 border-indigo-400 border-t-white rounded-full animate-spin mb-8"></div>
          <h2 className="text-3xl font-black text-white uppercase mb-4 tracking-widest">{loadingText}</h2>
        </div>
      )}

      <header className={`${isAdminAudit ? 'bg-slate-700' : 'bg-indigo-600'} px-6 py-4 shadow-lg flex flex-col z-[1100] border-b-4 border-white/10 shrink-0 gap-3`}>
          <div className="flex items-center justify-between w-full gap-4">
            <div className="flex items-center space-x-2 shrink-0">
              {!isAdminAudit && !isAccreditationMode && !showExam && !isExamFinished && (
                <>
                  <div className={`${timeMet ? 'bg-green-600' : 'bg-white/10'} px-3 py-1.5 rounded-2xl flex flex-col items-center min-w-[100px] border border-white/10 transition-colors duration-500`}>
                    <span className="text-[7px] font-black text-white/60 uppercase">CRONÓMETRO</span>
                    <span className="text-xs font-black text-white font-mono leading-none">
                      {formatSeconds(secondsElapsed)} / {formatSeconds(lesson.durationMinutes * 60)}
                    </span>
                  </div>
                  <div className={`${interactionsMet ? 'bg-green-600' : 'bg-white/10'} px-3 py-1.5 rounded-2xl flex flex-col items-center min-w-[100px] border border-white/10 transition-colors duration-500`}>
                    <span className="text-[7px] font-black text-white/60 uppercase">INTERACCIONES</span>
                    <span className="text-xs font-black text-white font-mono leading-none">{validCount} / {targetInteractions}</span>
                  </div>
                </>
              )}
            </div>

            <div className="flex-1 text-center overflow-hidden">
              <h2 className="text-[10px] md:text-xs font-black text-white uppercase tracking-tight leading-tight">
                MATERIA: {lesson.subject}<br />
                LECCIÓN: {lesson.title}
              </h2>
            </div>

            <div className="flex items-center space-x-2 shrink-0">
              {!isAdminAudit && !isAccreditationMode && !isExamFinished && !showExam && (
                <button onClick={handleTogglePause} className={`h-10 px-4 rounded-xl font-black text-[10px] uppercase shadow-lg transition-all flex items-center space-x-2 transform active:scale-90 active:bg-white/30 duration-100 ${isPaused ? 'bg-amber-400 text-indigo-900 animate-pulse' : 'bg-white/10 text-white hover:bg-white/20 border border-white/10'}`}>
                  <span>{isPaused ? '▶️' : '⏸️'}</span>
                  <span className="hidden sm:inline">{isPaused ? 'REANUDAR' : 'PAUSAR'}</span>
                </button>
              )}
              <button onClick={handleExit} className="h-10 px-4 rounded-xl bg-red-500 hover:bg-red-600 transition-all flex items-center justify-center font-black text-white text-[10px] uppercase shadow-lg space-x-2 border border-white/10 transform active:scale-90 active:bg-red-700 duration-100">
                <span className="hidden sm:inline">SALIR</span>
                <span>✕</span>
              </button>
            </div>
          </div>
      </header>

      <div className="flex-1 relative flex flex-col bg-sky-50 dark:bg-indigo-950 overflow-hidden min-h-0">
        <div className={`flex-1 flex flex-col min-h-0 ${(showExam || showResultModal || showAdminVerifyModal) ? 'opacity-20 pointer-events-none' : ''}`}>
          <div className="flex-1 overflow-y-auto px-[5%] py-10 space-y-4 custom-scrollbar min-h-0">
            {messages.map((m, i) => {
              const prevMsg = i > 0 ? messages[i-1] : null;
              const isDifferentDay = !prevMsg || (new Date(m.timestamp || '').toDateString() !== new Date(prevMsg.timestamp || '').toDateString());
              return (
                <React.Fragment key={i}>
                  {isDifferentDay && m.timestamp && <DateDivider date={m.timestamp} />}
                  <RichMessage 
                    message={m} 
                    onAction={handleSend} 
                    studentInitial={studentUsername.charAt(0).toUpperCase()} 
                    isLessonFinished={isExamFinished} 
                    isParentLoading={isTyping} 
                    isPlaying={playingMsgId === m.timestamp}
                    isAudioLoading={isAudioLoading}
                  />
                </React.Fragment>
              );
            })}
            {isTyping && (
              <div className="flex items-start space-x-3 w-full animate-pulse">
                <div className="w-10 h-10 rounded-2xl bg-indigo-100 dark:bg-indigo-800 flex items-center justify-center text-xl shrink-0">🤖</div>
                <div className="p-4 bg-white dark:bg-indigo-900 rounded-3xl border-2 border-indigo-50 shadow-sm">
                  <span className="text-xs font-black text-indigo-400 uppercase italic">El profesor está analizando y escribiendo...</span>
                </div>
              </div>
            )}
            <div ref={messagesEndRef} />
          </div>

          {!isAdminAudit && !isAccreditationMode && !isExamFinished && (
            <div className={`p-6 bg-white dark:bg-indigo-900 border-t-4 border-indigo-50 relative shrink-0 transition-opacity ${isPaused ? 'opacity-40 pointer-events-none' : 'opacity-100'}`}>
               {timeMet && interactionsMet && !showExam && (
                  <div className="absolute -top-16 left-0 right-0 px-6 flex justify-center animate-bounce">
                    <button onClick={startLessonExam} className="bg-green-600 text-white px-10 py-4 rounded-full font-black shadow-2xl border-4 border-white hover:bg-green-700 transition-all uppercase tracking-widest text-xs transform active:scale-95 duration-100 active:bg-green-800">
                      ¡OBJETIVOS LOGRADOS! SOLICITAR EXAMEN DE ACREDITACIÓN 🏁
                    </button>
                  </div>
               )}
               <div className="w-full flex items-center space-x-3" onClick={updateActivity}>
                <textarea 
                  value={input} 
                  onChange={(e) => setInput(e.target.value)} 
                  onKeyDown={(e) => {
                    updateActivity();
                    if (e.key === 'Enter' && !e.shiftKey) {
                      e.preventDefault();
                      handleSend();
                    }
                  }} 
                  className="flex-1 px-6 py-4 rounded-3xl border-4 border-indigo-50 dark:bg-indigo-950 font-bold resize-none h-16 shadow-inner text-lg outline-none focus:border-indigo-500 transition-all" 
                  placeholder={isPaused ? "Lección pausada..." : "Tu respuesta académica..."} 
                  disabled={isTyping || isPaused} 
                />
                <button 
                  onClick={() => handleSend()} 
                  disabled={isTyping || !input.trim() || isPaused} 
                  className="bg-indigo-600 text-white w-16 h-16 rounded-3xl text-xl shadow-xl hover:bg-indigo-700 transition-all flex items-center justify-center disabled:opacity-50 transform active:scale-90 active:bg-indigo-800 duration-100"
                >
                  ➔
                </button>
              </div>
            </div>
          )}
        </div>

        {showExam && examData && (
          <div className="absolute inset-0 bg-indigo-900/90 flex items-center justify-center p-4 z-[800] backdrop-blur-sm">
            <div className="bg-white w-full max-w-2xl rounded-[3rem] p-10 border-8 border-indigo-50 shadow-2xl overflow-y-auto max-h-[95vh] flex flex-col">
              {!showQuestionFeedback ? (
                <>
                  <div className="flex justify-between items-center mb-8">
                    <div className="bg-indigo-100 text-indigo-600 px-4 py-2 rounded-2xl font-black text-xs uppercase">PREGUNTA {currentQuestionIdx + 1} DE {isAccreditationMode ? 25 : 10}</div>
                    <div className="w-12 h-12 rounded-full border-4 border-indigo-600 flex items-center justify-center font-black text-sm text-indigo-600 transition-all duration-300">{examTimer}s</div>
                  </div>
                  <h3 className="text-2xl font-black text-indigo-900 text-center mb-10 leading-tight">{examData.questions[currentQuestionIdx].text}</h3>
                  {examData.questions[currentQuestionIdx].type === 'open' ? (
                    <textarea 
                      value={currentAnswer} 
                      onChange={(e) => { updateActivity(); setCurrentAnswer(e.target.value); }} 
                      className="w-full p-6 bg-indigo-50 rounded-3xl font-bold min-h-[150px] outline-none border-4 border-transparent focus:border-indigo-200 shadow-inner transition-all" 
                      placeholder="Analiza y responde..." 
                    />
                  ) : (
                    <div className="grid gap-3">
                        {examData.questions[currentQuestionIdx].options.map((opt: string, idx: number) => (
                        <button key={idx} onClick={() => { updateActivity(); setCurrentAnswer(opt); }} className={`p-5 rounded-3xl text-left font-bold border-4 transition-all transform active:scale-[0.96] active:bg-indigo-50 ${currentAnswer === opt ? 'bg-indigo-600 text-white border-indigo-600 shadow-lg' : 'bg-white border-indigo-50 hover:border-indigo-400'}`}>
                            {opt}
                        </button>
                        ))}
                    </div>
                  )}
                  <button onClick={handleCheckAnswer} disabled={!currentAnswer.trim() || isValidatingAI} className="mt-10 w-full bg-indigo-600 text-white font-black py-5 rounded-[2rem] text-xl shadow-xl uppercase transform active:scale-95 active:bg-indigo-800 transition-all flex items-center justify-center space-x-3 disabled:opacity-50">
                    {isValidatingAI ? (
                      <>
                        <div className="w-6 h-6 border-4 border-white/30 border-t-white rounded-full animate-spin"></div>
                        <span>Validando respuesta...</span>
                      </>
                    ) : (
                      <span>CALIFICAR RESPUESTA</span>
                    )}
                  </button>
                </>
              ) : (
                <div className="text-center py-6 flex flex-col items-center">
                  <div className={`text-5xl font-black mb-8 uppercase animate-in zoom-in duration-300 ${isLastAnswerCorrect ? 'text-green-600' : 'text-red-500'}`}>{isLastAnswerCorrect ? '¡CORRECTO!' : 'FALLASTE'}</div>
                  <div className="bg-indigo-50 p-8 rounded-[2.5rem] border-4 border-indigo-100 mb-10 w-full text-left shadow-inner">
                    {!isLastAnswerCorrect && <p className="text-sm font-black text-red-500 mb-2 uppercase">Lo correcto era: {examData.questions[currentQuestionIdx].correctAnswer}</p>}
                    <p className="text-lg font-bold italic text-indigo-900 leading-relaxed">{aiFeedback}</p>
                  </div>
                  <button onClick={handleNextQuestion} className="w-full bg-indigo-600 text-white font-black py-5 rounded-[2rem] shadow-xl text-xl uppercase tracking-widest transform active:scale-95 active:bg-indigo-800 transition-all">SIGUIENTE</button>
                </div>
              )}
            </div>
          </div>
        )}

        {showAdminVerifyModal && (
          <div className="absolute inset-0 bg-indigo-900/95 flex items-center justify-center p-6 z-[1200] backdrop-blur-md">
            <div className="bg-white w-full max-w-lg rounded-[3.5rem] p-12 border-8 border-indigo-50 shadow-2xl text-center">
              <h2 className="text-3xl font-black text-indigo-900 mb-4 uppercase">Verificación Parental</h2>
              <p className="text-indigo-400 font-bold mb-8">Pide a tu profesor que ingrese su contraseña para validar tu acreditación.</p>
              <input type="password" value={adminPassInput} onChange={(e) => setAdminPassInput(e.target.value)} className="w-full p-5 bg-indigo-50 rounded-2xl border-4 text-center text-2xl font-black" placeholder="••••" />
              <button onClick={handleVerifyAdminPass} className="w-full mt-6 bg-indigo-600 text-white font-black py-5 rounded-3xl shadow-xl uppercase transform active:scale-95 transition-all active:bg-indigo-800">AUTORIZAR ✅</button>
            </div>
          </div>
        )}

        {showResultModal && (
          <div className="absolute inset-0 bg-indigo-900/95 flex items-center justify-center p-6 z-[1200] backdrop-blur-md">
            <div className="bg-white w-full max-w-lg rounded-[3.5rem] p-12 border-8 border-indigo-50 shadow-2xl text-center animate-in zoom-in duration-500">
              <div className="text-7xl mb-6 float-animation">{correctAnswersCount >= (isAccreditationMode ? 15 : 6) ? '🏆' : '📚'}</div>
              <h2 className="text-4xl font-black text-indigo-900 mb-4 uppercase">{correctAnswersCount >= (isAccreditationMode ? 15 : 6) ? '¡LO LOGRASTE!' : 'SIGUE INTENTANDO'}</h2>
              <div className="inline-block px-10 py-5 rounded-[2rem] border-4 border-indigo-50 bg-indigo-50 text-indigo-600 mb-10 shadow-inner">
                <p className="text-5xl font-black">{correctAnswersCount} / {isAccreditationMode ? 25 : 10}</p>
                <p className="text-xs font-bold uppercase mt-2">Nota: {isAccreditationMode ? Math.round((correctAnswersCount / 25) * 10) : correctAnswersCount} / 10</p>
              </div>
              <button onClick={() => handleExit()} className="w-full bg-indigo-600 text-white font-black py-6 rounded-3xl shadow-xl uppercase tracking-widest transform active:scale-95 transition-all hover:bg-indigo-700 active:bg-indigo-800">VOLVER AL AULA 🚀</button>
            </div>
          </div>
        )}
      </div>
      <div ref={messagesEndRef} />
    </div>
  );
};

import React, { useState, useEffect, useRef, useMemo, useCallback, memo } from 'react';
import { Lesson, ChatMessage, Role } from '../types';
import { getStudentData, updateLessonInStudent, getUsers } from '../storage2';
import { getGeminiChat, generateExam, generateQuestionBank, validateOpenAnswer, generateSpeech, decode, decodeAudioData } from '../geminiService2';
// @ignore
import ReactMarkdown from 'react-markdown';
// @ignore
import remarkGfm from 'remark-gfm';
// @ignore
import rehypeRaw from 'rehype-raw';

interface LessonWindowProps {
  studentUsername: string;
  lessonId: string;
  onClose: (finishedDate?: string, finishedId?: string) => void;
  isAdminAudit?: boolean;
  isAccreditationMode?: boolean;
}

const ImageWithFallback: React.FC<{ src: string; alt: string }> = ({ src, alt }) => {
  const [error, setError] = useState(false);
  if (error) {
    return (
      <div className="my-4 p-6 rounded-[2rem] bg-indigo-50 dark:bg-indigo-900/30 border-4 border-dashed border-indigo-100 flex flex-col items-center text-center">
        <span className="text-4xl mb-4">🖼️</span>
        <p className="text-xs font-black text-indigo-900 dark:text-indigo-100 uppercase mb-1">Recurso</p>
        <a href={src} target="_blank" rel="noopener noreferrer" className="px-6 py-3 bg-indigo-600 text-white text-[10px] font-black rounded-2xl uppercase">Ver original ↗</a>
      </div>
    );
  }
  return <div className="relative group my-4"><img src={src} alt={alt} crossOrigin="anonymous" onError={() => setError(true)} className="max-w-full h-auto rounded-3xl border-4 border-white shadow-sm" /></div>;
};

const SafeLink: React.FC<any> = ({ children, href }) => <a href={href} target="_blank" rel="noopener noreferrer" className="text-indigo-600 dark:text-indigo-400 font-black underline decoration-2">{children} <span className="ml-1 text-[8px]">↗</span></a>;

const MarkdownComponents = {
  img: ({node, ...props}: any) => <ImageWithFallback src={props.src} alt={props.alt} />,
  a: ({node, ...props}: any) => <SafeLink {...props} />
};

interface ParsedAIResponse {
  explanation: string;
  challengeType?: 'MCQ' | 'WRITTEN';
  question?: { text: string; options?: string[]; correct?: string; };
  errorInfo?: string;
  refuerzo?: string;
  isPlagio?: boolean;
  isIrrelevant?: boolean;
}

interface RichMessageProps {
  message: ChatMessage;
  onAction: (val: string) => void;
  timeLeft?: number;
  isUnlocked?: boolean;
  isAudit?: boolean;
  studentInitial?: string;
  isLessonFinished?: boolean;
  isParentLoading?: boolean;
  isHistory?: boolean;
  isPlaying?: boolean;
  isAudioLoading?: boolean;
}

const RichMessage: React.FC<RichMessageProps> = memo(({ message, onAction, timeLeft, isUnlocked = false, isAudit, studentInitial, isLessonFinished, isParentLoading, isHistory, isPlaying, isAudioLoading }) => {
  const [selectedOption, setSelectedOption] = useState<string | null>(message.selectedOption || null);
  const text = message.parts[0].text;
  const isUser = message.role === 'user';
  const isSystemLog = text.startsWith('📢');
  const formatTime = (iso?: string) => iso ? new Date(iso).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit', hour12: false }) : '';

  const parseResponse = (raw: string): ParsedAIResponse => {
    const isPlagio = raw.includes('[PLAGIO_IA]');
    const isIrrelevant = raw.includes('[IRRELEVANTE]');
    const dataMatch = raw.match(/\[DATA_LOGICA\]([\s\S]*?)\[\/DATA_LOGICA\]/);
    const expMatch = raw.match(/\[EXPLICACION\]([\s\S]*?)\[\/EXPLICACION\]/);

    let explanation = expMatch ? expMatch[1].trim() : raw.replace(/\[DATA_LOGICA\][\s\S]*/g, '').replace(/\[EXPLICACION\]|\[\/EXPLICACION\]|\[RESPUESTA_VALIDA\]|\[RESPUESTA_INCORRECTA\]|\[PLAGIO_IA\]|\[IRRELEVANTE\]|\[REFUERZO\]|\[ERROR_INFO\]/g, '').trim();

    let questionData; let challengeType;
    if (dataMatch) {
      try {
        const json = JSON.parse(dataMatch[1].trim());
        challengeType = json.type;
        const cleanStr = (s: string) => (typeof s === 'string') ? s.replace(/^[A-Z]\)\s*/, '') : s;
        questionData = { text: json.question, options: Array.isArray(json.options) ? json.options.map(cleanStr) : [], correct: cleanStr(json.correct) };
      } catch (e) { console.error(e); }
    }
    return { explanation, challengeType, question: questionData, isPlagio, isIrrelevant };
  };

  const handleOptionClick = (opt: string) => {
    if (selectedOption || message.selectedOption || isAudit || isHistory || timeLeft === 0 || isParentLoading) return;
    setSelectedOption(opt); 
    setTimeout(() => onAction(opt), 800);
  };

  if (isUser) {
    return (
      <div className="flex items-start space-x-3 justify-end w-full animate-in fade-in slide-in-from-right-4 duration-300">
        <div className="bg-indigo-600 text-white p-5 rounded-[2.5rem] shadow-sm border-2 border-indigo-700 max-w-full w-fit ml-auto relative pb-10 min-w-[100px]">
          <div className="prose dark:prose-invert max-w-none text-lg font-bold">{text}</div>
          <div className="absolute bottom-3 right-8 text-xs font-black opacity-80 uppercase tracking-tighter">{formatTime(message.timestamp)}</div>
        </div>
        <div className="w-10 h-10 rounded-full bg-white dark:bg-indigo-800 border-2 border-indigo-200 flex items-center justify-center text-indigo-600 font-black shrink-0">{studentInitial}</div>
      </div>
    );
  }

  if (isSystemLog) {
    return (
      <div className="flex justify-center my-2 animate-in fade-in zoom-in duration-300">
        <div className="bg-slate-100 dark:bg-indigo-900/50 text-indigo-400 dark:text-indigo-300 px-6 py-2 rounded-2xl text-[10px] font-black uppercase tracking-widest border border-indigo-50 dark:border-indigo-800 shadow-sm flex items-center space-x-2">
          <span>{text}</span>
          <span className="opacity-50">•</span>
          <span className="opacity-50">{formatTime(message.timestamp)}</span>
        </div>
      </div>
    );
  }

  const parsed = parseResponse(text);
  const activeSelection = selectedOption || message.selectedOption;
  const showQuestionBlock = parsed.question && (isUnlocked || activeSelection || isAudit || message.is_unlocked || message.studentResponse);

  return (
    <div className={`flex items-start space-x-3 w-full animate-in fade-in slide-in-from-left-4 duration-500`}>
      <div className="w-10 h-10 rounded-2xl bg-indigo-50 dark:bg-indigo-800 border-2 border-indigo-100 flex items-center justify-center text-xl shrink-0">🤖</div>
      <div className={`p-6 rounded-[2.5rem] shadow-sm border-2 flex-1 w-full max-w-full relative pb-12 ${parsed.isIrrelevant ? 'bg-amber-50 border-amber-300' : 'bg-white dark:bg-indigo-900 border-indigo-50'}`}>
        <div className="flex flex-col space-y-4">
          {parsed.isIrrelevant ? (
            <div className="prose dark:prose-invert max-w-none text-lg font-bold text-amber-700">
              ⚠️ ¡Vuelve al tema! Tu respuesta está fuera de contexto. Por favor, enfócate en la lección para poder avanzar.
            </div>
          ) : (
            <div className="pregunta-contenedor prose dark:prose-invert max-w-none text-lg">
              <ReactMarkdown remarkPlugins={[remarkGfm]} rehypePlugins={[rehypeRaw]} components={MarkdownComponents}>{parsed.explanation}</ReactMarkdown>
              {!isUnlocked && !activeSelection && !isAudit && !isHistory && parsed.question && !isLessonFinished && !message.studentResponse && !message.is_unlocked && (
                <div className="mt-6"><button onClick={() => onAction("__UNLOCK_QUESTION__")} disabled={isParentLoading} className="bg-indigo-600 text-white border-2 border-indigo-500 px-6 py-4 rounded-2xl font-black text-sm hover:bg-indigo-700 shadow-xl uppercase tracking-widest disabled:opacity-50 transform active:scale-95 transition-all active:bg-indigo-800">Ya leí y comprendí 🎯</button></div>
              )}
              {showQuestionBlock && !isLessonFinished && (
                <div className="animate-in zoom-in-95 pt-6 border-t-4 border-indigo-50 mt-6">
                  <p className="texto-pregunta text-xl font-black mb-6 leading-tight">{parsed.question.text}</p>
                  {message.studentResponse && <div className={`p-6 rounded-[1.5rem] font-black text-lg shadow-md border-2 mb-6 ${message.validationStatus === 'correct' ? 'bg-green-500 border-green-600 text-white' : message.validationStatus === 'incorrect' ? 'bg-red-500 border-red-600 text-white' : 'bg-blue-600 border-blue-700 text-white'}`}><p className="text-[10px] font-black uppercase mb-2 opacity-80">Tu Respuesta</p>{message.studentResponse}</div>}
                  {parsed.challengeType === 'MCQ' && (
                    <div className="grid gap-3">
                      {parsed.question.options?.map((opt, idx) => {
                        const isSelected = activeSelection === opt; const isCorrect = opt === parsed.question?.correct;
                        let btnClass = "bg-white dark:bg-indigo-950 text-indigo-600 border-indigo-100 hover:bg-indigo-50";
                        if (activeSelection) {
                          if (message.validationStatus) {
                            if (isSelected) btnClass = message.validationStatus === 'correct' ? "bg-green-500 text-white border-green-600 shadow-lg" : "bg-red-500 text-white border-red-600 shadow-lg";
                            else if (isCorrect && message.validationStatus === 'incorrect') btnClass = "bg-green-500 text-white border-green-600 shadow-md animate-pulse";
                            else btnClass = "bg-slate-50 border-indigo-50 opacity-40 text-indigo-300";
                          } else { 
                            btnClass = isSelected ? "bg-blue-600 text-white border-blue-700 shadow-lg" : "bg-slate-50 border-indigo-50 opacity-60 text-indigo-300"; 
                          }
                        } else if (!isAudit && !isHistory) btnClass = "bg-indigo-600 border-indigo-500 hover:bg-indigo-700 text-white active:bg-indigo-800";
                        return <button key={idx} onClick={() => handleOptionClick(opt)} disabled={!!activeSelection || isAudit || isHistory || isParentLoading} className={`w-full text-left px-6 py-5 rounded-[1.5rem] font-black text-lg shadow-md transition-all active:scale-95 border-2 ${btnClass}`}>{String.fromCharCode(65 + idx)}) {opt}</button>;
                      })}
                    </div>
                  )}
                </div>
              )}
            </div>
          )}
        </div>
        <div className="absolute bottom-3 right-8 flex items-center space-x-3">
          {!isAudit && !isHistory && !parsed.isIrrelevant && (
            <button 
              onClick={() => onAction("__SPEAK__" + parsed.explanation + "||" + message.timestamp)} 
              disabled={isAudioLoading && !isPlaying}
              className={`transition-all p-2 rounded-xl disabled:opacity-30 flex items-center justify-center ${isPlaying ? 'text-indigo-600 bg-indigo-50 ring-2 ring-indigo-200 shadow-sm' : 'text-indigo-300 hover:text-indigo-600 hover:bg-indigo-50'}`}
              title={isPlaying ? "Pausar" : "Escuchar lección"}
            >
              <span className="text-sm leading-none">{isPlaying ? '⏸️' : isAudioLoading ? '⌛' : '🔊'}</span>
            </button>
          )}
          <span className="text-xs font-black opacity-60 uppercase tracking-tighter text-indigo-400">
            {formatTime(message.timestamp)}
          </span>
        </div>
      </div>
    </div>
  );
});

const DateDivider: React.FC<{ date: string }> = ({ date }) => {
  const d = new Date(date);
  const options: Intl.DateTimeFormatOptions = { weekday: 'long', day: 'numeric', month: 'long', year: 'numeric' };
  const formattedDate = d.toLocaleDateString('es-ES', options);
  const today = new Date().toDateString();
  const msgDate = d.toDateString();
  const label = today === msgDate ? 'Hoy' : formattedDate;
  return (
    <div className="flex justify-center my-6">
      <div className="bg-indigo-100 dark:bg-indigo-900/50 text-indigo-600 dark:text-indigo-200 px-6 py-2 rounded-full text-[10px] font-black uppercase tracking-widest border border-indigo-200 dark:border-indigo-800 shadow-sm">
        {label}
      </div>
    </div>
  );
};

export const LessonWindow: React.FC<LessonWindowProps> = ({ studentUsername, lessonId, onClose, isAdminAudit: forcedAudit = false, isAccreditationMode = false }) => {
  const [lesson, setLesson] = useState<Lesson | null>(null);
  const [messages, setMessages] = useState<ChatMessage[]>([]);
  const [input, setInput] = useState('');
  const [isLoading, setIsLoading] = useState(false);
  const [isTyping, setIsTyping] = useState(false);
  const [isPaused, setIsPaused] = useState(false);
  const [loadingText, setLoadingText] = useState('');
  const [secondsElapsed, setSecondsElapsed] = useState(0);
  const [validCount, setValidCount] = useState(0);
  const [targetInteractions, setTargetInteractions] = useState(30);
  const [isUnlocked, setIsUnlocked] = useState(false);

  const [showExam, setShowExam] = useState(false);
  const [examData, setExamData] = useState<any>(null);
  const [currentQuestionIdx, setCurrentQuestionIdx] = useState(0);
  const [currentAnswer, setCurrentAnswer] = useState('');
  const [showQuestionFeedback, setShowQuestionFeedback] = useState(false);
  const [isLastAnswerCorrect, setIsLastAnswerCorrect] = useState(false);
  const [aiFeedback, setAiFeedback] = useState('');
  const [isExamFinished, setIsExamFinished] = useState(false);
  const [correctAnswersCount, setCorrectAnswersCount] = useState(0);
  const [examTimer, setExamTimer] = useState(0);
  const [showResultModal, setShowResultModal] = useState(false);
  const [isValidatingAI, setIsValidatingAI] = useState(false);
  const [playingMsgId, setPlayingMsgId] = useState<string | null>(null);
  const [isAudioLoading, setIsAudioLoading] = useState(false);

  const [showAdminVerifyModal, setShowAdminVerifyModal] = useState(false);
  const [adminPassInput, setAdminPassInput] = useState('');
  const [adminPassAttempts, setAdminPassAttempts] = useState(3);
  const [isVerifyingPass, setIsVerifyingPass] = useState(false);

  const chatRef = useRef<any>(null);
  const messagesEndRef = useRef<HTMLDivElement>(null);
  const messagesRef = useRef<ChatMessage[]>([]);
  const audioRef = useRef<{ 
    context: AudioContext | null, 
    source: AudioBufferSourceNode | null,
    buffer: AudioBuffer | null,
    startTime: number,
    offset: number,
    playingMsgId: string | null
  }>({ 
    context: null, 
    source: null, 
    buffer: null,
    startTime: 0,
    offset: 0,
    playingMsgId: null
  });

  const loggedTimeGoal = useRef(false);
  const loggedInteractionsGoal = useRef(false);

  // Ref para rastrear la última actividad y pausar por inactividad
  const lastActivityRef = useRef<number>(Date.now());

  const isAdminAudit = forcedAudit || (lesson?.credits_transfered === true);
  const timeMet = useMemo(() => Math.floor(secondsElapsed / 60) >= (lesson?.durationMinutes || 0), [secondsElapsed, lesson]);
  const interactionsMet = validCount >= targetInteractions;

  useEffect(() => { messagesRef.current = messages; }, [messages]);

  // Temporizador principal de lección e inactividad
  useEffect(() => {
    if (!showExam && !isLoading && !isPaused && !isAdminAudit && !isAccreditationMode && !isExamFinished && lesson) {
      const timer = setInterval(() => {
        setSecondsElapsed(prev => prev + 1);

        // Chequeo de inactividad (3 minutos = 180 segundos)
        const now = Date.now();
        const inactiveTime = (now - lastActivityRef.current) / 1000;
        if (inactiveTime >= 180) {
          handleAutoPause();
        }
      }, 1000);
      return () => clearInterval(timer);
    }
  }, [showExam, isLoading, isPaused, isAdminAudit, isAccreditationMode, isExamFinished, lesson]);

  const addLogMessage = (text: string) => {
    const msg: ChatMessage = {
      role: 'model',
      parts: [{ text: `📢 ${text}` }],
      timestamp: new Date().toISOString(),
      is_unlocked: true,
      isSilent: true 
    };
    setMessages(prev => [...prev, msg]);
  };

  const handleAutoPause = () => {
    if (isPaused || showExam || isAdminAudit) return;

    // Descontar 3 minutos (180 segundos)
    setSecondsElapsed(prev => Math.max(0, prev - 180));

    // Pausar
    setIsPaused(true);

    // Log
    addLogMessage(`${studentUsername} no mostró actividad por más de 3 minutos. La lección se ha pausado automáticamente y se han descontado 3 minutos del tiempo transcurrido.`);

    // Reiniciar ref de actividad para evitar bucle inmediato
    lastActivityRef.current = Date.now();

    // Guardar estado
    if (lesson) {
      const updated: Lesson = {
        ...lesson,
        chatHistory: messagesRef.current,
        elapsedSeconds: Math.max(0, secondsElapsed - 180),
        validInteractionsCount: validCount
      };
      updateLessonInStudent(studentUsername, updated);
    }
  };

  const updateActivity = () => {
    lastActivityRef.current = Date.now();
  };

  useEffect(() => {
    if (timeMet && !loggedTimeGoal.current && !isAdminAudit && !isAccreditationMode) {
      addLogMessage(`${studentUsername} completo el tiempo requerido de estudio de esta lección`);
      loggedTimeGoal.current = true;
    }
  }, [timeMet, isAdminAudit, isAccreditationMode, studentUsername]);

  useEffect(() => {
    if (interactionsMet && !loggedTimeGoal.current && !isAdminAudit && !isAccreditationMode) {
      addLogMessage(`${studentUsername} completo las interacciónes requeridas de esta lección`);
      loggedInteractionsGoal.current = true;
    }
  }, [interactionsMet, isAdminAudit, isAccreditationMode, studentUsername]);

  // Temporizador de examen
  useEffect(() => {
    let timer: any;
    if (showExam && !showQuestionFeedback && !isExamFinished) {
      if (examTimer > 0) {
        timer = setInterval(() => {
          setExamTimer(prev => prev - 1);
        }, 1000);
      } else {
        handleCheckAnswer();
      }
    }
    return () => clearInterval(timer);
  }, [showExam, showQuestionFeedback, examTimer, isExamFinished]);

  useEffect(() => {
    const fetchLesson = async () => {
      const res = await getStudentData(studentUsername);
      if (res) {
        const found = res.lessons.find(l => l.id === lessonId);
        if (found) {
          setLesson(found);
          setSecondsElapsed(found.elapsedSeconds || 0);
          setValidCount(found.validInteractionsCount || 0);
          setTargetInteractions(Math.ceil(found.durationMinutes * 0.8));
          if (found.chatHistory?.length) setMessages(found.chatHistory);

          if (isAccreditationMode) {
            await initAccreditationExam(found);
          } else if (!isAdminAudit) {
            startGeminiChat(found, (found.chatHistory?.length || 0) > 0);
          }
        }
      }
    };
    fetchLesson();
  }, [studentUsername, lessonId, isAccreditationMode]);

  const scrollToBottom = () => {
    messagesEndRef.current?.scrollIntoView({ behavior: 'smooth' });
  };

  useEffect(() => { scrollToBottom(); }, [messages, isTyping]);

  const formatSeconds = (s: number) => {
    const mins = Math.floor(s / 60);
    const secs = String(s % 60).padStart(2, '0');
    return `${mins}:${secs}`;
  };

  const initAccreditationExam = async (l: Lesson) => {
    setIsLoading(true);
    setLoadingText("Generando banco de preguntas especializado...");
    try {
      let questionsPayload = l.questions;
      const hasQuestions = questionsPayload && questionsPayload.questions && Array.isArray(questionsPayload.questions) && questionsPayload.questions.length >= 50;

      if (!hasQuestions) {
        const generated = await generateQuestionBank(l.subject, l.title);
        questionsPayload = generated;
        const updatedLesson = { ...l, questions: generated };
        await updateLessonInStudent(studentUsername, updatedLesson);
        setLesson(updatedLesson);
      }

      const shuffle = (arr: any[]) => [...arr].sort(() => 0.5 - Math.random());
      const randomSelection = shuffle(questionsPayload.questions).slice(0, 25);

      setExamData({ questions: randomSelection.map((q, i) => {
          const type = q.type || 'multiple_choice';
          const isTF = type === 'true_false';
          return {
            id: i,
            text: q.question,
            type: type,
            options: isTF ? ["VERDADERO", "FALSO"] : (q.options || []),
            correctAnswer: isTF 
              ? (String(q.correct_answer).toUpperCase().includes("TRUE") || String(q.correct_answer).toUpperCase().includes("VERDADERO") ? "VERDADERO" : "FALSO")
              : q.correct_answer,
            acceptableAnswers: q.acceptable_answers || [],
            explanation: q.explanation || "Información validada académica."
          };
      })});

      setShowExam(true);
      setCurrentQuestionIdx(0);
      setCorrectAnswersCount(0);
      setExamTimer(60);
    } catch (err) { 
      console.error(err);
      onClose();
    } finally { setIsLoading(false); }
  };

  const startGeminiChat = async (l: Lesson, isResuming: boolean) => {
    if (chatRef.current) return;
    setIsTyping(true);
    try {
      if (isResuming) {
        addLogMessage(`${studentUsername} esta retomando la lección`);
      }
      const chat = await getGeminiChat(l, studentUsername, l.chatHistory);
      chatRef.current = chat;
      const response = await chat.sendMessage({ message: isResuming ? `[RESUME_MODE]` : `START_LESSON` });
      setMessages(prev => [...prev, { role: 'model', parts: [{ text: response.text || '' }], timestamp: new Date().toISOString(), is_unlocked: false }]);
    } catch (err) { console.error(err); } finally { setIsTyping(false); }
  };

  const stopCurrentAudio = () => {
    if (audioRef.current.source) {
      try {
        audioRef.current.source.stop();
      } catch (e) { }
      audioRef.current.source = null;
    }
  };

  const handleSpeak = async (text: string, msgId: string) => {
    if (isTyping || isLoading) return;

    if (!audioRef.current.context) {
      audioRef.current.context = new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 24000 });
    }
    const ctx = audioRef.current.context;

    // Toggle pause logic: If clicking the same one that's already playing, pause it.
    if (playingMsgId === msgId) {
      if (audioRef.current.source) {
        audioRef.current.offset += ctx.currentTime - audioRef.current.startTime;
        try { audioRef.current.source.stop(); } catch (e) {}
        audioRef.current.source = null;
      }
      setPlayingMsgId(null);
      return;
    }

    // Stop whatever is playing now from another bubble
    if (audioRef.current.source) {
      try { audioRef.current.source.stop(); } catch (e) {}
      audioRef.current.source = null;
    }

    // If switching messages, reset state for the new one
    if (audioRef.current.playingMsgId !== msgId) {
      audioRef.current.buffer = null;
      audioRef.current.offset = 0;
      audioRef.current.playingMsgId = msgId;
    }

    setIsAudioLoading(true);
    setPlayingMsgId(msgId);

    try {
      // If we don't have the buffer cached for this message, generate it
      if (!audioRef.current.buffer) {
        const base64Audio = await generateSpeech(text);
        if (!base64Audio) {
          setPlayingMsgId(null);
          setIsAudioLoading(false);
          return;
        }
        const arrayBuffer = decode(base64Audio);
        audioRef.current.buffer = await decodeAudioData(arrayBuffer, ctx, 24000, 1);
      }

      const buffer = audioRef.current.buffer;
      if (!buffer) {
        setPlayingMsgId(null);
        return;
      }

      const source = ctx.createBufferSource();
      source.buffer = buffer;
      source.connect(ctx.destination);

      source.onended = () => {
        // Only clear global state if this specific playback ended naturally
        if (audioRef.current.source === source) {
          audioRef.current.offset = 0;
          audioRef.current.source = null;
          setPlayingMsgId(null);
        }
      };

      // Ensure offset is within bounds
      const currentOffset = audioRef.current.offset % buffer.duration;
      source.start(0, currentOffset);

      audioRef.current.source = source;
      audioRef.current.startTime = ctx.currentTime;
    } catch (err) {
      console.error("Error al reproducir audio:", err);
      setPlayingMsgId(null);
    } finally {
      setIsAudioLoading(false);
    }
  };

  const handleSend = async (manualText?: string) => {
    updateActivity();
    if (isAdminAudit || isTyping || isPaused) return;

    if (manualText === "__UNLOCK_QUESTION__") {
        setIsUnlocked(true);
        setMessages(prev => {
            const updated = [...prev];
            for (let i = updated.length - 1; i >= 0; i--) {
                if (updated[i].role === 'model' && updated[i].parts[0].text.includes('[DATA_LOGICA]')) {
                    updated[i].is_unlocked = true;
                    break;
                }
            }
            return updated;
        });
        return;
    }

    if (manualText?.startsWith("__SPEAK__")) {
      const parts = manualText.replace("__SPEAK__", "").split("||");
      const textToSpeak = parts[0];
      const msgId = parts[1];
      handleSpeak(textToSpeak, msgId);
      return;
    }

    const userText = (manualText || input).trim();
    if (!userText) return;

    const isMcqSelection = !!manualText && manualText !== "__UNLOCK_QUESTION__";

    setInput('');
    setIsTyping(true);
    const userMsg: ChatMessage = { role: 'user', parts: [{ text: userText }], timestamp: new Date().toISOString() };

    setMessages(prev => {
      const updated = [...prev];
      if (isMcqSelection) {
        let lastQuestionIdx = -1;
        for (let i = updated.length - 1; i >= 0; i--) {
          if (updated[i].role === 'model' && updated[i].parts[0].text.includes('[DATA_LOGICA]')) {
            lastQuestionIdx = i;
            break;
          }
        }
        if (lastQuestionIdx !== -1) {
          updated[lastQuestionIdx] = {
            ...updated[lastQuestionIdx],
            selectedOption: userText,
            validationStatus: undefined 
          };
        }
      }
      return [...updated, userMsg];
    });

    try {
      const result = await chatRef.current.sendMessage({ message: userText });
      const text = result.text || '';

      const isIrrelevant = text.includes('[IRRELEVANTE]');
      const isValid = text.includes('[RESPUESTA_VALIDA]');

      if (!isIrrelevant && isValid) {
        setValidCount(prev => prev + 1);
      }

      const aiMsg: ChatMessage = { 
        role: 'model', 
        parts: [{ text }], 
        timestamp: new Date().toISOString(), 
        is_unlocked: false,
        validationStatus: isIrrelevant ? 'irrelevant' : (isValid ? 'correct' : 'incorrect')
      };

      setMessages(prev => {
        const updated = [...prev];
        let lastQuestionIdx = -1;
        for (let i = updated.length - 2; i >= 0; i--) {
          if (updated[i].role === 'model' && updated[i].parts[0].text.includes('[DATA_LOGICA]')) {
            lastQuestionIdx = i;
            break;
          }
        }

        if (lastQuestionIdx !== -1) {
          updated[lastQuestionIdx] = {
            ...updated[lastQuestionIdx],
            selectedOption: isMcqSelection ? userText : undefined,
            studentResponse: !isMcqSelection ? userText : undefined,
            validationStatus: isIrrelevant ? 'irrelevant' : (isValid ? 'correct' : 'incorrect')
          };
        }

        return [...updated, aiMsg];
      });
      setIsUnlocked(false);
    } catch (err) { console.error(err); } finally { setIsTyping(false); }
  };

  const handleTogglePause = async () => {
    updateActivity();
    const nextPause = !isPaused;
    setIsPaused(nextPause);

    const logText = nextPause ? `${studentUsername} pausó la lección` : `${studentUsername} renaudó la lección`;
    addLogMessage(logText);

    if (lesson && !isAdminAudit) {
      const updated: Lesson = {
        ...lesson,
        chatHistory: messagesRef.current,
        elapsedSeconds: secondsElapsed,
        validInteractionsCount: validCount
      };
      await updateLessonInStudent(studentUsername, updated);
    }
  };

  const handleExit = async () => {
    setIsLoading(true);
    setLoadingText("Guardando historial...");
    stopCurrentAudio();
    try {
      if (lesson && !isAdminAudit) {
        let finalMessages = [...messagesRef.current];

        if (showExam && !isExamFinished) {
          const totalQ = isAccreditationMode ? 25 : 10;
          finalMessages.push({
            role: 'model',
            parts: [{ text: `📢 ${studentUsername} salio del examen sin terminarlo en la pregunta ${currentQuestionIdx + 1} de ${totalQ}` }],
            timestamp: new Date().toISOString(),
            isSilent: true,
            is_unlocked: true
          });
        } else if (!lesson.completed && !isAccreditationMode && !isExamFinished) {
          finalMessages.push({
            role: 'model',
            parts: [{ text: `📢 ${studentUsername} salio de la lección sin terminar` }],
            timestamp: new Date().toISOString(),
            isSilent: true,
            is_unlocked: true
          });
        }

        const updated: Lesson = {
          ...lesson,
          chatHistory: finalMessages,
          elapsedSeconds: secondsElapsed,
          validInteractionsCount: validCount
        };
        await updateLessonInStudent(studentUsername, updated);
      }
    } catch (err) {
      console.error("Error al guardar historial al salir:", err);
    } finally {
      onClose();
    }
  };

  const handleCheckAnswer = async () => {
    updateActivity();
    if (!examData) return;
    const q = examData.questions[currentQuestionIdx];
    let isCorrect = false;

    if (q.type === 'multiple_choice' || q.type === 'true_false') {
        isCorrect = (currentAnswer === q.correctAnswer);
    } else {
        const clean = (s: string) => s.toLowerCase().trim();
        const studentAnsClean = clean(currentAnswer);
        isCorrect = q.acceptableAnswers?.some((ans: string) => studentAnsClean.includes(clean(ans))) || false;

        if (!isCorrect && studentAnsClean.length > 0) {
            setIsValidatingAI(true);
            try {
                isCorrect = await validateOpenAnswer(q.text, q.acceptableAnswers, currentAnswer);
            } catch (e) { 
                console.error("Error validando con IA:", e);
                isCorrect = false; 
            } finally { 
                setIsValidatingAI(false); 
            }
        }
    }

    setIsLastAnswerCorrect(isCorrect);
    setAiFeedback(q.explanation);
    if (isCorrect) setCorrectAnswersCount(prev => prev + 1);
    setShowQuestionFeedback(true);
  };

  const handleNextQuestion = () => {
    updateActivity();
    const total = isAccreditationMode ? 25 : 10;
    if (currentQuestionIdx < total - 1) {
      setCurrentQuestionIdx(prev => prev + 1);
      setShowQuestionFeedback(false);
      setCurrentAnswer('');
      setExamTimer(60);
    } else finishExam();
  };

  const startLessonExam = async () => {
    if (!lesson) return;
    updateActivity();
    setIsLoading(true);
    setLoadingText("Preparando evaluación final...");
    try {
      let questionsPayload = lesson.questions;
      const hasQuestions = questionsPayload && questionsPayload.questions && Array.isArray(questionsPayload.questions) && questionsPayload.questions.length >= 50;

      if (!hasQuestions) {
        const generated = await generateQuestionBank(lesson.subject, lesson.title);
        questionsPayload = generated;
        const updatedLesson = { ...lesson, questions: generated };
        await updateLessonInStudent(studentUsername, updatedLesson);
        setLesson(updatedLesson);
      }

      const shuffle = (arr: any[]) => [...arr].sort(() => 0.5 - Math.random());
      const randomSelection = shuffle(questionsPayload.questions).slice(0, 10);

      setExamData({ questions: randomSelection.map((q, i) => {
          const type = q.type || 'multiple_choice';
          const isTF = type === 'true_false';
          return {
            id: i,
            text: q.question,
            type: type,
            options: isTF ? ["VERDADERO", "FALSO"] : (q.options || []),
            correctAnswer: isTF 
              ? (String(q.correct_answer).toUpperCase().includes("TRUE") || String(q.correct_answer).toUpperCase().includes("VERDADERO") ? "VERDADERO" : "FALSO")
              : q.correct_answer,
            acceptableAnswers: q.acceptable_answers || [],
            explanation: q.explanation || "Información validada académica."
          };
      })});

      addLogMessage(`${studentUsername} solicito el examen de evalución de esta lección`);
      setShowExam(true);
      setCurrentQuestionIdx(0);
      setCorrectAnswersCount(0);
      setExamTimer(60);
    } catch (err) { 
      console.error(err);
    } finally { 
      setIsLoading(false); 
    }
  };

  const finishExam = async () => {
    setShowExam(false);
    const passingThreshold = isAccreditationMode ? 15 : 6;
    if (isAccreditationMode && correctAnswersCount >= passingThreshold) {
      setShowAdminVerifyModal(true);
    } else {
      await accreditAndShowResults(correctAnswersCount);
    }
  };

  const accreditAndShowResults = async (gradeCount: number) => {
    if (lesson) {
      const normalizedGrade = isAccreditationMode 
        ? Math.round((gradeCount / 25) * 10)
        : gradeCount;

      const isPassed = normalizedGrade >= 6;
      const statusText = isPassed ? 'Aprobada' : 'Reprobada';
      const resultAction = isPassed ? "aprobó" : "reprobó";
      const totalQuestions = isAccreditationMode ? 25 : 10;
      addLogMessage(`${studentUsername} ${resultAction} el examen de esta lección con ${gradeCount} de ${totalQuestions} correctas`);

      const updated: Lesson = { 
        ...lesson, 
        grade: normalizedGrade, 
        completed: isPassed, 
        lesson_status: statusText as any,
        chatHistory: messagesRef.current,
        elapsedSeconds: secondsElapsed,
        validInteractionsCount: validCount
      };
      await updateLessonInStudent(studentUsername, updated);
      setLesson(updated);
      setShowResultModal(true);
    }
  };

  const handleVerifyAdminPass = async () => {
    setIsVerifyingPass(true);
    try {
      const users = await getUsers();
      const admin = users.find(u => u.role === Role.ADMIN);
      const reversedPass = (admin?.password || '').split('').reverse().join('');
      if (adminPassInput === reversedPass) {
        setShowAdminVerifyModal(false);
        await accreditAndShowResults(correctAnswersCount);
      } else {
        setAdminPassAttempts(prev => prev - 1);
        setAdminPassInput('');
        if (adminPassAttempts <= 1) onClose();
      }
    } catch (err) { alert("Error"); } finally { setIsVerifyingPass(false); }
  };

  if (!lesson) return null;

  return (
    <div className={`fixed inset-0 bg-white dark:bg-indigo-950 z-[500] flex flex-col font-fredoka overflow-hidden select-none ${isAdminAudit ? 'relative h-full' : ''}`}>
      {isLoading && (
        <div className="fixed inset-0 bg-indigo-900/95 z-[2000] flex flex-col items-center justify-center p-8 text-center">
          <div className="w-24 h-24 border-8 border-indigo-400 border-t-white rounded-full animate-spin mb-8"></div>
          <h2 className="text-3xl font-black text-white uppercase mb-4 tracking-widest">{loadingText}</h2>
        </div>
      )}

      <header className={`${isAdminAudit ? 'bg-slate-700' : 'bg-indigo-600'} px-6 py-4 shadow-lg flex flex-col z-[1100] border-b-4 border-white/10 shrink-0 gap-3`}>
          <div className="flex items-center justify-between w-full gap-4">
            <div className="flex items-center space-x-2 shrink-0">
              {!isAdminAudit && !isAccreditationMode && !showExam && !isExamFinished && (
                <>
                  <div className={`${timeMet ? 'bg-green-600' : 'bg-white/10'} px-3 py-1.5 rounded-2xl flex flex-col items-center min-w-[100px] border border-white/10 transition-colors duration-500`}>
                    <span className="text-[7px] font-black text-white/60 uppercase">CRONÓMETRO</span>
                    <span className="text-xs font-black text-white font-mono leading-none">
                      {formatSeconds(secondsElapsed)} / {formatSeconds(lesson.durationMinutes * 60)}
                    </span>
                  </div>
                  <div className={`${interactionsMet ? 'bg-green-600' : 'bg-white/10'} px-3 py-1.5 rounded-2xl flex flex-col items-center min-w-[100px] border border-white/10 transition-colors duration-500`}>
                    <span className="text-[7px] font-black text-white/60 uppercase">INTERACCIONES</span>
                    <span className="text-xs font-black text-white font-mono leading-none">{validCount} / {targetInteractions}</span>
                  </div>
                </>
              )}
            </div>

            <div className="flex-1 text-center overflow-hidden">
              <h2 className="text-[10px] md:text-xs font-black text-white uppercase tracking-tight leading-tight">
                MATERIA: {lesson.subject}<br />
                LECCIÓN: {lesson.title}
              </h2>
            </div>

            <div className="flex items-center space-x-2 shrink-0">
              {!isAdminAudit && !isAccreditationMode && !isExamFinished && !showExam && (
                <button onClick={handleTogglePause} className={`h-10 px-4 rounded-xl font-black text-[10px] uppercase shadow-lg transition-all flex items-center space-x-2 transform active:scale-90 active:bg-white/30 duration-100 ${isPaused ? 'bg-amber-400 text-indigo-900 animate-pulse' : 'bg-white/10 text-white hover:bg-white/20 border border-white/10'}`}>
                  <span>{isPaused ? '▶️' : '⏸️'}</span>
                  <span className="hidden sm:inline">{isPaused ? 'REANUDAR' : 'PAUSAR'}</span>
                </button>
              )}
              <button onClick={handleExit} className="h-10 px-4 rounded-xl bg-red-500 hover:bg-red-600 transition-all flex items-center justify-center font-black text-white text-[10px] uppercase shadow-lg space-x-2 border border-white/10 transform active:scale-90 active:bg-red-700 duration-100">
                <span className="hidden sm:inline">SALIR</span>
                <span>✕</span>
              </button>
            </div>
          </div>
      </header>

      <div className="flex-1 relative flex flex-col bg-sky-50 dark:bg-indigo-950 overflow-hidden min-h-0">
        <div className={`flex-1 flex flex-col min-h-0 ${(showExam || showResultModal || showAdminVerifyModal) ? 'opacity-20 pointer-events-none' : ''}`}>
          <div className="flex-1 overflow-y-auto px-[5%] py-10 space-y-4 custom-scrollbar min-h-0">
            {messages.map((m, i) => {
              const prevMsg = i > 0 ? messages[i-1] : null;
              const isDifferentDay = !prevMsg || (new Date(m.timestamp || '').toDateString() !== new Date(prevMsg.timestamp || '').toDateString());
              return (
                <React.Fragment key={i}>
                  {isDifferentDay && m.timestamp && <DateDivider date={m.timestamp} />}
                  <RichMessage 
                    message={m} 
                    onAction={handleSend} 
                    studentInitial={studentUsername.charAt(0).toUpperCase()} 
                    isLessonFinished={isExamFinished} 
                    isParentLoading={isTyping} 
                    isPlaying={playingMsgId === m.timestamp}
                    isAudioLoading={isAudioLoading}
                  />
                </React.Fragment>
              );
            })}
            {isTyping && (
              <div className="flex items-start space-x-3 w-full animate-pulse">
                <div className="w-10 h-10 rounded-2xl bg-indigo-100 dark:bg-indigo-800 flex items-center justify-center text-xl shrink-0">🤖</div>
                <div className="p-4 bg-white dark:bg-indigo-900 rounded-3xl border-2 border-indigo-50 shadow-sm">
                  <span className="text-xs font-black text-indigo-400 uppercase italic">El profesor está analizando y escribiendo...</span>
                </div>
              </div>
            )}
            <div ref={messagesEndRef} />
          </div>

          {!isAdminAudit && !isAccreditationMode && !isExamFinished && (
            <div className={`p-6 bg-white dark:bg-indigo-900 border-t-4 border-indigo-50 relative shrink-0 transition-opacity ${isPaused ? 'opacity-40 pointer-events-none' : 'opacity-100'}`}>
               {timeMet && interactionsMet && !showExam && (
                  <div className="absolute -top-16 left-0 right-0 px-6 flex justify-center animate-bounce">
                    <button onClick={startLessonExam} className="bg-green-600 text-white px-10 py-4 rounded-full font-black shadow-2xl border-4 border-white hover:bg-green-700 transition-all uppercase tracking-widest text-xs transform active:scale-95 duration-100 active:bg-green-800">
                      ¡OBJETIVOS LOGRADOS! SOLICITAR EXAMEN DE ACREDITACIÓN 🏁
                    </button>
                  </div>
               )}
               <div className="w-full flex items-center space-x-3" onClick={updateActivity}>
                <textarea 
                  value={input} 
                  onChange={(e) => setInput(e.target.value)} 
                  onKeyDown={(e) => {
                    updateActivity();
                    if (e.key === 'Enter' && !e.shiftKey) {
                      e.preventDefault();
                      handleSend();
                    }
                  }} 
                  className="flex-1 px-6 py-4 rounded-3xl border-4 border-indigo-50 dark:bg-indigo-950 font-bold resize-none h-16 shadow-inner text-lg outline-none focus:border-indigo-500 transition-all" 
                  placeholder={isPaused ? "Lección pausada..." : "Tu respuesta académica..."} 
                  disabled={isTyping || isPaused} 
                />
                <button 
                  onClick={() => handleSend()} 
                  disabled={isTyping || !input.trim() || isPaused} 
                  className="bg-indigo-600 text-white w-16 h-16 rounded-3xl text-xl shadow-xl hover:bg-indigo-700 transition-all flex items-center justify-center disabled:opacity-50 transform active:scale-90 active:bg-indigo-800 duration-100"
                >
                  ➔
                </button>
              </div>
            </div>
          )}
        </div>

        {showExam && examData && (
          <div className="absolute inset-0 bg-indigo-900/90 flex items-center justify-center p-4 z-[800] backdrop-blur-sm">
            <div className="bg-white w-full max-w-2xl rounded-[3rem] p-10 border-8 border-indigo-50 shadow-2xl overflow-y-auto max-h-[95vh] flex flex-col">
              {!showQuestionFeedback ? (
                <>
                  <div className="flex justify-between items-center mb-8">
                    <div className="bg-indigo-100 text-indigo-600 px-4 py-2 rounded-2xl font-black text-xs uppercase">PREGUNTA {currentQuestionIdx + 1} DE {isAccreditationMode ? 25 : 10}</div>
                    <div className="w-12 h-12 rounded-full border-4 border-indigo-600 flex items-center justify-center font-black text-sm text-indigo-600 transition-all duration-300">{examTimer}s</div>
                  </div>
                  <h3 className="text-2xl font-black text-indigo-900 text-center mb-10 leading-tight">{examData.questions[currentQuestionIdx].text}</h3>
                  {examData.questions[currentQuestionIdx].type === 'open' ? (
                    <textarea 
                      value={currentAnswer} 
                      onChange={(e) => { updateActivity(); setCurrentAnswer(e.target.value); }} 
                      className="w-full p-6 bg-indigo-50 rounded-3xl font-bold min-h-[150px] outline-none border-4 border-transparent focus:border-indigo-200 shadow-inner transition-all" 
                      placeholder="Analiza y responde..." 
                    />
                  ) : (
                    <div className="grid gap-3">
                        {examData.questions[currentQuestionIdx].options.map((opt: string, idx: number) => (
                        <button key={idx} onClick={() => { updateActivity(); setCurrentAnswer(opt); }} className={`p-5 rounded-3xl text-left font-bold border-4 transition-all transform active:scale-[0.96] active:bg-indigo-50 ${currentAnswer === opt ? 'bg-indigo-600 text-white border-indigo-600 shadow-lg' : 'bg-white border-indigo-50 hover:border-indigo-400'}`}>
                            {opt}
                        </button>
                        ))}
                    </div>
                  )}
                  <button onClick={handleCheckAnswer} disabled={!currentAnswer.trim() || isValidatingAI} className="mt-10 w-full bg-indigo-600 text-white font-black py-5 rounded-[2rem] text-xl shadow-xl uppercase transform active:scale-95 active:bg-indigo-800 transition-all flex items-center justify-center space-x-3 disabled:opacity-50">
                    {isValidatingAI ? (
                      <>
                        <div className="w-6 h-6 border-4 border-white/30 border-t-white rounded-full animate-spin"></div>
                        <span>Validando respuesta...</span>
                      </>
                    ) : (
                      <span>CALIFICAR RESPUESTA</span>
                    )}
                  </button>
                </>
              ) : (
                <div className="text-center py-6 flex flex-col items-center">
                  <div className={`text-5xl font-black mb-8 uppercase animate-in zoom-in duration-300 ${isLastAnswerCorrect ? 'text-green-600' : 'text-red-500'}`}>{isLastAnswerCorrect ? '¡CORRECTO!' : 'FALLASTE'}</div>
                  <div className="bg-indigo-50 p-8 rounded-[2.5rem] border-4 border-indigo-100 mb-10 w-full text-left shadow-inner">
                    {!isLastAnswerCorrect && <p className="text-sm font-black text-red-500 mb-2 uppercase">Lo correcto era: {examData.questions[currentQuestionIdx].correctAnswer}</p>}
                    <p className="text-lg font-bold italic text-indigo-900 leading-relaxed">{aiFeedback}</p>
                  </div>
                  <button onClick={handleNextQuestion} className="w-full bg-indigo-600 text-white font-black py-5 rounded-[2rem] shadow-xl text-xl uppercase tracking-widest transform active:scale-95 active:bg-indigo-800 transition-all">SIGUIENTE</button>
                </div>
              )}
            </div>
          </div>
        )}

        {showAdminVerifyModal && (
          <div className="absolute inset-0 bg-indigo-900/95 flex items-center justify-center p-6 z-[1200] backdrop-blur-md">
            <div className="bg-white w-full max-w-lg rounded-[3.5rem] p-12 border-8 border-indigo-50 shadow-2xl text-center">
              <h2 className="text-3xl font-black text-indigo-900 mb-4 uppercase">Verificación Parental</h2>
              <p className="text-indigo-400 font-bold mb-8">Pide a tu profesor que ingrese su contraseña para validar tu acreditación.</p>
              <input type="password" value={adminPassInput} onChange={(e) => setAdminPassInput(e.target.value)} className="w-full p-5 bg-indigo-50 rounded-2xl border-4 text-center text-2xl font-black" placeholder="••••" />
              <button onClick={handleVerifyAdminPass} className="w-full mt-6 bg-indigo-600 text-white font-black py-5 rounded-3xl shadow-xl uppercase transform active:scale-95 transition-all active:bg-indigo-800">AUTORIZAR ✅</button>
            </div>
          </div>
        )}

        {showResultModal && (
          <div className="absolute inset-0 bg-indigo-900/95 flex items-center justify-center p-6 z-[1200] backdrop-blur-md">
            <div className="bg-white w-full max-w-lg rounded-[3.5rem] p-12 border-8 border-indigo-50 shadow-2xl text-center animate-in zoom-in duration-500">
              <div className="text-7xl mb-6 float-animation">{correctAnswersCount >= (isAccreditationMode ? 15 : 6) ? '🏆' : '📚'}</div>
              <h2 className="text-4xl font-black text-indigo-900 mb-4 uppercase">{correctAnswersCount >= (isAccreditationMode ? 15 : 6) ? '¡LO LOGRASTE!' : 'SIGUE INTENTANDO'}</h2>
              <div className="inline-block px-10 py-5 rounded-[2rem] border-4 border-indigo-50 bg-indigo-50 text-indigo-600 mb-10 shadow-inner">
                <p className="text-5xl font-black">{correctAnswersCount} / {isAccreditationMode ? 25 : 10}</p>
                <p className="text-xs font-bold uppercase mt-2">Nota: {isAccreditationMode ? Math.round((correctAnswersCount / 25) * 10) : correctAnswersCount} / 10</p>
              </div>
              <button onClick={() => handleExit()} className="w-full bg-indigo-600 text-white font-black py-6 rounded-3xl shadow-xl uppercase tracking-widest transform active:scale-95 transition-all hover:bg-indigo-700 active:bg-indigo-800">VOLVER AL AULA 🚀</button>
            </div>
          </div>
        )}
      </div>
      <div ref={messagesEndRef} />
    </div>
  );
};
